import type { ArticleB2 } from './articlesB2';

export const ARTICLE_ROWS: ArticleB2[] = [{"id": "b1-09-001", "seg": 9, "title": "Beruf", "de": ["Bei einem Beruf macht man etwas, um Geld zu verdienen. Von diesem Geld lebt man. Für einen Beruf muss man etwas gelernt haben, das man im Beruf braucht. Viele Leute finden ihre Arbeit auch wichtig, weil sie fühlen, gebraucht zu werden. Wenn man gut gelernt hat und eine Prüfung bestanden hat, bekommt man ein Papier, auf dem das steht. Mit so einem Nachweis kann man sich um eine Arbeitsstelle bewerben.", "Normalerweise darf man jeden Beruf lernen und ausüben, den man will. Für einige Berufe gibt es keine richtige Ausbildung, andere Berufe darf man nur ausüben, wenn man gut ausgebildet ist. Zum Beispiel darf man nur dann als Arzt arbeiten, wenn man eine Erlaubnis dafür hat. Der Staat will nicht, dass Menschen als Arzt arbeiten, die das gar nicht können und so die Kranken in Gefahr bringen.", "Manche Berufe waren früher wichtiger als andere. So gibt es kaum noch Schmiede, denn heute haben die Leute ein Auto und kein Pferd, das Hufeisen braucht. Darum wurde irgendwann der Beruf des Automechanikers erfunden. Die Berufe ändern sich also genauso wie die Wirtschaft.", "Der Beruf ist etwas anderes als ein Job: Der Job ist nur die Arbeit, die man gerade hat. Das ist nicht immer der eigentliche Beruf, den man gelernt hat. Viele Leute sind stolz auf ihren Beruf, auf das, was sie können und was sie damit verdienen. Menschen, die denselben Beruf haben, schließen sich oft in Vereinen zusammen. Die nennt man Berufsverbände. Ein Berufsverband kann sich dann dafür einsetzen, was für den Beruf wichtig ist."], "zh": ["从事一种职业，就是做某件事来挣钱，并靠这些钱生活。做一种职业，必须先学过工作中需要的东西。很多人也觉得自己的工作很重要，因为他们感到自己被需要。好好学习并通过考试后，会拿到一张写明这一点的证书。有了这样的证明，就可以去申请工作岗位。", "一般来说，人人可以学习和从事自己想做的任何职业。有些职业没有正规的培训，另一些职业则只有受过良好培训才能从事。比如只有获得许可才能当医生。国家不希望根本不会看病的人去当医生，让病人陷入危险。", "有些职业以前比别的职业更重要。比如现在几乎没有铁匠了，因为如今人们有汽车，不再有需要马蹄铁的马。所以后来出现了汽车修理工这个职业。可见职业和经济一样，也在变化。", "职业和工作（Job）不一样：Job 只是眼下正在做的活儿，不一定是自己学过的本行。很多人为自己的职业、为自己的本事和挣到的钱感到自豪。从事同一职业的人常常组成协会，叫作行业协会。行业协会可以为这个职业的重要事项去争取。"], "lemmas": [], "gloss": [{"w": "Arbeitsstelle", "de": "Platz, an dem man fest arbeitet", "zh": "工作岗位"}, {"w": "Hufeisen", "de": "Eisen unter dem Fuß eines Pferdes", "zh": "马蹄铁"}, {"w": "Schmiede", "de": "Handwerker, die Eisen heiß machen und formen", "zh": "铁匠"}, {"w": "Berufsverbände", "de": "Vereine von Menschen mit demselben Beruf", "zh": "行业协会"}, {"w": "ausgebildet", "de": "für einen Beruf fertig gelernt", "zh": "受过培训的"}], "qs": [{"q": "Was braucht man, um sich um eine Arbeitsstelle zu bewerben?", "qZh": "申请工作岗位需要什么？", "answer": "Einen Nachweis über eine bestandene Prüfung.", "wrong": ["Ein eigenes Auto.", "Einen Freund in der Firma."]}, {"q": "Warum darf nicht jeder als Arzt arbeiten?", "qZh": "为什么不是人人都能当医生？", "answer": "Kranke sollen nicht in Gefahr kommen.", "wrong": ["Es gibt schon zu viele Ärzte.", "Ärzte verdienen zu viel Geld."]}, {"q": "Was ist der Unterschied zwischen Beruf und Job?", "qZh": "职业和 Job 有什么区别？", "answer": "Der Job ist die Arbeit, die man gerade hat.", "wrong": ["Ein Job ist immer besser bezahlt.", "Für einen Job braucht man eine Prüfung."]}], "src": "改编自 Klexikon《Beruf》", "url": "https://klexikon.zum.de/index.php?oldid=160541", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-002", "seg": 9, "title": "Arbeit", "de": ["Mit Arbeit meint man meist eine Tätigkeit, die man macht, um Geld zu verdienen. Manchmal benutzt man auch das englische Wort Job. Wer arbeitet, wird auch Arbeitnehmer genannt. Arbeitgeber ist zum Beispiel ein Unternehmen. Das sagt, welche Arbeit der Arbeitnehmer erledigen soll. Arbeitgeber kann aber auch eine Gemeinde sein, die Polizei, ein Krankenhaus oder viele andere. Von einem Arbeitsplatz oder einer Arbeitsstelle spricht man, wenn jemand eine feste Arbeit in einem Unternehmen hat.", "Das ganze ist wie so eine Art Tauschgeschäft. Der Arbeitnehmer hilft dabei, die täglichen Aufgaben in einem Unternehmen zu erledigen. Dafür gibt das Unternehmen ihm Geld. Dieses Geld heißt Lohn. Den Lohn braucht der Arbeitnehmer, um wichtige Sachen wie Nahrung, Kleidung und eine Wohnung zu bezahlen.", "Nicht alle Tätigkeiten sind gleich gut bezahlt. Berufe wie der Arzt, die ein langes Studium an der Universität braucht, sind besser bezahlt als zum Beispiel die Arbeit eines Kellners. Es gibt aber auch Menschen, die ohne Lohn arbeiten. Das sind dann ehrenamtliche Mitarbeiter. Wenn jemand keine Arbeit findet, ist er ein Arbeitsloser.", "Es gibt verschiedene Formen der Arbeit. Die Zwangsarbeit ist eine Arbeit, zu der man gezwungen wird. Die Zwangsarbeiter bekommen kein Geld für ihre Arbeit. Zwangsarbeiter sind meistens Kriegsgefangene oder Menschen, die von einer Regierung verfolgt werden. Schwarzarbeiter verrichten Arbeit, ohne dass der Staat davon weiß. Sie versteuern ihren Lohn daher auch nicht.", "Kinderarbeit gibt es immer noch, vor allem in ärmeren Ländern. In ganz Europa ist sie aber auf jeden Fall verboten. Es gibt strenge Regeln und Gesetze, ab wann Jugendliche arbeiten dürfen. In Deutschland gibt es das Jugendarbeitsschutzgesetz. Dort ist festgelegt, wie lange Jugendliche arbeiten dürfen, wie viele Pausen sie machen müssen und welche Arbeiten ganz verboten sind. Dort steht, dass man 14 Jahre alt sein muss, um arbeiten zu dürfen. Das ist aber eine Ausnahme: Man darf dann nur ganz wenige Arbeiten erledigen, zum Beispiel darf man Zeitungen austragen. Im Gesetz ist ansonsten geregelt, dass man erst ab 15 Jahren eine Ausbildung anfangen oder eine Arbeit neben der Schule beginnen darf. Das Lernen für die Schule darf darunter aber nicht leiden! Nach viereinhalb Stunden müssen Jugendliche auf jeden Fall eine Pause einlegen, die mindestens 30 Minuten dauern muss. Gefährliche Arbeiten oder Arbeiten in der Nacht sind nicht erlaubt. Auch für die Arbeit von Erwachsenen gibt es besondere Regelungen. Diese sind aber nicht so streng wie die Regelungen für Kinder und Jugendliche."], "zh": ["说到工作，通常指为了挣钱而做的事。有时也用英语词 Job。工作的人也叫雇员。雇主比如是一家公司，由它来决定雇员要完成什么工作。不过雇主也可以是乡镇、警察局、医院等等。如果有人在一家公司有固定工作，就说他有一个工作岗位。", "整件事像是一种交换。雇员帮公司完成日常任务，公司为此付给他钱。这笔钱叫工资。雇员需要工资来支付食物、衣服和住房等重要东西。", "不是所有工作报酬都一样高。像医生这样需要在大学长期学习的职业，收入比服务员等工作高。也有人不拿工资工作，他们是志愿者。找不到工作的人就是失业者。", "工作有不同形式。强迫劳动是被迫去做的工作，强迫劳动者干活拿不到钱，他们大多是战俘或受政府迫害的人。打黑工的人工作时国家并不知道，所以他们的工资也不交税。", "童工至今仍然存在，尤其在较穷的国家。不过在整个欧洲童工都是禁止的。关于青少年从几岁起可以工作，有严格的规定和法律。德国有《青少年劳动保护法》，规定了青少年可以工作多长时间、必须休息几次、哪些工作完全禁止。法律规定满 14 岁才可以工作，但这是例外：那时只能做很少的几种工作，比如送报纸。除此之外，法律规定满 15 岁才能开始职业培训或在上学之余打工，但学习不能因此受影响！青少年工作四个半小时后必须休息，至少 30 分钟。危险的工作或夜间工作不允许。成年人的工作也有专门规定，不过没有对儿童和青少年那么严格。"], "lemmas": [], "gloss": [{"w": "Tauschgeschäft", "de": "man gibt etwas und bekommt etwas dafür", "zh": "交换"}, {"w": "ehrenamtliche", "de": "ohne Lohn, freiwillig", "zh": "志愿的"}, {"w": "Zwangsarbeit", "de": "Arbeit, die man machen muss, ohne es zu wollen", "zh": "强迫劳动"}, {"w": "Kriegsgefangene", "de": "Soldaten, die im Krieg gefangen wurden", "zh": "战俘"}, {"w": "Schwarzarbeiter", "de": "Menschen, die arbeiten, ohne es dem Staat zu sagen", "zh": "打黑工的人"}, {"w": "versteuern", "de": "für etwas Steuern bezahlen", "zh": "为…纳税"}], "qs": [{"q": "Wofür braucht der Arbeitnehmer seinen Lohn?", "qZh": "雇员用工资做什么？", "answer": "Für Nahrung, Kleidung und eine Wohnung.", "wrong": ["Um seinen Chef zu bezahlen.", "Nur für den Urlaub."]}, {"q": "Was machen Schwarzarbeiter falsch?", "qZh": "打黑工的人错在哪里？", "answer": "Sie bezahlen keine Steuern für ihren Lohn.", "wrong": ["Sie arbeiten zu langsam.", "Sie arbeiten ohne Pause."]}, {"q": "Was darf man in Deutschland schon mit 14 Jahren machen?", "qZh": "在德国 14 岁就可以做什么？", "answer": "Zum Beispiel Zeitungen austragen.", "wrong": ["Eine Ausbildung anfangen.", "In der Nacht arbeiten."]}], "src": "改编自 Klexikon《Arbeit》", "url": "https://klexikon.zum.de/index.php?oldid=154207", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-003", "seg": 9, "title": "Arbeitslosigkeit", "de": ["Arbeitslosigkeit bedeutet, dass es zu wenig Arbeit gibt für Menschen, die arbeiten wollen. Das kann verschiedene Gründe haben. Nach dem Ersten Weltkrieg musste Deutschland beispielsweise für die Kriegsschäden aufkommen. Daher ging es der Wirtschaft schlecht und viele Menschen konnten keinen Job finden. Oder die Industrie setzt viele Maschinen ein und braucht dann weniger Menschen, die arbeiten. Vielleicht will auch jemand die Arbeitsstelle wechseln, weil ihm die Arbeit nicht gefällt oder weil sie zu schwer ist. Wenn er dann kündigt und keine neue Arbeitsstelle findet, ist er arbeitslos, zumindest für eine gewisse Zeit. Manchmal wird einem Mitarbeiter auch aus einem bestimmten Grund gekündigt, er verliert also dann seine Arbeit. Das kann zum Beispiel geschehen, wenn die Firma nicht mit seiner Arbeit zufrieden war, oder wenn die Firma Geld sparen muss oder will.", "Aber nicht jeder, der nicht arbeitet, ist ein Arbeitsloser. Nicht zu den Arbeitslosen zählen zum Beispiel Hausfrauen oder Hausmänner, schulpflichtige Kinder, Studenten und Rentner. Wer wegen seiner Gesundheit nicht arbeitet, ist krank. Er bekommt dann Lohn von seiner Arbeitsstelle. Kann jemand gar nicht arbeiten, weil er zum Beispiel einen schweren Unfall hatte oder schwer psychisch krank ist, dann ist er invalid.", "Wer Arbeit sucht und keine findet, kann sich in den meisten Ländern bei einem Arbeitslosenamt anmelden. Dort erhält man vom Staat Geld als Ersatz für den fehlenden Lohn. Wie lange man das Geld erhält, hängt vom Land ab, vom Alter des Arbeitslosen und davon, wie lange er vorher gearbeitet hat. In Deutschland und der Schweiz sind das etwa zwei Jahre.", "In schlechten Zeiten muss der Staat sehr viel Arbeitslosengeld bezahlen. Es ist auch für viele Arbeitslose sehr unangenehm, immer Geld vom Staat erhalten zu müssen. Deshalb will der Staat, dass es so wenig Arbeitslose wie möglich gibt. Der Staat kann mithelfen, dass es mehr Arbeitsstellen gibt oder die Arbeitslosen darin unterstützen, einen anderen Beruf zu erlernen.", "Weil Arbeitslose von Steuergeldern finanziert werden, haben sie in der Gesellschaft ein geringes Ansehen. Viele Menschen finden es nicht richtig, dass sie andere Leute fürs zu Hause bleiben bezahlen müssen, während sie selber für ihr Geld arbeiten gehen. Daher gibt es auch Länder in denen es kein oder nur ein sehr geringes Arbeitslosengeld gibt. Arbeitslose Menschen verarmen dann aber oft und haben Schwierigkeiten über die Runden zu kommen."], "zh": ["失业的意思是，想工作的人太多，工作太少。原因可能各不相同。比如第一次世界大战后，德国必须赔偿战争损失，所以经济很差，很多人找不到工作。又或者工业大量使用机器，需要的工人就少了。也可能有人想换工作，因为不喜欢原来的工作或者工作太累。如果他辞职后找不到新工作，就失业了，至少是一段时间。有时员工也会因为某种原因被解雇，也就是丢了工作。比如公司对他的工作不满意，或者公司必须或想要省钱时，就可能发生这种事。", "不过并不是每个不工作的人都是失业者。比如家庭主妇或家庭主夫、上学的孩子、大学生和退休的人都不算失业者。因为健康原因不工作的人是病了，他会从单位拿到工资。如果有人根本不能工作，比如出了严重事故或有严重的心理疾病，他就是丧失劳动能力的人。", "找工作却找不到的人，在大多数国家可以到失业办公室登记，从国家那里领钱，代替没有的工资。能领多久取决于国家、失业者的年龄以及他之前工作了多久。在德国和瑞士大约是两年。", "经济不好的时候，国家要付很多失业金。对很多失业者来说，总要靠国家的钱生活也很不舒服。所以国家希望失业者越少越好。国家可以帮助创造更多工作岗位，或者支持失业者学一门别的职业。", "因为失业者靠税款供养，他们在社会上的名声不太好。很多人觉得不公平：自己辛苦工作挣钱，却要出钱让别人待在家里。所以也有一些国家没有失业金，或者失业金很少。但这样失业的人常常会变穷，很难维持生活。"], "lemmas": [], "gloss": [{"w": "Kriegsschäden", "de": "was im Krieg kaputtgegangen ist", "zh": "战争损失"}, {"w": "schulpflichtige", "de": "die zur Schule gehen müssen", "zh": "有上学义务的"}, {"w": "invalid", "de": "wegen Krankheit oder Unfall nicht mehr arbeitsfähig", "zh": "丧失劳动能力的"}, {"w": "Arbeitslosenamt", "de": "Amt für Menschen ohne Arbeit", "zh": "失业办公室"}, {"w": "verarmen", "de": "arm werden", "zh": "变穷"}, {"w": "über die Runden zu kommen", "de": "mit wenig Geld gerade genug haben", "zh": "勉强维持生活"}], "qs": [{"q": "Wer zählt nicht zu den Arbeitslosen?", "qZh": "谁不算失业者？", "answer": "Rentner und Studenten.", "wrong": ["Menschen, die ihre Arbeit verloren haben.", "Menschen, die gekündigt haben und nichts finden."]}, {"q": "Was bekommt man beim Arbeitslosenamt?", "qZh": "在失业办公室能得到什么？", "answer": "Geld vom Staat als Ersatz für den Lohn.", "wrong": ["Eine Wohnung vom Staat.", "Sofort eine neue Arbeitsstelle."]}, {"q": "Warum haben Arbeitslose laut Text oft ein geringes Ansehen?", "qZh": "根据文章，失业者为什么名声不太好？", "answer": "Sie werden von Steuergeldern bezahlt.", "wrong": ["Sie wollen nie arbeiten.", "Sie sind meistens krank."]}], "src": "改编自 Klexikon《Arbeitslosigkeit》", "url": "https://klexikon.zum.de/index.php?oldid=154632", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-004", "seg": 9, "title": "Gewerkschaft", "de": ["Eine Gewerkschaft ist eine Organisation, die sich für Arbeitnehmer einsetzt. Arbeitnehmer sind Menschen, die für eine Firma arbeiten oder auch für einen Verein, eine Stadt oder eine Kirche. Für diese Arbeit bekommen sie Geld, den Lohn. Die Firma oder Organisation, die den Lohn bezahlt, nennt man Arbeitgeber.", "In einer Gewerkschaft schließen sich viele Arbeitnehmer zusammen. Gemeinsam können sie besser dafür sorgen, dass sie fair bezahlt werden oder dass sie nicht zu lange arbeiten müssen. Die Mitglieder einer Gewerkschaft zahlen meistens einen Mitgliedsbeitrag. Dafür bekommen sie zum Beispiel Beratung, wenn es Streit am Arbeitsplatz gibt.", "Die ersten Gewerkschaften sind vor allem im 19. Jahrhundert entstanden. Damals arbeiteten viele Menschen in Fabriken. Sie wurden oft schlecht bezahlt. Außerdem mussten sie sehr lange und hart arbeiten. Viele Arbeiter wollten das nicht mehr hinnehmen. Sie schlossen sich zusammen, um gemeinsam für bessere Arbeitsbedingungen zu kämpfen.", "Gewerkschaften sprechen mit den Arbeitgebern darüber, welche Bedingungen fair sind. Es geht dann zum Beispiel um mehr Lohn, mehr Urlaub oder weniger Arbeitszeit. Wenn sich beide Seiten einigen, gilt das oft für viele Beschäftigte, zum Beispiel in einem bestimmten Bereich der Industrie, bei Verkehrsunternehmen oder in einer großen Firma.", "Wenn solche Gespräche scheitern und nicht zu einer Einigung führen, kann es zu einem Streik kommen. Bei einem Streik arbeiten viele Arbeitnehmer eine Zeit lang nicht weiter. Dann kann zum Beispiel eine Fabrik nichts mehr produzieren oder Busse und Bahnen fahren nicht. So entsteht Druck auf die Arbeitgeber, weiter zu verhandeln.", "Manche Gewerkschaften bringen sich in der Politik ein und setzen sich dort für Gesetze ein, die Arbeitnehmer schützen sollen. Das kann zum Beispiel für einen gesetzlichen Mindestlohn sein. In Deutschland stehen die Gewerkschaften Parteien wie der SPD oder Der Linken nahe. Auch in anderen Ländern verbinden sie sich oft mit Parteien der Sozialdemokratie oder des Sozialismus."], "zh": ["工会是一个为雇员争取利益的组织。雇员是为公司、协会、城市或教会工作的人，他们为此拿到钱，也就是工资。支付工资的公司或组织叫雇主。", "很多雇员在工会里联合起来。大家一起更能争取到合理的报酬，或者不用工作太长时间。工会会员大多要交会费，作为回报，比如在工作中发生争执时可以得到咨询。", "最早的工会主要出现在 19 世纪。当时很多人在工厂工作，报酬常常很低，而且要工作很长时间、很辛苦。很多工人不想再忍受下去，就联合起来，一起争取更好的工作条件。", "工会和雇主商量什么样的条件是公平的，比如加工资、多放假或少工作时间。双方达成一致后，结果常常适用于很多员工，比如某个工业领域、交通企业或一家大公司的员工。", "如果谈判失败、达不成一致，就可能罢工。罢工时很多雇员一段时间不工作。这样工厂就什么都生产不了，或者公交和火车停运。这会给雇主施加压力，让他们继续谈判。", "有些工会也参与政治，为保护雇员的法律出力，比如争取法定最低工资。在德国，工会和社民党、左翼党等政党关系密切。在其他国家，工会也常和社会民主主义或社会主义政党联系在一起。"], "lemmas": [], "gloss": [{"w": "Mitgliedsbeitrag", "de": "Geld, das Mitglieder regelmäßig bezahlen", "zh": "会费"}, {"w": "Arbeitsbedingungen", "de": "wie man arbeitet: Zeit, Lohn, Ort", "zh": "工作条件"}, {"w": "Einigung", "de": "wenn beide Seiten dasselbe wollen", "zh": "达成一致"}, {"w": "Mindestlohn", "de": "der niedrigste Lohn, den man zahlen darf", "zh": "最低工资"}, {"w": "Beschäftigte", "de": "Menschen, die irgendwo arbeiten", "zh": "员工"}], "qs": [{"q": "Was bekommen Mitglieder einer Gewerkschaft für ihren Beitrag?", "qZh": "工会会员交了会费能得到什么？", "answer": "Beratung bei Streit am Arbeitsplatz.", "wrong": ["Einen höheren Lohn ohne Gespräche.", "Kostenlosen Urlaub."]}, {"q": "Warum entstanden im 19. Jahrhundert die ersten Gewerkschaften?", "qZh": "19 世纪为什么出现了最早的工会？", "answer": "Arbeiter in Fabriken wurden schlecht bezahlt und arbeiteten sehr lange.", "wrong": ["Es gab zu wenige Fabriken.", "Die Regierung wollte es so."]}, {"q": "Was passiert oft, wenn die Gespräche mit den Arbeitgebern scheitern?", "qZh": "和雇主谈判失败时常常会发生什么？", "answer": "Es kann zu einem Streik kommen.", "wrong": ["Die Gewerkschaft wird verboten.", "Alle Arbeitnehmer bekommen mehr Lohn."]}], "src": "改编自 Klexikon《Gewerkschaft》", "url": "https://klexikon.zum.de/index.php?oldid=165318", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-005", "seg": 9, "title": "Streik", "de": ["Bei einem Streik hört man auf zu arbeiten, weil einem etwas nicht gefällt. Meist geht es um große Gruppen von Arbeitern oder Angestellten. Sie wollen damit ein Ziel erreichen: Sie wollen besser bezahlt werden oder mehr Urlaub bekommen, oder die Arbeit soll weniger gefährlich gemacht werden.", "Damit richten sie sich an diejenigen, von denen sie bezahlt werden und die daran etwas ändern können. Diese Leute heißen Arbeitgeber, ihnen gehören Firmen oder Fabriken. Wenn nicht gearbeitet wird, wird auch nichts hergestellt, das man verkaufen kann. Dadurch verlieren die Arbeitgeber viel Geld. Allerdings geben sie meistens nicht nach, denn sonst kämen die Leute auf die Idee, öfter zu streiken.", "Manchmal gibt es Streik, der sich nicht gegen die Arbeitgeber richtet. Zum Beispiel 1920 in Berlin hat eine Gruppe von Soldaten geputscht und die deutsche Regierung verjagt. Daher haben die meisten Arbeiter in Deutschland die Arbeit niedergelegt. Sie zeigten damit, dass sie gegen die Gruppe waren. Streiken die meisten Menschen in einem Land, nennt man das einen Generalstreik.", "Wann darf gestreikt werden? Wer entscheidet darüber? Darf man beim Streik einfach nach Hause gehen? Bekommt man dann noch Lohn oder Gehalt? Wer bezahlt den Streik? Das alles sind wichtige Fragen, zu denen es zum Teil auch Gesetze gibt. Normalerweise ruft eine Gewerkschaft zum Streik auf. Das ist ein großer Verein von Arbeitern oder Angestellten, die eine ähnliche Arbeit haben."], "zh": ["罢工就是因为不满意某件事而停止工作，大多是一大群工人或职员一起。他们想借此达到一个目的：想拿更多工资、多放假，或者让工作不那么危险。", "罢工针对的是付他们工资、能改变现状的人，这些人叫雇主，公司或工厂归他们所有。不工作，就生产不出可以卖的东西，雇主就会损失很多钱。不过雇主大多不会让步，否则人们会想着更常罢工。", "有时罢工不是针对雇主的。比如 1920 年在柏林，一群士兵发动政变，赶走了德国政府。于是德国大多数工人放下了工作，以此表明他们反对这群人。一个国家大多数人都罢工，就叫总罢工。", "什么时候可以罢工？谁来决定？罢工时能直接回家吗？还能拿到工资吗？罢工的费用谁出？这些都是重要问题，有的还有相关法律。一般由工会号召罢工。工会是由从事相近工作的工人或职员组成的大团体。"], "lemmas": [], "gloss": [{"w": "geputscht", "de": "die Regierung mit Gewalt übernommen", "zh": "发动政变"}, {"w": "verjagt", "de": "weggejagt", "zh": "赶走"}, {"w": "niedergelegt", "de": "die Arbeit niederlegen: aufhören zu arbeiten", "zh": "放下（工作）"}, {"w": "Generalstreik", "de": "Streik von fast allen Menschen in einem Land", "zh": "总罢工"}], "qs": [{"q": "Was wollen Streikende oft erreichen?", "qZh": "罢工的人常常想达到什么？", "answer": "Mehr Lohn oder mehr Urlaub.", "wrong": ["Eine neue Regierung.", "Weniger Kunden."]}, {"q": "Warum geben Arbeitgeber laut Text meistens nicht nach?", "qZh": "根据文章，雇主为什么大多不让步？", "answer": "Sonst würden die Leute öfter streiken.", "wrong": ["Sie verlieren beim Streik kein Geld.", "Streiken ist verboten."]}, {"q": "Wer ruft normalerweise zum Streik auf?", "qZh": "通常由谁号召罢工？", "answer": "Eine Gewerkschaft.", "wrong": ["Der Arbeitgeber.", "Die Polizei."]}], "src": "改编自 Klexikon《Streik》", "url": "https://klexikon.zum.de/index.php?oldid=170435", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-006", "seg": 9, "title": "Ausbildung", "de": ["In einer Ausbildung lernt man etwas, damit man später einen Beruf ausüben kann. In Österreich und der Schweiz sagt man Lehre. Man lernt viele Dinge kennen, aber auch, wie man etwas macht. Die Ausbildung macht man normalerweise erst, nachdem man eine Schule besucht hat.", "Ein Beispiel für eine Ausbildung ist der Automechaniker. Automechaniker sind die Leute, die kaputte Autos reparieren. Wenn man eine Ausbildung zum Automechaniker macht, lernt man zum Beispiel, wie ein Motor funktioniert und übt auch, wie man einen kaputten Motor reparieren kann.", "Wenn jemand eine Ausbildung macht, wird er Auszubildender genannt. Das Wort wird oft abgekürzt zu Azubi. Während einer Ausbildung arbeiten die Azubis meistens drei Tage in der Woche in einer Firma, einer Werkstatt oder einem Geschäft und lernen, was man in dem Beruf können muss und welche Aufgaben man hat. Die Auszubildenden gehen auch noch in die Berufsschule, meistens zwei Tage in der Woche. In einer Berufsschule lernen sie andere Dinge, die für ihren Beruf wichtig sind.", "Eine Ausbildung dauert meistens drei Jahre. Am Ende der Ausbildungszeit müssen die Auszubildenden eine große Prüfung bestehen. Oft hat diese Prüfung zwei Teile, einen praktischen und einen theoretischen.", "Bei der praktischen Prüfung müssen die Auszubildenden zeigen, dass sie das, was sie in ihrem Beruf machen müssen, auch können. Die theoretische Prüfung an der Berufsschule ist so ähnlich wie eine Klassenarbeit in der Schule vorher. Aber sie dauert länger und handelt von mehr Themen. Die Auszubildenden müssen dazu wissen, was sie in den drei Jahren an der Berufsschule gelernt haben."], "zh": ["参加职业培训，是为了学会以后能从事一种职业。在奥地利和瑞士叫学徒（Lehre）。培训中会认识很多东西，也学怎么做事。一般在上完学之后才参加职业培训。", "汽车修理工就是一个职业培训的例子。汽车修理工是修理坏汽车的人。参加汽车修理工培训，比如会学发动机怎么工作，也练习怎样修理坏掉的发动机。", "参加职业培训的人叫受训者，常简称 Azubi。培训期间，学徒大多每周三天在公司、车间或商店里工作，学习这个职业要会什么、有哪些任务。他们还要去职业学校，大多每周两天，在那里学习对职业重要的其他东西。", "职业培训大多持续三年。培训结束时，学徒必须通过一场大考试。这场考试常分两部分：实践部分和理论部分。", "实践考试中，学徒要证明他们会做本职工作中要做的事。职业学校的理论考试和以前学校里的课堂测验差不多，只是时间更长、内容更多。学徒要掌握三年在职业学校学到的东西。"], "lemmas": [], "gloss": [{"w": "Auszubildender", "de": "jemand, der eine Ausbildung macht", "zh": "受训者、学徒"}, {"w": "abgekürzt", "de": "kürzer gemacht", "zh": "缩写"}, {"w": "Berufsschule", "de": "Schule für Menschen in einer Ausbildung", "zh": "职业学校"}, {"w": "theoretischen", "de": "um Wissen, nicht um Praxis", "zh": "理论的"}, {"w": "Klassenarbeit", "de": "Test in der Schule", "zh": "课堂测验"}], "qs": [{"q": "Wie heißt die Ausbildung in Österreich und der Schweiz?", "qZh": "在奥地利和瑞士职业培训叫什么？", "answer": "Lehre.", "wrong": ["Studium.", "Praktikum."]}, {"q": "Wo sind Azubis normalerweise zwei Tage in der Woche?", "qZh": "学徒通常每周有两天在哪里？", "answer": "In der Berufsschule.", "wrong": ["Zu Hause.", "An der Universität."]}, {"q": "Was müssen Azubis am Ende der Ausbildung machen?", "qZh": "学徒在培训结束时必须做什么？", "answer": "Eine große Prüfung bestehen.", "wrong": ["Eine eigene Firma gründen.", "Ein Jahr im Ausland arbeiten."]}], "src": "改编自 Klexikon《Ausbildung》", "url": "https://klexikon.zum.de/index.php?oldid=158341", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-007", "seg": 9, "title": "Beamter", "de": ["Ein Beamter ist jemand, der für den Staat arbeitet. Beamte haben besondere Rechte und Pflichten. Das Wort stammt von „Amt“, einer wichtigen Aufgabe für den Staat. Allerdings ist nicht jeder, der für den Staat arbeitet, Beamter.", "Schon früher wollten Herrscher, dass sie ihren wichtigsten Helfern vertrauen konnten. Solche Helfer wurden ihr Leben lang gut versorgt. So mussten die Helfer sich keine Sorgen machen, zu verhungern oder arm zu sein. Dafür verlangten die Herrscher gute und verlässliche Arbeit.", "Seit etwa dem Jahr 1800 gibt es Beamte in dem Sinne, wie wir sie heute kennen. Ein Beamter ist nicht dem Chef der Regierung verpflichtet, sondern dem Staat. Er soll ordentlich und genau arbeiten, zum Wohl aller Menschen im Land. Außerdem darf er niemanden bevorzugen, etwa weil das sein Freund ist oder er Geld von ihm bekommt. Beamte dürfen auch nicht streiken, wenn sie mit ihrer Arbeit nicht einverstanden sind.", "Beamte haben den Beamtenstatus, sie sind verbeamtet. Der Staat darf sie dann nicht so einfach entlassen, außer, wenn sie etwas Schlimmes gemacht haben. Wenn ein Beamter zu alt zum Arbeiten ist, sorgt der Staat immer noch für ihn. Das Geld im Alter nennt man nicht Rente, sondern Pension.", "Viele Menschen arbeiten im Öffentlichen Dienst, das heißt für den Staat, ein Bundesland oder eine Gemeinde. Meist sind sie einfach Angestellte, genau wie für ein Unternehmen. Beamte hingegen sind normalerweise Lehrer, Polizisten oder Richter.", "Manchmal streitet man sich darüber, wer Beamter sein soll und wer nicht. Als die Eisenbahn in Deutschland noch Teil des Staates war, waren die Mitarbeiter oft Beamte. Später wurde die Bahn ein Unternehmen und hat nun keine Beamten mehr. Viele Lehrer werden heutzutage nicht mehr verbeamtet. Das ist für den Öffentlichen Dienst billiger."], "zh": ["公务员是为国家工作的人。公务员有特殊的权利和义务。这个词来自 Amt，意思是为国家承担的一项重要任务。不过并不是每个为国家工作的人都是公务员。", "早在以前，统治者就希望能信任自己最重要的帮手。这些帮手一辈子都有很好的保障，不用担心挨饿或贫穷。作为交换，统治者要求他们工作出色、可靠。", "大约从 1800 年起，才有了我们今天所说的公务员。公务员效忠的不是政府首脑，而是国家。他要认真、准确地工作，为全国所有人谋福利。此外，他不能偏袒任何人，比如因为对方是朋友或者给了他钱。公务员即使不同意自己的工作安排，也不能罢工。", "公务员拥有公务员身份，也就是被授予了公务员编制。国家不能随便解雇他们，除非他们做了很严重的事。公务员老得不能工作时，国家仍然照顾他。这笔养老钱不叫 Rente，而叫 Pension。", "很多人在公共部门工作，也就是为联邦、州或乡镇工作。他们大多只是普通职员，和在企业工作一样。而公务员通常是教师、警察或法官。", "谁应该是公务员、谁不应该，有时会有争议。德国铁路还属于国家的时候，员工常常是公务员。后来铁路变成了企业，现在就没有公务员了。如今很多教师也不再被授予公务员身份，这对公共部门来说更省钱。"], "lemmas": [], "gloss": [{"w": "Herrscher", "de": "jemand, der über ein Land bestimmt, z. B. ein König", "zh": "统治者"}, {"w": "verlässliche", "de": "so, dass man sich darauf verlassen kann", "zh": "可靠的"}, {"w": "bevorzugen", "de": "jemanden besser behandeln als andere", "zh": "偏袒"}, {"w": "verbeamtet", "de": "zum Beamten gemacht", "zh": "被授予公务员身份"}, {"w": "Öffentlichen Dienst", "de": "Arbeit für Staat, Land oder Gemeinde", "zh": "公共部门"}], "qs": [{"q": "Was dürfen Beamte nicht tun?", "qZh": "公务员不能做什么？", "answer": "Streiken.", "wrong": ["Im Alter Geld bekommen.", "Für eine Gemeinde arbeiten."]}, {"q": "Wie heißt das Geld, das Beamte im Alter bekommen?", "qZh": "公务员老了领的钱叫什么？", "answer": "Pension.", "wrong": ["Rente.", "Lohn."]}, {"q": "Warum werden heute viele Lehrer nicht mehr verbeamtet?", "qZh": "为什么如今很多教师不再是公务员？", "answer": "Es ist für den Öffentlichen Dienst billiger.", "wrong": ["Lehrer wollen das nicht.", "Es gibt keine Schulen mehr vom Staat."]}], "src": "改编自 Klexikon《Beamter》", "url": "https://klexikon.zum.de/index.php?oldid=157530", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-008", "seg": 9, "title": "Verkäufer", "de": ["Verkäufer oder Verkäuferin ist ein Beruf, für den es eine Ausbildung in einem Betrieb braucht. Dazu muss man die Berufsschule besuchen. Am besten kennen wir den Verkäufer aus dem Supermarkt, meistens sind es allerdings Verkäuferinnen.", "Der Verkäufer hat viele Aufgaben: Er nimmt die Ware entgegen, kontrolliert sie und ordnet sie im Laden ein. Er berät die Kunden und tauscht auch mal Ware aus, die nicht in Ordnung ist oder die der Kunde nicht brauchen kann. Er bedient auch die Kasse und nimmt dort das Geld ein. Welche Aufgaben ein Verkäufer genau übernimmt, hängt sehr davon ab, ob der Betrieb Lebensmittel, Kleidung, Sportartikel, Uhren oder andere Produkte verkauft.", "In Deutschland gibt es zwei verschiedene Ausbildungen, die unterschiedlich lange dauern: Die Ausbildung zum Verkäufer dauert zwei Jahre. Wenn man die Ausbildung noch ein Jahr länger macht, kann man aber auch \"Kaufmann im Einzelhandel\" werden. Im dritten Jahr der Ausbildung lernt man zusätzlich zu den Verkaufstätigkeiten noch Dinge, die man im Büro erledigt: Man lernt, wie man richtig aufschreibt, was verkauft wurde und wie viel Geld man eingenommen hat. Man lernt auch, wie man Werbung für den Betrieb macht oder wie man Mitarbeiter einlernt und Aufgaben an sie verteilt.", "Dieser Beruf ist also allein schon in den deutschsprachigen Ländern ziemlich verschieden. Er liegt in der Nähe des Kaufmanns. Dessen Ausbildung ist jedoch schwieriger und dauert länger. Durch gezielte Fortbildungen kann sich jedoch ein Verkäufer zum Kaufmann hocharbeiten."], "zh": ["售货员是一种需要在企业里接受职业培训的职业，还要上职业学校。我们最熟悉的是超市里的售货员，而且大多是女售货员。", "售货员有很多任务：他接收货物、检查货物，并把货物在店里摆放好。他为顾客提供建议，也会给顾客换掉有问题或用不上的东西。他还负责收银台、收钱。售货员具体做哪些事，很大程度上取决于店里卖的是食品、衣服、体育用品、手表还是别的产品。", "在德国有两种长短不同的职业培训：售货员的培训是两年。如果再多培训一年，就可以成为「零售商务员」。培训第三年，除了销售工作，还要学办公室里的事：学会怎样正确记录卖出了什么、收了多少钱，也学怎样为店铺做广告，或怎样带新员工、给他们分配任务。", "可见光在德语国家，这个职业就相当不同。它和商务员很接近，不过商务员的培训更难、时间更长。但售货员可以通过有针对性的进修，逐步晋升为商务员。"], "lemmas": [], "gloss": [{"w": "Ware", "de": "Dinge, die man verkauft", "zh": "货物"}, {"w": "Einzelhandel", "de": "Geschäfte, die direkt an Kunden verkaufen", "zh": "零售"}, {"w": "einlernt", "de": "jemandem eine neue Arbeit zeigen", "zh": "带（新人）入门"}, {"w": "Fortbildungen", "de": "Kurse, in denen man im Beruf weiterlernt", "zh": "进修"}, {"w": "hocharbeiten", "de": "durch Arbeit eine bessere Stelle bekommen", "zh": "逐步晋升"}], "qs": [{"q": "Was gehört zu den Aufgaben eines Verkäufers?", "qZh": "售货员的任务包括什么？", "answer": "Er berät Kunden und bedient die Kasse.", "wrong": ["Er repariert Autos.", "Er schreibt Gesetze."]}, {"q": "Wie lange dauert die Ausbildung zum Verkäufer in Deutschland?", "qZh": "在德国售货员的培训需要多久？", "answer": "Zwei Jahre.", "wrong": ["Fünf Jahre.", "Ein halbes Jahr."]}, {"q": "Was lernt man im dritten Jahr zusätzlich?", "qZh": "第三年还要额外学什么？", "answer": "Arbeiten im Büro, zum Beispiel Werbung machen.", "wrong": ["Eine Fremdsprache.", "Wie man ein Geschäft baut."]}], "src": "改编自 Klexikon《Verkäufer》", "url": "https://klexikon.zum.de/index.php?oldid=155884", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-009", "seg": 9, "title": "Hausmeister", "de": ["Ein Hausmeister kümmert sich um ein Gebäude. Das Gebäude ist ein Haus, in dem man wohnt, ein Krankenhaus, eine Schule oder irgend ein anderes Gebäude. Es gibt noch einige andere Ausdrücke für einen Hausmeister oder eine Hausmeisterin: Hauswart oder Facility Manager, in Österreich Hausbesorger oder Hausbetreuer, in der Schweiz Hauswart oder Fachmann Betriebsunterhalt. Dafür gibt es eine Ausbildung. Wer diese Ausbildung noch verlängert, wird Hausmeister und ist dann Chef über mehrere Hauswarte.", "Hausmeister sind Angestellte, die für den Besitzer des Gebäudes arbeiten. Was ein Hausmeister können muss und was seine Aufgaben sind, das hängt vom Gebäude und vom Besitzer ab. Meistens soll ein Hausmeister dafür sorgen, dass es im Haus sauber ist und dass nichts beschädigt ist. Manchmal gehört auch noch die Pflege eines Gartens dazu. Ein guter Hausmeister kann viele kleine Dinge selber reparieren, sonst ruft er Fachleute an, die zum Beispiel eine Heizung, eine Lüftung oder einen Lift in Ordnung bringen.", "Für die Mieter im Haus ist es praktisch und einfach, wenn der Hausmeister sich um vieles kümmert. Allerdings: Je mehr Aufgaben ein Hausmeister hat, desto mehr Zeit braucht er und desto mehr muss man ihm zahlen. Das Geld für den Hausmeister bezahlen letzten Endes die Mieter gemeinsam.", "Manche Leute erwarten Leistungen von einem Hausmeister, die dieser gar nicht tun darf oder die nicht seine Aufgabe ist. So erwarten sie, dass er Streit zwischen Mietern schlichtet. Der Hausmeister kann und darf dabei aber nichts, was andere Menschen nicht auch dürfen. Als Hausmeister muss man es aber dem Besitzer oder der Polizei melden, wenn es große Probleme gibt."], "zh": ["楼管负责照看一栋建筑。这栋建筑可以是住宅楼、医院、学校或任何别的建筑。楼管（男女都有）还有一些别的叫法：Hauswart 或 Facility Manager，在奥地利叫 Hausbesorger 或 Hausbetreuer，在瑞士叫 Hauswart 或 Fachmann Betriebsunterhalt。这个职业有专门的培训。把培训再延长的人可以成为楼管主管，管理好几个楼管员。", "楼管是为楼房业主工作的雇员。楼管要会什么、任务是什么，取决于建筑和业主。大多数情况下，楼管要保证楼里干净、没有东西损坏。有时还要打理花园。好的楼管能自己修很多小东西，否则他就打电话叫专业人员，比如来修暖气、通风或电梯。", "对楼里的租户来说，楼管能管很多事很方便、很省心。不过楼管的任务越多，他需要的时间就越多，付给他的钱也越多。楼管的费用最终由租户们共同承担。", "有些人对楼管的期望，是楼管根本不能做或不属于他职责的事。比如他们希望楼管调解租户之间的纠纷。但楼管在这方面并没有比别人更多的权力。不过如果出了大问题，楼管必须报告给业主或警察。"], "lemmas": [], "gloss": [{"w": "Besitzer", "de": "jemand, dem etwas gehört", "zh": "业主、所有者"}, {"w": "beschädigt", "de": "kaputt gemacht", "zh": "损坏的"}, {"w": "Lüftung", "de": "Anlage, die frische Luft ins Haus bringt", "zh": "通风设备"}, {"w": "Mieter", "de": "jemand, der für eine Wohnung Miete bezahlt", "zh": "租户"}, {"w": "schlichtet", "de": "einen Streit beenden helfen", "zh": "调解"}], "qs": [{"q": "Für wen arbeitet ein Hausmeister?", "qZh": "楼管为谁工作？", "answer": "Für den Besitzer des Gebäudes.", "wrong": ["Für die Polizei.", "Für die Stadtverwaltung."]}, {"q": "Wer bezahlt am Ende den Hausmeister in einem Wohnhaus?", "qZh": "住宅楼的楼管费用最终由谁付？", "answer": "Die Mieter gemeinsam.", "wrong": ["Der Staat.", "Nur der Hausmeister selbst."]}, {"q": "Was muss ein Hausmeister bei großen Problemen tun?", "qZh": "出了大问题楼管必须做什么？", "answer": "Es dem Besitzer oder der Polizei melden.", "wrong": ["Den Streit allein vor Gericht lösen.", "Die Mieter aus dem Haus schicken."]}], "src": "改编自 Klexikon《Hausmeister》", "url": "https://klexikon.zum.de/index.php?oldid=162489", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-010", "seg": 9, "title": "Arzt", "de": ["Arzt oder Ärztin ist ein Beruf. Der Arzt hilft kranken Menschen und versucht, sie gesund zu machen. Es ist ein Beruf, für den man an der Universität lange das Fach Medizin studieren muss. Viele Ärzte können sich „Doktor“ nennen, wenn sie an der Universität auch die zusätzliche Prüfung dazu bestanden haben. Einen Doktor-Titel kann man auch in anderen Fächern bekommen, zum Beispiel in Geschichte, Philosophie, Physik oder Chemie.", "Ärzte können in einem Krankenhaus arbeiten, in dem sie Patienten versorgen, die meistens länger als nur wenige Minuten bleiben. Es gibt auch Ärzte, die eine eigene Praxis haben. Dort bleibt man meist nur kurz und nach der Behandlung geht man sofort wieder nach Hause. In sehr vielen Arztpraxen arbeitet ein Hausarzt. Er hat ein sehr breites aber weniger tiefes Wissen. Zu ihm geht man als kranker Mensch, also als Patient, meist zuerst. Wenn der Hausarzt nicht weiter weiß, kann er den Patienten dann zu einem Facharzt weiterschicken. Es gibt auch viele Kinderärzte, die eine Praxis haben.", "Der Hausarzt behandelt den Patienten soweit er es kann. Auch gesunde Menschen können zu ihm gehen, zum Beispiel, wenn man geimpft werden muss oder sich einfach mal abchecken will, ob man irgendwelche Krankheiten hat.", "Zuerst fragt der Arzt den Patienten, aus welchem Grund er zu ihm kommt. Dann untersucht er den Patienten, prüft, ob er krank ist und um welche Krankheit es sich handelt. Auch kann er vorsorglich helfen, das heißt, dafür sorgen, dass man gesund bleibt. Schließlich sagt der Arzt, was der Patient tun soll. Falls die Krankheit schwieriger ist, schickt er den Patienten in ein Krankenhaus oder zu einem Spezialisten.", "Manchmal braucht der Patient auch ein Medikament. Manche Ärzte geben es gleich selber mit, andere schicken den Patienten in eine Apotheke. Was der Patient braucht, schreibt der Arzt auf einen Zettel. Das nennt man ein Rezept."], "zh": ["医生是一种职业。医生帮助生病的人，努力让他们恢复健康。要当医生，必须在大学里长时间学习医学。很多医生如果在大学里还通过了额外的考试，就可以称自己为「博士」。博士头衔在别的学科也能拿到，比如历史、哲学、物理或化学。", "医生可以在医院工作，照顾那些大多不只待几分钟的病人。也有医生开自己的诊所，在那里一般只待很短时间，看完就马上回家。很多诊所里是家庭医生。家庭医生的知识面很广，但没那么深。生病的人，也就是病人，大多先去看家庭医生。如果家庭医生也没办法，可以把病人转给专科医生。也有很多开诊所的儿科医生。", "家庭医生尽自己所能给病人治疗。健康的人也可以去找他，比如需要打疫苗，或者只是想检查一下自己有没有什么病。", "医生先问病人为什么来看病，然后给病人检查，看他是否生病、得的是什么病。医生也可以做预防，也就是帮人保持健康。最后医生告诉病人该怎么做。如果病比较复杂，就把病人送到医院或转给专家。", "有时病人还需要药。有的医生直接把药给病人，有的让病人去药店。医生把病人需要的东西写在一张单子上，这叫处方。"], "lemmas": [], "gloss": [{"w": "Praxis", "de": "Räume, in denen ein Arzt Patienten behandelt", "zh": "诊所"}, {"w": "Facharzt", "de": "Arzt für ein besonderes Gebiet", "zh": "专科医生"}, {"w": "geimpft", "de": "gegen eine Krankheit geschützt durch eine Spritze", "zh": "打过疫苗的"}, {"w": "abchecken", "de": "prüfen lassen (Umgangssprache)", "zh": "检查一下"}, {"w": "vorsorglich", "de": "bevor etwas Schlimmes passiert", "zh": "预防性地"}, {"w": "Rezept", "de": "Zettel vom Arzt für ein Medikament", "zh": "处方"}], "qs": [{"q": "Zu wem geht man als Patient meistens zuerst?", "qZh": "病人大多先去找谁？", "answer": "Zum Hausarzt.", "wrong": ["Direkt ins Krankenhaus.", "Zur Apotheke."]}, {"q": "Warum gehen auch gesunde Menschen zum Hausarzt?", "qZh": "为什么健康的人也去看家庭医生？", "answer": "Zum Beispiel, um sich impfen zu lassen.", "wrong": ["Um ein Rezept für Freunde zu holen.", "Weil man das jede Woche muss."]}, {"q": "Was ist ein Rezept?", "qZh": "处方是什么？", "answer": "Ein Zettel, auf dem steht, welches Medikament man braucht.", "wrong": ["Eine Rechnung für den Arztbesuch.", "Eine Anleitung zum Kochen."]}], "src": "改编自 Klexikon《Arzt》", "url": "https://klexikon.zum.de/index.php?oldid=155864", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-011", "seg": 9, "title": "Anwalt", "de": ["Ein Anwalt oder Rechtsanwalt ist jemand, der sich mit dem Recht und mit Gesetzen gut auskennt. Sein Beruf ist es meistens, Menschen zu helfen, die Ärger vor Gericht haben. Die Menschen, denen er hilft, nennt man Mandanten.", "Wer vor einem Gericht verklagt wird, der braucht einen Anwalt zur Verteidigung. Der Anwalt darf vor Gericht sprechen und weiß, was man tun muss, damit man sich nicht unnötig noch mehr in Schwierigkeiten bringt.", "Manche Leute glauben: Verteidiger helfen Verbrechern dabei, vor Gericht die Unwahrheit zu sagen und nicht bestraft zu werden. Das ist aber nicht ganz richtig. Anwälte haben nämlich trotzdem die Aufgabe, dafür zu sorgen, dass Recht geschieht. Wenn ein Anwalt stattdessen den Kläger vertritt, nennt man ihn den Anwalt der Anklage.", "Oft hat jemand nichts mit dem Gericht zu tun, er will aber, dass ein Anwalt ihm gute Ratschläge gibt. Wenn ein Unternehmer mit einem anderen Unternehmer einen Vertrag abschließen will, geht es um viel Geld. Darum gibt der Unternehmer einem Anwalt den Auftrag, sich den Vertrag vorher gut anzuschauen. Der Anwalt soll ihn warnen, wenn etwas im Vertrag steht, das schlecht für ihn ist, das ihm Nachteile bringt.", "Ein Staatsanwalt ist ein besonderer Anwalt: Er vertritt den Staat. Wenn die Polizei jemanden verdächtigt, dann geht sie mit ihrem Verdacht zum Staatsanwalt. Der Staatsanwalt entscheidet dann, ob es genug Beweise gibt, vor Gericht anzuklagen. Der Staatsanwalt ist dann der Kläger vor Gericht."], "zh": ["律师是很懂法律和法规的人。他的工作大多是帮助在法庭上遇到麻烦的人。他帮助的人叫委托人。", "在法庭上被起诉的人，需要律师为自己辩护。律师可以在法庭上发言，也知道该怎么做，才不会让自己毫无必要地陷入更大的麻烦。", "有些人以为，辩护律师帮罪犯在法庭上说假话、逃避惩罚。但这不完全对。律师仍然有责任让正义得到伸张。如果律师代表的是原告，就叫控方律师。", "常常有人和法庭毫无关系，只是想请律师给些好建议。如果一个企业主要和另一个企业主签合同，涉及很多钱，他就会委托律师事先仔细看看合同。合同里如果有对他不利、会让他吃亏的内容，律师要提醒他。", "检察官是一种特殊的律师：他代表国家。警察怀疑某人时，会带着怀疑去找检察官。检察官决定证据是否足够在法庭上起诉。之后检察官就是法庭上的原告。"], "lemmas": [], "gloss": [{"w": "Mandanten", "de": "Menschen, denen ein Anwalt hilft", "zh": "委托人"}, {"w": "verklagt", "de": "vor Gericht gebracht", "zh": "被起诉"}, {"w": "Verteidigung", "de": "Hilfe für jemanden, der angeklagt ist", "zh": "辩护"}, {"w": "Kläger", "de": "jemand, der vor Gericht klagt", "zh": "原告"}, {"w": "verdächtigt", "de": "glaubt, dass jemand etwas Schlimmes getan hat", "zh": "怀疑"}, {"w": "Beweise", "de": "Dinge, die zeigen, dass etwas wahr ist", "zh": "证据"}], "qs": [{"q": "Wie nennt man die Menschen, denen ein Anwalt hilft?", "qZh": "律师帮助的人叫什么？", "answer": "Mandanten.", "wrong": ["Kläger.", "Staatsanwälte."]}, {"q": "Warum lässt ein Unternehmer einen Vertrag vom Anwalt prüfen?", "qZh": "企业主为什么让律师看合同？", "answer": "Der Anwalt soll ihn vor Nachteilen warnen.", "wrong": ["Der Anwalt muss den Vertrag unterschreiben.", "Verträge sind sonst verboten."]}, {"q": "Was entscheidet der Staatsanwalt?", "qZh": "检察官决定什么？", "answer": "Ob es genug Beweise gibt, um anzuklagen.", "wrong": ["Wie hoch die Strafe ist.", "Welcher Anwalt den Fall bekommt."]}], "src": "改编自 Klexikon《Anwalt》", "url": "https://klexikon.zum.de/index.php?oldid=158170", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-012", "seg": 9, "title": "Polizist", "de": ["Polizist ist ein Beruf. Für die Polizei werden Polizisten vom Staat, vom Bundesland, von einem Kanton oder von einer Gemeinde angestellt. Ihre Hauptaufgabe ist es, die Menschen zu beschützen und für Ordnung und Sicherheit zu sorgen. Man kann auch sagen: Sie passen auf, ob jemand etwas macht, das verboten ist. Andernfalls greifen sie ein mit Zurechtweisungen, Bußen oder einer Meldung an ein Gericht.", "Vor der Ausbildung zum Polizisten braucht es einen Beruf, ein Abitur oder eine ähnliche Vorbildung, dann geht es zu verschiedenen Eignungstests. Wer in der Ausbildung ist, muss die Gesetze gut kennen und wissen, was jemand machen darf oder nicht. Er muss aber auch selber lernen, wie er handeln soll, wenn etwas nicht stimmt.", "Ein Polizist braucht einen Führerschein und er muss mit einer Pistole, mit Funkgeräten und anderen Geräten umgehen können. Zudem müssen Polizisten sportlich sein, da sie in gefährlichen Situationen schnell und richtig handeln müssen. Wichtig ist auch, dass sie gut mit ihren Kollegen zusammenarbeiten können.", "Nach der Grundausbildung leisten die Polizisten meist Dienst in einem Streifenwagen oder sie regeln den Verkehr auf einer Strasse. Auch auf Polizeiposten oder als Begleiter von schwierigen Transporten trifft man sie an. Sie schützen auch besondere Orte oder gefährdete Menschen wie zum Beispiel die wichtigsten Politiker.", "Viele Polizisten lassen sich auch für bestimmte Aufgaben ausbilden: Detektive ermitteln Verbrecher anhand von Spuren am Tatort. Schulpolizisten zeigen den Kindern, wie man sich sicher im Straßenverkehr bewegt. Einige spezialisieren sich auf die Arbeit rund um Drogen. Andere werden Chef einer Abteilung und so weiter."], "zh": ["警察是一种职业。警察由国家、联邦州、州（瑞士）或乡镇雇用，进入警察部门工作。他们的主要任务是保护人们，维护秩序和安全。也可以说：他们留意有没有人做违法的事。否则他们就会介入，进行训诫、罚款或向法院报告。", "参加警察培训之前，需要有一门职业、高中毕业证或类似的学历，然后要通过各种能力测试。受训的人必须熟悉法律，知道什么能做、什么不能做。他也必须学会出了问题时自己该怎么行动。", "警察需要驾照，还必须会用手枪、对讲机和其他设备。此外警察必须身体好，因为在危险情况下要迅速、正确地行动。和同事好好合作也很重要。", "基础培训后，警察大多在巡逻车上值勤，或在街上指挥交通。在警察岗亭里、或护送难度大的运输时也能见到他们。他们还保护特殊地点或有危险的人，比如最重要的政治家。", "很多警察还接受专门任务的培训：侦探根据犯罪现场的痕迹追查罪犯。学校警察教孩子们怎样在道路交通中保证安全。有些人专门负责和毒品有关的工作。还有人成为某个部门的负责人，等等。"], "lemmas": [], "gloss": [{"w": "Zurechtweisungen", "de": "Worte, mit denen man jemandem sagt, dass er etwas falsch macht", "zh": "训诫"}, {"w": "Bußen", "de": "Geld, das man als Strafe zahlt (Schweiz)", "zh": "罚款"}, {"w": "Eignungstests", "de": "Tests, ob man für etwas passt", "zh": "能力测试"}, {"w": "Funkgeräten", "de": "Geräte, mit denen man ohne Telefon sprechen kann", "zh": "对讲机"}, {"w": "Streifenwagen", "de": "Auto der Polizei", "zh": "巡逻车"}, {"w": "Tatort", "de": "Ort, an dem ein Verbrechen passiert ist", "zh": "犯罪现场"}], "qs": [{"q": "Was ist die Hauptaufgabe von Polizisten?", "qZh": "警察的主要任务是什么？", "answer": "Menschen schützen und für Ordnung sorgen.", "wrong": ["Gesetze schreiben.", "Steuern einsammeln."]}, {"q": "Warum müssen Polizisten sportlich sein?", "qZh": "警察为什么必须身体好？", "answer": "Sie müssen in gefährlichen Situationen schnell handeln.", "wrong": ["Sie müssen jeden Tag Fußball spielen.", "Sie dürfen kein Auto fahren."]}, {"q": "Was machen Schulpolizisten?", "qZh": "学校警察做什么？", "answer": "Sie zeigen Kindern, wie man sicher im Verkehr ist.", "wrong": ["Sie unterrichten Mathematik.", "Sie suchen Drogen in Schulen."]}], "src": "改编自 Klexikon《Polizist》", "url": "https://klexikon.zum.de/index.php?oldid=160655", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-013", "seg": 9, "title": "Krankenpfleger", "de": ["Krankenpfleger und Krankenschwestern pflegen und behandeln verletzte, kranke oder behinderte Menschen. Es ist ein Beruf, für den man eine Ausbildung benötigt. Heute gibt es dafür modernere Namen: Man spricht von Pflegefachmännern und Pflegefachfrauen. Zusammen nennt man sie auch Pflegefachpersonen oder Pflegekräfte.", "Krankenpfleger arbeiten meist in Krankenhäusern oder Pflegeheimen, manchmal fahren sie auch zu kranken Menschen nach Hause. Die kranken Menschen nennt man auch Patienten.", "Krankenpfleger arbeiten oft im Schichtdienst, das heißt: Sie müssen auch in der Nacht arbeiten. Sie müssen auch an Feiertagen oder an Wochenenden arbeiten. Dafür haben sie dann an anderen Tagen frei.", "Überall mangelt es an Pflegekräften, denn Menschen leben immer länger und brauchen, wenn sie alt sind, eine gute Pflege. Das heißt oft, dass Krankenpfleger viel arbeiten müssen, weil Personal fehlt. Viele Krankenpfleger fühlen sich überlastet, weil sie hart arbeiten müssen, nicht so viel Geld verdienen und viele Überstunden leisten müssen. Der Beruf ist aber sehr wichtig, weil Patienten gut versorgt werden müssen. Politiker überlegen deshalb, wie man mehr Frauen und Männer überzeugen kann, den Beruf zu erlernen.", "Krankenpfleger erfüllen viele verschiedene Aufgaben. Sie arbeiten dazu eng mit Ärzten und Therapeuten zusammen. Sie helfen den Ärzten bei ihrer Arbeit, indem sie Aufgaben durchführen, die sie von ihnen bekommen. Sie verabreichen den Patienten Medikamente, oft auch durch Spritzen. Sie legen ihnen Verbände an oder bereiten sie auf eine Operation vor. In einigen Ländern dürfen Krankenpfleger den Patienten auch Blut abnehmen.", "Sie helfen den Patienten aber auch bei ganz alltäglichen Dingen wie essen, waschen oder anziehen, wenn sie wegen ihrer Erkrankung Hilfe dabei brauchen. Krankenpfleger kennen sich auch mit medizinischen Maschinen aus und überwachen diese. Sie messen wichtige Daten wie Puls, Blutdruck oder Temperatur und beobachten den Zustand der Patienten. Diese Informationen und alles, was sie beim Patienten gemacht haben, schreiben sie genau auf. So wissen alle Pfleger und Ärzte immer genau Bescheid."], "zh": ["男护士和女护士护理和治疗受伤、生病或残疾的人。这个职业需要接受职业培训。如今有更现代的叫法：护理专业人员（男/女），统称护理人员。", "护士大多在医院或养老院工作，有时也上门去照顾病人。生病的人也叫病人。", "护士常常倒班，也就是说他们晚上也要工作，节假日和周末也要上班。作为补偿，他们在其他日子休息。", "到处都缺护理人员，因为人们越活越久，老了需要好的护理。这常常意味着因为人手不够，护士要做很多工作。很多护士感到负担过重，因为工作辛苦、挣得不多，还要加很多班。但这个职业非常重要，因为病人必须得到好的照顾。所以政治家们在想办法，怎样说服更多男女来学这门职业。", "护士承担很多不同的任务，为此他们和医生、治疗师紧密合作。他们执行医生交给的任务，协助医生工作。他们给病人用药，常常通过打针；给病人包扎，或为手术做准备。在一些国家护士还可以给病人抽血。", "如果病人因为生病需要帮助，护士也帮他们做吃饭、洗漱、穿衣这些日常小事。护士也懂医疗设备，并负责监控。他们测量脉搏、血压、体温等重要数据，观察病人的状况。这些信息以及他们给病人做过的一切，都要详细记录下来。这样所有护理人员和医生都随时清楚情况。"], "lemmas": [], "gloss": [{"w": "Pflegeheimen", "de": "Häuser, in denen alte oder kranke Menschen gepflegt werden", "zh": "养老院、护理院"}, {"w": "Schichtdienst", "de": "Arbeit zu wechselnden Zeiten, auch nachts", "zh": "倒班"}, {"w": "überlastet", "de": "hat zu viel Arbeit", "zh": "负担过重"}, {"w": "Überstunden", "de": "Stunden, die man mehr arbeitet als geplant", "zh": "加班"}, {"w": "verabreichen", "de": "jemandem ein Medikament geben", "zh": "给（药）"}, {"w": "Verbände", "de": "Stoff, den man um eine Wunde macht", "zh": "绷带"}], "qs": [{"q": "Was bedeutet Schichtdienst für Krankenpfleger?", "qZh": "倒班对护士意味着什么？", "answer": "Sie müssen auch nachts und am Wochenende arbeiten.", "wrong": ["Sie arbeiten nur vormittags.", "Sie arbeiten nur zu Hause."]}, {"q": "Warum fehlen überall Pflegekräfte?", "qZh": "为什么到处都缺护理人员？", "answer": "Die Menschen leben länger und brauchen im Alter Pflege.", "wrong": ["Es gibt keine Ausbildung mehr.", "Krankenhäuser werden geschlossen."]}, {"q": "Warum schreiben Krankenpfleger alles genau auf?", "qZh": "护士为什么要把一切记录下来？", "answer": "Damit alle Pfleger und Ärzte Bescheid wissen.", "wrong": ["Weil die Patienten es lesen wollen.", "Um ein Buch zu schreiben."]}], "src": "改编自 Klexikon《Krankenpfleger》", "url": "https://klexikon.zum.de/index.php?oldid=162756", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-014", "seg": 9, "title": "Erzieher", "de": ["Erzieherinnen und Erzieher haben die Aufgabe, auf Kinder und Jugendliche aufzupassen, sie zu erziehen und ihnen etwas beizubringen.", "Die meisten Erzieher arbeiten in Kindertagesstätten. Das sind Einrichtungen für Kinder, die noch nicht in die Schule gehen und in Gruppen betreut werden. Abgekürzt nennt man sie Kitas. Ein Kindergarten ist auch eine Kita. Erzieher können aber auch in Schulen oder Horten arbeiten.", "Manchmal arbeiten Erzieherinnen auch mit Erwachsenen und helfen zum Beispiel Familien, die besondere Schwierigkeiten haben. Oder sie arbeiten mit Menschen mit Behinderung und arbeiten in Heimen oder Beratungsstellen.", "Fast alle Erzieher sind Frauen. In Deutschland gibt es zum Beispiel etwa 420.000 Erzieherinnen und 22.000 Erzieher.", "Um ein Erzieher zu werden, muss man eine Ausbildung machen. Jeder Staat und jedes Bundesland hat eigene Regeln, wie man Erzieher werden kann. Man braucht mindestens einen mittleren Schulabschluss, manchmal auch die Fachhochschulreife oder Abitur. Die Ausbildung dauert drei bis fünf Jahre. Man muss eine Berufsschule besuchen und Praktika in verschiedenen Einrichtungen machen. Das heißt, man arbeitet zwischen den Schultagen immer wieder mit Kindern oder Jugendlichen. Man probiert dann das aus, was man in der Schule gelernt hat.", "In der Schule lernt eine Erzieherin, was Kinder brauchen, um sich auch außerhalb der Familie wohl zu fühlen. Sie lernt, wie man Kinder unterstützen kann, damit sie mit anderen Kindern der Gruppe gut zurechtkommen, wie man Konflikte löst oder mit verschiedenen Gefühlen umgeht. Erzieher wissen auch, wie sich Kinder entwickeln, zum Beispiel wie und wann sie sprechen oder laufen lernen."], "zh": ["幼教老师的任务是照看儿童和青少年，教育他们，教他们东西。", "大多数幼教老师在日托机构工作。日托机构是照顾还没上学的孩子的地方，孩子们分组受到照看，简称 Kita。幼儿园也是一种 Kita。不过幼教老师也可以在学校或课后托管班工作。", "有时幼教老师也和成年人打交道，比如帮助有特殊困难的家庭。或者她们和残疾人一起工作，在福利院或咨询机构上班。", "几乎所有幼教老师都是女性。比如在德国大约有 42 万名女幼教老师，男幼教老师只有 2.2 万名。", "要当幼教老师必须接受职业培训。每个国家、每个联邦州都有自己的规定。至少需要初中毕业证书，有时还需要专科高中毕业或高中毕业证书。培训持续三到五年，要上职业学校，还要在不同机构实习。也就是说，在上学的日子之间，会不断和儿童或青少年一起工作，把在学校学到的东西实际试一试。", "在学校里，幼教老师学习孩子在家庭以外感到自在需要什么；学习怎样支持孩子和组里的其他孩子好好相处，怎样解决冲突，怎样面对各种情绪。幼教老师也知道孩子是怎样成长的，比如什么时候、怎样学会说话或走路。"], "lemmas": [], "gloss": [{"w": "Kindertagesstätten", "de": "Einrichtungen, in denen kleine Kinder tagsüber betreut werden", "zh": "日托机构"}, {"w": "Horten", "de": "Orte, wo Schulkinder nach der Schule betreut werden", "zh": "课后托管班"}, {"w": "Beratungsstellen", "de": "Orte, wo man Rat und Hilfe bekommt", "zh": "咨询机构"}, {"w": "Praktika", "de": "kurze Zeit, in der man in einem Betrieb mitarbeitet und lernt", "zh": "实习"}, {"w": "zurechtkommen", "de": "gut mit etwas klarkommen", "zh": "相处好、应付得来"}], "qs": [{"q": "Wo arbeiten die meisten Erzieher?", "qZh": "大多数幼教老师在哪里工作？", "answer": "In Kitas.", "wrong": ["In Krankenhäusern.", "In Fabriken."]}, {"q": "Wie lange dauert die Ausbildung zum Erzieher?", "qZh": "幼教老师的培训需要多久？", "answer": "Drei bis fünf Jahre.", "wrong": ["Ein Jahr.", "Zehn Jahre."]}, {"q": "Was lernt eine Erzieherin zum Beispiel in der Schule?", "qZh": "幼教老师在学校里学什么？", "answer": "Wie man Konflikte zwischen Kindern löst.", "wrong": ["Wie man ein Auto repariert.", "Wie man Häuser baut."]}], "src": "改编自 Klexikon《Erzieher》", "url": "https://klexikon.zum.de/index.php?oldid=157753", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-015", "seg": 9, "title": "Landwirt", "de": ["Landwirt ist ein Beruf, den man auch Bauer nennt. Landwirte arbeiten in der Landwirtschaft und stellen etwas her, das die Menschen essen oder anders nutzen können. Farmer ist ein englischer Ausdruck für den Landwirt, vor allem für einen, der Tiere züchtet.", "Landwirte müssen immer noch lang am Tag arbeiten. Die Arbeit ist allerdings nicht mehr ganz so schwer wie früher, weil es heute Maschinen gibt. Darum müssen Landwirte sich gut mit Technik auskennen, damit sie die Maschinen bedienen und manchmal reparieren können.", "In der Landwirtschaft werden Tiere gezüchtet und Pflanzen angebaut. Landwirte kennen sich deshalb auch mit der Biologie aus. Außerdem ist ein Landwirt letztlich ein Kaufmann. Es geht darum, die Erzeugnisse wie Milch, Fleisch oder Getreide zu verkaufen. Landwirte müssen deshalb gut rechnen können.", "Wer Landwirt werden will, muss eine Landwirtschaftsschule besuchen. Oft ist das eine Berufsschule. Neben der Schule arbeitet man auch in einem Betrieb, damit man das, was man gelernt hat, üben kann. In Deutschland dauert die Ausbildung drei Jahre. Man kann allerdings auch Landwirtschaft an einer Universität studieren.", "Viele Landwirte machen sich Sorgen um ihre Arbeit. Mit den Erzeugnissen kann man nicht mehr so gut Geld verdienen wie früher, darum haben schon viele Landwirte den Bauernhof aufgegeben. Der Staat hilft manchmal mit Geld, denn Landwirte stellen nicht nur Erzeugnisse her, sie erhalten auch die Landschaft."], "zh": ["农民是一种职业，也叫 Bauer。农民从事农业，生产人们可以吃或以其他方式使用的东西。Farmer 是农民的英语说法，尤其指养动物的农民。", "农民至今每天仍要工作很长时间。不过因为现在有机器，工作已不像以前那么辛苦。所以农民必须很懂技术，才能操作机器，有时还要修理。", "农业里要饲养动物、种植植物，所以农民也懂生物学。此外，农民说到底也是商人：要把牛奶、肉、粮食这些产品卖出去，所以农民必须很会算账。", "想当农民必须上农业学校，这常常是一所职业学校。上学的同时还要在农场工作，练习学到的东西。在德国，培训需要三年。也可以在大学里学农学。", "很多农民为自己的工作担忧。靠农产品不再像以前那样好挣钱，所以已经有很多农民放弃了农场。国家有时会出钱帮忙，因为农民不只是生产农产品，他们还维护着乡村的景观。"], "lemmas": [], "gloss": [{"w": "züchtet", "de": "Tiere halten und vermehren", "zh": "饲养、培育"}, {"w": "angebaut", "de": "Pflanzen auf dem Feld wachsen lassen", "zh": "种植"}, {"w": "Erzeugnisse", "de": "Dinge, die man herstellt", "zh": "产品"}, {"w": "Getreide", "de": "Pflanzen wie Weizen oder Roggen", "zh": "粮食、谷物"}, {"w": "Bauernhof", "de": "Haus und Land eines Bauern", "zh": "农场"}], "qs": [{"q": "Warum müssen Landwirte sich mit Technik auskennen?", "qZh": "农民为什么必须懂技术？", "answer": "Sie müssen Maschinen bedienen und reparieren.", "wrong": ["Sie verkaufen Computer.", "Sie bauen Autos."]}, {"q": "Warum müssen Landwirte gut rechnen können?", "qZh": "农民为什么必须很会算账？", "answer": "Sie verkaufen ihre Erzeugnisse wie ein Kaufmann.", "wrong": ["Sie unterrichten Mathematik.", "Sie arbeiten in einer Bank."]}, {"q": "Warum hilft der Staat Landwirten manchmal mit Geld?", "qZh": "国家为什么有时出钱帮助农民？", "answer": "Sie erhalten auch die Landschaft.", "wrong": ["Sie bezahlen keine Steuern.", "Sie arbeiten nur im Winter."]}], "src": "改编自 Klexikon《Landwirt》", "url": "https://klexikon.zum.de/index.php?oldid=157129", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-016", "seg": 9, "title": "Handwerk", "de": ["Das Handwerk ist ein Teil der Wirtschaft. Damit meint man bestimmte Berufe. Man übt sie in einem eher kleinen Betrieb aus, der oft dem Handwerker selbst gehört. Handwerker stellen meist etwas her oder helfen bei etwas, weil ein Kunde es kurz vorher bestellt hat. Große Fabriken hingegen stellen große Mengen von etwas her, weil sie hoffen, dass viele Kunden die Waren kaufen wollen.", "Bekannte Handwerksberufe sind zum Beispiel Schmied, Schlosser, Schneider, Tischler oder Bäcker. Solche Berufe sind oft schon sehr alt. Was genau ein Handwerk ist und was ein sonstiger Beruf, ist aber nicht immer ganz klar. Viele Leute haben ein Handwerk gelernt, arbeiten aber in einer großen Fabrik.", "Früher haben Handwerker sich in Zünften zusammengeschlossen. Eine Zunft gab es dann für einen bestimmten Beruf, wie Bäcker. Die Zunft bestimmte, wie viele Bäcker es in der Stadt geben durfte, damit jeder Bäcker noch genug Kunden hatte. In den Jahren nach 1800 haben viele Staaten allerdings beschlossen, dass es Gewerbefreiheit geben soll. Demnach darf jeder einen Beruf lernen und ausüben, den er will.", "Trotzdem gibt es auch heute noch Grenzen. Handwerkskammern legen fest, welche Regeln es für bestimmte Berufe geben soll, die Handwerksberufe. So soll dafür gesorgt werden, dass die Handwerker ihren Beruf gut lernen. Manchmal gibt es Streit darüber, welcher Beruf ein Handwerk sein soll und welcher nicht. Zurzeit sind es etwa vierzig."], "zh": ["手工业是经济的一部分，指的是某些职业。这些职业一般在比较小的企业里从事，企业常常归手工业者自己所有。手工业者大多是因为顾客刚刚订了货，才去做某样东西或帮忙做某件事。大工厂则大批量生产，希望会有很多顾客来买这些货。", "有名的手工业职业比如铁匠、钳工、裁缝、木匠或面包师。这些职业常常很古老。不过什么算手工业、什么算其他职业，并不总是很清楚。很多人学的是手工业，却在大工厂里工作。", "以前手工业者结成行会。一个行会对应一种职业，比如面包师。行会规定城里可以有多少个面包师，好让每个面包师都有足够的顾客。不过在 1800 年之后的几年里，很多国家决定实行营业自由，从此人人都可以学习和从事自己想做的职业。", "不过今天仍有限制。手工业协会规定某些职业，也就是手工业职业，要遵守哪些规则，以保证手工业者把本行学好。有时人们会争论哪些职业算手工业、哪些不算。目前大约有四十种。"], "lemmas": [], "gloss": [{"w": "Schlosser", "de": "Handwerker, der mit Metall arbeitet", "zh": "钳工"}, {"w": "Tischler", "de": "Handwerker, der Möbel aus Holz macht", "zh": "木匠"}, {"w": "Zünften", "de": "alte Vereine von Handwerkern", "zh": "行会"}, {"w": "Gewerbefreiheit", "de": "Recht, jeden Beruf auszuüben", "zh": "营业自由"}, {"w": "Handwerkskammern", "de": "Organisationen der Handwerker", "zh": "手工业协会"}], "qs": [{"q": "Was ist der Unterschied zwischen Handwerker und Fabrik?", "qZh": "手工业者和工厂有什么区别？", "answer": "Handwerker machen meist etwas, das ein Kunde bestellt hat.", "wrong": ["Handwerker arbeiten nur nachts.", "Fabriken stellen nur kleine Mengen her."]}, {"q": "Was bestimmte früher eine Zunft?", "qZh": "以前行会规定什么？", "answer": "Wie viele Bäcker es in einer Stadt geben durfte.", "wrong": ["Wie viel Brot jeder essen darf.", "Wer König wird."]}, {"q": "Wie viele Handwerksberufe gibt es zurzeit ungefähr?", "qZh": "目前大约有多少种手工业职业？", "answer": "Etwa vierzig.", "wrong": ["Etwa vier.", "Etwa vierhundert."]}], "src": "改编自 Klexikon《Handwerk》", "url": "https://klexikon.zum.de/index.php?oldid=152782", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-017", "seg": 9, "title": "Gärtner", "de": ["Gärtner ist ein Beruf, in dem man vor allem mit verschiedenen Pflanzen zu tun hat. Gärtner bauen Pflanzen an und pflegen sie. Sie wissen, wie man Pflanzen züchtet und vermehrt, auf welchem Boden sie am besten wachsen und welche Nährstoffe sie dazu brauchen. Sie wissen auch, welches Licht und wie viel Wasser Pflanzen benötigen.", "Wichtig ist auch, dass Gärtner Krankheiten an Pflanzen erkennen und dann mit einem geeigneten Mittel helfen. Manche Gärtner verkaufen auch Pflanzen. Dann informieren und beraten sie Menschen, die sich weniger gut mit Pflanzen auskennen.", "Der Beruf ist körperlich anstrengend. Gärtner arbeiten viel im Freien oder im Gewächshaus. Sie benötigen unempfindliche Kleidung, da sie viel mit Erde und Wasser umgehen. Sie müssen sich viel bücken und auch schwere Säcke oder Kisten tragen. Oft benutzen sie Werkzeuge wie eine Schaufel oder Scheren.", "Wer Gärtner werden möchte, braucht keinen bestimmten Schulabschluss. Die meisten Auszubildenden haben aber einen mittleren Schulabschluss, sie haben also 10 Jahre Schule hinter sich. Ein Gärtner sollte sich für die Naturwissenschaften wie Biologie und Chemie interessieren. Auch Mathematik ist wichtig, denn oft müssen Gärtner berechnen, wie viel Erde man braucht oder wie viele Pflanzen auf eine bestimmte Fläche passen. Sie sollten auch gerne handwerklich arbeiten und kreativ sein, das heißt, sich selbst etwas ausdenken können."], "zh": ["园丁是主要和各种植物打交道的职业。园丁种植和养护植物。他们知道怎样培育和繁殖植物，植物在哪种土壤里长得最好，需要哪些养分。他们也知道植物需要怎样的光照和多少水。", "园丁还要能认出植物的病，并用合适的药剂去治。有些园丁也卖植物，这时他们会给不太懂植物的人介绍和建议。", "这份工作很耗体力。园丁常在户外或温室里工作。他们需要耐脏的衣服，因为常和泥土、水打交道。他们要经常弯腰，还要搬沉重的袋子或箱子，常用铁锹、剪刀这类工具。", "想当园丁不需要特定的毕业证书，不过大多数学徒有初中毕业证书，也就是上过 10 年学。园丁应该对生物、化学这些自然科学感兴趣。数学也很重要，因为园丁常常要算需要多少土、一块地能种多少棵植物。他们还应该喜欢动手、有创造力，也就是能自己想出点子。"], "lemmas": [], "gloss": [{"w": "vermehrt", "de": "mehr werden lassen", "zh": "繁殖"}, {"w": "Nährstoffe", "de": "Stoffe, die Pflanzen oder Menschen zum Wachsen brauchen", "zh": "养分"}, {"w": "Gewächshaus", "de": "Haus aus Glas für Pflanzen", "zh": "温室"}, {"w": "unempfindliche", "de": "die nicht schnell kaputt oder schmutzig geht", "zh": "耐用的、耐脏的"}, {"w": "bücken", "de": "den Oberkörper nach unten beugen", "zh": "弯腰"}], "qs": [{"q": "Was wissen Gärtner über Pflanzen?", "qZh": "园丁对植物了解什么？", "answer": "Welcher Boden, welches Licht und wie viel Wasser sie brauchen.", "wrong": ["Wie man Pflanzen malt.", "Wie man Pflanzen in Fabriken baut."]}, {"q": "Warum ist der Beruf körperlich anstrengend?", "qZh": "这份工作为什么耗体力？", "answer": "Man muss sich viel bücken und Schweres tragen.", "wrong": ["Man muss viel am Computer sitzen.", "Man muss jeden Tag weit fliegen."]}, {"q": "Wofür brauchen Gärtner Mathematik?", "qZh": "园丁为什么需要数学？", "answer": "Um zu berechnen, wie viel Erde man braucht.", "wrong": ["Um Steuern zu berechnen.", "Um Lieder zu schreiben."]}], "src": "改编自 Klexikon《Gärtner》", "url": "https://klexikon.zum.de/index.php?oldid=160623", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-018", "seg": 9, "title": "Trainer", "de": ["Ein Trainer ist jemand, der sich um Sportler kümmert. Er bringt den Sportlern bei, was man für den Sport können muss. Außerdem begleiten Trainer die Sportler zu Wettkämpfen. Manche Trainer sind für Gruppen oder Mannschaften da, andere betreuen einen einzelnen Sportler. Andere wiederum arbeiten in einem Fitness-Studio und helfen den Besuchern.", "Wer einen Beruf haben will, der mit Sport zu tun hat, der lernt wohl zuerst vieles in einem Sportverein. Das finden die Vereine gut, manche bieten auch Ausbildungen dafür an. In so einer Ausbildung lernt man viel über Sport allgemein, zum Beispiel, wie man richtig Sport treibt, ohne sich zu verletzen. Außerdem lernt man etwas zu einer bestimmten Sportart oder wie man anderen Sportlern etwas beibringt. Man kann auch an einer Hochschule wie einer Universität das Fach Sport studieren.", "Am Ende einer Ausbildung erhält man ein Zeugnis. Damit kann man sich für eine Arbeitsstelle als Trainer bei Vereinen bewerben. Oder aber man arbeitet selbstständig und bietet Sportlern an, sie gegen Geld zu trainieren. Sehr gute Sportler, die viel erreichen wollen, brauchen eigentlich jemanden, der sich lange Zeit nur um sie kümmert.", "Die meisten Trainer haben aber einen anderen Beruf: Trainer sind sie nur im Ehrenamt. Sie machen das als Freiwillige und bekommen kein Geld dafür. Viele kleine Vereine können sich keine bezahlten Trainer leisten."], "zh": ["教练是照顾运动员的人。他教运动员这项运动需要会的东西，还陪运动员去参加比赛。有的教练负责一个小组或一支队伍，有的只带一名运动员，还有的在健身房工作，帮助来健身的人。", "想从事和体育有关的职业，大概先会在体育俱乐部里学到很多。俱乐部很欢迎这样，有些俱乐部还为此提供培训。这种培训会学很多体育的基础知识，比如怎样正确运动才不会受伤。此外还会学某个具体运动项目，或者怎样教别的运动员。也可以在大学等高校里学体育专业。", "培训结束会拿到一份证书，有了它就可以去俱乐部申请教练职位。或者自己单干，收钱为运动员训练。想取得很高成就的顶尖运动员，其实需要有人长期只照顾他们。", "不过大多数教练另有一份职业，教练只是他们的志愿工作。他们作为志愿者，不拿报酬。很多小俱乐部请不起付费的教练。"], "lemmas": [], "gloss": [{"w": "Wettkämpfen", "de": "Sportveranstaltungen, bei denen man gegen andere antritt", "zh": "比赛"}, {"w": "Mannschaften", "de": "Gruppen von Sportlern, die zusammen spielen", "zh": "队伍"}, {"w": "Sportverein", "de": "Verein, in dem man Sport macht", "zh": "体育俱乐部"}, {"w": "selbstständig", "de": "ohne Chef, mit eigener Firma", "zh": "自己单干的"}, {"w": "Ehrenamt", "de": "Arbeit ohne Lohn, freiwillig", "zh": "志愿工作"}], "qs": [{"q": "Was macht ein Trainer?", "qZh": "教练做什么？", "answer": "Er bringt Sportlern bei, was sie für ihren Sport können müssen.", "wrong": ["Er verkauft Sportkleidung.", "Er baut Sportplätze."]}, {"q": "Wo lernt man oft zuerst viel über einen Sportberuf?", "qZh": "人们常常最先在哪里学到很多体育职业的东西？", "answer": "In einem Sportverein.", "wrong": ["Im Supermarkt.", "Im Krankenhaus."]}, {"q": "Warum haben viele kleine Vereine keine bezahlten Trainer?", "qZh": "为什么很多小俱乐部没有付费教练？", "answer": "Sie haben nicht genug Geld dafür.", "wrong": ["Bezahlte Trainer sind verboten.", "Sie brauchen keine Trainer."]}], "src": "改编自 Klexikon《Trainer》", "url": "https://klexikon.zum.de/index.php?oldid=151194", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-019", "seg": 9, "title": "Experte", "de": ["Ein Experte oder eine Expertin ist jemand, der sich besonders mit etwas Bestimmten auskennt oder etwas gut kann. Niemand wird als Experte geboren. Ein Experte hat vielleicht an einer Hochschule studiert, lange in einem Beruf gearbeitet oder viel über ein Thema gelesen. Deshalb kann man sich gut mit ihm darüber unterhalten, ihm Fragen stellen und von ihm lernen.", "Es gibt oft keine festen Regeln oder gar Gesetze, wann man sich Experte nennen darf. Wenn man einen Abschluss an der Universität erlangt, bekommt man ein Diplom. Das sagt aus, dass man auf diesem Gebiet viel weiß. Es kann aber auch sein, dass jemand, der nicht studiert hat, sich sehr gut auskennt.", "Das Wort Experte kommt ursprünglich aus der französischen Sprache. Das Adjektiv „expert“ bedeutet so viel wie „erfahren“ oder „sachkundig“. Man verwendet den Begriff bei uns etwa seit dem 19. Jahrhundert. Das Gegenteil von einem Experten ist ein Laie. Das ist jemand, der sich genauso gut oder genauso schlecht auskennt wie andere Leute auch.", "Experten sind zum Beispiel Wissenschaftler: Sie forschen und sorgen damit, dass die Menschheit mehr über etwas weiß. Andere Experten bringen Menschen etwas bei, etwa Lehrer. Oder man braucht Expertenwissen, um etwas herstellen zu können, wie ein Handwerker oder Ingenieur, oder zum Beispiel zum Kochen. Schließlich muss man sich gut auskennen, wenn man als Künstler Romane schreiben oder Bilder malen will. Maler müssen zum Beispiel wissen, wie Farben wirken und wie man Farben mischt."], "zh": ["专家是特别懂某样东西或特别擅长某件事的人。没有人生来就是专家。专家也许在高校学习过、在某个职业里工作了很久，或者读了很多关于某个主题的书。所以可以和他好好聊聊这个话题，向他提问、向他学习。", "什么时候可以自称专家，常常没有固定的规则，更没有法律。在大学毕业会拿到文凭，说明你在这个领域懂得很多。但也有可能没上过大学的人也非常在行。", "Experte 这个词最早来自法语。形容词 expert 大致是「有经验的」或「内行的」意思。我们大约从 19 世纪起使用这个词。专家的反义词是外行，也就是懂得和别人一样多、或一样少的人。", "比如科学家就是专家：他们做研究，让人类对某样东西了解得更多。另一些专家教别人东西，比如教师。要制造东西也需要专业知识，比如手工业者或工程师，又比如做饭。最后，想当艺术家写小说或画画，也必须很在行。比如画家必须知道颜色有什么效果、怎么调色。"], "lemmas": [], "gloss": [{"w": "erlangt", "de": "bekommen, erreicht", "zh": "获得"}, {"w": "sachkundig", "de": "weiß viel über eine Sache", "zh": "内行的"}, {"w": "Laie", "de": "jemand, der kein Experte ist", "zh": "外行"}, {"w": "forschen", "de": "wissenschaftlich etwas Neues herausfinden", "zh": "做研究"}], "qs": [{"q": "Wie wird man laut Text zum Experten?", "qZh": "根据文章，怎样成为专家？", "answer": "Durch Studium, lange Arbeit oder viel Lesen über ein Thema.", "wrong": ["Man wird als Experte geboren.", "Man kauft ein Diplom."]}, {"q": "Was ist das Gegenteil von einem Experten?", "qZh": "专家的反义词是什么？", "answer": "Ein Laie.", "wrong": ["Ein Lehrer.", "Ein Wissenschaftler."]}, {"q": "Was müssen Maler zum Beispiel wissen?", "qZh": "比如画家必须知道什么？", "answer": "Wie Farben wirken und wie man sie mischt.", "wrong": ["Wie man Romane schreibt.", "Wie man ein Haus baut."]}], "src": "改编自 Klexikon《Experte》", "url": "https://klexikon.zum.de/index.php?oldid=151090", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-020", "seg": 9, "title": "Schauspieler", "de": ["Ein Schauspieler ist jemand, der so tut, als wäre er jemand anders. Er spielt für Zuschauer eine Rolle im Theater oder im Film. Manche Menschen sind Schauspieler als Beruf, andere machen das in ihrer Freizeit. Es gibt Schauspielschulen, auf denen man das Schauspielen lernt.", "Wer Schauspieler werden will, muss sich gut in andere Menschen hineinversetzen können. Er muss ein Theaterstück oder ein Drehbuch für einen Film richtig verstehen. Daraus lernt er über den Menschen, den er darstellen soll. Wenn ein Schauspieler schlecht Gefühle zeigen kann, glauben die Zuschauer ihm die Rolle nicht. Sie sehen dann jemanden, der angeblich traurig ist, aber sie fühlen es nicht.", "Außerdem muss ein Schauspieler sehr deutlich sprechen. Dann ist es möglich, dass die Zuschauer verstehen, was er sagt – selbst wenn er weit weg auf einer Bühne steht. Schauspieler lernen darum, wie man richtig atmet und die Laute formt. Weil Schauspieler so gut sprechen können, arbeiten sie oft auch für das Radio.", "Manche Schauspieler sind große Stars: Wer in Filmen aus Hollywood mitspielt, ist vielleicht sogar auf der ganzen Welt bekannt. Es gibt auch viele Preise für Schauspieler wie den „Oscar“ oder die „Goldene Palme“. Die meisten Schauspieler aber haben es schwer, genug Rollen zu bekommen, so dass sie davon leben können. Oft hat ein Schauspieler einen Agenten, jemanden, der Rollen für ihn sucht."], "zh": ["演员就是假装成别人的人。他在剧院或电影里为观众扮演一个角色。有些人以演员为职业，有些人在业余时间演戏。有专门学表演的戏剧学校。", "想当演员，必须能很好地设身处地理解别人。他必须真正读懂剧本或电影脚本，从中了解他要扮演的人。如果演员不太会表达情感，观众就不会相信他的角色。他们看到一个据说很伤心的人，却感受不到。", "此外，演员说话必须非常清楚。这样即使他站在远处的舞台上，观众也能听懂他说什么。所以演员要学怎样正确呼吸、怎样发音。因为演员说话很好，他们也常为电台工作。", "有些演员是大明星：在好莱坞电影里演过戏的人，可能全世界都认识。演员还有很多奖项，比如「奥斯卡」或「金棕榈」。但大多数演员很难得到足够的角色来养活自己。演员常有一个经纪人，帮他找角色。"], "lemmas": [], "gloss": [{"w": "hineinversetzen", "de": "sich vorstellen, wie ein anderer denkt und fühlt", "zh": "设身处地"}, {"w": "Drehbuch", "de": "Text für einen Film", "zh": "电影剧本"}, {"w": "darstellen", "de": "eine Rolle spielen", "zh": "扮演"}, {"w": "Bühne", "de": "erhöhter Platz im Theater, wo gespielt wird", "zh": "舞台"}, {"w": "Agenten", "de": "jemand, der für einen anderen Arbeit sucht", "zh": "经纪人"}], "qs": [{"q": "Was passiert, wenn ein Schauspieler schlecht Gefühle zeigen kann?", "qZh": "演员不太会表达情感会怎样？", "answer": "Die Zuschauer glauben ihm die Rolle nicht.", "wrong": ["Er wird sofort ein Star.", "Er darf nur im Radio sprechen."]}, {"q": "Warum lernen Schauspieler richtig zu atmen?", "qZh": "演员为什么要学正确呼吸？", "answer": "Damit man sie auch weit weg gut versteht.", "wrong": ["Damit sie schneller laufen.", "Damit sie singen können."]}, {"q": "Was ist für die meisten Schauspieler schwer?", "qZh": "对大多数演员来说什么很难？", "answer": "Genug Rollen zu bekommen, um davon zu leben.", "wrong": ["Einen Oscar zu gewinnen.", "Deutlich zu sprechen."]}], "src": "改编自 Klexikon《Schauspieler》", "url": "https://klexikon.zum.de/index.php?oldid=161694", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-021", "seg": 9, "title": "Bank", "de": ["Eine Bank ist eine Firma, der man sein Geld zum Aufbewahren geben kann. Sie wechselt aber auch Geld von einer Währung in die andere, zum Beispiel von Euro in Schweizer Franken. Das Wort Bank kommt aus der italienischen Sprache und bedeutet „Tisch“. An so einem Tisch hat man früher Geld gewechselt.", "Banken können auf verschiedene Weise Geld verdienen. Auf einer Bank kann man Geld sicher verwahren lassen. Dafür bezahlt man eine Gebühr. Man kann einer Bank auch einen Auftrag geben etwas zu tun, jeden Monat die Miete zu bezahlen beispielsweise. Oder man wechselt Geld in eine andere Währung, von Schweizer Franken in Euro. Die Gebühr, die man für so einen Auftrag bezahlt, heißt Kommission.", "Wenn du Geld bei der Bank verwahren lässt, wird die Bank dieses Geld nicht im Tresor liegen lassen. Sie darf es an andere Leute verleihen. Wer Geld leiht, der bezahlt dafür einen kleinen Betrag, das heißt dann Zins. Die Bank behält einen Teil dieser Zinsen für sich, und gibt einen Teil an den weiter, der das Geld hat aufbewahren lassen.", "Wenn man Geld von einer Währung in eine andere Währung wechselt, muss man ebenfalls eine Gebühr bezahlen. Außerdem kauft die Bank eine Währung billiger ein, als sie selbst dafür verlangt. Den Unterschied behält sie als Gewinn. Der Preis für die Währung heißt Wechselkurs."], "zh": ["银行是一家可以把钱交给它保管的公司。它也把一种货币换成另一种，比如把欧元换成瑞士法郎。Bank 这个词来自意大利语，意思是「桌子」。以前人们就在这样的桌子上换钱。", "银行可以用不同方式挣钱。可以把钱放在银行安全保管，为此要付一笔费用。也可以委托银行做事，比如每个月替你付房租。或者把钱换成另一种货币，比如把瑞士法郎换成欧元。为这类委托付的费用叫手续费。", "你把钱存在银行，银行不会让这些钱一直躺在保险柜里，它可以把钱借给别人。借钱的人要为此付一小笔钱，叫利息。银行把一部分利息留给自己，一部分给存钱的人。", "把钱从一种货币换成另一种货币，同样要付手续费。此外银行买进一种货币的价格比它卖出的价格低，差价就是它的利润。货币的价格叫汇率。"], "lemmas": [], "gloss": [{"w": "Aufbewahren", "de": "sicher halten, bis man es wieder braucht", "zh": "保管"}, {"w": "Gebühr", "de": "Geld, das man für eine Leistung bezahlt", "zh": "费用"}, {"w": "Tresor", "de": "sicherer Schrank für Geld", "zh": "保险柜"}, {"w": "Zins", "de": "Geld, das man für geliehenes Geld bezahlt", "zh": "利息"}, {"w": "Wechselkurs", "de": "Preis einer Währung in einer anderen Währung", "zh": "汇率"}], "qs": [{"q": "Was bedeutet das italienische Wort, von dem „Bank“ kommt?", "qZh": "Bank 这个词来自的意大利语意思是什么？", "answer": "Tisch.", "wrong": ["Geld.", "Haus."]}, {"q": "Was macht die Bank mit dem Geld, das man ihr gibt?", "qZh": "银行用别人存的钱做什么？", "answer": "Sie verleiht es an andere Leute.", "wrong": ["Sie lässt es immer im Tresor liegen.", "Sie verbrennt es."]}, {"q": "Wie heißt der Preis für eine Währung?", "qZh": "货币的价格叫什么？", "answer": "Wechselkurs.", "wrong": ["Zins.", "Miete."]}], "src": "改编自 Klexikon《Bank》", "url": "https://klexikon.zum.de/index.php?oldid=154189", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-022", "seg": 9, "title": "Bankkonto", "de": ["Ein Bankkonto ist so etwas wie ein Geldbeutel, der aber auf der Bank liegt. Auf dem Bankkonto liegen aber keine Scheine und Münzen, sondern das Geld ist nur aufgeschrieben. In einen Geldbeutel kann man Geld hinein tun oder wieder herausnehmen.", "Um das mit dem Bankkonto zu machen, kann man Geld einzahlen, abheben oder auf ein anderes Konto verschieben. Dazu muss man aber nicht nur die Kontonummer kennen. Geld einzahlen kann jeder, aber um Geld wegzunehmen, muss man eine Berechtigung haben.", "Wenn man aus seinem Bankkonto etwas bezahlen will, beispielsweise einen neuen Teppich im Möbelhaus, kann man das heute mit seiner Bankkarte tun. Wer beispielsweise die Miete ohne Bargeld bezahlen will, muss Geld von einem Konto auf ein anderes übertragen. Das Geld muss also umgebucht werden.", "Der bekannteste Fall dafür ist eine Überweisung. Auf dem Überweisungszahlschein gibt man das eigene und das andere Konto an, auf das das Geld bezahlt werden soll und den Betrag, also wie viel Geld, vom eigenen auf das andere Konto übertragen werden soll. Das kann man heute auch über das Internet mit dem sogenannten Online-Banking erledigen.", "Von einem Bankkonto kann man mehr Geld abheben, als tatsächlich drauf ist. Man macht dadurch Schulden. Das nennt man: ein Konto überziehen. Das kann man aber nicht beliebig weit treiben. Meistens kann man so weit in die Schulden gehen, dass das Konto mit dem nächsten Lohn wieder auf Null kommt. Das ist aber gefährlich. Viele Leute können in einer solchen Lage keine Zahnarzt-Rechnung oder eine Auto-Reparatur mehr bezahlen.", "Heute lässt man sich seinen Lohn nicht in Scheinen ausbezahlen, sondern der Chef schickt das Geld direkt auf das Bankkonto des Angestellten. Das ist seit etwa 50 Jahren so üblich. So füllt sich das Bankkonto regelmäßig, ohne dass man Geld in die Hand nehmen muss."], "zh": ["银行账户有点像放在银行里的钱包。不过账户里没有纸币和硬币，钱只是记录下来的。往钱包里可以放钱，也可以拿钱出来。", "对银行账户也可以这样做：可以存钱、取钱，或者把钱转到另一个账户。但光知道账号还不够。人人都可以存钱，但要拿走钱必须有权限。", "想用账户里的钱付款，比如在家具店买一块新地毯，如今可以用银行卡。比如想不用现金付房租，就得把钱从一个账户转到另一个账户，也就是转账。", "最常见的就是汇款。在汇款单上要写上自己的账户和收款账户，以及金额，也就是要从自己账户转多少钱到对方账户。如今也可以通过网上银行在网上办理。", "可以从账户里取出比实际余额更多的钱，这样就欠了债，叫透支。不过不能无限透支。一般最多能透支到下次工资到账后账户刚好回到零。但这很危险，很多人到了这种地步，连牙医账单或修车费都付不起。", "如今工资不再发现金，而是老板直接把钱打到员工的银行账户上。这大约已经流行了 50 年。这样账户会定期有钱进来，不用经手现金。"], "lemmas": [], "gloss": [{"w": "einzahlen", "de": "Geld auf ein Konto bringen", "zh": "存钱"}, {"w": "abheben", "de": "Geld von einem Konto holen", "zh": "取钱"}, {"w": "Berechtigung", "de": "Erlaubnis", "zh": "权限"}, {"w": "Überweisung", "de": "Geld von einem Konto auf ein anderes schicken", "zh": "汇款、转账"}, {"w": "überziehen", "de": "mehr Geld nehmen, als auf dem Konto ist", "zh": "透支"}], "qs": [{"q": "Was braucht man, um Geld von einem Konto wegzunehmen?", "qZh": "要从账户里拿钱需要什么？", "answer": "Eine Berechtigung.", "wrong": ["Nur die Kontonummer.", "Einen Brief vom Chef."]}, {"q": "Was bedeutet „ein Konto überziehen“?", "qZh": "「透支账户」是什么意思？", "answer": "Mehr Geld abheben, als auf dem Konto ist.", "wrong": ["Ein neues Konto eröffnen.", "Das Konto schließen."]}, {"q": "Wie kommt heute der Lohn meistens zum Angestellten?", "qZh": "如今工资大多怎样到员工手里？", "answer": "Der Chef schickt ihn direkt auf das Bankkonto.", "wrong": ["Der Chef gibt ihn in Scheinen.", "Man holt ihn bei der Post ab."]}], "src": "改编自 Klexikon《Bankkonto》", "url": "https://klexikon.zum.de/index.php?oldid=158082", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-023", "seg": 9, "title": "Geld", "de": ["Unter Geld versteht man vor allem Bargeld: Münzen und Geldscheine. Zum Geld gehört aber auch das Geld auf einem Konto bei der Bank. Mit Geld können wir viele Dinge kaufen, die wir zum Leben brauchen. Wenn wir in den Supermarkt gehen, tauschen wir unser Geld gegen Waren wie Brot ein, wir bezahlen mit Geld. Deshalb nennt man das Geld auch Zahlungsmittel.", "Als die Menschen noch kein Geld kannten, haben sie Dinge getauscht. Später kam man auf die Idee, eine bestimmte Menge kostbares Metall zu nehmen und daraus eine Münze herzustellen. Das war handlicher als andere Tauschwaren.", "Lange Zeit waren nur Münzen das richtige Geld. Sie bestanden aus einem seltenen und wertvollen Metall, wie Silber oder Gold. Wer eine Silbermünze besaß, der konnte sicher sein: Die Münze ist mindestens so viel wert, wie so viel Silber gerade wert ist. Vor etwa 1000 Jahren gab es in China das erste Papiergeld. Es sollte eigentlich nur eingesetzt werden, wenn die Münzen knapp wurden.", "Geldscheine drucken oder Münzen prägen darf nur der Staat. Das eigene Geld eines Staates ist eine Währung. Aber einfach beliebig viel Geldscheine drucken darf der Staat auch nicht, sonst verliert das Geld seinen Wert. Wenn irgend ein Mensch Geld nachdruckt, nennt man das Falschgeld. Dafür wird man streng bestraft.", "Um ohne Bargeld bezahlen zu können, braucht man ein Konto bei einer Bank. Dann kann man darauf Geld einzahlen. Das heißt, man bringt Bargeld zur Bank und gibt es dort ab. Die Bank behält das Geld und vermerkt das in ihrem Computer. Man sagt: „Das Geld wird deinem Konto gutgeschrieben.“ Um ein Konto zu haben muss man alt genug sein."], "zh": ["说到钱，首先指现金：硬币和纸币。但银行账户里的钱也算钱。用钱可以买很多生活需要的东西。我们去超市时，用钱换面包之类的商品，也就是用钱付款。所以钱也叫支付手段。", "人们还不知道钱的时候，是以物易物。后来人们想到，拿一定量的贵重金属做成硬币，这比其他交换物更方便。", "很长时间里只有硬币才是真正的钱。硬币用银或金这类稀少、贵重的金属做成。有银币的人可以放心：这枚硬币至少值同样多的银子当时的价钱。大约 1000 年前中国出现了最早的纸币，本来只是在硬币短缺时使用。", "只有国家可以印纸币或铸硬币。一个国家自己的钱就是一种货币。但国家也不能随便想印多少就印多少，否则钱就会贬值。如果有人私自印钱，叫假币，会受到严厉惩罚。", "想不用现金付款，就需要在银行开一个账户，然后往里面存钱。也就是把现金带到银行交给银行。银行留下这笔钱，在电脑里记上一笔。人们说：「钱存入你的账户了。」要开账户，必须年满一定年龄。"], "lemmas": [], "gloss": [{"w": "Zahlungsmittel", "de": "etwas, womit man bezahlt", "zh": "支付手段"}, {"w": "handlicher", "de": "leichter zu tragen und zu benutzen", "zh": "更方便的"}, {"w": "prägen", "de": "Münzen herstellen", "zh": "铸造（硬币）"}, {"w": "Falschgeld", "de": "Geld, das nicht echt ist", "zh": "假币"}, {"w": "gutgeschrieben", "de": "auf das Konto gebucht", "zh": "记入（账户）"}], "qs": [{"q": "Was haben die Menschen gemacht, bevor es Geld gab?", "qZh": "有钱之前人们怎么做？", "answer": "Sie haben Dinge getauscht.", "wrong": ["Sie haben mit Karten bezahlt.", "Sie haben nichts gekauft."]}, {"q": "Wo gab es das erste Papiergeld?", "qZh": "最早的纸币出现在哪里？", "answer": "In China.", "wrong": ["In Italien.", "In Deutschland."]}, {"q": "Warum darf der Staat nicht beliebig viele Geldscheine drucken?", "qZh": "国家为什么不能随便印纸币？", "answer": "Sonst verliert das Geld seinen Wert.", "wrong": ["Es gibt nicht genug Papier.", "Die Banken verbieten es."]}], "src": "改编自 Klexikon《Geld》", "url": "https://klexikon.zum.de/index.php?oldid=158939", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-024", "seg": 9, "title": "Währung", "de": ["Unter Währungen versteht man die Geldsorten verschiedener Staaten. Weltweit sind heute über 160 Währungen anerkannt. Manche Währungen gelten in mehreren Ländern.", "In vielen europäischen Ländern ist der Euro seit dem Jahr 2002 die offizielle Währung. In Europa hatte jedes Land seine eigene Währung. In Deutschland war es die D-Mark und in Österreich der Schilling. In Italien war es die Lira, in Griechenland die Drachme und so weiter.", "Wer Geld in einer bestimmten Währung hat, kann es in eine andere Währung umtauschen. So tauscht man zum Beispiel etwas von den Euros, die man hat, in Schweizer Franken. Man bekommt aber nicht für einen Euro genau einen Franken. Wie viel der Franken wert ist, verglichen mit dem Euro, das nennt man den Wechselkurs.", "Wenn der Kurs günstig ist, bekommt man für seine Euros eher viele Franken. Zu einer anderen Zeit ist der Kurs aber womöglich ein anderer. Das kommt daher, dass eine Währung wertvoller oder auch weniger wertvoll werden kann. Den täglich gültigen Wechselkurs kann man bei einer Bank erfahren.", "Wenn der Franken teuer und der Euro billig ist, bedeutet dies: Für Deutsche werden schweizerische Produkte teurer. Auch Urlaub in der Schweiz wird teurer. Es bedeutet aber auch: Deutsche Produkte werden in der Schweiz billiger. Das bedeutet wiederum, dass Deutschland besser Waren in die Schweiz verkaufen kann. Das sichert Arbeitsplätze in Deutschland. Wenn der Wechselkurs steigt oder sinkt, hat das jeweils seine Vor- und Nachteile."], "zh": ["货币是指不同国家的钱的种类。如今全世界有 160 多种货币得到承认。有些货币在好几个国家通用。", "从 2002 年起，欧元是很多欧洲国家的官方货币。以前欧洲每个国家都有自己的货币：德国是马克，奥地利是先令，意大利是里拉，希腊是德拉克马，等等。", "持有某种货币的人，可以把它换成另一种货币。比如把手里的一些欧元换成瑞士法郎。但一欧元并不正好换一法郎。法郎和欧元相比值多少，叫作汇率。", "汇率好的时候，用欧元能换到比较多的法郎。但换个时间，汇率也许就不一样了。这是因为一种货币可能变得更值钱，也可能变得不那么值钱。当天有效的汇率可以在银行查到。", "如果法郎贵、欧元便宜，意味着：对德国人来说瑞士产品变贵了，去瑞士度假也变贵了。但这也意味着德国产品在瑞士变便宜了，于是德国能更好地把商品卖到瑞士，这保住了德国的工作岗位。汇率涨也好跌也好，各有利弊。"], "lemmas": [], "gloss": [{"w": "anerkannt", "de": "offiziell akzeptiert", "zh": "得到承认的"}, {"w": "umtauschen", "de": "gegen etwas anderes tauschen", "zh": "兑换"}, {"w": "günstig", "de": "gut für einen, billig", "zh": "有利的、便宜的"}, {"w": "gültigen", "de": "der jetzt gilt", "zh": "有效的"}], "qs": [{"q": "Seit wann ist der Euro in vielen europäischen Ländern die Währung?", "qZh": "欧元从什么时候起成为很多欧洲国家的货币？", "answer": "Seit 2002.", "wrong": ["Seit 1950.", "Seit 2020."]}, {"q": "Wo kann man den täglichen Wechselkurs erfahren?", "qZh": "在哪里可以查到当天的汇率？", "answer": "Bei einer Bank.", "wrong": ["Beim Arzt.", "Im Supermarkt."]}, {"q": "Was passiert, wenn der Franken teuer und der Euro billig ist?", "qZh": "法郎贵、欧元便宜时会怎样？", "answer": "Urlaub in der Schweiz wird für Deutsche teurer.", "wrong": ["Deutsche Produkte werden in der Schweiz teurer.", "Alle Preise bleiben gleich."]}], "src": "改编自 Klexikon《Währung》", "url": "https://klexikon.zum.de/index.php?oldid=155264", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-025", "seg": 9, "title": "Steuer", "de": ["Eine Steuer ist ein bestimmter Geldbetrag. Jeder Einwohner oder jede Familie muss diesen Betrag bezahlen, aber auch jedes Unternehmen. Das Geld erhält die Gemeinde, der Kanton oder das Bundesland und auch der Staat.", "Gebraucht wird das Geld für den Bau von Krankenhäusern, Schulen, Hallenbädern und anderen Gebäuden aber auch für den Kauf von Waffen und vielen anderen Dingen. Auch die Politiker oder andere Angestellte werden daraus bezahlt, zum Beispiel Lehrer. Das Geld wird also für Ausgaben benutzt, von denen im Grunde alle Einwohner profitieren. Mit den Steuern nehmen die Gemeinden oder Staaten den Großteil ihres Geldes ein, damit sie ihre Aufgaben erfüllen können.", "Nicht jeder zahlt gleich viel Steuern. In jedem Land ist genau festgelegt, wer wie viel Steuern bezahlen muss. Der wichtigste Punkt bei der Berechnung ist das Einkommen: Wer viel Geld verdient, muss auch mehr Steuern bezahlen, als jemand der einen niedrigen Lohn hat. Wer Kinder hat, die noch zur Schule oder Universität gehen, muss oft auch weniger Steuern bezahlen. So gibt es eine Vielzahl an Regeln, die besagen, wer wie viele Steuern zahlen muss. Am Ende eines Jahres füllen Erwachsene deshalb ihre Steuererklärung aus, damit man ihren Steuerbeitrag berechnen kann.", "Es gibt auch besondere Steuern. Die bezahlt man beispielsweise für ein Auto. Mit diesem Geld werden dann Straßen gebaut. In vielen Ländern bezahlt man eine Steuer auf Kohlendioxid, das durch Autos oder Heizungen entsteht. Man will damit den Klimawandel bremsen. Es gibt auch die Warenumsatzsteuer oder die Mehrwertsteuer. Jedes Mal, wenn zum Beispiel etwas in einem Laden verkauft wird, bezahlt man damit eine Steuer. Maler, Friseure und viele andere bezahlen eine Mehrwertsteuer auf ihre Dienstleistungen."], "zh": ["税是一笔规定的钱。每个居民或每个家庭都要交，每个企业也要交。这笔钱归乡镇、州（瑞士）或联邦州，也归国家。", "这笔钱用来建医院、学校、室内游泳馆和其他建筑，也用来买武器和很多别的东西。政治家和其他公职人员，比如教师，也从这里拿工资。所以这些钱用于基本上所有居民都能受益的开支。乡镇或国家的大部分收入来自税收，这样才能完成它们的任务。", "不是人人交的税都一样多。每个国家都规定得很清楚，谁要交多少税。计算时最重要的是收入：挣得多的人，比工资低的人要交更多税。有孩子还在上学或上大学的人，常常也可以少交税。所以有许多规则规定谁要交多少税。因此成年人每年年底都要填报税表，好计算出他们要交的税额。", "还有一些特别的税。比如为汽车交的税，这笔钱用来修路。很多国家对汽车或暖气排放的二氧化碳征税，想以此减缓气候变化。还有销售税或增值税：比如每次在店里卖出东西，就交了一笔税。油漆工、理发师和很多其他人要为他们提供的服务交增值税。"], "lemmas": [], "gloss": [{"w": "profitieren", "de": "einen Vorteil haben", "zh": "受益"}, {"w": "Einkommen", "de": "Geld, das man verdient", "zh": "收入"}, {"w": "Steuererklärung", "de": "Formular, in dem man dem Staat sein Einkommen angibt", "zh": "报税表"}, {"w": "Mehrwertsteuer", "de": "Steuer, die man beim Kaufen bezahlt", "zh": "增值税"}, {"w": "Dienstleistungen", "de": "Arbeit für Kunden, z. B. Haare schneiden", "zh": "服务"}], "qs": [{"q": "Wofür wird Steuergeld zum Beispiel gebraucht?", "qZh": "税款比如用在哪里？", "answer": "Für Schulen und Krankenhäuser.", "wrong": ["Für den Urlaub der Politiker.", "Nur für Autos."]}, {"q": "Wer muss mehr Steuern bezahlen?", "qZh": "谁要交更多的税？", "answer": "Wer viel Geld verdient.", "wrong": ["Wer Kinder hat.", "Wer wenig verdient."]}, {"q": "Warum gibt es in vielen Ländern eine Steuer auf Kohlendioxid?", "qZh": "为什么很多国家对二氧化碳征税？", "answer": "Man will den Klimawandel bremsen.", "wrong": ["Man will mehr Autos verkaufen.", "Man will Heizungen verbieten."]}], "src": "改编自 Klexikon《Steuer》", "url": "https://klexikon.zum.de/index.php?oldid=160471", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-026", "seg": 9, "title": "Versicherung", "de": ["Einer Versicherung zahlt man regelmäßig einen bestimmten Geldbetrag. Dafür bezahlt einem die Versicherung einen Schaden, den man erleidet. Versichern kann man sich gegen Krankheiten und Unfälle, aber auch gegen Diebstahl, einen Brand in der Wohnung und andere Schäden.", "Versicherungen helfen also dem Menschen in Notfällen und wenn er Pech hat. Großes Pech trifft zwar selten ein, aber dafür ist es dann umso schlimmer für den Betroffenen. Wer ein Leben lang Geld in eine Unfallversicherung einbezahlt und selber nie einen Unfall hat, bekommt sein Geld nicht zurück. Wer aber einmal einen schweren Unfall hat, bekommt mehr Geld für die ärztliche Versorgung, als er einbezahlt hat.", "Eine Krankenversicherung brauchen bei uns alle Menschen. Das ist so vorgeschrieben, das gilt aber lange nicht in allen Ländern der Welt. Meist muss man kleinere Dinge wie etwa leichtere Medikamente aus der Apotheke selber bezahlen. Die großen Beträge wie etwa Krankenhaus-Aufenthalte bezahlt die Krankenversicherung. Man nennt sie auch Krankenkasse. Auch eine Versicherung gegen Unfälle muss man in vielen Ländern haben. Oft hängt das mit der Krankenkasse zusammen, denn beides betrifft Schäden am eigenen Körper.", "Gegen Schäden, die ein Mensch einem anderen Menschen zufügt, gibt es Haftpflicht-Versicherungen. Die braucht man zum Beispiel für jedes Auto, Motorrad oder Fahrrad. Hier muss man nämlich damit rechnen, dass man einen Unfall verursacht. Dabei sind dann nicht nur die Schäden an Menschen, sondern auch an den Sachen versichert, zum Beispiel an beschädigten Fahrzeugen. Für andere Schäden braucht man eine Privat-Haftpflichtversicherung. Die zahlt zum Beispiel, wenn ein Kind mit dem Dreirad eine fremde Autotür zerkratzt."], "zh": ["人们定期给保险公司交一笔钱。作为回报，如果你遭受损失，保险公司替你赔偿。可以投保疾病和意外，也可以投保盗窃、住宅火灾和其他损失。", "所以保险在紧急情况下、在人倒霉的时候帮助人。大的不幸虽然很少发生，但一旦发生，对当事人来说就特别糟糕。一辈子交意外险却从来没出过事故的人，钱是拿不回来的。但如果出过一次严重事故，得到的医疗费用就会比他交的钱多。", "在我们这里，所有人都必须有医疗保险。这是法律规定的，但远不是世界上所有国家都这样。一般小事情，比如药店里的普通药，要自己付钱。住院这种大额费用由医疗保险支付，医疗保险也叫 Krankenkasse。在很多国家，人们还必须有意外保险。这常常和医保连在一起，因为两者都涉及自己身体受到的伤害。", "对于一个人给别人造成的损失，有责任险。比如每辆汽车、摩托车或自行车都需要。因为开车骑车时，必须考虑到自己可能造成事故。这时不只是人受的伤，物品的损失也在保险范围内，比如被撞坏的车辆。其他损失则需要个人责任险。比如小孩骑三轮车把别人的车门刮花了，就由它来赔。"], "lemmas": [], "gloss": [{"w": "Schaden", "de": "etwas, das kaputt oder verletzt ist", "zh": "损失、损害"}, {"w": "Betroffenen", "de": "die Person, der etwas passiert", "zh": "当事人"}, {"w": "vorgeschrieben", "de": "durch eine Regel verlangt", "zh": "规定的"}, {"w": "zufügt", "de": "jemandem etwas Schlechtes machen", "zh": "给…造成"}, {"w": "Haftpflicht", "de": "Pflicht, für Schäden an anderen zu bezahlen", "zh": "责任（险）"}, {"w": "zerkratzt", "de": "mit etwas Spitzem kaputt gemacht", "zh": "刮花"}], "qs": [{"q": "Was bekommt man, wenn man nie einen Unfall hat?", "qZh": "从来没出过事故的人能拿回什么？", "answer": "Man bekommt sein Geld nicht zurück.", "wrong": ["Man bekommt alles Geld zurück.", "Man bekommt ein neues Auto."]}, {"q": "Was bezahlt die Krankenversicherung meistens?", "qZh": "医疗保险大多付什么？", "answer": "Große Beträge wie Krankenhaus-Aufenthalte.", "wrong": ["Alle kleinen Medikamente.", "Den Urlaub."]}, {"q": "Wofür braucht man eine Haftpflicht-Versicherung?", "qZh": "责任险用来做什么？", "answer": "Für Schäden, die man anderen Menschen macht.", "wrong": ["Für Schäden am eigenen Körper.", "Für den Kauf eines Hauses."]}], "src": "改编自 Klexikon《Versicherung》", "url": "https://klexikon.zum.de/index.php?oldid=155755", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-027", "seg": 9, "title": "Aktie", "de": ["Eine Aktie ist ein besonderes Stück Papier, so ähnlich wie ein Geldschein. Weil es wertvoll ist, nennt man es auch Wertpapier. Wer eine Aktie besitzt, dem gehört damit ein Anteil von einem Unternehmen. Darum nennt man die Aktie auch Anteils-Schein. Aktien kann man kaufen und auch wieder verkaufen. Der Handel mit Aktien geschieht meist an der Börse. Dieser Handel läuft heutzutage natürlich vor allem über Computer und nicht mehr mit Papier.", "Wenn ein Unternehmen neue Maschinen kaufen oder eine neue Fabrik bauen will, braucht es dafür viel Geld. Dieses Geld kann es entweder bei einer Bank leihen – oder eben Aktien verkaufen. Wer eine Aktie kauft, gibt sein Geld dem Unternehmen und erhält dafür einen Anteil an dem Unternehmen. Allen Aktionären zusammen gehört also das Unternehmen.", "Sie dürfen deshalb auch mitbestimmen, was in dem Unternehmen passiert und zum Beispiel den Chef wählen. Je mehr Aktien man hat, desto mehr hat man zu sagen. Solche Unternehmen heißen auch Aktiengesellschaft oder kurz AG. Die meisten großen Unternehmen sind Aktiengesellschaften, zum Beispiel Daimler oder BMW, aber auch Chemie- und Energie-Konzerne.", "Aktien kann man kaufen und wieder verkaufen. Der Ort, wo Aktien gehandelt werden, heißt Börse. Solche Börsen gibt es in vielen großen Städten. Die bekannteste deutsche Börse steht in Frankfurt am Main. Dort werden die Aktien der wichtigsten Firmen in Deutschland gehandelt und festgelegt, wie viel die Aktien wert sind."], "zh": ["股票是一种特殊的纸，有点像纸币。因为它很值钱，也叫有价证券。拥有股票的人，就拥有一家企业的一部分份额，所以股票也叫股份凭证。股票可以买，也可以再卖掉。股票交易大多在证券交易所进行。当然，如今交易主要通过电脑，而不再用纸。", "一家企业想买新机器或建新工厂，需要很多钱。这笔钱可以向银行借，也可以靠卖股票得到。买股票的人把钱交给企业，换来企业的一部分份额。所以企业归全体股东共同所有。", "因此股东可以参与决定企业里的事，比如选老板。股票越多，说话就越有分量。这样的企业叫股份公司，简称 AG。大多数大企业都是股份公司，比如戴姆勒或宝马，还有化工和能源集团。", "股票可以买进卖出。买卖股票的地方叫证券交易所。很多大城市都有交易所。德国最有名的交易所在美因河畔法兰克福，在那里交易德国最重要公司的股票，并确定股票值多少钱。"], "lemmas": [], "gloss": [{"w": "Wertpapier", "de": "Papier, das Geld wert ist", "zh": "有价证券"}, {"w": "Anteil", "de": "ein Teil von etwas", "zh": "份额"}, {"w": "Börse", "de": "Ort, an dem Aktien gekauft und verkauft werden", "zh": "证券交易所"}, {"w": "Aktionären", "de": "Menschen, die Aktien besitzen", "zh": "股东"}, {"w": "mitbestimmen", "de": "bei Entscheidungen mitmachen", "zh": "参与决定"}], "qs": [{"q": "Was besitzt man, wenn man eine Aktie hat?", "qZh": "拥有股票意味着拥有什么？", "answer": "Einen Anteil an einem Unternehmen.", "wrong": ["Einen Kredit bei der Bank.", "Ein Stück Land."]}, {"q": "Warum verkauft ein Unternehmen Aktien?", "qZh": "企业为什么卖股票？", "answer": "Es braucht Geld, zum Beispiel für eine neue Fabrik.", "wrong": ["Es will weniger Mitarbeiter haben.", "Es muss Steuern sparen."]}, {"q": "Wo steht die bekannteste deutsche Börse?", "qZh": "德国最有名的交易所在哪里？", "answer": "In Frankfurt am Main.", "wrong": ["In Berlin.", "In München."]}], "src": "改编自 Klexikon《Aktie》", "url": "https://klexikon.zum.de/index.php?oldid=154074", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-028", "seg": 9, "title": "Handel", "de": ["Beim Handel tauschen die Menschen Waren untereinander aus. Früher haben sie eine Ware direkt gegen eine andere getauscht, das war der Tauschhandel. Heutzutage bezahlt man eine Ware meist mit Geld.", "Wenn man von „dem Handel“ spricht, meint man damit den gesamten Handel in einem Land oder der Welt. Der Handel ist ein Teil der Wirtschaft. Wenn etwas hergestellt worden ist, dann braucht man den Handel, damit der Hersteller seine Ware an die Leute bringt und Geld damit verdient. Außerdem wollen die Kunden Waren kaufen können.", "Man sagt auch, dass ein Land Handel betreibt. Händler ist dann aber meistens nicht das Land selbst, der Staat, sondern die vielen Unternehmen im Land. China, die USA und Deutschland sind diejenigen Länder, die am meisten Handel mit anderen Ländern betreiben.", "Ein Teil des Handels ist der Einzelhandel. Damit meint man die Geschäfte und Läden, die etwas an normale Kunden verkaufen. Solche Kunden kaufen Waren für sich selbst und für ihren Haushalt. Ein Kunde kauft sich zum Beispiel von Zeit zu Zeit einen neuen Kühlschrank.", "Einzelhandel ist der Gegensatz zum Großhandel: Großhändler handeln mit einer Ware, von der sie viel verkaufen. Beispielsweise handelt ein Unternehmen mit Kühlschränken. Die Einzelhändler kaufen einige Kühlschränke beim Großhandelsunternehmen und verkaufen sie dann an ihre Kunden weiter."], "zh": ["贸易就是人们相互交换商品。以前人们直接用一种商品换另一种，那是以物易物。如今买商品大多用钱付。", "说到「贸易」，指的是一个国家或全世界的全部买卖。贸易是经济的一部分。东西生产出来以后，需要贸易，生产者才能把商品卖到人们手里、挣到钱。另外，顾客也想能买到商品。", "人们也说一个国家在做贸易。不过做买卖的大多不是国家本身，而是国内众多的企业。中国、美国和德国是和其他国家贸易往来最多的国家。", "贸易的一部分是零售。零售指把东西卖给普通顾客的商店。这些顾客买东西给自己和家里用，比如时不时买一台新冰箱。", "零售的对立面是批发：批发商经营一种商品，而且卖得很多。比如一家企业专门做冰箱买卖。零售商从批发企业买几台冰箱，再卖给自己的顾客。"], "lemmas": [], "gloss": [{"w": "Tauschhandel", "de": "Ware gegen Ware tauschen, ohne Geld", "zh": "以物易物"}, {"w": "Hersteller", "de": "Firma, die etwas produziert", "zh": "生产者"}, {"w": "Einzelhandel", "de": "Verkauf an normale Kunden", "zh": "零售"}, {"w": "Großhandel", "de": "Verkauf großer Mengen an Geschäfte", "zh": "批发"}], "qs": [{"q": "Wie hat man früher Waren bekommen?", "qZh": "以前人们怎样得到商品？", "answer": "Man hat eine Ware gegen eine andere getauscht.", "wrong": ["Man hat mit Karte bezahlt.", "Man hat sie im Internet bestellt."]}, {"q": "Welche Länder betreiben am meisten Handel mit anderen Ländern?", "qZh": "哪些国家和其他国家贸易最多？", "answer": "China, die USA und Deutschland.", "wrong": ["Frankreich, Italien und Spanien.", "Japan, Brasilien und Kanada."]}, {"q": "Was macht ein Einzelhändler mit den Kühlschränken vom Großhandel?", "qZh": "零售商拿批发来的冰箱做什么？", "answer": "Er verkauft sie an seine Kunden weiter.", "wrong": ["Er repariert sie.", "Er gibt sie zurück."]}], "src": "改编自 Klexikon《Handel》", "url": "https://klexikon.zum.de/index.php?oldid=158862", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-029", "seg": 9, "title": "Markt", "de": ["Ein Markt ist ein Ort in einer Stadt, an dem etwas verkauft wird. Im Mittelalter war es noch etwas Besonderes, wenn eine Stadt einen Markt hatte. Dazu brauchte sie eine Erlaubnis vom Herrscher des Landes, zum Beispiel vom König. Heute haben viele Städte einen Marktplatz, an dem oft auch das Rathaus liegt.", "Normalerweise findet ein Markt nur an bestimmten Zeiten statt. Das ist dann etwa ein Markttag, an dem Händler mit ihren Ständen ihre Waren verkaufen. Dafür, dass sie einen Stand dort haben dürfen, zahlen sie eine Gebühr. Heute gibt es allerdings auch große Warenhäuser und Supermärkte, darum finden viele Leute solche Märkte nicht mehr so wichtig wie früher.", "Es gibt unterschiedliche Märkte. Manche sind nur für bestimmte Waren da, wie ein Blumenmarkt oder Käsemarkt. Markthallen hat man gebaut, damit die Händler ein Dach über dem Kopf haben. Auf einem Flohmarkt dürfen auch Menschen verkaufen, die sonst keine Händler sind.", "Von Märkten spricht man auch in der Wirtschaft. So ein Markt ist an sich nicht sichtbar, sondern mehr ein Gedanke. Zum Beispiel bedeutet der Rohstoffmarkt, dass einige Unternehmen Rohstoffe wie Erdöl oder Eisen anbieten. Andere Unternehmen kaufen die Waren."], "zh": ["集市是城里卖东西的地方。在中世纪，一座城市有集市还是件特别的事，需要得到国家统治者比如国王的许可。如今很多城市都有集市广场，市政厅也常常在广场上。", "集市一般只在固定时间开。比如在集市日，商贩们在自己的摊位上卖货。他们要交一笔费用才能在那里摆摊。不过如今也有大百货商店和超市，所以很多人觉得这样的集市不像以前那么重要了。", "集市有各种各样的。有些只卖特定商品，比如花市或奶酪市场。人们建了市场大厅，好让商贩头上有个顶。在跳蚤市场上，平时不做买卖的人也可以卖东西。", "经济学里也说「市场」。这种市场本身看不见，更像是一个概念。比如原材料市场，意思是一些企业提供石油或铁这类原材料，另一些企业购买这些商品。"], "lemmas": [], "gloss": [{"w": "Ständen", "de": "kleine Tische oder Buden zum Verkaufen", "zh": "摊位"}, {"w": "Gebühr", "de": "Geld, das man für etwas bezahlt", "zh": "费用"}, {"w": "Flohmarkt", "de": "Markt, auf dem man gebrauchte Sachen verkauft", "zh": "跳蚤市场"}, {"w": "Rohstoffe", "de": "Stoffe aus der Natur, z. B. Erdöl", "zh": "原材料"}], "qs": [{"q": "Was brauchte eine Stadt im Mittelalter für einen Markt?", "qZh": "中世纪的城市要有集市需要什么？", "answer": "Eine Erlaubnis vom Herrscher.", "wrong": ["Ein großes Rathaus.", "Viele Supermärkte."]}, {"q": "Was zahlen Händler für einen Stand auf dem Markt?", "qZh": "商贩在集市摆摊要付什么？", "answer": "Eine Gebühr.", "wrong": ["Steuern an den König.", "Nichts."]}, {"q": "Wer darf auf einem Flohmarkt verkaufen?", "qZh": "谁可以在跳蚤市场上卖东西？", "answer": "Auch Menschen, die sonst keine Händler sind.", "wrong": ["Nur große Firmen.", "Nur Bauern."]}], "src": "改编自 Klexikon《Markt》", "url": "https://klexikon.zum.de/index.php?oldid=160800", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-030", "seg": 9, "title": "Supermarkt", "de": ["Ein Supermarkt ist ein Laden mit vielen verschiedenen Waren. Vor allem findet man dort Waren, die man täglich oder häufig braucht. Das sind vor allem Lebensmittel, aber auch Dinge, um sich zu waschen oder die Wohnung sauber zu halten.", "Schon früher gab es Läden für solche Dinge. Man nannte sie Gemischtwarenläden oder Tante-Emma-Läden. Ein Supermarkt ist aber viel größer. Außerdem bittet man dort nicht einen Verkäufer, einem die Ware zu geben. Man geht durch den Supermarkt und nimmt sich die Dinge, die man kaufen will. Das heißt Selbstbedienung. Es gibt sie etwa seit dem Jahr 1950.", "An der Kasse musste früher eine Angestellte jeden Preis einzeln eintippen. Dann kamen modernere Kassen, die einen Strichcode einscannen können. Das geht für die Angestellten viel schneller. Immer mehr Supermärkte bieten heute sogar Kassen an, an denen der Kunde seine Waren selber einscannen kann. Dazu sollte man ehrlich sein, es gibt aber auch Kontrollen.", "Supermärkte sind meistens keine einzelnen Geschäfte. Ein Supermarkt gehört zu einer Kette von vielen Geschäften derselben Marke, wie Edeka, Aldi oder Migros. Es ist schwierig zu sagen, ab wann es solche Läden gab. In Deutschland setzte sich die Idee etwa um das Jahr 1960 durch, in der Schweiz nur wenig später."], "zh": ["超市是一家商品种类很多的商店。在那里主要能买到每天或经常需要的东西，主要是食品，也有洗漱用品和打扫住处用的东西。", "以前就有卖这些东西的店，叫杂货店或「艾玛阿姨小店」。不过超市要大得多。而且在超市里不用请店员把货递给你，而是自己在超市里走，拿想买的东西。这叫自助服务，大约从 1950 年开始有。", "以前收银台的员工要把每个价格一个一个敲进去。后来有了更现代的收银机，能扫描条形码，员工快多了。如今越来越多的超市甚至提供自助收银台，顾客可以自己扫描商品。用的时候要诚实，不过也会有检查。", "超市大多不是单独一家店，而是属于同一品牌的连锁店，比如 Edeka、Aldi 或 Migros。很难说这种店是从什么时候开始有的。在德国，这个做法大约在 1960 年左右普及，在瑞士稍晚一点。"], "lemmas": [], "gloss": [{"w": "Lebensmittel", "de": "Dinge zum Essen und Trinken", "zh": "食品"}, {"w": "Selbstbedienung", "de": "man nimmt die Waren selbst", "zh": "自助服务"}, {"w": "eintippen", "de": "mit den Fingern auf Tasten schreiben", "zh": "敲入"}, {"w": "Strichcode", "de": "Code aus schwarzen Strichen auf einer Ware", "zh": "条形码"}, {"w": "Kette", "de": "viele Geschäfte mit demselben Namen", "zh": "连锁店"}], "qs": [{"q": "Was findet man vor allem im Supermarkt?", "qZh": "在超市里主要能买到什么？", "answer": "Lebensmittel und Dinge für jeden Tag.", "wrong": ["Autos und Möbel.", "Nur Kleidung."]}, {"q": "Was bedeutet Selbstbedienung?", "qZh": "自助服务是什么意思？", "answer": "Man nimmt sich die Waren selbst.", "wrong": ["Ein Verkäufer bringt alles nach Hause.", "Man bezahlt nicht."]}, {"q": "Was gibt es heute in immer mehr Supermärkten?", "qZh": "如今越来越多的超市有什么？", "answer": "Kassen, an denen Kunden selbst scannen.", "wrong": ["Kassen ohne Strichcode.", "Verkäufer, die alle Preise eintippen."]}], "src": "改编自 Klexikon《Supermarkt》", "url": "https://klexikon.zum.de/index.php?oldid=165353", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-031", "seg": 9, "title": "Laden", "de": ["Ein Laden ist ein Ort, an dem man Dinge kaufen kann. Das können zum Beispiel Lebensmittel oder Elektronik sein. Manche Läden sind auf ein Produkt spezialisiert. Andere Läden verkaufen alles Mögliche. Die Menschen, die in einem Laden arbeiten, nennt man Verkäufer oder Detailhandelsfachleute.", "Der Name Laden kommt daher, dass die Menschen im Mittelalter ein Holzbrett als Ladentheke benutzten. Im Mittelhochdeutschen hieß ein Brett „Latte“ oder „Lade“. Wir haben den Ausdruck heute noch im Begriff „Fensterladen“.", "Früher gingen die Leute vor allem auf dem Markt einkaufen oder pflanzten ihr Essen selber an. Dann kamen erste kleine Läden. Dort ging man zur Theke und die Person hinter der Theke gab einem die Waren. Etwa seit dem Jahr 1950 gibt es überall auf der Welt Läden, in denen die Kunden die Waren selber nehmen und dann an der Kasse bezahlen können. Das bezeichnet man als Selbstbedienungsladen. In den USA gab es diese Läden schon einiges früher. Eines der ersten Unternehmen, die das nach Europa brachten, war die Schweizer Supermarktkette Migros im Jahr 1948.", "Heute gibt es Läden in allen Größen und Varianten. Vom kleinen Marktstand bis hin zu den Hypermärkten in den Industriezonen großer Städte. Seit dem Jahr 2000 werden Läden jedoch weniger besucht als früher. Immer mehr Menschen kaufen stattdessen im Internet ein, weil das bequemer ist."], "zh": ["商店是可以买东西的地方，比如食品或电子产品。有些商店专卖一种产品，有些什么都卖。在商店工作的人叫售货员或零售专业人员。", "Laden 这个名字的来历是：中世纪的人用一块木板当柜台。在中古高地德语里，木板叫 Latte 或 Lade。今天这个说法还保留在 Fensterladen（百叶窗）这个词里。", "以前人们主要去集市买东西，或者自己种吃的。后来出现了最早的小商店。在那里要走到柜台前，柜台后的人把货递给你。大约从 1950 年起，世界各地都有了顾客自己拿货、再到收银台付款的商店，叫自选商店。在美国这种店出现得还要早一些。最早把它带到欧洲的企业之一，是 1948 年的瑞士超市连锁 Migros。", "如今商店大小、种类各式各样，从小小的集市摊位，到大城市工业区里的大卖场。不过从 2000 年起，去商店的人比以前少了。越来越多的人改在网上买东西，因为更方便。"], "lemmas": [], "gloss": [{"w": "spezialisiert", "de": "nur auf eine Sache konzentriert", "zh": "专门（经营）的"}, {"w": "Theke", "de": "Tisch im Laden, über den man die Ware bekommt", "zh": "柜台"}, {"w": "Hypermärkten", "de": "sehr große Supermärkte", "zh": "大卖场"}, {"w": "bequemer", "de": "angenehmer, mit weniger Mühe", "zh": "更方便的"}], "qs": [{"q": "Woher kommt der Name „Laden“?", "qZh": "Laden 这个名字从哪里来？", "answer": "Von einem Holzbrett, das als Theke diente.", "wrong": ["Von einem König im Mittelalter.", "Von einem englischen Wort."]}, {"q": "Welches Unternehmen brachte den Selbstbedienungsladen früh nach Europa?", "qZh": "哪家企业较早把自选商店带到欧洲？", "answer": "Migros.", "wrong": ["Aldi.", "Edeka."]}, {"q": "Warum gehen seit 2000 weniger Menschen in Läden?", "qZh": "为什么从 2000 年起去商店的人少了？", "answer": "Viele kaufen im Internet ein.", "wrong": ["Läden sind verboten.", "Es gibt keine Kassen mehr."]}], "src": "改编自 Klexikon《Laden》", "url": "https://klexikon.zum.de/index.php?oldid=161218", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-032", "seg": 9, "title": "Wirtschaft", "de": ["Wirtschaft nennt man alles, was dazu gehört, dass die Menschen etwas herstellen oder tun, wovon sie leben können. Man sagt auch, dass sie sich etwas erwirtschaften. Wenn jemand mit seinem Beruf Geld verdient, wenn jemand im Laden etwas einkauft, wenn jemand mit einer Fabrik Waren herstellt: Das alles und noch mehr macht die Wirtschaft aus.", "Das Wort Wirt gibt es in der deutschen Sprache schon seit 1200 Jahren. Ein Wirt war der Herr des Hauses oder einer Burg, jemand, der Gäste aufnehmen und schützen konnte. Wirtschaft bedeutete eigentlich Gastfreundschaft. Heute noch nennt man eine Gaststätte oder ein Restaurant auch eine Wirtschaft.", "Ein anderes Wort für Wirtschaft ist Ökonomie. Bei diesem Wort denkt man oft an die Volkswirtschaft, also das Arbeiten, Herstellen, Kaufen und Verkaufen in einem ganzen Land. Oder man spricht von der Weltwirtschaft, davon, wie die Wirtschaft in allen Ländern der Welt funktioniert.", "Wenn es darum geht, einen Haushalt zu führen, sagt man auch Hauswirtschaft. Wer das gelernt hat, weiß, wie man gesund kocht, wie man gut mit Geld umgeht und beim Einkaufen nicht zuviel ausgibt, wie man kleine Dinge im Haushalt repariert und so weiter."], "zh": ["经济，指的是人们为了生活而生产东西或做事的一切。也可以说人们在「挣得」什么。有人靠职业挣钱，有人在商店买东西，有人开工厂生产商品：这些以及更多的事构成了经济。", "Wirt 这个词在德语里已经有 1200 年了。Wirt 原来是一家之主或城堡的主人，能接待并保护客人。Wirtschaft 本来的意思是好客。今天人们仍把饭馆或餐厅叫作 Wirtschaft。", "经济的另一个说法是 Ökonomie。听到这个词，人们常想到国民经济，也就是整个国家里的工作、生产、买和卖。或者人们说世界经济，即世界各国的经济是怎样运作的。", "说到管理一个家庭，也叫家政。学过家政的人知道怎样做健康的饭菜，怎样理财、买东西不乱花钱，怎样修理家里的小东西，等等。"], "lemmas": [], "gloss": [{"w": "erwirtschaften", "de": "durch Arbeit verdienen", "zh": "挣得"}, {"w": "Gastfreundschaft", "de": "wenn man Gäste gern aufnimmt", "zh": "好客"}, {"w": "Gaststätte", "de": "Restaurant oder Kneipe", "zh": "饭馆"}, {"w": "Volkswirtschaft", "de": "die Wirtschaft eines ganzen Landes", "zh": "国民经济"}], "qs": [{"q": "Was bedeutete „Wirtschaft“ ursprünglich?", "qZh": "Wirtschaft 最初的意思是什么？", "answer": "Gastfreundschaft.", "wrong": ["Geld verdienen.", "Fabrik."]}, {"q": "Was meint man mit Volkswirtschaft?", "qZh": "国民经济指什么？", "answer": "Arbeiten, Herstellen, Kaufen und Verkaufen in einem ganzen Land.", "wrong": ["Die Wirtschaft in einer Familie.", "Nur den Handel mit anderen Ländern."]}, {"q": "Was weiß jemand, der Hauswirtschaft gelernt hat?", "qZh": "学过家政的人知道什么？", "answer": "Wie man gesund kocht und gut mit Geld umgeht.", "wrong": ["Wie man eine Fabrik leitet.", "Wie man Aktien kauft."]}], "src": "改编自 Klexikon《Wirtschaft》", "url": "https://klexikon.zum.de/index.php?oldid=158771", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-033", "seg": 9, "title": "Globalisierung", "de": ["Bei der Globalisierung arbeiten die Länder der Welt immer mehr zusammen. Etwas, das vorher nur an einem Ort oder in einem Land erledigt wurde, betrifft nun auch andere Länder oder Kontinente.", "Das Wort Globalisierung wird etwa seit dem Jahr 1990 häufig im Deutschen verwendet. Es kommt vom Globus: Das ist ein Modell der Weltkugel.", "Wenn man in den eigenen Kühlschrank schaut, findet man bereits viele Beispiele für die Globalisierung. Auf den Packungen steht oft, woher ein Lebensmittel kommt. Die Milch stammt vielleicht von Kühen, die in Deutschland, Österreich oder der Schweiz leben. Aber ihr Futter hat der Bauer wahrscheinlich von einem anderen Kontinent her gekauft.", "Auch wenn das Wort neu ist: Schon seit dem Altertum gibt es viel Handel und andere Kontakte zwischen Gegenden, die weit voneinander entfernt liegen. Man wollte in dem einen Land etwas haben, das es nur woanders gab. Oder man fand keine Arbeit und ist dorthin gezogen, wo es Arbeit gab.", "Nicht alle Menschen finden die Globalisierung immer gut. Sie meinen, dass auf diese Weise die reichen Länder die armen Länder besser ausbeuten können, so wie früher die Kolonien. Außerdem würde am Ende alles auf der Welt gleich aussehen: Die Länder und Kulturen würden sich nicht mehr voneinander unterscheiden. Andere Menschen sehen aber die Globalisierung als Chance. Auf diese Weise könnten die Länder voneinander lernen."], "zh": ["全球化就是世界各国越来越多地合作。以前只在一个地方或一个国家做的事，现在也牵涉到别的国家或大洲。", "Globalisierung 这个词大约从 1990 年起在德语里常用。它来自 Globus，也就是地球仪。", "看看自己的冰箱，就能找到很多全球化的例子。包装上常写着食品来自哪里。牛奶也许来自德国、奥地利或瑞士的奶牛，但农民给牛喂的饲料很可能是从别的大洲买来的。", "虽然这个词是新的，但从古代起，相距很远的地区之间就已经有很多贸易和其他往来。人们想要一样只在别处才有的东西；或者在本地找不到工作，就搬到有工作的地方去。", "并不是所有人都总觉得全球化是好事。他们认为，这样富国能更好地剥削穷国，就像以前对殖民地那样。而且最后世界上一切都会变得一样：国家和文化之间再也没有区别。但也有人把全球化看成机会，认为各国可以借此相互学习。"], "lemmas": [], "gloss": [{"w": "Kontinente", "de": "große Teile der Erde, z. B. Asien, Afrika", "zh": "大洲"}, {"w": "Futter", "de": "Essen für Tiere", "zh": "饲料"}, {"w": "Altertum", "de": "sehr alte Zeit, z. B. bei den Römern", "zh": "古代"}, {"w": "ausbeuten", "de": "andere für sich arbeiten lassen und ihnen wenig geben", "zh": "剥削"}, {"w": "Kolonien", "de": "Länder, die von einem anderen Land beherrscht wurden", "zh": "殖民地"}], "qs": [{"q": "Woher kommt das Wort Globalisierung?", "qZh": "Globalisierung 这个词从哪里来？", "answer": "Vom Globus, einem Modell der Erde.", "wrong": ["Von einer Firma aus den USA.", "Von einem lateinischen Wort für Handel."]}, {"q": "Welches Beispiel für Globalisierung findet man im Kühlschrank?", "qZh": "冰箱里能找到哪个全球化的例子？", "answer": "Das Futter der Kühe kommt von einem anderen Kontinent.", "wrong": ["Die Milch kommt immer aus China.", "Der Kühlschrank ist aus Holz."]}, {"q": "Was befürchten Kritiker der Globalisierung?", "qZh": "批评全球化的人担心什么？", "answer": "Dass alles auf der Welt gleich aussieht.", "wrong": ["Dass es zu viele Kulturen gibt.", "Dass Länder nicht mehr handeln."]}], "src": "改编自 Klexikon《Globalisierung》", "url": "https://klexikon.zum.de/index.php?oldid=151666", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-034", "seg": 9, "title": "Fairer Handel", "de": ["Beim fairen Handel sollen die Hersteller einer Ware einen gerechten Preis dafür bekommen. Meist sind die Hersteller Bauern oder Handwerker in armen Ländern in Afrika, Südamerika oder in Asien. Ursprünglich ging es vor allem um Bananen, Kaffee und Kakao. Oft brauchen wir den englischen Ausdruck.", "Viele Bauern arbeiten heute noch hart, lange und fast immer von Hand. Sie verkaufen ihre Waren an Händler, die die Waren in reiche Länder bringen und sie dort verkaufen. Beim herkömmlichen Handel erhalten die Bauern aber oft so wenig Geld, dass sie kaum davon leben können. Der Handel verdient dabei sehr viel. Für die Käufer sind die Produkte trotzdem nicht unbedingt billig, weil viel Geld im Handel steckenbleibt.", "Damit diese Bauern genug zu essen haben, muss deshalb meist die ganze Familie mithelfen. So kommt es auch zu Kinderarbeit. Die Kinder können dann oft nicht zur Schule gehen und können deshalb auch als Erwachsene der Armut nicht entfliehen.", "In Europa störten sich in den Jahren ab 1960 immer mehr Gruppen von Menschen am unfairen Handel. Sie begannen deshalb selber, die Waren bei den Bauern einzukaufen und verkauften sie bei uns. Sie eröffneten auch eigene Geschäfte, die anfangs „Dritte-Welt-Läden“ hießen. Heute nennt man sie „Weltläden“. Die Produkte werden oft auch in Naturkostläden und zunehmend in den üblichen Supermärkten verkauft.", "Interessant daran ist: Wenn man einem Bauern den doppelten Lohn bezahlt, werden beispielsweise Kaffee oder Bananen nur um einige Cent teurer. Die Preise für den Transport, die Ladenmieten und das Personal im Verkauf erhöhen sich nämlich nicht. Ein Paar Turnschuhe würde nur etwa um einen Euro teurer."], "zh": ["公平贸易就是要让商品的生产者得到合理的价格。生产者大多是非洲、南美或亚洲穷国的农民或手艺人。最初主要涉及香蕉、咖啡和可可。人们也常用英语说法（Fair Trade）。", "很多农民至今仍然辛苦地长时间劳动，而且几乎全靠手工。他们把货卖给商人，商人把货运到富国去卖。但在传统贸易中，农民拿到的钱常常少得几乎无法生活，商人却赚得很多。对买家来说，这些产品也不一定便宜，因为很多钱卡在了贸易环节里。", "为了让这些农民吃得饱，常常全家都要帮忙，于是就有了童工。这些孩子常常不能上学，长大后也就无法摆脱贫困。", "从 1960 年起，欧洲越来越多的团体对不公平贸易感到不满。他们开始自己直接从农民那里买货，拿到我们这里来卖。他们还开了自己的店，最初叫「第三世界商店」，现在叫「世界商店」。这些产品也常在有机食品店里卖，越来越多地也进入了普通超市。", "有意思的是：如果付给农民双倍工钱，咖啡或香蕉只贵几分钱。因为运输、店铺租金和销售人员的费用并不会增加。一双运动鞋大约只贵一欧元。"], "lemmas": [], "gloss": [{"w": "gerechten", "de": "fair, so wie es richtig ist", "zh": "公正的、合理的"}, {"w": "herkömmlichen", "de": "normal, wie bisher üblich", "zh": "传统的"}, {"w": "entfliehen", "de": "von etwas wegkommen", "zh": "摆脱"}, {"w": "Naturkostläden", "de": "Läden für Bio-Lebensmittel", "zh": "有机食品店"}], "qs": [{"q": "Wer soll beim fairen Handel einen gerechten Preis bekommen?", "qZh": "公平贸易中谁应该得到合理价格？", "answer": "Die Bauern und Handwerker, die die Ware herstellen.", "wrong": ["Die großen Supermärkte.", "Die Käufer in reichen Ländern."]}, {"q": "Warum kommt es bei armen Bauern zu Kinderarbeit?", "qZh": "贫穷的农民家里为什么会出现童工？", "answer": "Die ganze Familie muss mithelfen, damit alle genug essen.", "wrong": ["Die Kinder wollen nicht zur Schule.", "Kinder verdienen mehr als Erwachsene."]}, {"q": "Wie viel teurer wird Kaffee, wenn der Bauer doppelt so viel bekommt?", "qZh": "农民拿到双倍工钱，咖啡会贵多少？", "answer": "Nur einige Cent.", "wrong": ["Doppelt so teuer.", "Zehn Euro mehr."]}], "src": "改编自 Klexikon《Fairer Handel》", "url": "https://klexikon.zum.de/index.php?oldid=155732", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-035", "seg": 9, "title": "Import und Export", "de": ["Importe sind Waren, die aus dem Ausland ins eigene Land gebracht und dann verkauft werden. Wenn Dinge ins Ausland verkauft werden, spricht man vom Export. Wenn die Handelswaren keine Landesgrenzen überschreiten, nennt man das Binnenwirtschaft. Manche Länder importieren eher, andere exportieren eher. Das Land, das heute am meisten exportiert, ist China, gefolgt von Deutschland und den USA.", "Viele Länder stellen bestimmte Waren besonders gut oder besonders billig her. Deshalb wollen viele Menschen in anderen Ländern solche Waren von dort kaufen. Einige Schweizer Unternehmen zum Beispiel können besonders gute Turbinen für Kraftwerke bauen. Die exportieren sie in viele andere Länder. Den Stahl dazu haben sie aber nicht aus dem eigenen Land. Den müssen sie aus dem Ausland importieren.", "Manche Dinge gibt es nur in bestimmten Ländern. Bananen, Kaffee oder Kakao wachsen nur in warmen Ländern. Zudem braucht es viel Handarbeit, bis diese Produkte zum Versand bereit sind und exportiert werden können. Oft bezahlen die Importländer dann auch für diese Waren keinen fairen Preis, deshalb bleiben viele arme Länder arm. Dies gilt auch für viele andere Rohstoffe, die aus dem Bergbau kommen.", "Europa importiert auch sehr viel Energie, also Erdöl aus dem Nahen Osten oder Erdgas aus Russland. Eine Ausnahme bilden zum Beispiel die Niederlande mit ihren eigenen Gasfeldern. Dadurch wurde Europa von diesen Ländern abhängig: Sie können den Öl- oder Gashahn auch zudrehen. Dann steht unsere Industrie still, wir können nicht mehr heizen und Auto fahren."], "zh": ["进口是把外国的商品运到本国来卖。把东西卖到国外，就叫出口。如果商品不跨越国界，就叫国内经济。有些国家进口多一些，有些出口多一些。如今出口最多的国家是中国，其次是德国和美国。", "很多国家某些商品做得特别好或特别便宜，所以其他国家的很多人想从那里买。比如一些瑞士企业很会造发电厂用的涡轮机，出口到很多国家。但造涡轮机的钢材不是本国产的，必须从国外进口。", "有些东西只有某些国家才有。香蕉、咖啡或可可只长在温暖的国家。而且要靠大量手工劳动，这些产品才能准备好发货出口。进口国常常也不给这些商品公平的价格，所以很多穷国一直很穷。很多来自采矿业的原材料也是这样。", "欧洲还进口大量能源，比如中东的石油或俄罗斯的天然气。荷兰有自己的气田，算是例外。这样欧洲就依赖这些国家了：他们也可以关掉石油或天然气的阀门。那样我们的工业就会停摆，我们就没法取暖、没法开车。"], "lemmas": [], "gloss": [{"w": "Landesgrenzen", "de": "Grenzen zwischen Ländern", "zh": "国界"}, {"w": "Turbinen", "de": "Maschinen, die in Kraftwerken Strom machen", "zh": "涡轮机"}, {"w": "Versand", "de": "das Verschicken von Waren", "zh": "发货"}, {"w": "abhängig", "de": "braucht etwas von jemandem", "zh": "依赖的"}, {"w": "zudrehen", "de": "schließen, z. B. einen Hahn", "zh": "关上"}], "qs": [{"q": "Was ist ein Export?", "qZh": "出口是什么？", "answer": "Dinge, die ins Ausland verkauft werden.", "wrong": ["Waren aus dem Ausland.", "Handel nur im eigenen Land."]}, {"q": "Woher holen Schweizer Firmen den Stahl für ihre Turbinen?", "qZh": "瑞士企业造涡轮机的钢材从哪里来？", "answer": "Aus dem Ausland.", "wrong": ["Aus der Schweiz.", "Sie brauchen keinen Stahl."]}, {"q": "Warum ist Europa von anderen Ländern abhängig?", "qZh": "为什么欧洲依赖其他国家？", "answer": "Es importiert viel Erdöl und Erdgas.", "wrong": ["Es exportiert zu viele Bananen.", "Es hat zu viele Gasfelder."]}], "src": "改编自 Klexikon《Import und Export》", "url": "https://klexikon.zum.de/index.php?oldid=157700", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-036", "seg": 9, "title": "Werbung", "de": ["Werbung ist eine Art, wie man zu anderen Menschen spricht. Werbung soll Menschen dazu bringen, dass sie über etwas anders denken als vorher. Vor allem geht es darum, dass die Menschen etwas kaufen.", "Die Werbung erzählt den Menschen etwas über das, was verkauft wird. Zunächst einmal muss der Werbende bekannt machen, dass es die Ware oder Dienstleistung überhaupt gibt. Am besten sagt man das denjenigen Menschen, die es überhaupt brauchen können. Wer zum Beispiel keine Kinder hat, würde sich keinen Kinderwagen kaufen. Das nennt man spezifische oder kundenbezogene Werbung.", "Außerdem lobt die Werbung die Ware oder die Dienstleistung: Es gibt nämlich meistens noch andere Hersteller oder Dienstleister, die dasselbe anbieten. Werbung behauptet daher, dass die eigene Ware oder Dienstleistung besser sei als die der anderen Hersteller oder Dienstleister.", "Die Werbenden arbeiten mit Botschaften, die den Menschen sagen, was sie tun sollen, zum Beispiel: Kaufe diese Ware. Diese Botschaft kann ein Text sein, also Wörter oder meist ganze Sätze. Oft kommt ein Bild dazu, oder es wird ein kurzer Film gedreht.", "Die Werbung muss dann verbreitet werden. Normalerweise bezahlt der Werbende dafür, in Form einer Anzeige. Das ist zum Beispiel eine Seite in einer Zeitung oder Zeit für einen Werbefilm im Fernsehen. Man kann auch eine Plakatfläche an der Straße mieten. Es gibt viele Orte für Werbung."], "zh": ["广告是对别人说话的一种方式。广告要让人们对某样东西的看法和以前不一样。最主要的是让人们买东西。", "广告向人们介绍要卖的东西。首先，做广告的人要让人知道有这种商品或服务。最好告诉那些真正用得上的人。比如没有孩子的人不会买婴儿车。这叫定向广告或针对顾客的广告。", "此外，广告还夸赞商品或服务：因为通常还有别的生产者或服务商提供同样的东西。所以广告会说自家的商品或服务比别人的好。", "做广告的人用信息告诉人们该做什么，比如：买这个商品。信息可以是文字，也就是词语，大多是完整的句子。常常还配上图片，或者拍一段短片。", "然后广告必须传播出去。通常做广告的人要为此付钱，形式是广告位，比如报纸上的一页，或者电视里播广告片的时段。也可以租街边的广告牌。做广告的地方很多。"], "lemmas": [], "gloss": [{"w": "Dienstleistung", "de": "Arbeit, die man für Kunden macht", "zh": "服务"}, {"w": "Kinderwagen", "de": "Wagen, in dem man ein Baby schiebt", "zh": "婴儿车"}, {"w": "behauptet", "de": "sagt, dass etwas so ist", "zh": "声称"}, {"w": "Botschaften", "de": "Nachrichten, die etwas sagen wollen", "zh": "信息"}, {"w": "Anzeige", "de": "bezahlte Werbung in Zeitung oder Fernsehen", "zh": "广告（位）"}], "qs": [{"q": "Was ist das wichtigste Ziel von Werbung?", "qZh": "广告最主要的目的是什么？", "answer": "Dass die Menschen etwas kaufen.", "wrong": ["Dass die Menschen mehr lesen.", "Dass Firmen weniger verkaufen."]}, {"q": "Was ist kundenbezogene Werbung?", "qZh": "针对顾客的广告是什么？", "answer": "Werbung für die Menschen, die etwas wirklich brauchen können.", "wrong": ["Werbung nur im Fernsehen.", "Werbung ohne Bilder."]}, {"q": "Wofür bezahlt man bei einer Anzeige zum Beispiel?", "qZh": "比如登广告是为什么付钱？", "answer": "Für eine Seite in einer Zeitung.", "wrong": ["Für einen Besuch beim Friseur.", "Für einen Kinderwagen."]}], "src": "改编自 Klexikon《Werbung》", "url": "https://klexikon.zum.de/index.php?oldid=168458", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-037", "seg": 9, "title": "Post", "de": ["Die Post ist ein Unternehmen, das Briefe und andere Postsachen befördert. Mit Post kann auch das Postwesen an sich gemeint sein. In den meisten Ländern gibt oder gab es ein bestimmtes Unternehmen, das Post befördern durfte. Oft war das ein Unternehmen, das dem Staat gehörte.", "Wer im Mittelalter einen Brief verschicken wollte, musste dafür viel Geld zahlen. Man schickte einen Boten mit dem Brief auf den Weg zum Empfänger. Der Sender, also derjenige, der den Brief geschrieben hatte, musste die Reise des Boten bezahlen.", "Vor etwa 500 Jahren gründete man die ersten Postunternehmen. In den deutschen Ländern war vor allem die Adelsfamilie Thurn und Taxis wichtig. Ihr Unternehmen hatte an vielen Orten Stationen. Dort gab man einen Brief ab und zahlte für das Versenden. Die Boten von Thurn und Taxis nahmen immer mehrere Briefe mit. Das machte alles etwas günstiger.", "In den Jahren nach 1800 begannen manche Staaten, sich selbst um die Post zu kümmern. Seitdem durfte nur noch die Post des Staates Briefe befördern. Die staatliche Post hatte also ein Monopol. Sie stellte überall Briefkästen auf und stellte Briefträger ein.", "Außerdem gründete man den Weltpostverein, im Jahr 1874. Fast alle Staaten wurden darin Mitglied. Sie einigten sich auf Regeln, wie man Postsachen von einem Land ins andere befördert. Für die Bezahlung setzte man Briefmarken ein."], "zh": ["邮政是一家运送信件和其他邮件的企业。「邮政」也可以指整个邮政事业。在大多数国家，过去或现在都有一家专门允许运送邮件的企业，它常常归国家所有。", "中世纪谁想寄信，得花很多钱。人们派一名信差带着信去找收信人。寄信人，也就是写信的人，要承担信差路上的费用。", "大约 500 年前，人们创办了最早的邮政企业。在德意志各国，最重要的是贵族家族图恩和塔克西斯。他们的企业在很多地方设有驿站，人们在那里交信并付邮费。图恩和塔克西斯的信差总是一次带好几封信，这让一切都便宜了一些。", "1800 年以后的几年里，一些国家开始自己管理邮政。从此只有国家邮政才能运送信件，国家邮政就有了垄断地位。它在各处设立邮筒，并雇用邮递员。", "此外，1874 年成立了万国邮政联盟，几乎所有国家都加入了。各国就如何在国与国之间运送邮件商定了规则，并用邮票来付费。"], "lemmas": [], "gloss": [{"w": "befördert", "de": "von einem Ort zum anderen bringen", "zh": "运送"}, {"w": "Boten", "de": "Menschen, die eine Nachricht bringen", "zh": "信差"}, {"w": "Empfänger", "de": "jemand, der etwas bekommt", "zh": "收件人"}, {"w": "Monopol", "de": "nur einer darf etwas verkaufen oder anbieten", "zh": "垄断"}, {"w": "Briefträger", "de": "jemand, der Briefe zu den Häusern bringt", "zh": "邮递员"}], "qs": [{"q": "Wer musste im Mittelalter die Reise des Boten bezahlen?", "qZh": "中世纪谁要支付信差的路费？", "answer": "Der Sender des Briefes.", "wrong": ["Der Empfänger.", "Der König."]}, {"q": "Warum wurde das Versenden bei Thurn und Taxis günstiger?", "qZh": "为什么图恩和塔克西斯寄信更便宜了？", "answer": "Die Boten nahmen immer mehrere Briefe mit.", "wrong": ["Die Briefe waren kürzer.", "Der Staat bezahlte alles."]}, {"q": "Was setzte man beim Weltpostverein für die Bezahlung ein?", "qZh": "万国邮政联盟用什么付费？", "answer": "Briefmarken.", "wrong": ["Münzen aus Gold.", "Bankkarten."]}], "src": "改编自 Klexikon《Post》", "url": "https://klexikon.zum.de/index.php?oldid=152481", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-038", "seg": 9, "title": "Hotel", "de": ["Ein Hotel ist ein Gebäude mit vielen Zimmern. In diesen Zimmern kann man gegen Bezahlung eine oder mehrere Nächte lang schlafen. Das macht man zum Beispiel, wenn man an einem Ort im Urlaub ist oder wenn man geschäftlich unterwegs ist.", "Neben den Hotelzimmern haben viele Hotels noch ein Restaurant, wo man etwas essen kann. Häufig ist im Preis für die Übernachtung ein Frühstück inbegriffen. Das Abendessen im Restaurant wird in der Regel separat bezahlt.", "Nicht alle Hotels sind gleich teuer und gleich gut. Um zu sehen, wie gut ein Hotel ausgestattet ist, gibt es ein Bewertungssystem mit eins bis fünf Sternen. Fünf ist das beste und eins das schlechteste.", "Früher buchte man sein Hotel über ein Reisebüro. Heute buchen die meisten Leute mit dem Internet. Das geht direkt beim Hotel oder über eine Website für Buchungen, die dafür Geld vom Hotel erhält."], "zh": ["旅馆是一栋有很多房间的建筑。付钱就可以在这些房间里睡一晚或几晚。比如在某地度假或出差时，人们就会住旅馆。", "除了客房，很多旅馆还有餐厅，可以在那里吃饭。住宿费里常常包含早餐，餐厅的晚饭一般另外付钱。", "旅馆并不都一样贵、一样好。为了看出一家旅馆设施有多好，有一套一到五星的评级制度。五星最好，一星最差。", "以前人们通过旅行社订旅馆。如今大多数人在网上订，可以直接向旅馆订，也可以通过预订网站订，网站会从旅馆那里收钱。"], "lemmas": [], "gloss": [{"w": "geschäftlich", "de": "wegen der Arbeit", "zh": "因公、出差"}, {"w": "Übernachtung", "de": "eine Nacht schlafen in einem Hotel", "zh": "住宿"}, {"w": "inbegriffen", "de": "schon im Preis dabei", "zh": "包含在内的"}, {"w": "ausgestattet", "de": "mit Dingen versehen", "zh": "配备的"}, {"w": "Reisebüro", "de": "Firma, die Reisen verkauft", "zh": "旅行社"}], "qs": [{"q": "Was ist oft im Preis für die Übernachtung inbegriffen?", "qZh": "住宿费里常常包含什么？", "answer": "Ein Frühstück.", "wrong": ["Das Abendessen.", "Eine Stadtführung."]}, {"q": "Was zeigen die Sterne bei einem Hotel?", "qZh": "旅馆的星级表示什么？", "answer": "Wie gut ein Hotel ausgestattet ist.", "wrong": ["Wie alt das Hotel ist.", "Wie viele Zimmer es hat."]}, {"q": "Wie buchen die meisten Leute heute ein Hotel?", "qZh": "如今大多数人怎样订旅馆？", "answer": "Im Internet.", "wrong": ["Per Brief.", "Nur im Reisebüro."]}], "src": "改编自 Klexikon《Hotel》", "url": "https://klexikon.zum.de/index.php?oldid=160796", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-039", "seg": 9, "title": "Restaurant", "de": ["Ein Restaurant ist ein Ort, an dem man gegen Bezahlung etwas essen kann. Das Wort kommt ursprünglich aus der französischen Sprache. Das Verb „se restaurer“ heißt „sich stärken“. Das Restaurant ist also ein Ort, an dem man etwas isst, um Energie zu tanken.", "Weil es manchmal schwierig ist, das richtige Restaurant auszusuchen, hat man sich viele Arten ausgedacht es zu bewerten. Am bekanntesten ist die Bewertung mit Sternen. Wenn ein Restaurant einen Stern hat, hat es bereits eine gehobene Küche. Zwei Sterne sind noch besser. Ein Restaurant mit drei Sternen ist ein Luxus-Restaurant. Des Weiteren gibt es viele Internetseiten, in denen Gäste über ihren Besuch in einem Restaurant schreiben können.", "Es gibt viele verschiedene Arten von Restaurants. Ein allgemeines Wort ist Gaststätte. In einem Café zum Beispiel ging es früher vor allem darum, dass man Kaffee und vielleicht auch Kuchen bekam. Heute erhält man dort aber auch andere Speisen, so dass man nicht mehr genau sagen kann, was ein Restaurant und was ein Café ist.", "In einem Schnellrestaurant muss es vor allem schnell gehen. Gekocht werden einfache Speisen wie Pizza, Bratwurst, Hamburger oder Pommes frites. Meistens bestellt man diese an einer Theke und holt sie dort auch selber ab. Die meisten Schnellrestaurants bieten auch an, dass man die Speisen mitnehmen kann. Das nennt man „Take Away“."], "zh": ["餐厅是付钱就能吃饭的地方。这个词最早来自法语，动词 se restaurer 意思是「增强体力」。所以餐厅就是人们吃东西补充能量的地方。", "因为挑选合适的餐厅有时不容易，人们想出了很多评价方法。最有名的是星级评价。一家餐厅有一颗星，就已经是高档餐厅了。两颗星更好，三星餐厅是豪华餐厅。另外还有很多网站，顾客可以在上面写自己去餐厅的体验。", "餐厅有很多种。一个总称是 Gaststätte（饭馆）。比如在咖啡馆里，以前主要是喝咖啡，也许再吃块蛋糕。但如今在那里也能吃到别的东西，所以已经说不清什么是餐厅、什么是咖啡馆了。", "在快餐店里最重要的是快。做的是比萨、煎香肠、汉堡或薯条这类简单食物。一般在柜台点餐，也在那里自己取餐。大多数快餐店也可以把食物带走，这叫「外带」。"], "lemmas": [], "gloss": [{"w": "Energie zu tanken", "de": "neue Kraft bekommen", "zh": "补充能量"}, {"w": "bewerten", "de": "sagen, wie gut etwas ist", "zh": "评价"}, {"w": "gehobene", "de": "besonders gut und teuer", "zh": "高档的"}, {"w": "Speisen", "de": "Essen, Gerichte", "zh": "饭菜"}], "qs": [{"q": "Was bedeutet das französische Verb „se restaurer“?", "qZh": "法语动词 se restaurer 是什么意思？", "answer": "Sich stärken.", "wrong": ["Sich ausruhen.", "Sich treffen."]}, {"q": "Was bedeutet es, wenn ein Restaurant drei Sterne hat?", "qZh": "餐厅有三颗星意味着什么？", "answer": "Es ist ein Luxus-Restaurant.", "wrong": ["Es ist ein Schnellrestaurant.", "Es hat drei Köche."]}, {"q": "Was bedeutet „Take Away“?", "qZh": "「外带」是什么意思？", "answer": "Man nimmt das Essen mit.", "wrong": ["Man isst im Restaurant.", "Man bezahlt nicht."]}], "src": "改编自 Klexikon《Restaurant》", "url": "https://klexikon.zum.de/index.php?oldid=163879", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-040", "seg": 9, "title": "Organisation", "de": ["Eine Organisation sorgt dafür, dass Ideen entstehen und etwas getan wird. Das Wort kommt, genau wie Organ, vom griechischen Wort für Werkzeug. Manchmal meint man mit Organisation eine Gruppe von Menschen, manchmal das, was sie tun.", "Eine Organisation kann ein Verein, ein Unternehmen oder auch die Vereinten Nationen oder das Rote Kreuz sein. Es sind Gruppen von Menschen, die dieselben Ziele haben. Solche Gruppen kommen aber nicht einfach so zusammen: Eine Organisation hat einen Namen, feste Regeln und Aufgaben.", "Gemeint kann auch ein Teil eines Vereins oder eines Unternehmens sein: Die Organisation sind dann diejenigen, die organisieren, die Menschen, die sich um etwas kümmern. So spricht man von der Organisation eines Treffens. Wenn die Organisation gut war, soll das bedeuten, dass die Organisatoren gut gearbeitet haben und das Treffen allen gefallen hat.", "Gehört eine Organisation zum Staat, dann nennt man sie Behörde. Ein Ministerium ist eine Behörde, genau wie ein Geheimdienst oder das Gesundheitsamt in einer Stadt. Die Behörde kümmert sich um die Verwaltung im Land oder in der Stadt.", "Menschen in einer Organisation müssen genau wissen, was sie tun sollen. Es gibt jemanden, der bestimmen kann, wer was macht. Schließlich überprüft jemand, ob die Organisation auch das leistet, wofür sie da ist."], "zh": ["组织让想法产生、让事情得以完成。这个词和 Organ（器官）一样，来自希腊语中表示「工具」的词。Organisation 有时指一群人，有时指他们所做的事。", "组织可以是一个协会、一家企业，也可以是联合国或红十字会。它们是目标相同的一群人。但这样的团体不是随便凑在一起的：一个组织有名字、固定的规则和任务。", "Organisation 也可以指协会或企业的一部分：这时它指的是组织者，即负责某件事的人。比如说一次聚会的组织工作。如果说组织得好，意思是组织者干得不错，聚会让大家都满意。", "属于国家的组织叫机关。部委是机关，情报部门或城市的卫生局也是。机关负责国家或城市的行政管理。", "组织里的人必须清楚知道自己该做什么。要有人决定谁做什么。最后还要有人检查，这个组织是否完成了它该做的事。"], "lemmas": [], "gloss": [{"w": "Werkzeug", "de": "Gerät für eine Arbeit, z. B. ein Hammer", "zh": "工具"}, {"w": "Vereinten Nationen", "de": "Organisation fast aller Länder der Welt (UNO)", "zh": "联合国"}, {"w": "Behörde", "de": "Amt des Staates", "zh": "机关"}, {"w": "Verwaltung", "de": "Organisation von Aufgaben in Staat oder Firma", "zh": "行政管理"}], "qs": [{"q": "Was hat eine Organisation laut Text?", "qZh": "根据文章，组织有什么？", "answer": "Einen Namen, feste Regeln und Aufgaben.", "wrong": ["Immer viel Geld.", "Nur ein Mitglied."]}, {"q": "Wie nennt man eine Organisation, die zum Staat gehört?", "qZh": "属于国家的组织叫什么？", "answer": "Behörde.", "wrong": ["Verein.", "Unternehmen."]}, {"q": "Was bedeutet es, wenn die Organisation eines Treffens gut war?", "qZh": "说一次聚会组织得好是什么意思？", "answer": "Die Organisatoren haben gut gearbeitet.", "wrong": ["Das Treffen war sehr kurz.", "Niemand ist gekommen."]}], "src": "改编自 Klexikon《Organisation》", "url": "https://klexikon.zum.de/index.php?oldid=157993", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-041", "seg": 9, "title": "Verein", "de": ["Ein Verein ist eine Gruppe von Menschen. So eine Gruppe besteht aus mindestens zwei Menschen. Sie wollen gemeinsam dasselbe erreichen oder tun. Einen Verein soll es dauerhaft geben, nicht nur für eine kurze Zeit. Die Menschen im Verein heißen Mitglieder.", "Menschen gründen Vereine, um gemeinsam etwas zu tun. Sie wollen zum Beispiel Sport treiben, Geld für arme Leute sammeln oder die Stadt schöner machen. Alleine würden die Menschen nicht so viel erreichen.", "Wer in Deutschland einen gewöhnlichen eingetragenen Verein gründen will, muss sich an Regeln halten. Der Verein muss vor allem ein gemeinsames Ziel verfolgen, zum Beispiel den Sport fördern. Geld zu verdienen darf dabei nicht sein Hauptzweck sein.", "Bei einer Mitgliederversammlung dürfen alle Mitglieder mitmachen. Die Versammlung stimmt über die wichtigsten Dinge ab. Zum Beispiel kann sie entscheiden, wie viel Geld man für die Mitgliedschaft zahlen muss.", "Sie wählt auch einen Vorstand. Der Vorstand vertritt den Verein nach außen. Er muss unter anderem einen Plan machen, wie der Verein an Geld kommt und wofür der Verein es ausgibt.", "In den meisten Vereinen müssen die Mitglieder jedes Jahr Geld dafür bezahlen, dass sie Mitglied sein dürfen. Diese Vereinsbeiträge oder Mitgliedsbeiträge sind für viele Vereine besonders wichtig. Außerdem bitten Vereine um Spenden: Eine Spende ist Geld, das jemand freiwillig gibt, weil er den Verein gut findet."], "zh": ["协会是一群人，至少由两个人组成。他们想一起达到同一个目标或做同一件事。协会应该长期存在，而不只是短时间的。协会里的人叫会员。", "人们成立协会是为了一起做事。比如他们想一起运动、为穷人募捐，或者让城市更美。一个人单干就做不了这么多。", "在德国，想成立一个普通的注册协会，必须遵守规则。协会首先必须追求一个共同目标，比如促进体育运动。挣钱不能是它的主要目的。", "所有会员都可以参加会员大会。大会对最重要的事情进行表决，比如可以决定会费交多少。", "会员大会还选出理事会。理事会对外代表协会。它还要制定计划：协会怎样筹钱、钱用在哪里。", "大多数协会的会员每年都要交钱才能保留会员资格。这种会费对很多协会特别重要。此外协会也请求捐款：捐款是有人因为觉得协会好而自愿给的钱。"], "lemmas": [], "gloss": [{"w": "dauerhaft", "de": "für lange Zeit", "zh": "长期的"}, {"w": "Mitglieder", "de": "Menschen, die zu einer Gruppe gehören", "zh": "会员"}, {"w": "Mitgliederversammlung", "de": "Treffen aller Mitglieder", "zh": "会员大会"}, {"w": "Vorstand", "de": "Gruppe, die einen Verein leitet", "zh": "理事会"}, {"w": "Spenden", "de": "Geld, das man freiwillig gibt", "zh": "捐款"}], "qs": [{"q": "Wie viele Menschen braucht ein Verein mindestens?", "qZh": "协会至少需要几个人？", "answer": "Zwei.", "wrong": ["Zehn.", "Hundert."]}, {"q": "Was darf nicht der Hauptzweck eines eingetragenen Vereins sein?", "qZh": "注册协会的主要目的不能是什么？", "answer": "Geld zu verdienen.", "wrong": ["Sport zu fördern.", "Etwas gemeinsam zu tun."]}, {"q": "Wer entscheidet, wie viel man für die Mitgliedschaft zahlt?", "qZh": "谁决定会费交多少？", "answer": "Die Mitgliederversammlung.", "wrong": ["Das Gericht.", "Der Bürgermeister."]}], "src": "改编自 Klexikon《Verein》", "url": "https://klexikon.zum.de/index.php?oldid=168881", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-042", "seg": 9, "title": "Ehrenamt", "de": ["Ein Ehrenamt ist eine Arbeit, für die man meistens kein Geld bekommt. Man tut stattdessen etwas Gutes für die Gesellschaft. Die Arbeit, die man dabei tut, wird als ehrenamtliche Arbeit bezeichnet. In ein Ehrenamt wird man gewählt. Wenn jemand ohne Wahl kostenlos für andere arbeitet, nennt man das „freiwillige Arbeit“ oder „Freiwilligenarbeit“.", "Früher bezeichnete man vor allem Ämter in der Politik als Ehrenamt. Auch in Vereinen oder in Stiftungen arbeiten viele Menschen ehrenamtlich. Oft unterscheidet man nicht genau zwischen Ehrenamt und Freiwilligenarbeit. Es gibt zum Beispiel Wahlhelfer, die Werbematerial für die Wahl eines neuen Präsidenten verteilen, oder Leute, die von Tür zu Tür gehen, um Spenden für arme Menschen zu sammeln. Viele gutmütige Menschen besuchen auch alte oder kranke Menschen in einem Heim oder Krankenhaus. Das ist eher Freiwilligenarbeit.", "Manche Ehrenämter sind nur für eine bestimmte Zeit da. Andere sind regelmäßige Tätigkeiten, wie beispielsweise eine freiwillige Feuerwehr. Ohne die vielen Menschen, die freiwillig oder ehrenamtlich etwas arbeiten, würden viele Dinge nicht richtig funktionieren.", "Etwa jeder Dritte in Deutschland erledigt ehrenamtliche oder freiwillige Arbeit. Mehr als die Hälfte davon sind Frauen. Viele sind auch Rentner, weil sie keine Zeit mehr darauf verwenden müssen, ihren Lebensunterhalt zu verdienen. Wer sich neben der Arbeit ehrenamtlich einbringen will, muss das in Deutschland angeben und manchmal braucht es auch vom Staat eine Erlaubnis dafür."], "zh": ["志愿职务是一种大多拿不到钱的工作。人们做这件事，是为社会做好事。做的这种工作叫荣誉性工作。志愿职务是选出来的。如果有人没有经过选举、免费为别人工作，就叫「自愿工作」或「志愿者工作」。", "以前主要把政治方面的职务叫作 Ehrenamt。在协会或基金会里也有很多人做义务工作。人们常常不严格区分志愿职务和志愿者工作。比如有选举帮手为新总统选举发宣传材料，也有人挨家挨户为穷人募捐。很多好心人还去养老院或医院看望老人和病人，这更算是志愿者工作。", "有些志愿职务只在一段时间内存在，另一些是长期固定的工作，比如志愿消防队。如果没有这么多自愿或义务工作的人，很多事情就无法正常运转。", "德国大约每三个人里就有一个在做义务或志愿工作，其中一半以上是女性。很多也是退休的人，因为他们不必再花时间挣钱养活自己。在德国，想在工作之余做义务工作的人，必须申报，有时还需要国家的许可。"], "lemmas": [], "gloss": [{"w": "Stiftungen", "de": "Organisationen, die Geld für einen guten Zweck geben", "zh": "基金会"}, {"w": "gutmütige", "de": "freundlich und hilfsbereit", "zh": "好心的"}, {"w": "Feuerwehr", "de": "Leute, die Feuer löschen", "zh": "消防队"}, {"w": "Lebensunterhalt", "de": "Geld, das man zum Leben braucht", "zh": "生计"}], "qs": [{"q": "Was ist der Unterschied zwischen Ehrenamt und freiwilliger Arbeit?", "qZh": "志愿职务和自愿工作有什么区别？", "answer": "In ein Ehrenamt wird man gewählt.", "wrong": ["Für ein Ehrenamt bekommt man viel Geld.", "Freiwillige Arbeit ist verboten."]}, {"q": "Welches Beispiel für ein regelmäßiges Ehrenamt nennt der Text?", "qZh": "文章举了哪个长期志愿职务的例子？", "answer": "Die freiwillige Feuerwehr.", "wrong": ["Einen Besuch beim Arzt.", "Einen Job im Supermarkt."]}, {"q": "Wie viele Menschen in Deutschland arbeiten ehrenamtlich oder freiwillig?", "qZh": "德国有多少人做义务或志愿工作？", "answer": "Etwa jeder Dritte.", "wrong": ["Fast niemand.", "Alle Rentner."]}], "src": "改编自 Klexikon《Ehrenamt》", "url": "https://klexikon.zum.de/index.php?oldid=160354", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-043", "seg": 9, "title": "Kinderarbeit", "de": ["Kinderarbeit bedeutet, dass Kinder Arbeit verrichten müssen, die ihnen schadet und dass sie wegen dieser Arbeit nicht zur Schule gehen können. So haben es die Staaten der Vereinten Nationen bestimmt.", "Die meisten Staaten haben Gesetze erlassen, die die Kinderarbeit verbieten. Sie regeln auch genauer, was man darunter verstehen soll und welche Strafen es für Übertretungen geben kann. In der Europäischen Union und der Schweiz ist es verboten, dass Kinder unter 15 Jahren arbeiten. Man muss sich aber genau ansehen, was alles zu Arbeit im Sinne von Kinderarbeit zählt.", "Vor ein paar Jahrhunderten war Kinderarbeit auch in Europa üblich. Im Mittelalter mussten Kinder, genauso wie ihre Eltern, auf den Feldern arbeiten. Auch später, im 19. Jahrhundert, arbeiteten Kinder in den Fabriken, die damals gegründet wurden. Kindern musste man weniger bezahlen als Erwachsenen. Schule für alle gab es auch noch nicht.", "Die Sache mit der Kinderarbeit ist dort nicht überall gleich. Es kann schon von einem Dorf zum anderen anders sein. Aber allgemein gilt: Auch heute ist Kinderarbeit noch ein großes Problem in der Welt. Die UNICEF vermutet, dass fast 200 Millionen Kinder in armen Ländern in Asien, Südamerika und in Afrika arbeiten, anstatt zur Schule zu gehen. Dies trifft zum Teil auch auf den Osten Europas zu.", "Die Kinder arbeiten nicht freiwillig. Meistens sind ihre Familien so arm, dass sie ohne die Kinderarbeit zu wenig zu essen haben. Oder zumindest können sie sich das Schulgeld nicht leisten. Viele Kinder müssen auch arbeiten, weil sie Waisen sind, also keine Eltern mehr haben oder weil sich sonst niemand um sie kümmert."], "zh": ["童工是指孩子必须做对自己有害的工作，并因为这份工作而不能上学。联合国各成员国是这样规定的。", "大多数国家都颁布了禁止童工的法律，还更具体地规定了什么算童工，以及违反规定会受什么惩罚。在欧盟和瑞士，15 岁以下的孩子不准工作。不过要仔细看看，哪些活儿算是童工意义上的工作。", "几百年前，童工在欧洲也很普遍。中世纪孩子和父母一样要在田里干活。后来到了 19 世纪，孩子们还在当时新建的工厂里做工。付给孩子的钱比大人少。那时也还没有人人都能上的学校。", "童工问题在各地并不一样，甚至一个村和另一个村都可能不同。但总的来说，童工至今仍是世界上的一大问题。联合国儿童基金会估计，亚洲、南美和非洲的穷国有将近 2 亿孩子在工作，而不是上学。东欧部分地区也有这种情况。", "孩子们不是自愿工作的。大多是因为家里太穷，不靠孩子工作就吃不饱，或者至少交不起学费。很多孩子必须工作，也是因为他们是孤儿，也就是没有父母了，或者没有别人照顾他们。"], "lemmas": [], "gloss": [{"w": "verrichten", "de": "eine Arbeit machen", "zh": "做（工作）"}, {"w": "Übertretungen", "de": "wenn man gegen eine Regel handelt", "zh": "违规"}, {"w": "üblich", "de": "normal, wie es oft gemacht wird", "zh": "普遍的"}, {"w": "Schulgeld", "de": "Geld, das man für die Schule bezahlen muss", "zh": "学费"}, {"w": "Waisen", "de": "Kinder ohne Eltern", "zh": "孤儿"}], "qs": [{"q": "Ab welchem Alter dürfen Kinder in der EU und der Schweiz arbeiten?", "qZh": "在欧盟和瑞士孩子几岁起可以工作？", "answer": "Ab 15 Jahren.", "wrong": ["Ab 10 Jahren.", "Ab 21 Jahren."]}, {"q": "Warum arbeiteten Kinder im 19. Jahrhundert in Fabriken?", "qZh": "19 世纪孩子为什么在工厂做工？", "answer": "Man musste ihnen weniger bezahlen.", "wrong": ["Sie wollten nicht spielen.", "Die Schule war zu teuer für die Fabriken."]}, {"q": "Warum arbeiten heute viele Kinder in armen Ländern?", "qZh": "如今穷国的很多孩子为什么工作？", "answer": "Ihre Familien haben sonst nicht genug zu essen.", "wrong": ["Sie arbeiten gern freiwillig.", "Sie wollen reich werden."]}], "src": "改编自 Klexikon《Kinderarbeit》", "url": "https://klexikon.zum.de/index.php?oldid=161296", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-044", "seg": 9, "title": "Taschengeld", "de": ["Taschengeld, in der Schweiz Sackgeld, nennt man Geld, das Kinder und Jugendliche von ihren Eltern bekommen. Damit können sie sich Dinge kaufen, die sie sich wünschen. Das können zum Beispiel Süßigkeiten sein, Sammelbilder oder später Computerspiele oder besondere Kleidung. Normalerweise geht es also um kleine Dinge, die nicht viel kosten. Damit können Kinder lernen, wie man mit Geld umgeht: Wie viel man dafür bekommt und dass man nicht zu viel ausgeben sollte.", "Kinder dürfen in den meisten Ländern nicht selbst etwas kaufen, sondern die Eltern müssen entscheiden und dürfen auch Dinge zurückgeben, die das Kind gekauft hat, solange es nicht 18 Jahre alt ist. Vom Taschengeld hingegen darf ein Kind Dinge kaufen, ohne dass es die Eltern um Erlaubnis fragen muss. Eltern können ihre Kinder trotzdem daran hindern, Dinge zu kaufen, die die Eltern nicht wollen. Sie können auch einfach kein Taschengeld mehr zahlen.", "Oft steht darum auch in Gesetzen etwas über Taschengeld: In Deutschland gibt es eine Regel im Gesetz, die „Taschengeldparagraph“ genannt wird. Darin wird geregelt, dass Kinder und Jugendliche auch selbstständig die Dinge kaufen dürfen, wenn sie die von ihrem Taschengeld bezahlen. In Österreich gibt es auch so eine Regel.", "Nicht überall auf der Welt bekommen Kinder Taschengeld. In vielen Gegenden haben die meisten Leute nicht genug Geld dafür. Manchmal müssen Kinder sogar selbst arbeiten. Entweder tun sie das, um Geld für sich und die Eltern zu bekommen, oder sie helfen den Eltern bei der Arbeit, damit überhaupt Geld da ist. Auch bei uns haben einige Leute nicht genug Geld, dass sie ihren Kindern etwas abgeben können."], "zh": ["零花钱，在瑞士叫 Sackgeld，是孩子和青少年从父母那里拿到的钱。他们可以用它买自己想要的东西，比如糖果、收集卡片，后来也可能是电脑游戏或特别的衣服。一般都是不太贵的小东西。孩子可以借此学习怎样用钱：能拿到多少钱，以及不该花太多。", "在大多数国家，孩子不能自己买东西，必须由父母决定。孩子不满 18 岁时，父母还可以把孩子买的东西退掉。但用零花钱，孩子可以不经父母允许买东西。不过父母仍然可以阻止孩子买他们不想让孩子买的东西，也可以干脆不再给零花钱。", "所以法律里也常有关于零花钱的规定：德国法律里有一条被称为「零花钱条款」的规定，规定儿童和青少年用自己的零花钱付钱时，也可以自己买东西。奥地利也有类似规定。", "并不是世界各地的孩子都有零花钱。很多地方的大多数人钱不够。有时孩子甚至要自己工作：要么是为自己和父母挣钱，要么是帮父母干活，家里才能有收入。在我们这里，也有一些人没有足够的钱分给孩子。"], "lemmas": [], "gloss": [{"w": "Süßigkeiten", "de": "Bonbons, Schokolade usw.", "zh": "糖果"}, {"w": "umgeht", "de": "mit etwas umgehen: es benutzen und behandeln", "zh": "对待、使用"}, {"w": "hindern", "de": "machen, dass jemand etwas nicht tun kann", "zh": "阻止"}, {"w": "selbstständig", "de": "allein, ohne Hilfe", "zh": "自己、独立地"}], "qs": [{"q": "Was können Kinder mit Taschengeld lernen?", "qZh": "孩子用零花钱能学到什么？", "answer": "Wie man mit Geld umgeht.", "wrong": ["Wie man eine Bank gründet.", "Wie man Steuern zahlt."]}, {"q": "Was regelt der Taschengeldparagraph in Deutschland?", "qZh": "德国的零花钱条款规定了什么？", "answer": "Kinder dürfen Dinge selbst kaufen, die sie vom Taschengeld bezahlen.", "wrong": ["Kinder müssen jeden Monat 50 Euro bekommen.", "Eltern dürfen kein Taschengeld geben."]}, {"q": "Warum bekommen nicht alle Kinder Taschengeld?", "qZh": "为什么不是所有孩子都有零花钱？", "answer": "Viele Familien haben nicht genug Geld dafür.", "wrong": ["Taschengeld ist überall verboten.", "Kinder wollen kein Geld."]}], "src": "改编自 Klexikon《Taschengeld》", "url": "https://klexikon.zum.de/index.php?oldid=158784", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-045", "seg": 9, "title": "Haushalt", "de": ["Ein Haushalt sind Personen, die zusammen im selben Haus wohnen. Das kann eine Familie, eine Einzelperson, ein Pärchen oder eine Gruppe sein. Wenn Leute, die nicht miteinander verwandt oder verheiratet sind, zusammenziehen spricht man von einer Wohngemeinschaft, kurz WG. Das gibt es zum Beispiel bei Studenten oder guten Freunden. In der Wirtschaft werden WGs auch manchmal als mehrere Haushalte betrachtet, weil jedes WG-Mitglied für sich selber Geld verdient und ausgibt.", "Leute, die in einem Haushalt mit mehreren Bewohnern leben, müssen auf einander Rücksicht nehmen. Sie teilen sich zum Beispiel Räume und Gegenstände, wie das Badezimmer. Wenn Freunde oder Pärchen zusammenziehen, dann ist das eine neue Situation. Sie müssen nun lernen, wie sie in Frieden zusammenleben, sonst ist das schlecht für die Beziehung.", "Früher hatten die Menschen in der Familie feste Aufgaben: Der Vater ging arbeiten, während die Mutter für die Kinder sorgte. Man nennt das eine „klassische Rollenverteilung“. Heute ist das seltener geworden. Meistens arbeitet auch die Mutter nach der Babypause wieder auf ihrem Beruf. Der Vater arbeitet vielleicht nur in Teilzeit. Jedes Paar vereinbart also, wer was macht.", "Wenn Menschen zusammenwohnen, ist das ein Privathaushalt. In der Politik spricht man oft vom Staatshaushalt. Damit meint man die Einnahmen, die einem Staat für die Ausgaben zur Verfügung stehen, also für Straßen, Schulen und so weiter. Wie in einem Haushalt tragen die Bewohner durch Steuern dazu bei, dass der Staat Geld hat. In einem Unternehmen spricht man vom Unternehmenshaushalt."], "zh": ["一个住户（Haushalt）就是住在同一所房子里的人。可以是一个家庭、单身的人、一对情侣或一群人。如果彼此没有亲戚关系也没结婚的人搬到一起住，就叫合租公寓，简称 WG。比如学生或好朋友之间就会合租。在经济学里，有时也把一个合租公寓看作几个住户，因为每个合租成员各自挣钱、各自花钱。", "和几个人一起生活的人必须互相体谅。比如他们共用房间和物品，像卫生间。朋友或情侣搬到一起住，是一种新情况。他们现在得学会和平共处，否则会伤害感情。", "以前家里每个人有固定分工：父亲出去工作，母亲照顾孩子，这叫「传统分工」。如今这种情况少了。母亲大多在产假后重新回到工作岗位，父亲也许只做兼职。所以每对夫妻都要商量好谁做什么。", "人们住在一起，是私人住户。政治上常说国家预算（Staatshaushalt），指国家可用于支出的收入，用来修路、建学校等等。就像在一个家里一样，居民通过交税让国家有钱。在企业里则说企业预算。"], "lemmas": [], "gloss": [{"w": "verwandt", "de": "zur selben Familie gehörend", "zh": "有亲戚关系的"}, {"w": "Wohngemeinschaft", "de": "Wohnung, die sich mehrere Menschen teilen", "zh": "合租公寓"}, {"w": "Rücksicht nehmen", "de": "an die anderen denken", "zh": "体谅"}, {"w": "Rollenverteilung", "de": "wer welche Aufgaben übernimmt", "zh": "分工"}, {"w": "Teilzeit", "de": "weniger Stunden als normal arbeiten", "zh": "兼职"}], "qs": [{"q": "Was ist eine WG?", "qZh": "WG 是什么？", "answer": "Leute, die nicht verwandt sind und zusammen wohnen.", "wrong": ["Eine große Familie mit Kindern.", "Ein Hotel für Studenten."]}, {"q": "Was müssen Paare lernen, wenn sie zusammenziehen?", "qZh": "情侣搬到一起住要学会什么？", "answer": "Wie sie in Frieden zusammenleben.", "wrong": ["Wie man ein Haus baut.", "Wie man Steuern spart."]}, {"q": "Was meint man mit Staatshaushalt?", "qZh": "国家预算指什么？", "answer": "Das Geld, das der Staat für seine Ausgaben hat.", "wrong": ["Die Wohnung des Präsidenten.", "Die Möbel in einem Ministerium."]}], "src": "改编自 Klexikon《Haushalt》", "url": "https://klexikon.zum.de/index.php?oldid=159743", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-046", "seg": 9, "title": "Krankenkasse", "de": ["Eine Krankenkasse ist ein Unternehmen, das Menschen dabei hilft, für Ärzte und Pfleger zu bezahlen. Wenn man einen Arzt oder ein Krankenhaus besucht, kann das sehr teuer werden. Nicht jeder hat so viel Geld, dass er sich das plötzlich leisten kann.", "Wer bei einer Krankenkasse Mitglied ist, zahlt jeden Monat dafür Geld. Mit dem Geld, das dabei zusammen kommt, werden die Kosten bezahlt, die zum Beispiel bei einem Aufenthalt im Krankenhaus entstehen. Die Krankenkasse bezahlt auch für eine Therapie, bei der Krankheiten oder Verletzungen meist längere Zeit behandelt werden.", "Die Krankenkasse bezahlt aber nicht alle Kosten. Einen bestimmten Teil der Arztkosten muss jeder selber zahlen. Diesen Anteil nennt man Selbstbeteiligung, in der Schweiz als Franchise bekannt. Die Höhe der Selbstbeteiligung kann selbst gewählt werden. Bei einer tiefen Selbstbeteiligung sind allerdings die monatlichen Kosten für die Krankenkasse höher.", "Die ersten Krankenkassen entstanden vor über hundert Jahren, in Deutschland etwa in der Zeit von Reichskanzler Bismarck. Was eine Krankenkasse tun kann, ist im Staat in Gesetzen geregelt. Es gibt kleinere Kassen, welche nur einige hundert Menschen versichern, die etwa für ein Unternehmen arbeiten, aber auch viel größere, die mit ihren Leistungen Werbung machen. In den meisten Ländern ist es Pflicht, bei einer Krankenkasse angemeldet zu sein. In manchen Ländern gibt es keine Krankenkassen. Dort sterben manchmal Menschen, weil sie es sich nicht leisten können, zum Arzt zu gehen."], "zh": ["医疗保险公司是帮助人们支付医生和护理费用的企业。看医生或住院可能非常贵，不是每个人都有那么多钱，能突然负担得起。", "在医保公司投保的人每个月要交钱。大家交的钱汇在一起，用来支付比如住院时产生的费用。医保公司也支付治疗费用，有些疾病或伤要较长时间治疗。", "不过医保不支付全部费用，每个人都要自己承担一部分医疗费，这部分叫自付额，在瑞士叫 Franchise。自付额的高低可以自己选。不过自付额低的话，每月的保费就高。", "最早的医保公司出现在一百多年前，在德国大约是首相俾斯麦的时代。医保公司能做什么，由国家的法律规定。有的医保公司很小，只为几百人投保，比如某家企业的员工；也有很大的医保公司，用自己的服务做广告。在大多数国家，人们必须在医保公司登记。有些国家没有医保公司，那里有时会有人因为看不起医生而死去。"], "lemmas": [], "gloss": [{"w": "Aufenthalt", "de": "Zeit, die man an einem Ort bleibt", "zh": "逗留、住（院）"}, {"w": "Therapie", "de": "Behandlung einer Krankheit", "zh": "治疗"}, {"w": "Selbstbeteiligung", "de": "Teil der Kosten, den man selbst zahlt", "zh": "自付额"}, {"w": "Pflicht", "de": "etwas, das man tun muss", "zh": "义务"}], "qs": [{"q": "Wofür bezahlt die Krankenkasse zum Beispiel?", "qZh": "医保公司比如支付什么？", "answer": "Für einen Aufenthalt im Krankenhaus.", "wrong": ["Für einen Urlaub am Meer.", "Für ein neues Auto."]}, {"q": "Was passiert bei einer tiefen Selbstbeteiligung?", "qZh": "自付额低会怎样？", "answer": "Die monatlichen Kosten sind höher.", "wrong": ["Man muss gar nichts mehr bezahlen.", "Man darf nicht zum Arzt."]}, {"q": "Wann entstanden in Deutschland die ersten Krankenkassen?", "qZh": "德国最早的医保公司是什么时候出现的？", "answer": "Zur Zeit von Reichskanzler Bismarck.", "wrong": ["Im Jahr 2000.", "Im Mittelalter."]}], "src": "改编自 Klexikon《Krankenkasse》", "url": "https://klexikon.zum.de/index.php?oldid=154672", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-047", "seg": 9, "title": "Rathaus", "de": ["Rathaus nennt man das Haus, in dem die Politiker und Mitarbeiter einer Stadt oder Gemeinde „Politik machen“ und arbeiten. Hier trifft sich der Stadtrat oder Rat, das heißt die Volksvertretung der Stadt. So ein Parlament entscheidet über die wichtigsten Dinge in der Stadt. Außerdem arbeiten dort der Bürgermeister und die Verwaltung: der Chef der Stadt und seine Mitarbeiter.", "In manchen Städten sind die Politiker und Mitarbeiter in ein neues Gebäude umgezogen. Das ist meist viel größer und auch moderner. Das alte Gebäude heißt dann vielleicht immer noch „Rathaus“ oder „Altes Rathaus“. Manchmal sagt man „Rathaus“ und meint damit nicht wirklich das Gebäude, sondern die Politiker der Stadt oder die Stadtverwaltung.", "Das Gebäude soll oft auch schön aussehen. Es soll den Einwohnern und Besuchern zeigen, wie reich und mächtig die Stadt ist. Häufig liegt das Rathaus in der Mitte der Stadt, nahe anderen wichtigen Gebäuden. Weil ein Rathaus wichtig für eine Stadt ist, gibt es vielleicht auch Führungen: Man erklärt Besuchern, was im Rathaus gemacht wird. Alte, schöne Rathäuser ziehen sogar Touristen aus anderen Ländern an.", "Ein Rathaus braucht einen großen Saal, in dem der Stadtrat sich treffen kann. Oft heißt er Ratssaal. In einer großen Stadt wie Hamburg gibt es 121 Ratsmitglieder. Es gibt ganze Länder, die weniger Mitglieder im Parlament haben. Je größer die Stadt, desto mehr Ratsmitglieder darf sie haben. In kleinen Gemeinden sind es vielleicht nur ein Dutzend Leute."], "zh": ["市政厅是一座城市或乡镇的政治家和工作人员「搞政治」和办公的房子。市议会在这里开会，市议会就是城市的民意代表机构。这样的议会决定城里最重要的事情。此外市长和行政部门也在这里工作，也就是城市的负责人和他的工作人员。", "有些城市的政治家和工作人员已经搬进了新楼，新楼一般大得多，也更现代。旧楼也许仍叫「市政厅」或「老市政厅」。有时说「市政厅」，指的并不是那栋楼，而是城市的政治家或市政府。", "市政厅的楼通常也要好看。它要向居民和访客展示城市有多富裕、多有实力。市政厅常常在市中心，靠近其他重要建筑。因为市政厅对城市很重要，也许还有导览，向访客介绍市政厅里做什么。古老漂亮的市政厅甚至吸引外国游客。", "市政厅需要一个大厅供市议会开会，常叫议事厅。在汉堡这样的大城市有 121 名议员，有些国家的议会成员还没这么多。城市越大，议员就可以越多。小乡镇也许只有十几个人。"], "lemmas": [], "gloss": [{"w": "Volksvertretung", "de": "Menschen, die für die Bürger entscheiden", "zh": "民意代表机构"}, {"w": "Verwaltung", "de": "Menschen, die die Arbeit einer Stadt organisieren", "zh": "行政部门"}, {"w": "mächtig", "de": "hat viel Macht", "zh": "有实力的"}, {"w": "Führungen", "de": "Besuche mit jemandem, der alles erklärt", "zh": "导览"}, {"w": "Dutzend", "de": "zwölf", "zh": "一打、十几个"}], "qs": [{"q": "Wer arbeitet im Rathaus?", "qZh": "谁在市政厅工作？", "answer": "Der Bürgermeister und die Verwaltung.", "wrong": ["Nur Touristen.", "Die Bundesregierung."]}, {"q": "Was soll ein schönes Rathaus zeigen?", "qZh": "漂亮的市政厅要展示什么？", "answer": "Wie reich und mächtig die Stadt ist.", "wrong": ["Wie alt der Bürgermeister ist.", "Wie viele Autos es gibt."]}, {"q": "Wie viele Ratsmitglieder gibt es in Hamburg?", "qZh": "汉堡有多少名议员？", "answer": "121.", "wrong": ["12.", "1210."]}], "src": "改编自 Klexikon《Rathaus》", "url": "https://klexikon.zum.de/index.php?oldid=166970", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-048", "seg": 9, "title": "Bürgermeister", "de": ["Ein Bürgermeister steht an der Spitze einer Stadt oder Gemeinde und ihrer Einwohner. Was ein Bürgermeister oder eine Bürgermeisterin genau macht und darf, hängt vom Land ab. Normalerweise hat ein Land ein Gesetz, in dem das beschrieben ist. In Deutschland und Österreich bestimmen die Bundesländer die Regeln dazu. In der Schweiz hieß der Bürgermeister früher Gemeindeammann. Heute heißt er Gemeindepräsident oder Stadtpräsident.", "In vielen Ländern ist der Bürgermeister der Chef der Verwaltung und hat sein Büro im Rathaus. Die Verwaltung sind die Leute, die für die Stadt arbeiten. Er vertritt die Stadt nach außen, spricht in ihrem Namen. In einigen Ländern ist ein Bürgermeister außerdem der Vorsitzende des Parlaments der Stadt.", "In einigen Ländern wählen die Einwohner der Stadt ihren Bürgermeister selbst. Dabei entscheiden sie zwischen Kandidaten, also Menschen, die gerne Bürgermeister werden wollen. Das nennt man eine direkte Wahl. In anderen Ländern wählt das Parlament der Stadt den Bürgermeister. In anderen Ländern wieder bestimmt die Regierung des Landes, wer in welcher Stadt Bürgermeister ist: Das ist früher auch in Deutschland und Österreich normal gewesen.", "In größeren Städten kriegt ein Bürgermeister Geld, so dass er keinen anderen Beruf braucht: Er arbeitet hauptamtlich als Bürgermeister. In den sehr großen Städten Deutschlands ist der Titel „Oberbürgermeister“. In kleineren Städten und Gemeinden arbeitet er hingegen ehrenamtlich und hat daneben einen anderen Beruf. Außerdem gibt es oft noch stellvertretende Bürgermeister. Sie übernehmen kleinere Aufgaben und sind meist Ehrenamtliche."], "zh": ["市长是一座城市或乡镇及其居民的领导。市长具体做什么、可以做什么，取决于国家。一般国家有法律对此加以规定。在德国和奥地利，由各联邦州规定。在瑞士，市长以前叫 Gemeindeammann，如今叫乡镇主席或市主席。", "在很多国家，市长是行政部门的负责人，在市政厅办公。行政部门就是为城市工作的人。市长对外代表城市，以城市的名义说话。在有些国家，市长还是市议会的主席。", "在一些国家，市民自己选市长，在候选人，也就是想当市长的人之间做选择，这叫直接选举。在另一些国家，由市议会选市长。还有些国家由国家政府决定谁当哪座城市的市长，这在以前的德国和奥地利也很普遍。", "在较大的城市，市长拿工资，不需要别的职业，他专职当市长。在德国的大城市，头衔是「市长（Oberbürgermeister）」。而在较小的城市和乡镇，市长是义务的，另有一份职业。此外常常还有副市长，负责较小的任务，大多也是义务的。"], "lemmas": [], "gloss": [{"w": "Spitze", "de": "der oberste Platz", "zh": "顶端、领导地位"}, {"w": "vertritt", "de": "spricht oder handelt für jemanden", "zh": "代表"}, {"w": "Vorsitzende", "de": "Leiter einer Gruppe oder Sitzung", "zh": "主席"}, {"w": "Kandidaten", "de": "Menschen, die gewählt werden wollen", "zh": "候选人"}, {"w": "hauptamtlich", "de": "als richtiger Beruf, mit Lohn", "zh": "专职的"}], "qs": [{"q": "Wo hat der Bürgermeister oft sein Büro?", "qZh": "市长常在哪里办公？", "answer": "Im Rathaus.", "wrong": ["Im Bahnhof.", "In der Schule."]}, {"q": "Was ist eine direkte Wahl?", "qZh": "什么是直接选举？", "answer": "Die Einwohner wählen den Bürgermeister selbst.", "wrong": ["Die Regierung bestimmt den Bürgermeister.", "Der alte Bürgermeister wählt den neuen."]}, {"q": "Wie arbeitet ein Bürgermeister in kleinen Gemeinden?", "qZh": "小乡镇的市长怎样工作？", "answer": "Ehrenamtlich, neben einem anderen Beruf.", "wrong": ["Nur am Wochenende im Ausland.", "Er bekommt sehr viel Geld."]}], "src": "改编自 Klexikon《Bürgermeister》", "url": "https://klexikon.zum.de/index.php?oldid=154077", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-049", "seg": 9, "title": "Gemeinde", "de": ["Eine Gemeinde ist ein Ort, an dem Menschen leben. Sie haben eine eigene Regierung, das ist meist ein Stadtrat oder ein Gemeinderat. Eine Gemeinde kann eine Stadt sein, ein Dorf oder mehrere Dörfer, die sich zu einer Gemeinde zusammengeschlossen haben. In Deutschland nennt man sie oft „Kommunen“. Das Wort kommt aus dem Französischen und bedeutet „gemeinsam“. Eine solche Gemeinde nennt man auch Politische Gemeinde oder Einwohnergemeinde. Dörfer, die zu einer größeren Gemeinde gehören werden auch als Ortsteile bezeichnet.", "Jede Gemeinde in Deutschland gehört zu einem Landkreis, der zu einem Bundesland gehört. In der Schweiz gehört jede Gemeinde zu einem Kanton. In anderen Ländern ist es meist ähnlich, nur die Begriffe lauten anders.", "Die Gemeinden haben typische Aufgaben. Am wichtigsten ist es, dass sie genau wissen, wer in der Gemeinde wohnt. Wer dorthin zieht, muss sich auf der Gemeinde anmelden und gehört dann zu den Einwohnern. Er ist dann aber nicht Bürger. Wer wegzieht, muss sich abmelden. Auf der Gemeinde kann ein Paar eine Ehe schließen. Eltern müssen melden, wenn sie ein Kind bekommen haben. Verwandte melden, wenn ein Mensch gestorben ist. Meist sind die Gemeinden auch für die Bereitstellung des Trinkwassers verantwortlich, aber auch für die Behandlung des Abwassers, für die Beseitigung des Mülls und für viele andere Dinge. Große Gemeinden haben oft zusätzlich eine eigene Versorgung mit Elektrizität."], "zh": ["乡镇是人们生活的地方，有自己的管理机构，大多是市议会或乡镇议会。乡镇可以是一座城市、一个村子，或者几个村子合并成的一个乡镇。在德国常叫 Kommunen，这个词来自法语，意思是「共同的」。这样的乡镇也叫行政乡镇或居民乡镇。属于较大乡镇的村子也叫镇区。", "德国的每个乡镇都属于一个县，县属于一个联邦州。在瑞士，每个乡镇属于一个州。在别的国家大多也差不多，只是叫法不同。", "乡镇有一些典型任务。最重要的是确切知道谁住在乡镇里。搬到那里的人必须到乡镇登记，然后就算居民了，但还不是公民。搬走的人必须注销登记。一对情侣可以在乡镇登记结婚。父母生了孩子必须申报，有人去世了亲属要申报。乡镇大多还负责供应饮用水，也负责处理污水、清运垃圾和很多别的事。大的乡镇常常还有自己的电力供应。"], "lemmas": [], "gloss": [{"w": "zusammengeschlossen", "de": "zu einer Gruppe verbunden", "zh": "合并"}, {"w": "Landkreis", "de": "Verwaltungseinheit zwischen Gemeinde und Bundesland", "zh": "县"}, {"w": "anmelden", "de": "offiziell sagen, dass man irgendwo wohnt", "zh": "登记"}, {"w": "abmelden", "de": "offiziell sagen, dass man wegzieht", "zh": "注销登记"}, {"w": "Abwassers", "de": "schmutziges Wasser aus Küche und Bad", "zh": "污水"}], "qs": [{"q": "Was bedeutet das Wort „Kommune“?", "qZh": "Kommune 这个词是什么意思？", "answer": "Gemeinsam.", "wrong": ["Dorf.", "Regierung."]}, {"q": "Was muss man tun, wenn man in eine Gemeinde zieht?", "qZh": "搬到一个乡镇时必须做什么？", "answer": "Sich bei der Gemeinde anmelden.", "wrong": ["Ein Haus kaufen.", "Den Bürgermeister besuchen."]}, {"q": "Wofür ist eine Gemeinde oft verantwortlich?", "qZh": "乡镇常负责什么？", "answer": "Für Trinkwasser und Müll.", "wrong": ["Für das Militär.", "Für die Fernsehsender."]}], "src": "改编自 Klexikon《Gemeinde》", "url": "https://klexikon.zum.de/index.php?oldid=157771", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-09-050", "seg": 9, "title": "Zoll (Grenze)", "de": ["Zoll nennt man eine Gebühr im internationalen Handel. Dieses Geld muss man bezahlen, wenn man eine Ware in ein anderes Land bringen will. Auch die Behörde, die den Zoll eintreibt, heißt Zoll. Außerdem ist Zoll ein altes Längenmaß aus England. Ein Zoll entspricht etwa zweieinhalb Zentimetern.", "Ein Land verlangt den Zoll von demjenigen, der eine Ware ins Land bringen will. Damit verdient das Land Geld. Außerdem will ein Land oft, dass Waren aus dem Ausland ein wenig teurer werden. Dann kaufen die Einwohner wahrscheinlich eher die Waren, die im Land selbst hergestellt werden.", "Manche Länder schließen sich zusammen und gründen eine Zollunion. Auch die Länder der Europäischen Union bilden eine Zollunion. Dazu gehören noch einige weitere Länder: Andorra, San Marino und die Türkei. Ansonsten können Länder ein Zollabkommen vereinbaren. Zwischen diesen Ländern muss man dann keinen oder wenig Zoll bezahlen, oder nur für einige Waren.", "Wer für die Zollbehörde arbeitet, ist ein Zöllner oder Zollbeamter. Sie nehmen noch manche anderen Steuern außer dem Zoll ein. Zollbeamte prüfen an der Grenze auch, ob verbotene Waren mitgenommen werden, zum Beispiel Drogen, besondere Reptilien und viele andere Dinge.", "Auch Deutschland und Österreich haben Zollbeamte, obwohl diese Länder in der Europäischen Union sind und nicht allein bestimmen können, was für Zölle sie fordern. Darüber entscheidet die gesamte Europäische Union. Die deutschen und österreichischen Zollbeamten folgen den Regeln der Europäischen Union. Sie arbeiten normalerweise an Häfen und Flughäfen. Außerdem müssen auch Pakete aus fremden Ländern durch den Zoll."], "zh": ["关税是国际贸易中的一种费用。想把商品带进另一个国家，就要交这笔钱。征收关税的机关也叫海关（Zoll）。此外 Zoll 还是英国一种古老的长度单位，一英寸大约等于两厘米半。", "一个国家向把商品带进国内的人收关税，这样国家就有收入。此外，国家也常希望外国商品贵一点，这样居民就更可能买本国生产的商品。", "有些国家联合起来，成立关税同盟。欧盟国家也组成了一个关税同盟，另外还有几个国家：安道尔、圣马力诺和土耳其。此外国家之间也可以签订关税协定，这样在这些国家之间就不用交或只交很少的关税，或者只对某些商品收税。", "在海关工作的人是海关人员或海关公务员。除了关税，他们还征收一些别的税。海关人员在边境还检查有没有人带违禁品，比如毒品、特殊的爬行动物和很多别的东西。", "德国和奥地利也有海关人员，虽然这两个国家在欧盟里，不能单独决定收什么关税，这由整个欧盟决定。德国和奥地利的海关人员遵守欧盟的规定，一般在港口和机场工作。此外来自外国的包裹也要过海关。"], "lemmas": [], "gloss": [{"w": "eintreibt", "de": "Geld verlangen und einsammeln", "zh": "征收"}, {"w": "Zollunion", "de": "Länder ohne Zoll untereinander", "zh": "关税同盟"}, {"w": "Zollabkommen", "de": "Vertrag über Zölle zwischen Ländern", "zh": "关税协定"}, {"w": "Reptilien", "de": "Tiere wie Schlangen oder Echsen", "zh": "爬行动物"}, {"w": "Häfen", "de": "Orte, wo Schiffe anlegen", "zh": "港口"}], "qs": [{"q": "Wann muss man Zoll bezahlen?", "qZh": "什么时候要交关税？", "answer": "Wenn man eine Ware in ein anderes Land bringt.", "wrong": ["Wenn man im Supermarkt einkauft.", "Wenn man eine Wohnung mietet."]}, {"q": "Warum will ein Land, dass Waren aus dem Ausland teurer werden?", "qZh": "国家为什么希望外国商品贵一点？", "answer": "Damit die Einwohner eher Waren aus dem eigenen Land kaufen.", "wrong": ["Damit niemand mehr einkauft.", "Damit die Grenze geschlossen wird."]}, {"q": "Wer entscheidet über die Zölle in Deutschland?", "qZh": "谁决定德国的关税？", "answer": "Die gesamte Europäische Union.", "wrong": ["Jede Stadt allein.", "Die Zollbeamten selbst."]}], "src": "改编自 Klexikon《Zoll (Grenze)》", "url": "https://klexikon.zum.de/index.php?oldid=165698", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-001", "seg": 10, "title": "Medien", "de": ["Die Medien übermitteln Nachrichten oder Ideen, aber auch Gefühle, Fragen oder Vermutungen. Das Wort selbst heißt in der Einzahl Medium. Das kommt aus der lateinischen Sprache und bedeutet „die Mitte“.", "Ein Medium kann auch das Telefon sein, oder ein anderes technisches Gerät. Man spricht dann mit einem anderen Menschen ohne ihn zu sehen. Dieser Mensch kann auch sehr weit weg sein. Aber das Telefon überbringt die Sprache und andere Töne. Auch Notizen, Postkarten, E-Mails und so weiter gehören zu dieser Art von Medien.", "Meistens denken die Leute beim Wort Medien an Massenmedien. Ein Massenmedium richtet sich an viele Menschen, an Menschenmassen. Es muss also auch viele Menschen erreichen können, die das sehen und hören. Beispiele sind die Zeitung, das Radio oder das Fernsehen. Heutzutage ist das Internet in vielen Ländern der Erde schon zum wichtigsten Massenmedium geworden.", "Massenmedien sind in der Demokratie besonders wichtig: Sie sollen Informationen beschaffen und verbreiten. Dabei sollen sie diese Informationen auch bewerten und einordnen. Die Politik und die Wirtschaft sollen kontrolliert und kritisiert werden. So können sich alle Bürger gut informieren.", "In Staaten, die nicht demokratisch sind, ist dies oft nicht möglich. Die Medien werden von der Regierung beherrscht, damit sie nur die Informationen verbreiten, die der Regierung recht sind. Man nennt das Zensur."], "zh": ["媒体传递消息或想法，也传递情感、问题或猜测。这个词的单数是 Medium，来自拉丁语，意思是「中间」。", "媒介也可以是电话或别的技术设备。这时人和另一个人说话却看不见他，那个人也可以离得很远。但电话传递了话语和其他声音。便条、明信片、电子邮件等等也属于这类媒介。", "大多数时候，人们一听到「媒体」就想到大众媒体。大众媒体面向很多人，面向大众，所以必须能让很多人看到、听到。例子有报纸、广播和电视。如今在世界上很多国家，互联网已经成了最重要的大众媒体。", "大众媒体在民主社会里特别重要：它们要获取和传播信息，同时还要评价信息、加以分析，要监督和批评政治与经济。这样所有公民都能很好地了解情况。", "在不民主的国家，这往往做不到。媒体被政府控制，只能传播政府认可的信息，这叫审查。"], "lemmas": [], "gloss": [{"w": "übermitteln", "de": "von einem zum anderen bringen", "zh": "传递"}, {"w": "Vermutungen", "de": "was man glaubt, aber nicht sicher weiß", "zh": "猜测"}, {"w": "Massenmedien", "de": "Medien für sehr viele Menschen", "zh": "大众媒体"}, {"w": "verbreiten", "de": "an viele Menschen weitergeben", "zh": "传播"}, {"w": "Zensur", "de": "Kontrolle, was in den Medien stehen darf", "zh": "审查"}], "qs": [{"q": "Was bedeutet das lateinische Wort „Medium“?", "qZh": "拉丁语 Medium 是什么意思？", "answer": "Die Mitte.", "wrong": ["Die Nachricht.", "Die Zeitung."]}, {"q": "Welches Massenmedium ist heute in vielen Ländern das wichtigste?", "qZh": "如今在很多国家最重要的大众媒体是什么？", "answer": "Das Internet.", "wrong": ["Das Radio.", "Die Postkarte."]}, {"q": "Was ist Zensur?", "qZh": "什么是审查？", "answer": "Die Regierung bestimmt, welche Informationen verbreitet werden.", "wrong": ["Die Medien kritisieren die Regierung.", "Alle Bürger schreiben Zeitungsartikel."]}], "src": "改编自 Klexikon《Medien》", "url": "https://klexikon.zum.de/index.php?oldid=158878", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-002", "seg": 10, "title": "Nachrichten", "de": ["Das Wort Nachricht steht für eine Information, die von einem Menschen zum anderen geht. Vor allem, wenn man von der Mehrzahl spricht, also Nachrichten, meint man eine besondere Art von Information: Nachrichten sind für viele Menschen interessant und sie sind neu, man sagt auch sie sind aktuell. Auf englisch heißt Nachricht „News“. Das bedeutet „Neuigkeit“.", "Nachrichten werden von Journalisten gemacht, also Leuten, die für eine Zeitung, das Fernsehen oder eine Website arbeiten. Das nennt man zusammen die Medien. Die Journalisten sprechen mit vielen Menschen und erfahren so von neuen Dingen. Aber nicht alles, was in den Medien steht, ist auch eine Nachricht: Zum Beispiel kann ein Journalist auch einen Kommentar schreiben, also seine eigene Meinung zu etwas. Eine Nachricht hingegen soll keine bestimmte Meinung enthalten.", "Nachrichten sollen neu sein: Sie berichten von etwas, das bislang noch nicht bekannt war, oder von etwas, das es bislang noch nicht gab. Ein Journalist will deshalb auch möglichst der erste sein, der eine Nachricht „bringt“. Im Wort „Journalismus“ steckt das französische Wort „Jour“. Das bedeutet: der Tag. Eine Nachricht ist also nur einen Tag lang eine Nachricht. Später ist es keine mehr.", "Außerdem spricht man von einem „Nachrichtenwert“. Eine Nachricht soll von etwas Wichtigem erzählen, das die Leute interessiert. Wichtig ist ein Ereignis, das für viele Menschen Folgen haben kann. Beispiele sind Wahlergebnisse, neue Gesetze, Naturkatastrophen oder Funde von Gift in Lebensmitteln.", "Oft sieht man in den Medien aber auch Nachrichten, die an sich nicht wichtig sind, sondern von etwas Seltsamen berichten. Der Nachrichtenwert liegt darin, dass die Sache ungewöhnlich und zum Staunen ist. Ein Spruch dazu lautet: „Hund beißt Mann“ ist keine Nachricht, weil Hunde das eben so machen. „Mann beißt Hund“ hingegen wäre eine interessante Nachricht. Wenn eine Nachricht gar nicht stimmt, nennt man das eine „Ente”."], "zh": ["Nachricht 这个词指从一个人传到另一个人的信息。特别是说复数 Nachrichten（新闻）时，指的是一种特别的信息：新闻让很多人感兴趣，而且是新的，也就是说有时效性。英语里叫 News，意思是「新鲜事」。", "新闻由记者制作，也就是为报纸、电视或网站工作的人，这些合起来叫媒体。记者和很多人交谈，由此得知新的事情。不过媒体上登的东西并不都是新闻：比如记者也可以写评论，也就是自己对某事的看法。而新闻不应该带有某种特定观点。", "新闻应该是新的：它报道之前还不为人知的事，或者之前还没有的事。所以记者都想第一个「发」新闻。Journalismus（新闻业）这个词里有法语词 jour，意思是「一天」。所以一条新闻只当一天的新闻，之后就不是了。", "另外还有「新闻价值」的说法。新闻要讲述人们关心的重要事情。重要的事件，是可能对很多人产生影响的事件，比如选举结果、新法律、自然灾害或食品中发现有毒物质。", "不过媒体上也常有本身并不重要、而是讲奇怪事情的新闻。它的新闻价值在于事情不寻常、让人惊讶。有句话说：「狗咬人」不是新闻，因为狗本来就会咬人；「人咬狗」才是有趣的新闻。如果一条新闻根本不是真的，就叫「鸭子」（Ente，假新闻）。"], "lemmas": [], "gloss": [{"w": "aktuell", "de": "neu, gerade jetzt wichtig", "zh": "有时效性的"}, {"w": "Journalisten", "de": "Menschen, die für Medien Berichte schreiben", "zh": "记者"}, {"w": "Kommentar", "de": "Text mit der eigenen Meinung", "zh": "评论"}, {"w": "Naturkatastrophen", "de": "große Unglücke durch die Natur, z. B. Erdbeben", "zh": "自然灾害"}, {"w": "zum Staunen", "de": "so, dass man sich sehr wundert", "zh": "令人惊讶的"}], "qs": [{"q": "Was ist der Unterschied zwischen Nachricht und Kommentar?", "qZh": "新闻和评论有什么区别？", "answer": "Ein Kommentar enthält die eigene Meinung, eine Nachricht nicht.", "wrong": ["Eine Nachricht ist immer länger.", "Ein Kommentar ist immer neu."]}, {"q": "Was bedeutet das französische Wort „Jour“?", "qZh": "法语 jour 是什么意思？", "answer": "Der Tag.", "wrong": ["Die Zeitung.", "Die Nachricht."]}, {"q": "Warum ist „Mann beißt Hund“ eine Nachricht?", "qZh": "为什么「人咬狗」是新闻？", "answer": "Weil es sehr ungewöhnlich ist.", "wrong": ["Weil Hunde gefährlich sind.", "Weil es jeden Tag passiert."]}], "src": "改编自 Klexikon《Nachrichten》", "url": "https://klexikon.zum.de/index.php?oldid=161697", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-003", "seg": 10, "title": "Zeitung", "de": ["Eine Zeitung ist eine Sammlung von Nachrichten und Berichten. Zeitungen erscheinen regelmäßig, meist einmal am Tag oder in der Woche. Eine Zeitung informiert ihre Leser über Neuigkeiten. Normalerweise meint man mit einer Zeitung Gedrucktes.", "Ursprünglich bedeutete das Wort Zeitung selbst Nachricht. Heute sammelt man in einer Zeitung verschiedene Nachrichten und Neuigkeiten in Artikeln. Ein Zeitungsartikel ist ein einzelner Beitrag, der in einer Zeitung erscheint. Eine Zeitung ist meist in verschiedene Abschnitte gegliedert, die man Rubriken nennt: Politik, Lokales, Wirtschaft, Medien oder Sport. So kann der Leser gezielt die Artikel zu einem bestimmten Thema aufschlagen.", "Journalisten nennt man die Menschen, die für Zeitungen oder andere Medien die Inhalte machen. Ein Reporter ist ein Journalist, der zu einem Ereignis oder Ort fährt, um darüber zu berichten. Zusammengestellt wird die Zeitung in der Redaktion.", "Viele Zeitungen können an einem Kiosk oder in einem Geschäft gekauft werden. Manche Zeitungen sind kostenlos erhältlich. Eine Zeitung ist oft auch als Abonnement erhältlich. Sie wird dann regelmäßig direkt mit der Post geliefert. Für alle gelieferten Zeitungen muss dann einmal im Monat oder im Jahr ein Gesamtpreis bezahlt werden.", "Viele Zeitungen verdienen Geld auch durch Reklame: Unternehmer zahlen für Anzeigen, das sind Flächen in der Zeitung, auf denen Werbung für etwas gemacht wird. Ohne Reklame wären Zeitungen viel teurer. Allerdings kann man befürchten, dass eine Zeitung vielleicht manches nicht schreibt, weil die Reklame-Kunden das schlecht fänden.", "Heute gibt es auch Zeitungen im Internet. Diese werden Internet-Zeitungen oder Online-Zeitungen genannt. Vieles davon können die Leser kostenlos lesen. Darum wird es für Online-Zeitungen schwieriger, Geld zu verdienen."], "zh": ["报纸是新闻和报道的汇集。报纸定期出版，大多每天或每周一次。报纸向读者报道新鲜事。一般说报纸指的是印刷品。", "Zeitung 这个词本身原来就是「消息」的意思。如今报纸把各种新闻和新鲜事收在文章里。报纸文章就是登在报纸上的一篇稿子。报纸大多分成不同的版块，叫栏目：政治、本地、经济、媒体或体育。这样读者可以有针对性地翻到某个主题的文章。", "为报纸或其他媒体制作内容的人叫记者。去事件现场或某个地方做报道的记者叫采访记者。报纸在编辑部里编排。", "很多报纸可以在报亭或商店买到，有些报纸免费。报纸也常可以订阅，这样会定期通过邮局直接送到家，每月或每年为所有送来的报纸付一笔总价。", "很多报纸也靠广告挣钱：企业主付钱买广告位，也就是报纸上为某样东西做广告的版面。没有广告，报纸会贵很多。不过人们会担心，报纸也许有些事不写，因为广告客户会不喜欢。", "如今网上也有报纸，叫网络报纸或在线报纸。其中很多内容读者可以免费看，所以在线报纸挣钱变难了。"], "lemmas": [], "gloss": [{"w": "erscheinen", "de": "herauskommen, veröffentlicht werden", "zh": "出版"}, {"w": "Rubriken", "de": "Teile einer Zeitung zu einem Thema", "zh": "栏目"}, {"w": "Redaktion", "de": "Büro, in dem die Zeitung gemacht wird", "zh": "编辑部"}, {"w": "Abonnement", "de": "man bekommt etwas regelmäßig und bezahlt dafür", "zh": "订阅"}, {"w": "Reklame", "de": "Werbung", "zh": "广告"}], "qs": [{"q": "Was bedeutete das Wort „Zeitung“ ursprünglich?", "qZh": "Zeitung 这个词原来是什么意思？", "answer": "Nachricht.", "wrong": ["Papier.", "Woche."]}, {"q": "Was ist ein Reporter?", "qZh": "采访记者是什么人？", "answer": "Ein Journalist, der zu einem Ereignis fährt und darüber berichtet.", "wrong": ["Jemand, der Zeitungen verkauft.", "Jemand, der Anzeigen bezahlt."]}, {"q": "Warum wird es für Online-Zeitungen schwieriger, Geld zu verdienen?", "qZh": "为什么在线报纸挣钱变难了？", "answer": "Vieles können die Leser kostenlos lesen.", "wrong": ["Niemand liest mehr Nachrichten.", "Sie dürfen keine Werbung haben."]}], "src": "改编自 Klexikon《Zeitung》", "url": "https://klexikon.zum.de/index.php?oldid=159355", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-004", "seg": 10, "title": "Zeitungsente", "de": ["Eine Zeitungsente ist eine Geschichte, die nicht stimmt. So eine Geschichte oder Nachricht steht in einer Zeitung und handelt von etwas, das es nicht gibt oder nicht passiert ist. Der Journalist, der das geschrieben hat, hat sich geirrt. Manchmal vermutet man aber auch, dass jemand etwas Falsches geschrieben hat, obwohl er es besser wusste.", "Heute spricht man nicht mehr so oft von Zeitungsente. Außer Zeitungen gibt es mittlerweile auch andere Medien für Nachrichten, zum Beispiel das Fernsehen und das Internet. Man sagt heute oft „fake news“. Das ist Englisch für „gefälschte Nachrichten“.", "Wer Nachrichten schreibt, kann sich irren. Vielleicht hat er nicht richtig zugehört. Manchmal lügen die Leute einen Journalisten an, damit er was Falsches schreibt. Einige Journalisten prüfen eine Geschichte nicht gut genug nach, weil sie keine Zeit dazu haben. Schließlich könnte es sein, dass ein Journalist die Geschichte gar nicht nachprüfen will: Sie hört sich so toll an, dass viele Leute sie lesen wollen. Dann verkauft man viele Zeitungen."], "zh": ["「报纸鸭子」（Zeitungsente）是不真实的报道。这样的报道或新闻登在报纸上，讲的是不存在或没发生过的事。写报道的记者弄错了。但有时人们也怀疑，有人明知不对还故意写了错误的内容。", "如今人们不太常说 Zeitungsente 了。除了报纸，现在还有别的新闻媒体，比如电视和互联网。人们现在常说 fake news，这是英语，意思是「假新闻」。", "写新闻的人可能会出错。也许他没听清楚；有时人们故意对记者撒谎，好让他写错。有些记者没有好好核实，因为没时间。最后也可能是记者根本不想核实：故事听起来太精彩了，很多人都想看，这样报纸就能卖得多。"], "lemmas": [], "gloss": [{"w": "geirrt", "de": "sich irren: etwas Falsches glauben", "zh": "弄错"}, {"w": "gefälschte", "de": "nicht echt, falsch gemacht", "zh": "伪造的"}, {"w": "nachprüfen", "de": "kontrollieren, ob etwas stimmt", "zh": "核实"}], "qs": [{"q": "Was ist eine Zeitungsente?", "qZh": "什么是「报纸鸭子」？", "answer": "Eine Geschichte in der Zeitung, die nicht stimmt.", "wrong": ["Ein Tier auf der Titelseite.", "Eine sehr alte Zeitung."]}, {"q": "Wie sagt man heute oft statt „Zeitungsente“?", "qZh": "如今人们常用什么代替 Zeitungsente？", "answer": "Fake News.", "wrong": ["Breaking News.", "Good News."]}, {"q": "Warum prüft ein Journalist eine Geschichte manchmal nicht nach?", "qZh": "记者为什么有时不核实报道？", "answer": "Er hat keine Zeit oder die Geschichte verkauft sich gut.", "wrong": ["Es ist verboten, Geschichten zu prüfen.", "Die Leser wollen nur wahre Geschichten."]}], "src": "改编自 Klexikon《Zeitungsente》", "url": "https://klexikon.zum.de/index.php?oldid=154942", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-005", "seg": 10, "title": "Information", "de": ["Eine Information ist ein Stück Wissen. Das Wort kommt aus dem Lateinischen und ist verwandt mit unserem Wort „Form“, im Sinne von Aussehen oder Gestalt. An einer Bushaltestelle findet man zum Beispiel eine Tabelle mit der Information, wann die Busse fahren. Bei einer „Information“ denkt man an etwas kleines, bestimmtes, bei „Wissen“ denkt man eher an viele Informationen in einem Zusammenhang. Die Information ist mehr das, was sich im Computer oder im Bücherregal befindet, Wissen ist das, was jemand im Kopf hat.", "Unter dem Wort Information kann man vieles verstehen. Meistens denkt man an das Wissen selbst. Es gibt aber auch Orte, die man „Information“ nennt, etwa in einem Bahnhof oder die Tourist-Information in einer Stadt. Ein anderes Wort dafür wäre „Auskunft“.", "Eine Information versteht man oft erst, wenn man den Zusammenhang kennt, wenn man weiß, wozu man sie verwenden kann. Wenn ein Auto zehntausend Euro kostet, muss man wissen, was für ein Auto das genau ist und wo man es für diesen Preis bekommt. Informationen, die man in bestimmter Weise an bestimmten Stellen hinterlegt hat, nennt man auch Daten. Viele Daten zusammen können in einer Datenbank gespeichert werden.", "Manche Leute sprechen sogar von einer „Informationsflut“: vor lauter Informationen wird es schwierig, herauszufinden, welche davon überhaupt für einen selbst wichtig sind. Außerdem kann jemand, der eine Information herstellt oder weitergibt, sich geirrt haben. Informationen können also fehlerhaft sein, aber auch veralten.", "Informationen sind nützlich, damit man etwas entscheiden kann. Wer etwa ein Haus bauen will, braucht viele Informationen, zum Beispiel über den Boden, wo er bauen will. Wenn Politiker über Gesetze entscheiden, brauchen sie Informationen. Dann können sie besser abschätzen, welche Folgen das Gesetz für die Menschen haben könnte."], "zh": ["信息是一点知识。这个词来自拉丁语，和我们的 Form（形状、外观）一词同源。比如在公交车站能看到一张表格，上面有公交车几点开的信息。说「信息」时，人们想到的是一点具体的小东西；说「知识」时，想到的更多是很多相互联系的信息。信息更像是电脑里或书架上的东西，知识则是人脑子里的东西。", "Information 这个词可以有很多意思。人们大多想到知识本身。但也有一些地方叫 Information，比如火车站里的问讯处或城市里的游客问讯处，另一个说法是 Auskunft。", "一条信息常常要知道上下文、知道它能用来做什么，才能理解。如果一辆车卖一万欧元，就得知道具体是什么车、在哪里能以这个价钱买到。按一定方式存放在特定地方的信息也叫数据，很多数据可以存在数据库里。", "有人甚至说「信息泛滥」：信息太多，很难找出哪些对自己真正重要。而且制造或转述信息的人也可能弄错了。所以信息可能有错，也可能过时。", "信息对做决定很有用。比如想盖房子，就需要很多信息，比如要盖房那块地的土壤情况。政治家决定法律时也需要信息，这样才能更好地估计法律会给人们带来什么后果。"], "lemmas": [], "gloss": [{"w": "Zusammenhang", "de": "wie Dinge miteinander verbunden sind", "zh": "上下文、联系"}, {"w": "Auskunft", "de": "Ort oder Person, die Informationen gibt", "zh": "问讯处"}, {"w": "Datenbank", "de": "Ort im Computer, wo viele Daten gespeichert sind", "zh": "数据库"}, {"w": "veralten", "de": "alt und nicht mehr richtig werden", "zh": "过时"}, {"w": "abschätzen", "de": "ungefähr beurteilen", "zh": "估计"}], "qs": [{"q": "Was ist der Unterschied zwischen Information und Wissen?", "qZh": "信息和知识有什么区别？", "answer": "Wissen ist das, was jemand im Kopf hat.", "wrong": ["Information ist immer richtig.", "Wissen findet man nur im Computer."]}, {"q": "Was ist ein anderes Wort für die „Information“ im Bahnhof?", "qZh": "火车站的 Information 还可以怎么说？", "answer": "Auskunft.", "wrong": ["Datenbank.", "Fahrkarte."]}, {"q": "Was ist das Problem bei einer „Informationsflut“?", "qZh": "「信息泛滥」的问题是什么？", "answer": "Es ist schwer zu finden, welche Informationen wichtig sind.", "wrong": ["Es gibt zu wenige Informationen.", "Computer gehen kaputt."]}], "src": "改编自 Klexikon《Information》", "url": "https://klexikon.zum.de/index.php?oldid=158569", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-006", "seg": 10, "title": "Wissen", "de": ["Als Wissen bezeichnet man bekannte Informationen oder Sachverhalte, bei denen sicher ist, dass sie stimmen. Es ist also die Kenntnis von Tatsachen. Eng verwandt mit dem Wissen sind Begriffe wie „Überzeugung“ oder „allgemeine Meinung“. Der Unterschied von Wissen zu diesen Begriffen lässt sich aber manchmal nur schwer erklären.", "Manchmal sind viele der Meinung, dass etwas richtig sei. Man sagt: „Es herrscht die allgemeine Meinung vor.“ Trotzdem kann es falsch sein. Nur weil sehr viele denken, dass ein Flügelschlag eines Schmetterlings keinen Sturm erzeugen kann, muss das nicht stimmen. In Wirklichkeit können ungünstige Kettenreaktionen tatsächlich zum Sturm führen. So etwas bezeichnet man auch als „Schmetterlingseffekt“.", "Früher waren die Menschen der Überzeugung, dass sich die Erde in der Mitte des Universums befindet. Dies wurde als Wissen auch in den Schulen und Universitäten gelehrt. Später fand Nikolaus Kopernikus heraus, dass das nicht stimmt. Es dauerte aber lange, bis dies von allen als richtig anerkannt wurde. Das Wissen hat sich also verändert. Was früher als richtig galt, war plötzlich falsch.", "Manchmal verschwindet Wissen auch einfach. Wenn Erkenntnisse nicht an die Nachkommen weitergegeben werden, so kann es passieren, dass irgendwann niemand mehr weiß, was vorher einmal zum Wissen gehörte. Das Mittelalter war so eine Zeit, in der viele Erkenntnisse der Wissenschaft verloren gingen. Das Wissen wurde entweder gar nicht erst in Büchern aufgeschrieben oder Bibliotheken sind abgebrannt. Erst viel später hat man in alten Schriften aus fernen Ländern längst vergessenes Wissen wiederentdeckt."], "zh": ["知识指的是已知的、确定是真的信息或事实，也就是对事实的了解。和知识密切相关的概念有「信念」或「普遍看法」。不过知识和这些概念的区别，有时很难说清楚。", "有时很多人都认为某件事是对的，人们说：「普遍看法占上风。」但它仍可能是错的。很多人认为蝴蝶扇一下翅膀不可能引起风暴，但这不一定对。实际上，不利的连锁反应确实可能导致风暴，这也叫「蝴蝶效应」。", "以前人们相信地球位于宇宙的中心，这在学校和大学里也被当作知识来教。后来尼古拉·哥白尼发现这是错的。不过过了很久，大家才都承认这一点是对的。所以知识发生了变化：以前被认为对的，突然就错了。", "有时知识也会干脆消失。如果认识没有传给后人，可能某一天就再也没有人知道以前曾属于知识的东西。中世纪就是这样一个时期，很多科学认识失传了。知识要么根本没写进书里，要么图书馆被烧毁了。直到很久以后，人们才在远方国家的古籍里重新发现了早已被遗忘的知识。"], "lemmas": [], "gloss": [{"w": "Tatsachen", "de": "Dinge, die wirklich so sind", "zh": "事实"}, {"w": "Überzeugung", "de": "was man fest glaubt", "zh": "信念"}, {"w": "Kettenreaktionen", "de": "eine Sache führt zur nächsten", "zh": "连锁反应"}, {"w": "anerkannt", "de": "von allen als richtig angenommen", "zh": "被承认的"}, {"w": "Nachkommen", "de": "Kinder, Enkel und spätere Menschen", "zh": "后人"}], "qs": [{"q": "Was ist der Schmetterlingseffekt?", "qZh": "什么是蝴蝶效应？", "answer": "Kleine Dinge können durch Kettenreaktionen einen Sturm machen.", "wrong": ["Schmetterlinge fliegen im Sturm.", "Viele Menschen haben immer recht."]}, {"q": "Was fand Nikolaus Kopernikus heraus?", "qZh": "哥白尼发现了什么？", "answer": "Die Erde ist nicht in der Mitte des Universums.", "wrong": ["Die Erde ist flach.", "Die Sonne dreht sich um den Mond."]}, {"q": "Warum gingen im Mittelalter viele Erkenntnisse verloren?", "qZh": "中世纪为什么很多认识失传了？", "answer": "Sie wurden nicht aufgeschrieben oder Bibliotheken brannten ab.", "wrong": ["Niemand konnte lesen.", "Die Bücher waren zu teuer."]}], "src": "改编自 Klexikon《Wissen》", "url": "https://klexikon.zum.de/index.php?oldid=158162", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-007", "seg": 10, "title": "Kommunikation", "de": ["Kommunikation bedeutet, dass man sich miteinander austauscht. Wenn ein Mensch etwas zu einem anderen sagt, ist das Kommunikation. Es ist dabei egal, ob das Gesprochene lustig oder traurig ist. Es ist sogar egal, ob die beiden überhaupt miteinander sprechen, sich nur zuwinken oder technische Geräte benutzen. Es können auch mehrere Menschen gleichzeitig beteiligt sein.", "Hauptsache, sie tauschen etwas miteinander aus. Nur dann betreiben sie Kommunikation. Man kann auch sagen: sie kommunizieren. Das Wort kommt vom lateinischen Wort „communicare“. Das bedeutet übersetzt: etwas teilen, mitteilen, gemeinsam tun.", "Ohne Kommunikation würden Tiere und Menschen vereinsamen und sehr traurig werden. Kinder, deren Eltern nicht mit ihnen sprechen, sind oft traurig. Kommunikation fällt den meisten Menschen leicht. Aber es gibt viele, die das nicht gut können, vielleicht weil ihre Seele krank ist und sie dann nicht verstehen, was wir meinen, wenn wir sie anlächeln. Und es gibt andere, die lernen wollen, besser zu kommunizieren. Die üben dann Kommunikation. Lehrer studieren das, weil die Kommunikation mit den Schülern wichtig ist.", "Kommunikation ist so interessant, dass Wissenschaftler sie erforschen. Manche haben herausgefunden, dass in unserem Gehirn etwas Besonderes passiert, wenn wir mit anderen etwas zusammen machen, eben kommunizieren. Andere erforschen, ob es gut für die Menschen ist, wenn sie immer mehr über Smartphones und das Internet miteinander kommunizieren, statt miteinander zu reden.", "Auch Tiere kommunizieren miteinander, zum Beispiel wenn Vögel im Herbst zusammen in den Süden fliegen, wo es wärmer ist. Jeder Vogel achtet dabei auf seinen Nachbarn, man tauscht Blicke aus und gibt mit dem Schnabel Geräusche von sich. Ein Hund kommuniziert mit seinen Besitzern, wenn er winselt und an die frische Luft gehen will."], "zh": ["交流就是彼此交换。一个人对另一个人说了些什么，这就是交流。说的内容好笑还是悲伤都没关系。甚至两人是不是在说话、只是挥挥手、还是在用技术设备，也都没关系。也可以有好几个人同时参与。", "重要的是他们相互交换了些什么，只有这样才是在交流，也可以说他们在沟通。这个词来自拉丁语 communicare，翻译过来是：分享、告知、一起做。", "没有交流，动物和人都会变得孤独、非常难过。父母不和他们说话的孩子常常不开心。大多数人觉得交流很容易，但也有很多人不太擅长，也许是因为他们心理有病，我们对他们微笑时，他们不明白我们的意思。还有些人想学着更好地沟通，于是就练习交流。教师会学这个，因为和学生交流很重要。", "交流非常有意思，所以科学家研究它。有些人发现，我们和别人一起做事、也就是交流时，大脑里会发生特别的事。另一些人研究，人们越来越多地通过智能手机和互联网交流、而不是面对面说话，这对人是否有好处。", "动物之间也会交流，比如秋天鸟儿一起飞往更暖和的南方。每只鸟都留意身边的同伴，彼此交换眼神，用喙发出声音。狗呜呜叫着想出去透透气时，也是在和主人交流。"], "lemmas": [], "gloss": [{"w": "austauscht", "de": "gibt und bekommt (Informationen)", "zh": "交换"}, {"w": "zuwinken", "de": "mit der Hand ein Zeichen geben", "zh": "挥手"}, {"w": "vereinsamen", "de": "ganz allein und einsam werden", "zh": "变得孤独"}, {"w": "erforschen", "de": "wissenschaftlich untersuchen", "zh": "研究"}, {"w": "winselt", "de": "leise, traurige Töne machen (Hund)", "zh": "呜呜叫"}], "qs": [{"q": "Was bedeutet das lateinische Wort „communicare“?", "qZh": "拉丁语 communicare 是什么意思？", "answer": "Etwas teilen oder mitteilen.", "wrong": ["Etwas kaufen.", "Etwas vergessen."]}, {"q": "Was passiert ohne Kommunikation?", "qZh": "没有交流会怎样？", "answer": "Menschen und Tiere werden einsam und traurig.", "wrong": ["Menschen werden klüger.", "Tiere fliegen in den Süden."]}, {"q": "Wie kommuniziert ein Hund mit seinen Besitzern?", "qZh": "狗怎样和主人交流？", "answer": "Er winselt, wenn er hinaus will.", "wrong": ["Er schreibt Nachrichten.", "Er fliegt in den Süden."]}], "src": "改编自 Klexikon《Kommunikation》", "url": "https://klexikon.zum.de/index.php?oldid=157717", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-008", "seg": 10, "title": "Smartphone", "de": ["Ein Smartphone ist ein Telefon, mit dem man auch im Internet surfen und viele andere Sachen machen kann. Es ist eine Weiterentwicklung des Handys. Der Name kommt aus dem Englischen und bedeutet so viel wie „schlaues Telefon“. Smartphones sind eigentlich kleine Computer, auf denen verschiedene Programme installiert sind. Diese Programme nennt man Apps. Mit ihnen kann man zum Beispiel Musik hören, fotografieren, Spiele spielen, E-Mails und andere Botschaften austauschen oder auch einen Kalender führen.", "Die ersten Smartphones stellte die finnische Firma Nokia her, schon 1996. Richtig bekannt wurde aber erst das iPhone der Firma Apple im Jahr 2007. Bald darauf brachten auch andere Firmen eigene Smartphones heraus. Ein besonders großer Hersteller heute ist Samsung.", "Anders als die ersten Smartphones haben die meisten heutigen Modelle keine Tasten mehr, sondern werden direkt über den Bildschirm gesteuert. Den kann man mit dem Finger berühren oder darauf „wischen“, um die einzelnen Funktionen und Apps zu starten. Fast jedes Smartphone hat eine ziemlich gute Kamera, darum kauft sich kaum noch jemand eine Kompaktkamera.", "Für die Firmen wird es schwierig, sich etwas Neues auszudenken, damit man mehr Geräte verkauft als die anderen Firmen. Neue Smartphones haben oft ein schärferes Bild und funktionieren schneller. Dafür verbrauchen sie aber vielleicht mehr Strom, so dass der Akku rasch leer ist. Eine richtig neue Idee ist das faltbare Smartphone. Dann aber wieder gibt es nicht so viele Apps, die mit einem geteilten Bildschirm gut umgehen können."], "zh": ["智能手机是一种也能上网、能做很多别的事的电话，是手机的进一步发展。这个名字来自英语，大致意思是「聪明的电话」。智能手机其实是装了各种程序的小电脑，这些程序叫应用（App）。用它们可以听音乐、拍照、玩游戏、收发电子邮件和其他消息，也可以记日程。", "最早的智能手机是芬兰诺基亚公司在 1996 年就造出来的。但真正出名的是苹果公司 2007 年的 iPhone。不久以后别的公司也推出了自己的智能手机。如今特别大的一家制造商是三星。", "和最早的智能手机不同，现在大多数型号已经没有按键，而是直接在屏幕上操作。可以用手指点屏幕或在上面「滑动」，来启动各种功能和应用。几乎每部智能手机都有相当好的摄像头，所以几乎没人再买卡片相机了。", "对公司来说，想出新东西、比别家卖出更多手机越来越难。新手机常常画面更清晰、运行更快，但也许更耗电，电池很快就没电了。真正新的点子是折叠屏手机。可是能很好地适应分屏的应用又没那么多。"], "lemmas": [], "gloss": [{"w": "Weiterentwicklung", "de": "neue, bessere Form von etwas", "zh": "进一步发展"}, {"w": "installiert", "de": "auf einem Gerät eingerichtet", "zh": "安装的"}, {"w": "Tasten", "de": "Knöpfe zum Drücken", "zh": "按键"}, {"w": "Akku", "de": "Batterie, die man wieder laden kann", "zh": "电池"}, {"w": "faltbare", "de": "man kann es zusammenklappen", "zh": "可折叠的"}], "qs": [{"q": "Was bedeutet „Smartphone“ ungefähr?", "qZh": "Smartphone 大致是什么意思？", "answer": "Schlaues Telefon.", "wrong": ["Kleines Telefon.", "Schnelles Telefon."]}, {"q": "Welche Firma stellte die ersten Smartphones her?", "qZh": "哪家公司造出了最早的智能手机？", "answer": "Nokia.", "wrong": ["Apple.", "Samsung."]}, {"q": "Warum kauft sich kaum noch jemand eine Kompaktkamera?", "qZh": "为什么几乎没人再买卡片相机了？", "answer": "Fast jedes Smartphone hat eine gute Kamera.", "wrong": ["Kameras sind verboten.", "Fotos sind nicht mehr beliebt."]}], "src": "改编自 Klexikon《Smartphone》", "url": "https://klexikon.zum.de/index.php?oldid=159404", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-009", "seg": 10, "title": "E-Mail", "de": ["Eine E-Mail ist ein elektronischer Brief. Wer eine E-Mail schicken oder erhalten möchte, braucht einen Internetzugang und einen Computer oder ein Handy. Man kann das mit einem Computerprogramm machen, aber auch über eine Internetseite.", "Das Programm oder die Website hilft dabei, die Nachricht zu schreiben. Es merkt sich nämlich die Adressen, an die man schon einmal etwas geschickt hat. Außerdem werden die eigenen und die erhaltenen E-Mails gespeichert.", "E-Mails wurden um das Jahr 1990 immer beliebter, weil sie im Vergleich zu einem Brief den Empfänger viel schneller erreichen. Als Erfinder gilt der amerikanische Forscher Ray Tomlinson. Für die Regierung der USA entwickelte er etwas, das schon so ähnlich wie das heutige Internet aussah. E-Mails waren eigentlich dazu gedacht, Informationen zwischen Computern und nicht zwischen Menschen auszutauschen. Die Anwender nutzten sie aber genau dafür. Tomlinson führte auch das Zeichen „@“ ein, weil es bisher nicht verwendet wurde.", "Eine E-Mail-Adresse kann zum Beispiel so aussehen: name@beispielwort.com. Eine E-Mail-Adresse hat zwei Teile: Der erste Teil gehört zum einzelnen Benutzer. Der zweite Teil gehört zum Server, das ist der Ort, an dem die E-Mail ankommt und abgeholt wird. Dazwischen steht das @-Zeichen. Viele nennen es das „Ätt-Zeichen\", vom englischen Wort „at“, das „bei“ bedeutet. Ein alter deutscher Name dafür ist „Klammeraffe“.", "In einer E-Mail steht nicht nur Text. Manchen E-Mails ist auch eine Datei oder ein Programm mitgegeben. Manche dieser Dateien oder Programme sind gefährlich. Wenn man die E-Mail öffnet, um sie zu lesen, kommt die Datei oder das Programm gleich auf den eigenen Computer. Es startet von alleine und macht schädliche Dinge."], "zh": ["电子邮件是一种电子信件。想发送或接收电子邮件，需要能上网，还需要电脑或手机。可以用电脑程序，也可以通过网页来收发。", "程序或网站会帮你写信：它记得你以前发过邮件的地址。另外，自己发的和收到的邮件都会保存下来。", "大约从 1990 年起，电子邮件越来越受欢迎，因为它比信件快得多地送到收件人手里。美国研究员雷·汤姆林森被认为是它的发明者。他为美国政府开发了一种已经和今天的互联网很像的东西。电子邮件本来是用来在电脑之间而不是人与人之间交换信息的，但用户恰恰拿它来做这个。汤姆林森还引入了「@」这个符号，因为它以前没人用。", "电子邮件地址比如可以是这样：name@beispielwort.com。电子邮件地址有两部分：第一部分属于单个用户，第二部分属于服务器，也就是邮件到达和被取走的地方。中间是 @ 符号。很多人把它叫作「Ätt 符号」，来自英语 at，意思是「在」。它有个古老的德语名字叫「Klammeraffe」（抱着的猴子）。", "电子邮件里不只有文字，有些邮件还附带文件或程序，其中有些是危险的。打开邮件阅读时，文件或程序会马上进到自己的电脑里，自动启动，做有害的事。"], "lemmas": [], "gloss": [{"w": "Internetzugang", "de": "Möglichkeit, ins Internet zu gehen", "zh": "上网条件"}, {"w": "gespeichert", "de": "aufbewahrt im Computer", "zh": "保存的"}, {"w": "Erfinder", "de": "jemand, der etwas Neues erfindet", "zh": "发明者"}, {"w": "Server", "de": "großer Computer, der Daten für andere bereithält", "zh": "服务器"}, {"w": "schädliche", "de": "die Schaden machen", "zh": "有害的"}], "qs": [{"q": "Warum wurden E-Mails um 1990 beliebter?", "qZh": "为什么大约 1990 年起电子邮件更受欢迎了？", "answer": "Sie erreichen den Empfänger viel schneller als ein Brief.", "wrong": ["Sie sind schöner als Briefe.", "Briefe wurden verboten."]}, {"q": "Wer gilt als Erfinder der E-Mail?", "qZh": "谁被认为是电子邮件的发明者？", "answer": "Ray Tomlinson.", "wrong": ["Mark Zuckerberg.", "Steve Jobs."]}, {"q": "Warum sollte man bei Dateien in E-Mails vorsichtig sein?", "qZh": "为什么要小心邮件里的文件？", "answer": "Manche Dateien oder Programme sind gefährlich.", "wrong": ["Sie machen die E-Mail zu lang.", "Man muss dafür bezahlen."]}], "src": "改编自 Klexikon《E-Mail》", "url": "https://klexikon.zum.de/index.php?oldid=160500", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-010", "seg": 10, "title": "WhatsApp", "de": ["WhatsApp ist eine App für Smartphones und größere Computer. Damit können sich zwei oder mehr Menschen Nachrichten schicken. Diese Nachrichten können Texte enthalten, Tonaufnahmen, Fotos oder Videos. WhatsApp heißt auf Deutsch etwa „Was geht ab?“ oder „Was ist los?“", "Im Gegensatz zur SMS müssen alle Beteiligten einen Internetzugang haben. Man muss seine Handynummer angeben, um sich anzumelden. Einige Zeit kostet WhatsApp jedes Jahr etwas, aber seit 2016 kann man es wieder kostenlos nutzen.", "Mehr als eine Milliarde Menschen nutzen die App. Täglich werden damit mehr als 55 Milliarden Nachrichten verschickt. Die Firma, die WhatsApp erfunden hat, wurde 2009 in Kalifornien in den USA gegründet. Im Jahr 2014 wurde die App von Facebook gekauft. Facebook ist ein soziales Netzwerk, in dem man auch Neuigkeiten verbreiten und mit anderen in Kontakt treten kann.", "Für WhatsApp bezahlte Facebook viel Geld. Nicht jeder fand den Kauf gut, denn Facebook merkt sich, wer die Benutzer sind und was sie mögen. Dadurch können Unternehmen wie Facebook gezielt Werbung sowohl auf Internetseiten als auch in Apps einblenden und so Geld einnehmen.", "Wenn man bei WhatsApp etwas über sich schreibt oder Bilder verschickt, dann erhält das zwar nur der Empfänger. Dieser kann das aber sehr einfach weiterverbreiten. Das kann so gehen wie bei einer Lawine."], "zh": ["WhatsApp 是一款用于智能手机和电脑的应用。两个或更多的人可以用它互发消息。消息可以是文字、录音、照片或视频。WhatsApp 用德语说大概是「怎么样？」或「出什么事了？」。", "和短信不同，所有参与者都必须能上网。注册时必须填写手机号。有一段时间 WhatsApp 每年要收一点钱，但从 2016 年起又可以免费使用了。", "超过十亿人在用这款应用，每天发送的消息超过 550 亿条。发明 WhatsApp 的公司 2009 年在美国加利福尼亚成立。2014 年这款应用被 Facebook 收购。Facebook 是一个社交网络，在上面也可以传播新鲜事、和别人联系。", "Facebook 为 WhatsApp 付了很多钱。并不是人人都觉得这笔收购是好事，因为 Facebook 会记住用户是谁、喜欢什么。这样 Facebook 这类公司就能在网页和应用里有针对性地投放广告来挣钱。", "在 WhatsApp 上写自己的事或发图片，虽然只有收件人收到，但他可以非常轻松地继续转发。这可能像雪崩一样一发不可收拾。"], "lemmas": [], "gloss": [{"w": "Tonaufnahmen", "de": "aufgenommene Töne oder Stimmen", "zh": "录音"}, {"w": "Beteiligten", "de": "alle, die mitmachen", "zh": "参与者"}, {"w": "soziales Netzwerk", "de": "Website, auf der Menschen Kontakt haben", "zh": "社交网络"}, {"w": "einblenden", "de": "auf dem Bildschirm zeigen", "zh": "显示、插入"}, {"w": "Lawine", "de": "viel Schnee, der den Berg hinunterstürzt", "zh": "雪崩"}], "qs": [{"q": "Was braucht man, um WhatsApp zu nutzen?", "qZh": "用 WhatsApp 需要什么？", "answer": "Einen Internetzugang und eine Handynummer.", "wrong": ["Nur ein altes Telefon ohne Internet.", "Ein Facebook-Konto."]}, {"q": "Wer kaufte WhatsApp im Jahr 2014?", "qZh": "2014 年谁收购了 WhatsApp？", "answer": "Facebook.", "wrong": ["Google.", "Nokia."]}, {"q": "Warum sollte man bei WhatsApp vorsichtig sein?", "qZh": "为什么用 WhatsApp 要小心？", "answer": "Der Empfänger kann Bilder sehr einfach weiterverbreiten.", "wrong": ["Nachrichten kommen nie an.", "WhatsApp ist sehr teuer."]}], "src": "改编自 Klexikon《WhatsApp》", "url": "https://klexikon.zum.de/index.php?oldid=160703", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-011", "seg": 10, "title": "Facebook", "de": ["Facebook ist der Name einer Website. Auf dieser Website treffen sich Menschen nicht wirklich, aber sie tauschen ihre Gedanken und Bilder aus. Die Menschen geben an, welche anderen Menschen sie als ihre Freunde ansehen. Diese Menschen sind wie die Knoten eines Netzes. Darum nennt man eine Website wie Facebook auch ein Netzwerk.", "Die Website Facebook gehört einem Unternehmen, das genauso heißt. Der Chef dieses Unternehmens ist Mark Zuckerberg. Er hat Facebook im Jahr 2004 gegründet. Damals war er noch Student an einer Universität. Eigentlich wollte er eine Website haben, auf der man schreiben konnte, welche Frauen man schön findet. Zuckerberg ist heute einer der reichsten Männer der Welt.", "Wer bei Facebook mitmachen will, erstellt ein Konto. Vom Konto aus schreibt man etwas oder man lädt Bilder hoch. Dann sucht man andere Menschen mit Konten und schreibt sie an.", "Die Website merkt sich alles, was die Mitmacher tun. Die Website sammelt diese Information, damit sie den Mitmachern Werbung zeigen kann. Diese Werbung soll von Dingen handeln, die für den Mitmacher interessant sein können. Wer also viel über Fußball schreibt, der bekommt oft Werbung zu sehen, die mit Fußball zu tun hat.", "Es gibt viele Menschen, die das schlecht finden. Eine Website soll nicht so viel über die Mitmacher wissen. Das könnte einmal gegen die Mitmacher genutzt werden. Außerdem denken viele, dass Facebook gegen den Datenschutz verstößt, weil es Daten über seine Mitmacher sammelt und diese verkauft.", "Wenn man bei Facebook ein Konto hat und etwas über sich schreibt oder Bilder teilt, dann können alle Menschen im Internet es sehen. Man kann zwar das Konto so einstellen, dass nur Freunde das sehen können. Aber davon muss man erst einmal wissen und es dann auch tun."], "zh": ["Facebook 是一个网站的名字。人们在这个网站上并不真正见面，但会交流想法和图片。人们标明把哪些人当作自己的朋友。这些人就像一张网的结点，所以像 Facebook 这样的网站也叫网络。", "Facebook 网站属于一家同名公司，公司老板是马克·扎克伯格。他 2004 年创办了 Facebook，当时还是大学生。他本来只想做一个网站，在上面写自己觉得哪些女生漂亮。如今扎克伯格是世界上最富有的人之一。", "想加入 Facebook 的人要创建一个账号。从账号上写东西或上传图片，然后搜索别的有账号的人，给他们发消息。", "网站会记住用户做的一切。它收集这些信息，好给用户看广告，这些广告应该是用户可能感兴趣的东西。所以常写足球的人，会经常看到和足球有关的广告。", "很多人觉得这样不好。一个网站不应该对用户了解这么多，这有一天可能被用来对付用户。此外很多人认为 Facebook 违反了数据保护，因为它收集用户的数据并出售。", "在 Facebook 上有账号、写自己的事或分享图片的话，网上所有人都能看到。虽然可以把账号设置成只有朋友能看，但首先得知道有这个功能，还得真的去设置。"], "lemmas": [], "gloss": [{"w": "Knoten", "de": "Punkte, an denen sich Linien treffen", "zh": "结点"}, {"w": "gegründet", "de": "neu angefangen (Firma)", "zh": "创办"}, {"w": "Konto", "de": "persönlicher Zugang auf einer Website", "zh": "账号"}, {"w": "lädt", "de": "hier: lädt … hoch = schickt Dateien ins Internet", "zh": "上传"}, {"w": "verstößt", "de": "gegen eine Regel handeln", "zh": "违反"}], "qs": [{"q": "Wann hat Mark Zuckerberg Facebook gegründet?", "qZh": "扎克伯格什么时候创办了 Facebook？", "answer": "Im Jahr 2004.", "wrong": ["Im Jahr 1990.", "Im Jahr 2014."]}, {"q": "Warum sammelt Facebook Informationen über seine Mitmacher?", "qZh": "Facebook 为什么收集用户信息？", "answer": "Um ihnen passende Werbung zu zeigen.", "wrong": ["Um ihnen Geld zu schenken.", "Um sie zu Fußballspielen einzuladen."]}, {"q": "Was kann man tun, damit nur Freunde die eigenen Beiträge sehen?", "qZh": "怎样才能只让朋友看到自己的帖子？", "answer": "Das Konto entsprechend einstellen.", "wrong": ["Weniger Bilder hochladen.", "Ein zweites Konto kaufen."]}], "src": "改编自 Klexikon《Facebook》", "url": "https://klexikon.zum.de/index.php?oldid=158980", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-012", "seg": 10, "title": "Hacker", "de": ["Ein Hacker ist ein Mensch, der sich sehr gut mit Computern und Technik und vor allem mit dem Programmieren auskennt. Hacker können heimlich auf Internetseiten, in PCs, Laptops und Smartphones von anderen Leuten und Unternehmen eindringen und dabei auch Computer-Programme verändern.", "Dabei finden sie auch Passwörter heraus, die eigentlich den Zugang zu einer App oder einem Programm schützen sollen. Wenn ein Hacker so etwas schafft, nennt man das einen Hack. Das wird „Häcker” und „Häck” ausgesprochen.", "Manche Hacker begehen Verbrechen, weil sie zum Beispiel im Internet oder in Geräten Schaden anrichten, Geld von Bankkonten stehlen oder auf anderen Wegen betrügen. Es gibt aber auch Hacker, die gute Absichten haben. Sie finden zum Beispiel heraus, dass ein Computer-Programm oder eine Website nicht sicher ist. Darauf weisen sie dann hin, damit die Probleme gelöst werden und alles wieder sicher ist.", "Einige deutsche Hacker mit guten Absichten haben schon im Jahr 1984 einen Verein gegründet: den „Chaos Computer Club”. Heute hat der Verein mehrere Tausend Mitglieder und trifft sich einmal im Jahr.", "Damit sich Unternehmen vor Angriffen von kriminellen Hackern mit schlechten Absichten schützen können, arbeiten manchmal Hacker für sie. Sie helfen ihnen, Schwachstellen in Apps, Programmen und Geräten zu finden und zu beseitigen. Auch jeder von uns kann sich schützen, indem er oder sie sich Passwörter aussucht, die man nicht so schnell erraten kann. Dafür ist es wichtig, möglichst viele verschiedene Zeichen zu benutzen, also Klein- und Großbuchstaben, Zahlen und auch Sonderzeichen wie % und @."], "zh": ["黑客是非常懂电脑和技术、尤其精通编程的人。黑客能偷偷进入别人和企业的网站、个人电脑、笔记本和智能手机，还能修改电脑程序。", "这时他们也会找出密码，密码本来是用来保护应用或程序的访问权限的。黑客做成了这样的事，就叫一次 Hack。读作「Häcker」和「Häck」。", "有些黑客犯罪，比如在网上或设备里搞破坏、从银行账户偷钱，或用别的方式诈骗。但也有出于好意的黑客。比如他们发现某个电脑程序或网站不安全，就会指出来，好让问题得到解决，一切重新变得安全。", "一些出于好意的德国黑客早在 1984 年就成立了一个协会：「混沌计算机俱乐部」。如今这个协会有几千名会员，每年聚会一次。", "为了让企业能防范怀有恶意的犯罪黑客的攻击，有时黑客会为企业工作，帮它们找出并消除应用、程序和设备里的漏洞。我们每个人也可以保护自己：选不容易被猜到的密码。为此要尽量用多种不同的字符，也就是小写和大写字母、数字，还有 %、@ 这样的特殊符号。"], "lemmas": [], "gloss": [{"w": "heimlich", "de": "so, dass es niemand merkt", "zh": "偷偷地"}, {"w": "eindringen", "de": "ohne Erlaubnis hineingehen", "zh": "侵入"}, {"w": "betrügen", "de": "jemanden täuschen, um Vorteile zu haben", "zh": "诈骗"}, {"w": "Absichten", "de": "was man tun will", "zh": "意图"}, {"w": "Schwachstellen", "de": "Stellen, die nicht sicher sind", "zh": "漏洞"}], "qs": [{"q": "Was können Hacker tun?", "qZh": "黑客能做什么？", "answer": "Heimlich in Computer und Smartphones eindringen.", "wrong": ["Nur Computer verkaufen.", "Telefone reparieren."]}, {"q": "Was machen Hacker mit guten Absichten?", "qZh": "出于好意的黑客做什么？", "answer": "Sie zeigen, wo ein Programm nicht sicher ist.", "wrong": ["Sie stehlen Geld von Bankkonten.", "Sie verkaufen Passwörter."]}, {"q": "Wie kann man sich laut Text selbst schützen?", "qZh": "根据文章，人们怎样保护自己？", "answer": "Mit Passwörtern aus vielen verschiedenen Zeichen.", "wrong": ["Mit sehr kurzen Passwörtern.", "Indem man kein Internet benutzt."]}], "src": "改编自 Klexikon《Hacker》", "url": "https://klexikon.zum.de/index.php?oldid=158521", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-013", "seg": 10, "title": "Datenschutz", "de": ["Datenschutz heißt, dass man Daten nicht einfach nutzen darf. Mit Daten sind Informationen über Menschen gemeint: Name, Geburtsdatum, Wohnort, Telefonnummer und so weiter. Diese Informationen sind etwas sehr Persönliches. Jeder Mensch soll bestimmen können, wer außer ihm selbst diese Informationen haben darf und wer nicht. Der Datenschutz ist deshalb ein wichtiges Recht von Menschen. Im Datenschutzgesetz steht geschrieben, was man mit den Daten anderer Menschen machen darf und was nicht. Hält sich jemand nicht an dieses Gesetz, kann er bestraft werden.", "Jeder kann etwas für den Datenschutz tun. Erstens muss man beachten, dass man Informationen, die man über andere Menschen hat, nicht einfach weitergibt. Zweitens muss jeder selbst überlegen, welche Informationen andere über ihn wissen dürfen. Wenn man zum Beispiel WhatsApp benutzt, muss man auf beides achten, weil man die Informationen mit anderen Menschen teilt.", "Es gibt Menschen und Organisationen, die persönliche Daten über andere Menschen wissen dürfen. Zum Beispiel darf eine Schule etwas über ihre eigenen Schüler wissen. Das muss sie sogar, sonst könnte sie zum Beispiel keine Briefe nach Hause schicken. Die Schule darf solche Daten aber nicht für etwas anderes verwenden, das gar nichts mit der Schule zu tun hat. Sie darf sie auch nicht in der Schulzeitung abdrucken, wo sie dann jeder lesen kann.", "Es gibt aber auch Unternehmen, die mit den Daten anderer Menschen sehr viel Geld verdienen. Dazu gehören zum Beispiel die Internet-Unternehmen Google und Facebook. Wenn jemand auf deren Webseite etwas sucht, dann erfahren sie natürlich, wofür diese Person sich interessiert. Sie verkaufen dieses Wissen dann an andere Unternehmen weiter."], "zh": ["数据保护是说，数据不能随便使用。数据指的是关于人的信息：姓名、出生日期、住址、电话号码等等。这些信息是非常私人的东西。每个人都应该能决定，除了自己以外谁可以拥有这些信息、谁不可以。所以数据保护是人的一项重要权利。《数据保护法》写明了别人的数据可以怎样用、不可以怎样用。不遵守这部法律的人可能会受罚。", "每个人都可以为数据保护出一份力。第一，要注意不随便把掌握的别人的信息传出去。第二，每个人都要自己想想，别人可以知道自己的哪些信息。比如用 WhatsApp 时，这两点都要注意，因为你在和别人分享信息。", "有些人和组织可以知道别人的个人数据。比如学校可以了解自己的学生，而且必须了解，否则就没法给家里寄信。但学校不能把这些数据用在和学校毫无关系的其他事情上，也不能登在人人都能看的校报上。", "但也有企业靠别人的数据赚了很多钱，比如谷歌和 Facebook 这些互联网公司。有人在它们的网站上搜索东西，它们自然就知道这个人对什么感兴趣，然后把这些信息卖给其他企业。"], "lemmas": [], "gloss": [{"w": "Persönliches", "de": "etwas, das nur einen selbst betrifft", "zh": "私人的事"}, {"w": "beachten", "de": "auf etwas achten", "zh": "注意"}, {"w": "weitergibt", "de": "anderen gibt", "zh": "转交、传出去"}, {"w": "abdrucken", "de": "in einer Zeitung drucken", "zh": "登出、印出"}], "qs": [{"q": "Was sind mit Daten in diesem Text gemeint?", "qZh": "文中的数据指什么？", "answer": "Informationen über Menschen wie Name und Wohnort.", "wrong": ["Zahlen in einer Mathe-Aufgabe.", "Fotos von Landschaften."]}, {"q": "Was darf eine Schule mit den Daten ihrer Schüler nicht tun?", "qZh": "学校不能怎样处理学生的数据？", "answer": "Sie in der Schulzeitung abdrucken.", "wrong": ["Briefe nach Hause schicken.", "Die Namen der Schüler kennen."]}, {"q": "Womit verdienen Google und Facebook viel Geld?", "qZh": "谷歌和 Facebook 靠什么赚了很多钱？", "answer": "Mit Daten über ihre Benutzer.", "wrong": ["Mit dem Verkauf von Smartphones.", "Mit Briefmarken."]}], "src": "改编自 Klexikon《Datenschutz》", "url": "https://klexikon.zum.de/index.php?oldid=165701", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-014", "seg": 10, "title": "Datei", "de": ["Eine Datei ist wie ein Behälter für Daten auf einem Computer. Die Daten können ganz verschiedene Dinge sein, wie beispielsweise Bilder, Texte, Dokumente, Programme oder Listen. Eine Datei hat einen Namen, so dass man sie leicht finden kann. Die allermeisten der Daten, die in einem Computer gespeichert sind, sind in Dateien untergebracht.", "Auf dem Computer findet man Programme, mit denen man Dateien öffnen und betrachten kann. Die „Daten-Behälter“ sind aber sehr verschieden. Daher kann man nicht alle Dateien so lesen wie ein Dokument. Manche Dateien enthalten Programme und sind nur für den Computer selbst nützlich. Andere Dateien sind verschlüsselt, so dass man sie nur dann lesen kann, wenn man dazu berechtigt ist.", "Oft merkt der Benutzer nichts von den Dateien: Wenn man eine Foto-App öffnet und sich die Bilder betrachtet, sieht man zunächst nicht, dass jedes Foto eine eigene Datei mit einem eigenen Namen ist. Allerdings, wenn man Bilder mit Freunden teilt, dann teilt man eigentlich eine Foto-Datei und sendet diese Datei an ein anderes Gerät.", "Eine Datei beinhaltet oft mehr als nur die eigentlichen Daten, die man speichern oder teilen wollte. Beispielsweise hängen in einer Bild-Datei an einem Bild weitere Informationen, wie beispielsweise der Zeitpunkt, an dem das Bild aufgenommen wurde, mit welchem Gerät, und manchmal sogar auch der Ort, an dem das Bild aufgenommen wurde und noch viele Dinge mehr. All diese Informationen teilt man, wenn man die Datei weitergibt. Hier muss man aufpassen, denn manchmal möchte man das nicht."], "zh": ["文件就像电脑里装数据的容器。数据可以是各种各样的东西，比如图片、文字、文档、程序或列表。文件有名字，这样容易找到。电脑里存的数据绝大多数都放在文件里。", "电脑上有可以打开和查看文件的程序。不过这些「数据容器」差别很大，所以不是所有文件都能像文档那样读。有些文件里是程序，只对电脑本身有用。还有些文件是加密的，只有获得授权才能读。", "用户常常意识不到文件的存在：打开相册应用看照片时，一开始看不出每张照片都是一个有自己名字的文件。不过和朋友分享照片时，其实分享的是一个照片文件，把这个文件发到了另一台设备上。", "一个文件里常常不只有你想保存或分享的数据本身。比如图片文件里，图片还附带其他信息，比如拍照的时间、用的设备，有时甚至还有拍照的地点，以及其他很多东西。把文件传给别人时，这些信息也一起分享出去了。这里要小心，因为有时你并不想这样。"], "lemmas": [], "gloss": [{"w": "Behälter", "de": "etwas, in dem man Dinge aufbewahrt", "zh": "容器"}, {"w": "untergebracht", "de": "an einem Ort aufbewahrt", "zh": "存放"}, {"w": "verschlüsselt", "de": "so geschrieben, dass nur Berechtigte es lesen können", "zh": "加密的"}, {"w": "berechtigt", "de": "hat die Erlaubnis", "zh": "有权的"}, {"w": "aufgenommen", "de": "fotografiert oder gefilmt", "zh": "拍摄"}], "qs": [{"q": "Warum hat eine Datei einen Namen?", "qZh": "文件为什么有名字？", "answer": "Damit man sie leicht finden kann.", "wrong": ["Damit sie schöner aussieht.", "Damit der Computer schneller ist."]}, {"q": "Wann kann man eine verschlüsselte Datei lesen?", "qZh": "什么时候能读加密文件？", "answer": "Wenn man dazu berechtigt ist.", "wrong": ["Immer, mit jedem Programm.", "Nur am Abend."]}, {"q": "Welche Informationen kann eine Bild-Datei zusätzlich enthalten?", "qZh": "图片文件还可能附带什么信息？", "answer": "Wann und wo das Bild aufgenommen wurde.", "wrong": ["Die Telefonnummer des Empfängers.", "Das Passwort des Computers."]}], "src": "改编自 Klexikon《Datei》", "url": "https://klexikon.zum.de/index.php?oldid=159736", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-015", "seg": 10, "title": "Download", "de": ["Download ist das englische Wort für „herunterladen“. Es wird „Daunloud“ ausgesprochen. Mit einem Download lädt man eine Datei „herunter“. Dabei wird sie meist von einem Computer im Internet zu einem anderen Computer übertragen und gespeichert. So eine Datei kann ein Bild, ein Text, ein Film oder etwas anderes sein. Ein Programm, mit dem man etwas leicht herunterladen kann, heißt Download Manager.", "Ein Download kann lang oder kurz dauern. Das hängt davon ab, wie groß die Datei ist, aber auch davon, wie schnell die Internetverbindung ist. Mit dem Download meint man das Herunterladen vom Internet, und nicht, wenn man zum Beispiel eine Datei von einem Computer zum anderen kopiert.", "Manchmal laden Menschen etwas aus dem Internet herunter, obwohl sie das gar nicht dürfen. Die Datei könnte durch das Urheberrecht geschützt sein. Die Eigentümer zum Beispiel eines Hollywood-Films mögen das gar nicht, und man kann dafür bestraft werden. Man kann aber auch downloaden und etwas dafür bezahlen.", "Upload ist das Gegenteil von Download. Upload spricht man „Aploud“. Mit einem Upload lädt man eine Datei „hoch“ zu einem Computer im Internet. Viele Menschen speichern auf diese Weise ihre Bilder oder Dokumente auf einem Computer im Internet. Auf diese Weise können sie auch dann auf ihre Dateien zugreifen, wenn sie unterwegs sind und nur ein Smartphone dabei haben. Oder sie können einen Link auf die Dateien an einen Freund senden, so dass auch er auf bestimmte Sachen zugreifen kann."], "zh": ["Download 是英语「下载」的意思，读作「Daunloud」。下载就是把一个文件「拉下来」。这时文件大多从互联网上的一台电脑传到另一台电脑并保存下来。这样的文件可以是图片、文本、电影或别的东西。能方便地下载东西的程序叫下载管理器。", "下载可能要很久，也可能很快。这取决于文件有多大，也取决于网速有多快。说下载指的是从互联网上下载，而不是比如把文件从一台电脑复制到另一台电脑。", "有时人们从网上下载了本来不允许下载的东西。文件可能受版权保护。比如好莱坞电影的所有者很不喜欢这样，下载的人可能会受罚。不过也可以付费下载。", "上传是下载的反义词，读作「Aploud」。上传就是把文件「传上去」，传到互联网上的一台电脑。很多人用这种方式把自己的照片或文档存在网上的电脑里。这样即使在外面只带着智能手机，也能访问自己的文件。或者可以把文件的链接发给朋友，让他也能访问某些东西。"], "lemmas": [], "gloss": [{"w": "übertragen", "de": "von einem Ort zum anderen schicken", "zh": "传送"}, {"w": "Internetverbindung", "de": "Verbindung zum Internet", "zh": "网络连接"}, {"w": "Urheberrecht", "de": "Recht von jemandem, der ein Werk gemacht hat", "zh": "版权"}, {"w": "Eigentümer", "de": "jemand, dem etwas gehört", "zh": "所有者"}, {"w": "zugreifen", "de": "benutzen, öffnen", "zh": "访问"}], "qs": [{"q": "Wovon hängt ab, wie lange ein Download dauert?", "qZh": "下载要多久取决于什么？", "answer": "Von der Größe der Datei und der Internetverbindung.", "wrong": ["Von der Farbe des Computers.", "Von der Uhrzeit."]}, {"q": "Warum kann man für einen Download bestraft werden?", "qZh": "为什么下载可能会受罚？", "answer": "Die Datei kann durch das Urheberrecht geschützt sein.", "wrong": ["Downloads sind immer verboten.", "Der Computer wird zu langsam."]}, {"q": "Was ist ein Upload?", "qZh": "上传是什么？", "answer": "Man lädt eine Datei zu einem Computer im Internet hoch.", "wrong": ["Man kauft einen neuen Computer.", "Man löscht eine Datei."]}], "src": "改编自 Klexikon《Download》", "url": "https://klexikon.zum.de/index.php?oldid=159683", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-016", "seg": 10, "title": "Link", "de": ["Ein Link ist ein Verweis zu einem anderen Text, zu einer anderen Stelle im Text oder zu einem Bild. Links kennt man vor allem aus dem Internet. Oft werden Links auch Hyperlinks genannt. Wenn man zum Beispiel auf einer Website das Wort „Frühling“ antippt oder anklickt, springt das Programm zur Seite mit dem Thema „Frühling“.", "Ein Ausdruck mit einem Link muss aber nicht unbedingt blau sein. Oft ist der Ausdruck unterstrichen oder trägt eine andere Besonderheit. Ein Link kann sich nicht nur hinter einem Wort verbergen, sondern auch hinter einem Bild oder einem Symbol. Dies kann ein Herz sein, ein Pfeil oder was auch immer.", "Der Ausdruck „Link“ kommt aus dem Englischen und bedeutet Gelenk. Ein Gelenk am Körper verbindet zwei Knochen miteinander. Bei uns brauchen wir den Ausdruck eben für die Verbindung zweier Stellen auf dem Computer, Smartphone oder Tablet.", "Früher und heute noch in gedruckten Texten kann es keine Links geben. In gedruckten Lexika etwa steht dann etwas mit einem Pfeil in Klammern. Das bedeutet: Siehe unter diesem Stichwort."], "zh": ["链接是指向另一篇文字、文字中另一处或一张图片的引用。链接主要在互联网上常见，也常叫超链接。比如在网站上点或按一下「春天」这个词，程序就会跳到讲「春天」的页面。", "带链接的词不一定是蓝色的。它常常有下划线，或者有别的特别之处。链接不只能藏在一个词后面，也可以藏在一张图片或一个符号后面，比如一颗心、一个箭头或别的什么。", "Link 这个词来自英语，意思是关节。身体上的关节把两块骨头连在一起。我们则用这个词表示电脑、智能手机或平板上两个位置之间的连接。", "以前、以及今天的印刷文字里，不可能有链接。比如在印刷的百科全书里，会在括号里写一个带箭头的东西，意思是：请参见这个词条。"], "lemmas": [], "gloss": [{"w": "Verweis", "de": "Hinweis auf eine andere Stelle", "zh": "引用、参见"}, {"w": "antippt", "de": "kurz mit dem Finger berührt", "zh": "轻点"}, {"w": "unterstrichen", "de": "mit einer Linie unter dem Wort", "zh": "加下划线的"}, {"w": "Gelenk", "de": "Stelle, an der sich zwei Knochen bewegen", "zh": "关节"}, {"w": "Stichwort", "de": "Wort, unter dem man in einem Lexikon etwas findet", "zh": "词条"}], "qs": [{"q": "Was ist ein Link?", "qZh": "链接是什么？", "answer": "Ein Verweis zu einem anderen Text oder Bild.", "wrong": ["Ein Programm zum Fotografieren.", "Ein großer Computer."]}, {"q": "Was bedeutet das englische Wort „link“?", "qZh": "英语 link 是什么意思？", "answer": "Gelenk.", "wrong": ["Blau.", "Seite."]}, {"q": "Wie zeigt man in gedruckten Lexika einen Verweis?", "qZh": "印刷百科全书里怎样表示参见？", "answer": "Mit einem Pfeil in Klammern.", "wrong": ["Mit einem blauen Wort zum Anklicken.", "Gar nicht."]}], "src": "改编自 Klexikon《Link》", "url": "https://klexikon.zum.de/index.php?oldid=151063", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-017", "seg": 10, "title": "Video", "de": ["Video ist ein lateinisches Wort und bedeutet „ich sehe“. Heute meint man damit meistens einen Film. Das ist oft ein kurzer Film, der vielleicht sogar von Menschen gemacht wurde, die das nicht als Beruf machen.", "Viele denken vor allem an den Videorekorder und die Videokassette. Damit fing es um das Jahr 1970 an. Die Videokassette enthält ein Magnetband, genauso wie eine Musikkassette. Auf diesem Magnetband nimmt man einen Film auf. Im Wort „Rekorder“ steckt der englische Ausdruck für „aufzeichnen“.", "Die meisten Leute haben sich damals Videorekorder gekauft, um Filme und andere Sendungen aus dem Fernsehen aufzunehmen. So konnte man die Sendungen öfter sehen. Oder aber man war nicht zu Hause, wenn die Sendung im Fernsehen kam. Dann konnte man den Videorekorder so einstellen, dass er die Sendung aufzeichnete. So konnte man sie später ansehen.", "Außerdem konnte man sich „Videos“, also Videokassetten, mit Spielfilmen kaufen. Wenn man einen Spielfilm nicht im Kino gesehen hatte, hatte man ihn für zuhause auf Video. Es gab auch Läden, die solche Kassetten verliehen. Man suchte sich im Laden eine Kassette aus, schaute sich den Film an und gab dann die Kassette zurück. Das kostete nicht so viel wie der Kauf."], "zh": ["Video 是一个拉丁语词，意思是「我看见」。如今人们大多用它指一段影片，常常是一段短片，甚至可能是业余的人拍的。", "很多人首先想到录像机和录像带，这大约从 1970 年开始。录像带里有一卷磁带，和音乐磁带一样。电影就录在这卷磁带上。Rekorder（录像机）这个词里有英语「录制」的意思。", "当时大多数人买录像机，是为了录电视上的电影和其他节目。这样可以多看几遍。或者电视播节目时人不在家，就可以把录像机设好，让它录下节目，以后再看。", "此外还能买到录有故事片的「录像」，也就是录像带。没在电影院看过的片子，可以买录像带在家看。也有出租录像带的店：在店里挑一盘带子，看完电影再还回去，这比买便宜。"], "lemmas": [], "gloss": [{"w": "Videorekorder", "de": "Gerät, das Filme aus dem Fernsehen aufnimmt", "zh": "录像机"}, {"w": "Magnetband", "de": "Band, auf dem Töne oder Bilder gespeichert werden", "zh": "磁带"}, {"w": "aufzeichnen", "de": "aufnehmen, speichern", "zh": "录制"}, {"w": "Sendungen", "de": "Programme im Fernsehen oder Radio", "zh": "节目"}, {"w": "verliehen", "de": "für kurze Zeit gegeben", "zh": "出租"}], "qs": [{"q": "Was bedeutet das lateinische Wort „Video“?", "qZh": "拉丁语 video 是什么意思？", "answer": "Ich sehe.", "wrong": ["Ich höre.", "Ich spiele."]}, {"q": "Warum kauften sich viele Leute einen Videorekorder?", "qZh": "为什么很多人买录像机？", "answer": "Um Sendungen aus dem Fernsehen aufzunehmen.", "wrong": ["Um Musik zu machen.", "Um ins Kino zu gehen."]}, {"q": "Was konnte man in manchen Läden mit Videokassetten machen?", "qZh": "在有些店里可以怎样处理录像带？", "answer": "Sie ausleihen und zurückgeben.", "wrong": ["Sie reparieren lassen.", "Sie gegen Bücher tauschen."]}], "src": "改编自 Klexikon《Video》", "url": "https://klexikon.zum.de/index.php?oldid=154890", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-018", "seg": 10, "title": "Kamera", "de": ["Eine Kamera ist ein Gerät, um Fotos oder Videos zu machen. Mit so einem Instrument fängt man Licht ein: Die Sonne oder eine Lampe strahlt Licht aus, das auf einen Gegenstand fällt. Dieses Licht wird reflektiert, zurückgeworfen. Kommt dieses Licht in eine Kamera, entsteht dort ein Bild.", "Früher lag in einer Kamera ein leerer Plastikstreifen. Auf diesem Streifen bildete sich das Bild ab. Aus dem Plastikstreifen konnte man dann die richtigen Fotos machen. Dies nannte man „analoge\" Kamera. In den modernen Kameras befindet sich kein Filmstreifen. Das Bild wird elektronisch abgespeichert. Diese nennt man „digitale\" Kameras oder \"Digitalkameras\".", "Wenn man mit der Kamera stillstehende Bilder macht, ist es eine Fotokamera oder ein Fotoapparat. Wenn man mit ihr Videos macht, also Bilder, die sich bewegen, sagt man Filmkamera oder Videokamera. Allerdings gibt es heute auch viele Fotoapparate, mit denen man auch Videos filmen kann.", "Das Wort Kamera kommt aus der italienischen Sprache: „camera“ bedeutet Kammer oder Zimmer. Die ersten Kameras waren auch tatsächlich nicht viel mehr als eine Kiste mit einem Loch in der Wand. Heute würde man so eine Kiste eine Lochkamera nennen."], "zh": ["相机是拍照片或视频的设备。用这种仪器可以捕捉光：太阳或灯发出光，光照到一个物体上，又被反射回来。这光进入相机，相机里就形成了图像。", "以前相机里放着一条空白的塑料胶片，图像就印在这条胶片上，再用胶片冲洗出真正的照片。这叫「胶片」相机。现代相机里没有胶片，图像以电子方式保存，叫「数码」相机。", "用相机拍静止的画面，就是照相机。用它拍视频，也就是会动的画面，就叫摄影机或摄像机。不过如今也有很多照相机可以拍视频。", "Kamera 这个词来自意大利语：camera 意思是小室或房间。最早的相机确实不过是一个墙上有个洞的箱子。今天人们会把这种箱子叫作针孔相机。"], "lemmas": [], "gloss": [{"w": "reflektiert", "de": "zurückgeworfen (Licht)", "zh": "反射"}, {"w": "Streifen", "de": "langes, schmales Stück", "zh": "条"}, {"w": "elektronisch", "de": "mit Strom und Computer", "zh": "电子的"}, {"w": "Kammer", "de": "kleines Zimmer", "zh": "小室"}], "qs": [{"q": "Wie entsteht ein Bild in einer Kamera?", "qZh": "相机里的图像是怎样形成的？", "answer": "Licht, das von einem Gegenstand zurückkommt, fällt in die Kamera.", "wrong": ["Die Kamera malt das Bild.", "Der Strom macht das Bild ohne Licht."]}, {"q": "Was ist der Unterschied zwischen analoger und digitaler Kamera?", "qZh": "胶片相机和数码相机有什么区别？", "answer": "Die digitale Kamera speichert das Bild elektronisch.", "wrong": ["Die analoge Kamera macht nur Videos.", "Die digitale Kamera hat einen Plastikstreifen."]}, {"q": "Was bedeutet das italienische Wort „camera“?", "qZh": "意大利语 camera 是什么意思？", "answer": "Kammer oder Zimmer.", "wrong": ["Licht.", "Bild."]}], "src": "改编自 Klexikon《Kamera》", "url": "https://klexikon.zum.de/index.php?oldid=160070", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-019", "seg": 10, "title": "Mikrofon", "de": ["Ein Mikrofon ist ein Gerät, das für Sprache und Töne empfindlich ist. Wenn wir sprechen, verbreiten wir Schallwellen. Diese Wellen sind unsichtbar, sie bewegen die Luft auf ganz bestimmte Weise. Unsere Ohren sind genau für solche Schallwellen empfindlich. Ähnlich wie ein Ohr kann auch ein Mikrofon „hören“.", "Mikrofone in Telefonen sind winzig. Man kann sie kaum sehen. Meistens sitzen sie in einem Loch, das so klein ist wie ein Salzkorn. Jedes Handy hat ein Mikrofon, sonst könnte der andere, mit dem wir telefonieren, uns nicht hören. Wenn Leute im Fernsehen reden, haben sie meistens Mikrofone ohne Kabel an ihrem Anzug oder an der Bluse angesteckt. Diese Mikrofone sind nur so groß wie ein kleiner Finger.", "Wenn wir schreien, schickt unser Mund heftige Schallwellen in die Luft. Nach kurzer Zeit klingen sie ab, der Schrei verstummt. Ein Mikrofon nimmt zwar den Schall auf, aber es kann ihn nicht speichern. Im Jahr 1860 baute jemand das erste Mikrofon. Erst viel später konnte man mit dem Mikrofon die Stimme über viele Kilometer übertragen. Man nannte das „telefonieren“ oder Radio hören.", "Es dauerte lange, bis jemand ein Gerät erfand, das die Stimmen speichern konnte. Handys und Computer tun das heute ganz selbstverständlich. Es gibt dafür Aufnahme-Apps. Musik aus dem Radio, vom Keyboard oder von einer elektrischen Gitarre kann man auch direkt über ein Kabel aufnehmen. Es klingt dann sogar besser, als wenn man ein Mikrofon benutzt."], "zh": ["麦克风是一种对话语和声音敏感的设备。我们说话时会发出声波。这些波看不见，它们以特定方式让空气振动。我们的耳朵正好能感受到这样的声波。麦克风也能像耳朵一样「听」。", "电话里的麦克风非常小，几乎看不见，大多藏在一个像盐粒那么小的孔里。每部手机都有麦克风，否则和我们通话的人就听不到我们说话。电视上说话的人大多把无线麦克风别在西装或衬衫上，这种麦克风只有小手指那么大。", "我们喊叫时，嘴巴向空气里发出强烈的声波，不一会儿声音就减弱，喊声也消失了。麦克风虽然能接收声音，却不能保存声音。1860 年有人造出了第一个麦克风。很久以后，人们才能用麦克风把声音传到许多公里以外，人们把这叫作「打电话」或听广播。", "过了很久才有人发明了能保存声音的设备。如今手机和电脑做这件事已经理所当然，有专门的录音应用。收音机、电子琴或电吉他的音乐也可以直接用线录下来，听起来甚至比用麦克风还好。"], "lemmas": [], "gloss": [{"w": "empfindlich", "de": "reagiert schon auf wenig", "zh": "敏感的"}, {"w": "Schallwellen", "de": "Wellen in der Luft, die man hört", "zh": "声波"}, {"w": "winzig", "de": "sehr, sehr klein", "zh": "极小的"}, {"w": "verstummt", "de": "wird ganz still", "zh": "沉默、消失"}, {"w": "selbstverständlich", "de": "ganz normal", "zh": "理所当然的"}], "qs": [{"q": "Warum hat jedes Handy ein Mikrofon?", "qZh": "为什么每部手机都有麦克风？", "answer": "Sonst könnte der andere beim Telefonieren uns nicht hören.", "wrong": ["Damit man Fotos machen kann.", "Damit der Akku länger hält."]}, {"q": "Wann wurde das erste Mikrofon gebaut?", "qZh": "第一个麦克风是什么时候造的？", "answer": "Im Jahr 1860.", "wrong": ["Im Jahr 1960.", "Im Jahr 1760."]}, {"q": "Was kann ein Mikrofon allein nicht?", "qZh": "麦克风本身不能做什么？", "answer": "Den Schall speichern.", "wrong": ["Töne aufnehmen.", "Sprache hören."]}], "src": "改编自 Klexikon《Mikrofon》", "url": "https://klexikon.zum.de/index.php?oldid=161302", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-020", "seg": 10, "title": "Film", "de": ["Film ist eigentlich eine dünne Schicht von etwas. Wenn man in ein Glas mit Wasser etwas Öl gießt, dann bleibt das Öl ganz oben schwimmen. Es hat sich ein Ölfilm gebildet.", "Als die Fotografie erfunden wurde, hat man einen dünnen Film von einem bestimmten Stoff auf Glasplatten gestrichen. Dieser Stoff ist lichtempfindlich: Eine Stelle, wo Licht auf den Film geraten ist, wurde dunkler. Später hat man statt Glasplatten den Film auf Plastikstreifen gestrichen. Diese Streifen hat man schließlich selbst Film genannt.", "Film wurde also ein Streifen, auf dem Bilder waren. Wer Fotos machen wollte, musste einen Film in seinen Fotoapparat legen. Man konnte einen Filmstreifen auch schnell durch die Kamera drehen und dabei ganz schnell viele Fotos machen. Wenn man sich die Bilder des Streifens nacheinander angesehen hat, schien es so, als wenn sich das, was auf den Bildern war, bewegte. Schließlich dachte man beim Wort Film vor allem an eine Geschichte aus „bewegten Bildern“, die man im Kino sah: an einen Spielfilm.", "Seit 1895 gibt es solche Filme. Weil sie keinen Ton hatten, nennt man sie heute Stummfilme. Etwa um 1930 konnte man zu den Bildern auch Ton hören, also die Stimmen von Menschen oder Geräusche. Einige Jahre später wurden Spielfilme auch farbig. Es dauerte aber bis etwa 1970, bis die meisten Filme im Kino in Farbe waren: Es war deutlich teurer, einen Film in Farbe statt in Schwarz-Weiß zu filmen.", "Wir verwenden heute noch viele Wörter aus der alten Zeit: Einen Spielfilm nennen wir auch „Streifen“, und wenn ein Film gemacht wird, heißt es, er wird „gedreht“. Früher hat man nämlich bei der Aufnahme den Film mit einer Handkurbel weitergedreht. Heutzutage filmt man aber mit einem Sensor, auf den das Licht fällt. Der Sensor macht daraus digitale Informationen."], "zh": ["Film 其实是指一层薄薄的东西。往一杯水里倒点油，油就浮在最上面，形成一层油膜。", "发明摄影时，人们把一层薄薄的某种物质涂在玻璃板上。这种物质对光敏感：光照到的地方会变暗。后来人们不用玻璃板，而是把这层膜涂在塑料条上，最后就把这些塑料条本身叫作胶片（Film）。", "于是 Film 就成了印着图像的长条。想拍照的人得在照相机里装胶卷。也可以让胶片快速转过相机，一下子拍很多张照片。一张接一张地看胶片上的画面，画面上的东西看起来就像在动。最后人们一听到 Film，主要想到的是在电影院里看的由「活动画面」组成的故事，也就是故事片。", "从 1895 年起就有这样的电影了。因为没有声音，今天把它们叫作默片。大约 1930 年起，画面配上了声音，比如人的说话声或各种响声。几年后故事片也有了彩色。但直到大约 1970 年，电影院里的大多数电影才是彩色的：拍彩色片比拍黑白片贵得多。", "我们今天仍在用很多旧时代的词：故事片也叫「Streifen」（片子），拍电影叫「drehen」（转）。因为以前拍摄时要用手摇柄转动胶片。不过如今拍电影用的是传感器，光照到传感器上，传感器把它变成数字信息。"], "lemmas": [], "gloss": [{"w": "lichtempfindlich", "de": "reagiert auf Licht", "zh": "感光的"}, {"w": "gestrichen", "de": "als dünne Schicht aufgetragen", "zh": "涂上"}, {"w": "Stummfilme", "de": "Filme ohne Ton", "zh": "默片"}, {"w": "Handkurbel", "de": "Griff, den man mit der Hand dreht", "zh": "手摇柄"}, {"w": "Sensor", "de": "Teil, das Licht oder Wärme misst", "zh": "传感器"}], "qs": [{"q": "Was bedeutet „Film“ eigentlich?", "qZh": "Film 本来是什么意思？", "answer": "Eine dünne Schicht von etwas.", "wrong": ["Eine Geschichte im Kino.", "Ein Fernseher."]}, {"q": "Warum nennt man die ersten Filme Stummfilme?", "qZh": "为什么把最早的电影叫默片？", "answer": "Sie hatten keinen Ton.", "wrong": ["Sie waren ohne Farbe.", "Sie waren sehr kurz."]}, {"q": "Warum sagt man, ein Film wird „gedreht“?", "qZh": "为什么说拍电影是「转」？", "answer": "Früher drehte man den Film mit einer Handkurbel weiter.", "wrong": ["Die Schauspieler drehen sich im Kreis.", "Das Kino dreht sich."]}], "src": "改编自 Klexikon《Film》", "url": "https://klexikon.zum.de/index.php?oldid=151442", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-021", "seg": 10, "title": "Kino", "de": ["Das Kino ist ein Ort, wo man Spielfilme zeigt. Früher sagte man auch Filmtheater oder Lichtspielhaus. Das Wort Kino stammt vom griechischen Wort für „Bewegung“. Bei einem Kino denkt man normalerweise an ein großes Haus. Wer einen Film sehen will, zahlt dafür am Eingang Geld für eine Eintrittskarte. Das große Zimmer, in dem man Filme zeigt, heißt Saal.", "Im Kinosaal gibt es viele Sitze für die Zuschauer. Sie schauen auf eine Leinwand, also ein großes weißes Tuch. Oben hinter den Zuschauern befindet sich der Projektor. Das ist eine Maschine, aus der Lichtstrahlen kommen. Sie werden auf die Leinwand „geworfen“ oder „projiziert“.", "Die ersten Filme wurden auf dem Jahrmarkt oder im Theater gezeigt. Ab etwa dem Jahr 1920 hat man große Filmtheater nur für Spielfilme gebaut. In dieser Zeit waren die Filme noch stumm, man konnte noch nicht gut gleichzeitig Ton aufnehmen. Deshalb hat ein Orchester oder ein Musiker am Klavier Musik zum Film gespielt. Um 1930 hatten aber die meisten Filme schon Ton.", "Ab etwa 1950 kam das Fernsehen. Viele Leute blieben zuhause, weil sie das einfacher und gemütlicher fanden. Darum mussten viele Kinos schließen. Kinobesitzer haben sich vieles ausgedacht, um Leute ins Kino zu locken: Mal waren die Filme „dreidimensional“, oder die Leinwand wurde breiter, oder der Ton kam von allen Seiten.", "Multiplex zum Beispiel nennt man heute die großen Kinos in großen Städten. Darin gibt es mehrere Säle. Einige davon sind sehr groß: Dort werden die neuesten und teuersten Filme der Woche gezeigt."], "zh": ["电影院是放映故事片的地方，以前也叫电影剧场或光影屋。Kino 这个词来自希腊语的「运动」。说到电影院，人们一般想到一栋大房子。想看电影的人要在入口付钱买票。放电影的大房间叫放映厅。", "放映厅里有很多观众座位，观众看的是银幕，也就是一块很大的白布。观众身后上方是放映机，这是一台射出光束的机器，光束被「投」到银幕上，也就是「投影」。", "最早的电影是在年市或剧院里放映的。大约从 1920 年起，人们建造了专门放故事片的大电影院。那时电影还是无声的，人们还不能很好地同时录音，所以由乐队或钢琴师为电影配乐。到 1930 年左右，大多数电影已经有了声音。", "大约从 1950 年起有了电视。很多人待在家里，因为觉得这样更省事、更舒服，所以很多电影院不得不关门。影院老板想了很多办法吸引人们去电影院：有时电影是「三维」的，有时银幕更宽，有时声音从四面八方传来。", "比如如今大城市里的大型影院叫多厅影院（Multiplex），里面有好几个放映厅，有些非常大，在那里放映当周最新、最贵的电影。"], "lemmas": [], "gloss": [{"w": "Eintrittskarte", "de": "Karte, mit der man hineindarf", "zh": "门票"}, {"w": "Leinwand", "de": "großes weißes Tuch für Filme", "zh": "银幕"}, {"w": "Projektor", "de": "Maschine, die Bilder an die Wand wirft", "zh": "放映机"}, {"w": "Jahrmarkt", "de": "Fest mit Karussells und Buden", "zh": "年市、游乐集市"}, {"w": "locken", "de": "jemanden dazu bringen zu kommen", "zh": "吸引"}], "qs": [{"q": "Was bedeutet das griechische Wort, von dem „Kino“ kommt?", "qZh": "Kino 来自的希腊语词是什么意思？", "answer": "Bewegung.", "wrong": ["Licht.", "Haus."]}, {"q": "Wer spielte früher Musik zu den Stummfilmen?", "qZh": "以前谁为默片配乐？", "answer": "Ein Orchester oder ein Musiker am Klavier.", "wrong": ["Die Zuschauer.", "Niemand."]}, {"q": "Warum mussten ab etwa 1950 viele Kinos schließen?", "qZh": "为什么大约 1950 年起很多电影院关门了？", "answer": "Viele Leute sahen lieber zu Hause fern.", "wrong": ["Filme wurden verboten.", "Es gab keine neuen Filme."]}], "src": "改编自 Klexikon《Kino》", "url": "https://klexikon.zum.de/index.php?oldid=154686", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-022", "seg": 10, "title": "Fernsehturm", "de": ["Ein Fernsehturm ist ein sehr hoher Turm, der meistens in einer großen Stadt steht. Seinen Namen hat er daher, dass man von diesem Turm aus Fernseh-Signale aussendet. Auf diese Weise können die Menschen zuhause mit ihren Fernsehern auch tatsächlich Fernsehprogramme empfangen.", "Fernsehtürme hat man vor allem gebaut, um Fernsehen übertragen zu können. Durch die Höhe haben die Signale viele Häuser erreicht. Daher hat es sich für viele Menschen erst gelohnt, sich ein Fernsehgerät zu kaufen. Daneben hat man Radio und andere Funksignale ausgestrahlt.", "Weil Fernsehtürme so hoch sind, hat man von ihnen aus eine hervorragende Aussicht über die Stadt und die Landschaft herum. Touristen fahren gern für die Aussicht mit dem Fahrstuhl hoch. In manchen Fernsehtürmen gibt es oben auch ein Restaurant.", "Viele Einwohner einer Stadt sind stolz auf ihren Fernsehturm. Man kann ihn gut von überall sehen. Er gehört zum Stadtbild und zeigt auch, dass es eine wirklich große, wichtige Stadt ist, die sich so einen Turm leisten konnte."], "zh": ["电视塔是一座很高的塔，大多立在大城市里。它得名于人们从塔上发送电视信号。这样人们在家里用电视机才能真正收到电视节目。", "人们建电视塔主要是为了能传送电视。因为塔很高，信号能到达许多房子。所以对很多人来说，买一台电视机才划得来。此外塔上也发送广播和其他无线信号。", "因为电视塔很高，从塔上能把城市和周围的风景看得一清二楚。游客喜欢为了风景坐电梯上去。有些电视塔顶上还有餐厅。", "很多城市居民为自己的电视塔骄傲。从哪儿都能看到它。它是城市面貌的一部分，也说明这是一座真正重要的大城市，才建得起这样一座塔。"], "lemmas": [], "gloss": [{"w": "aussendet", "de": "in die Luft schickt (Signale)", "zh": "发送"}, {"w": "empfangen", "de": "bekommen (Signale, Programme)", "zh": "接收"}, {"w": "gelohnt", "de": "hat sich gerechnet, war es wert", "zh": "划得来"}, {"w": "hervorragende", "de": "sehr gute", "zh": "极好的"}, {"w": "Stadtbild", "de": "wie eine Stadt von außen aussieht", "zh": "城市面貌"}, {"w": "leisten", "de": "Geld für etwas haben", "zh": "负担得起"}], "qs": [{"q": "Warum heißt der Turm Fernsehturm?", "qZh": "为什么叫电视塔？", "answer": "Von dort aus sendet man Fernseh-Signale.", "wrong": ["Man kann dort fernsehen.", "Er sieht aus wie ein Fernseher."]}, {"q": "Warum fahren Touristen gern auf den Fernsehturm?", "qZh": "游客为什么喜欢上电视塔？", "answer": "Wegen der Aussicht über die Stadt.", "wrong": ["Weil man dort Fernseher kaufen kann.", "Weil es dort billig ist."]}, {"q": "Was zeigt ein Fernsehturm für viele Einwohner?", "qZh": "电视塔对很多居民说明了什么？", "answer": "Dass ihre Stadt groß und wichtig ist.", "wrong": ["Dass die Stadt sehr alt ist.", "Dass es dort viele Kinos gibt."]}], "src": "改编自 Klexikon《Fernsehturm》", "url": "https://klexikon.zum.de/index.php?oldid=158752", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-023", "seg": 10, "title": "Technik", "de": ["Mit „Technik“ meint man Maschinen und Geräte, die von Menschen gemacht worden sind. Diese Dinge haben einen Nutzen: Man kann mit ihnen etwas bauen, herstellen oder erforschen. Zur Technik gehören aber auch Bauwerke wie Straßen, Brücken oder Häuser. Damit kann man sich das Leben leichter machen. Technik ist eine Art Gegenstück zu Natur.", "Das Wort Technik kommt aus dem Griechischen und bedeutet etwa so viel wie Handwerk. Man kann auch sagen, Technik ist das, was Handwerker gemacht haben. Neue Techniken führten auch zu neuen Berufen. Seit es Computer gibt, braucht es zum Beispiel Programmierer.", "Dank der Technik können die Menschen etwas leichter machen als ohne. Einen Text zu drucken geht zum Beispiel schneller, als wenn man ihn mit der Hand selber schreibt. Anderes können wir sogar nur mit Hilfe der Technik tun: ohne Flugzeug, Heißluftballon oder etwas ähnlichem könnten wir nicht fliegen.", "Technik ist aber auch die Art, wie man etwas macht: Jeder Handwerker muss bestimmte Techniken beherrschen. Ein Schmied zum Beispiel braucht andere Techniken als ein Schneider. Er arbeitet mit anderen Werkzeugen und muss sie richtig bedienen können.", "Oft hört man das Wort Technik auch, wenn es um Geschicklichkeit geht. Manche Sportler werden nach ihrer Technik gefragt, mit Skiern, einem Ball oder einem Turngerät umzugehen. Jeder hat da vielleicht eine etwas andere Herangehensweise, und wer am geschicktesten ist, also die beste Technik hat, erzielt die besten Ergebnisse."], "zh": ["「技术」指的是人造的机器和设备。这些东西有用处：可以用它们建造、生产或研究东西。不过道路、桥梁或房屋这样的建筑也属于技术。有了它们，生活就更轻松。技术可以说是自然的对立面。", "Technik 这个词来自希腊语，意思大约是手艺。也可以说，技术就是手艺人做出来的东西。新技术也带来了新职业。比如自从有了电脑，就需要程序员。", "有了技术，人们做事比没有时轻松。比如打印一篇文字，比自己用手写要快。还有些事只有借助技术才能做到：没有飞机、热气球之类的东西，我们就不能飞。", "技术也是做某件事的方法：每个手艺人都要掌握一定的技巧。比如铁匠需要的技巧和裁缝不一样。他用别的工具干活，而且必须会正确使用这些工具。", "说到灵巧时，人们也常用 Technik 这个词。有些运动员会被问到他们用滑雪板、球或体操器械的技术。每个人的方法可能都有点不同，最灵巧、也就是技术最好的人，成绩最好。"], "lemmas": [], "gloss": [{"w": "Nutzen", "de": "etwas Gutes, das man von einer Sache hat", "zh": "用处"}, {"w": "Handwerk", "de": "Arbeit mit den Händen, z. B. Tischler", "zh": "手艺"}, {"w": "beherrschen", "de": "sehr gut können", "zh": "掌握"}, {"w": "Schneider", "de": "jemand, der Kleider näht", "zh": "裁缝"}, {"w": "Geschicklichkeit", "de": "die Fähigkeit, etwas gut mit den Händen oder dem Körper zu machen", "zh": "灵巧"}, {"w": "erzielt", "de": "erreicht (ein Ergebnis)", "zh": "取得"}], "qs": [{"q": "Was gehört außer Maschinen auch zur Technik?", "qZh": "除了机器，还有什么属于技术？", "answer": "Bauwerke wie Straßen und Brücken.", "wrong": ["Bäume und Flüsse.", "Tiere."]}, {"q": "Welcher Beruf entstand durch den Computer?", "qZh": "电脑带来了哪种职业？", "answer": "Programmierer.", "wrong": ["Schmied.", "Schneider."]}, {"q": "Was bedeutet Technik beim Sport?", "qZh": "运动中的 Technik 指什么？", "answer": "Wie geschickt man zum Beispiel mit dem Ball umgeht.", "wrong": ["Wie teuer die Schuhe sind.", "Wie viele Zuschauer kommen."]}], "src": "改编自 Klexikon《Technik》", "url": "https://klexikon.zum.de/index.php?oldid=160478", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-024", "seg": 10, "title": "Automat", "de": ["Ein Automat ist eine Maschine. Sie erledigt bestimmte, immer wiederkehrende Aufgaben. Automation oder Automatisierung bedeutet, dass etwas von allein gemacht werden kann. Meistens ist damit gemeint, dass Maschinen Aufgaben erledigen, ohne dass Menschen dies direkt kontrollieren müssen.", "Anders als Menschen wird die Maschine nie müde. Wenn sie beschädigt ist, kann man sie meist schnell reparieren. Selber denken kann aber weder der Automat, noch der Roboter oder eine andere Maschine. Sie alle werden wie Computer von Menschen gebaut und programmiert.", "Heute gibt es sehr viele und unterschiedliche Automaten. Das vielleicht bekannteste Beispiel ist wohl der Verkaufsautomat. In so einem Automaten stecken Fächer mit Waren. Der Käufer wirft Geld ein oder bezahlt mit Karte. Dann öffnet der Automat ein Fach, und der Käufer bekommt seine Ware.", "Solche Waren können alles Mögliche sein: Getränke, Essen, Fahrkarten oder auch Geld selbst. Man kann nämlich auch von einem Bankautomaten Geld abheben, so, wie man es sonst am Schalter in der Bank machen würde. Dafür benötigt man eine Bankkarte und eine Geheimzahl als Schlüssel, damit die Maschine weiß, dass es tatsächlich der Kunde ist, der sein Geld abheben will, und nicht ein Betrüger.", "Mehr und mehr Automaten sind heute online, also mit dem Internet verbunden. So können sie dem Eigentümer melden, wenn etwas fehlt oder kaputt ist. Dann kommt ein Techniker, und der Automat ist nicht lange „außer Betrieb“."], "zh": ["自动机是一种机器。它完成一定的、反复出现的任务。自动化的意思是某件事可以自己完成。大多指的是机器完成任务，不需要人直接控制。", "机器和人不同，永远不会累。坏了的话，大多能很快修好。但无论自动机、机器人还是别的机器，都不会自己思考。它们都和电脑一样，由人来制造和编程。", "今天有很多不同的自动机。最有名的例子大概是自动售货机。这种机器里有装着商品的格子。买的人投钱或刷卡付款，机器就打开一个格子，买的人拿到商品。", "这样的商品可以是各种东西：饮料、食物、车票，甚至钱本身。因为也可以从银行自动取款机取钱，就像平时在银行柜台那样。为此需要一张银行卡和一个密码当钥匙，让机器知道真的是客户本人要取钱，而不是骗子。", "如今越来越多的自动机是在线的，也就是连着互联网。这样它们可以在缺货或出故障时通知主人。然后会来一位技术员，机器就不会长时间「停止运行」。"], "lemmas": [], "gloss": [{"w": "erledigt", "de": "macht fertig", "zh": "完成"}, {"w": "wiederkehrende", "de": "die immer wieder kommen", "zh": "反复出现的"}, {"w": "Fächer", "de": "kleine Teile in einem Schrank oder Kasten", "zh": "格子"}, {"w": "abheben", "de": "Geld vom Konto holen", "zh": "取（钱）"}, {"w": "Geheimzahl", "de": "Zahl, die nur man selbst kennt", "zh": "密码"}, {"w": "Betrüger", "de": "jemand, der andere täuscht, um Geld zu bekommen", "zh": "骗子"}], "qs": [{"q": "Was kann ein Automat nicht?", "qZh": "自动机不能做什么？", "answer": "Selber denken.", "wrong": ["Müde werden und trotzdem arbeiten.", "Aufgaben erledigen."]}, {"q": "Was braucht man am Bankautomaten?", "qZh": "在银行自动取款机要用什么？", "answer": "Eine Bankkarte und eine Geheimzahl.", "wrong": ["Einen Ausweis und ein Foto.", "Nur Münzen."]}, {"q": "Warum sind viele Automaten online?", "qZh": "为什么很多自动机联网？", "answer": "Sie können melden, wenn etwas fehlt oder kaputt ist.", "wrong": ["Damit man im Internet surfen kann.", "Damit sie schneller werden."]}], "src": "改编自 Klexikon《Automat》", "url": "https://klexikon.zum.de/index.php?oldid=158084", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-025", "seg": 10, "title": "Drohne", "de": ["Eine Drohne ist eine männliche Biene, Hummel oder Wespe. Oft meint man damit aber auch ein unbemanntes Fluggerät. Man sagt auch Flugdrohne. Anders als bei einem Flugzeug fliegen also keine Menschen mit. Das Wort Drohne selbst gab es schon vor 1100 Jahren in der deutschen Sprache und ist mit „dröhnen“ verwandt.", "Es gibt sehr unterschiedliche Drohnen: Manche sind klein, andere sind groß. Manche werden von einem Menschen ferngesteuert, andere bewegen sich automatisch nach einem Programm. Viele Drohnen haben eine Kamera: Dank der Kamera kann man sehen, wohin die Drohne fliegt, das ist gut zum Steuern. Oft startet man eine Drohne überhaupt, weil man Fotos machen will.", "Vor allem unterscheidet man Drohnen nach dem Zweck. Die militärischen Drohnen werden von Soldaten verwendet. Damit können sie ein Gebiet beobachten oder gar kämpfen. Die zivilen Drohnen hingegen haben nichts mit Krieg zu tun. Jeder kann sie kaufen, aber für das Fliegenlassen gibt es zum Teil strenge Regeln.", "Für die verschiedenen Größen und Zwecke gibt es viele Ausdrücke. Mikro-Fluggeräte zum Beispiel sind weniger als zehn Zentimeter groß. Man nutzt sie, um etwas zu messen, etwa, wie sauber die Luft ist, oder macht Fotos oder Videos."], "zh": ["Drohne 是雄性的蜜蜂、熊蜂或黄蜂。不过人们常用它指无人驾驶的飞行器，也叫飞行无人机。和飞机不同，上面没有人跟着飞。Drohne 这个词 1100 年前德语里就有了，和 dröhnen（轰鸣）是同源词。", "无人机各式各样：有的小，有的大。有的由人遥控，有的按程序自动飞行。很多无人机带摄像头：有了摄像头就能看到无人机往哪儿飞，便于操控。人们常常干脆就是为了拍照才放飞无人机。", "无人机主要按用途来区分。军用无人机由士兵使用，可以用来侦察某个地区，甚至作战。民用无人机则和战争无关。谁都可以买，但放飞时有些规定很严格。", "不同的大小和用途有许多叫法。比如微型飞行器不到十厘米大。人们用它测量东西，比如空气有多干净，或者拍照片和视频。"], "lemmas": [], "gloss": [{"w": "unbemanntes", "de": "ohne Menschen an Bord", "zh": "无人驾驶的"}, {"w": "ferngesteuert", "de": "aus der Ferne gelenkt", "zh": "遥控的"}, {"w": "Steuern", "de": "Lenken, die Richtung bestimmen", "zh": "操控"}, {"w": "Zweck", "de": "wofür man etwas benutzt", "zh": "用途"}, {"w": "zivilen", "de": "nicht militärisch", "zh": "民用的"}, {"w": "messen", "de": "feststellen, wie viel oder wie groß etwas ist", "zh": "测量"}], "qs": [{"q": "Was ist eine Drohne bei den Tieren?", "qZh": "动物里的 Drohne 是什么？", "answer": "Eine männliche Biene, Hummel oder Wespe.", "wrong": ["Ein kleiner Vogel.", "Eine Fledermaus."]}, {"q": "Wozu ist die Kamera an einer Drohne gut?", "qZh": "无人机上的摄像头有什么用？", "answer": "Man sieht, wohin die Drohne fliegt, und kann Fotos machen.", "wrong": ["Sie macht die Drohne schneller.", "Sie schützt vor Regen."]}, {"q": "Was gilt für zivile Drohnen?", "qZh": "民用无人机有什么规定？", "answer": "Jeder kann sie kaufen, aber es gibt Regeln fürs Fliegen.", "wrong": ["Nur Soldaten dürfen sie benutzen.", "Man darf sie nur nachts fliegen."]}], "src": "改编自 Klexikon《Drohne》", "url": "https://klexikon.zum.de/index.php?oldid=159354", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-026", "seg": 10, "title": "Satellit", "de": ["Ein Satellit ist ein Objekt, das einen Himmelskörper begleitet. Meistens reden wir dabei von Satelliten, die einen Planeten ständig umkreisen. Man sagt, dass sie sich in einer Umlaufbahn um diesen Planeten befinden. Das Wort Satellit kommt aus der lateinischen Sprache und bedeutet „Begleiter“.", "Zunächst gibt es natürliche Satelliten: Das sind Himmelskörper, die einen anderen Himmelskörper umkreisen. Der Mond ist ein natürlicher Satellit der Erde. Genauso können auch andere Planeten einen oder mehrere Monde haben, die sie begleiten.", "Künstliche Satelliten sind viel kleiner. Es sind Raumflugkörper, die von Menschen gebaut wurden. Sie haben sie mit Raketen in den Weltraum geschossen. Die meisten Satelliten umkreisen die Erde und nützen den Menschen auf verschiedene Weisen.", "Im Jahr 1957 hat die Sowjetunion den ersten künstlichen Satelliten mit einer Rakete ins All geschossen. Der Satellit darin hieß Sputnik. 92 Tage lang umkreiste er die Erde, bis er herunterstürzte. Ein Jahr später war Explorer der erste Satellit der USA. Dieses Land hat mittlerweile die meisten Satelliten hochgeschossen. Es sind mehrere Hundert.", "Heute ziehen ständig tausende künstliche Satelliten um die Erde herum. Sie tun dies auf unterschiedlichen Bahnen. Manche fliegen mehrere Hundert Kilometer hoch, andere mehrere 10.000 Kilometer. Einige drehen sich so mit der Erde mit, dass sie scheinbar über einem bestimmten Punkt der Erde stehen."], "zh": ["卫星是伴随一个天体的物体。我们大多说的是不停绕着一颗行星转的卫星。人们说它们处在绕这颗行星的轨道上。Satellit 这个词来自拉丁语，意思是「伴随者」。", "首先有天然卫星：就是绕着另一个天体转的天体。月球是地球的天然卫星。同样，别的行星也可以有一个或多个月亮陪着它们。", "人造卫星小得多。它们是人造的航天器，人们用火箭把它们射进太空。大多数人造卫星绕地球转，以各种方式为人们服务。", "1957 年，苏联用火箭把第一颗人造卫星送上太空。这颗卫星叫斯普特尼克，它绕地球转了 92 天，然后坠落。一年后，探险者号成为美国的第一颗卫星。现在美国发射的卫星最多，有好几百颗。", "今天不断有成千上万颗人造卫星绕着地球转。它们在不同的轨道上。有的飞几百公里高，有的几万公里高。有些卫星和地球一起转，看起来好像停在地球上某一点的上空。"], "lemmas": [], "gloss": [{"w": "Himmelskörper", "de": "Stern, Planet oder Mond", "zh": "天体"}, {"w": "umkreisen", "de": "sich im Kreis um etwas bewegen", "zh": "绕着转"}, {"w": "Umlaufbahn", "de": "Weg, auf dem sich etwas um einen Planeten bewegt", "zh": "轨道"}, {"w": "Begleiter", "de": "jemand, der mitgeht", "zh": "伴随者"}, {"w": "Weltraum", "de": "der Raum außerhalb der Erde", "zh": "太空"}, {"w": "herunterstürzte", "de": "nach unten fiel", "zh": "坠落"}], "qs": [{"q": "Was bedeutet das lateinische Wort „Satellit“?", "qZh": "拉丁语 Satellit 是什么意思？", "answer": "Begleiter.", "wrong": ["Stern.", "Rakete."]}, {"q": "Wie kommen künstliche Satelliten in den Weltraum?", "qZh": "人造卫星怎样进入太空？", "answer": "Mit Raketen.", "wrong": ["Mit Flugzeugen.", "Mit Ballons."]}, {"q": "Wie hieß der erste künstliche Satellit?", "qZh": "第一颗人造卫星叫什么？", "answer": "Sputnik.", "wrong": ["Explorer.", "Jupiter."]}], "src": "改编自 Klexikon《Satellit》", "url": "https://klexikon.zum.de/index.php?oldid=162235", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-027", "seg": 10, "title": "Strom", "de": ["Im Alltag gibt es viele verschiedene Ströme. Im Mittelalter bedeutete der Ausdruck Strom „schnell fließendes Wasser“. Später bedeutete er „großer Fluss“. Heute verstehen wir darunter einen Fluss, der direkt ins Meer fließt, also beispielsweise den Rhein, die Donau, den Mississippi oder den Amazonas.", "Zu einem Strom gehört, dass viele gleiche Dinge gemeinsam in dieselbe Richtung fließen. Im Fall des Rheins sind es Wassertropfen oder Wassermoleküle. Sie werden durch eine Kraft angetrieben, die man vielleicht gar nicht sieht.", "In der heutigen Umgangssprache denken wir beim Wort „Strom“ meistens an elektrischen Strom. Da fließen eine Art Teilchen in einem Kabel gemeinsam in eine Richtung. Es sind Elektronen. Wir sehen die Kraft nicht, welche sie antreibt. Aber wir spüren sie, wenn wir versehentlich ein kaputtes Kabel berühren. Wir erleben aber auch, was der elektrische Strom bewirken kann: Der Herd wird heiß, das Smartphone wird aufgeladen und so weiter.", "Es gibt aber noch viele andere Ströme: die Strömung im Meer oder der Lavastrom aus einem Vulkan. Man sagt auch: „es regnet in Strömen“, wenn es ganz furchtbar gießt, oder: „die Fußballfans strömen aus dem Stadion“, wenn das Spiel zu Ende ist.", "Man spricht vom Datenstrom, wenn viele Informationen durch ein Kabel fließen. „Streaming“ sagt man, wenn man einen Film aus dem Internet schaut. Dafür wird er nicht erst auf den eigenen Computer heruntergeladen: Die Daten für den Film „strömen“ in den eigenen Apparat, während man den Film schon schaut."], "zh": ["日常生活中有许多不同的「流」。中世纪时 Strom 这个词指「流得很快的水」，后来指「大河」。今天我们指直接流入大海的河流，比如莱茵河、多瑙河、密西西比河或亚马孙河。", "「流」的特点是许多相同的东西一起朝同一个方向流动。就莱茵河来说，那是水滴或水分子。推动它们的力量我们也许根本看不见。", "在今天的口语里，听到 Strom 这个词，我们大多想到电流。那是一种微粒在电线里一起朝一个方向流动，这些微粒就是电子。我们看不见推动它们的力量，但不小心碰到坏电线时就能感觉到。我们也能体会到电流的作用：灶台变热，智能手机充上电，等等。", "还有很多别的「流」：海里的洋流，火山喷出的熔岩流。人们还说「es regnet in Strömen」（大雨倾盆），表示雨下得特别大；或者说「球迷从体育场涌出来」，表示比赛结束了。", "很多信息通过电缆流动时，人们说「数据流」。在网上看电影叫 Streaming（流媒体）。这时电影不用先下载到自己的电脑上：电影的数据一边「流」进自己的设备，人一边已经在看了。"], "lemmas": [], "gloss": [{"w": "angetrieben", "de": "in Bewegung gebracht", "zh": "推动"}, {"w": "Umgangssprache", "de": "Sprache im Alltag", "zh": "口语"}, {"w": "Teilchen", "de": "sehr kleines Stück", "zh": "微粒"}, {"w": "versehentlich", "de": "aus Versehen, ohne Absicht", "zh": "不小心"}, {"w": "strömen", "de": "in großer Menge fließen oder gehen", "zh": "涌"}, {"w": "heruntergeladen", "de": "aus dem Internet geholt", "zh": "下载"}], "qs": [{"q": "Was bedeutete „Strom“ im Mittelalter?", "qZh": "中世纪时 Strom 是什么意思？", "answer": "Schnell fließendes Wasser.", "wrong": ["Elektrizität.", "Ein kleiner See."]}, {"q": "Was fließt beim elektrischen Strom im Kabel?", "qZh": "电流在电线里流动的是什么？", "answer": "Elektronen.", "wrong": ["Wassertropfen.", "Luft."]}, {"q": "Was bedeutet „Streaming“?", "qZh": "Streaming 是什么意思？", "answer": "Man schaut einen Film, während die Daten noch ankommen.", "wrong": ["Man kauft einen Film im Laden.", "Man schaut einen Film im Kino."]}], "src": "改编自 Klexikon《Strom》", "url": "https://klexikon.zum.de/index.php?oldid=157178", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-028", "seg": 10, "title": "Kühlschrank", "de": ["Ein Kühlschrank ist ein Gerät oder Möbel, das man meist in einer Küche findet. In Österreich sagt man auch Eiskasten. Im Kühlschrank kann man Lebensmittel aufbewahren. Dort werden sie kalt gehalten, damit sie nicht so schnell verderben. Kühlschränke gibt es aber auch zum Beispiel in Krankenhäusern, wo man zum Beispiel bestimmte Medikamente oder auch Blutkonserven kühlt.", "Die ersten Kühlschränke baute man um das Jahr 1930. Es dauerte dann noch vierzig Jahre, bis die meisten Menschen in reichen Ländern einen Kühlschrank in der Küche hatten. Heute steht in fast jedem Haushalt ein Kühlschrank.", "Lange Zeit konnte man etwas nur an einem kühlen Ort kühl aufbewahren. Das war etwa ein Keller. Eisschränke waren kühl, weil man sie mit Eis gefüllt hat: In einem anderen Teil des Eisschranks standen dann die Lebensmittel.", "In einem Kühlschrank gibt es ein Kühlmittel. Ein Motor treibt eine Pumpe an. Die Pumpe drückt das Kühlmittel zusammen. Dadurch wird es warm. Diese Wärme entlässt man hinter dem Kühlschrank in die Luft. Der Kühlschrank erwärmt somit die Küche.", "Die Pumpe in einem Kühlschrank nennt man auch „Kompressor“. Sein Motor braucht Elektrizität. Ein Kühlschrank ist daher nicht nur teuer, wenn man ihn kauft, sondern auch dadurch, dass er im Haushalt Strom braucht. Je wärmer es in der Küche ist, desto mehr Strom braucht man: Im Winter kostet deshalb der Betrieb nicht so viel wie im Sommer.", "Die Europäische Union hat Regeln eingeführt, dass die Hersteller deutlich machen müssen, wie viel Strom ein Kühlschrank oder ein anderes Elektrogerät verbraucht. Vergeben werden die Buchstaben A für geringen bis G für hohen Stromverbrauch. Die Kunden im Laden wissen dann, dass sie am besten einen Kühlschrank mit einem „A“ kaufen sollten, wenn sie Strom sparen wollen."], "zh": ["冰箱是一种电器或家具，大多在厨房里。在奥地利也叫 Eiskasten。冰箱里可以存放食物，食物在里面保持低温，就不会那么快坏。不过医院里也有冰箱，比如用来冷藏某些药品或储备血液。", "最早的冰箱大约在 1930 年造出来。之后又过了四十年，富裕国家的大多数人家厨房里才有冰箱。今天几乎每个家庭都有一台冰箱。", "很长时间里，人们只能在凉爽的地方把东西冷着保存，比如地窖。冰柜之所以凉，是因为人们往里装了冰：食物就放在冰柜的另一部分。", "冰箱里有一种制冷剂。一台电机带动一个泵，泵把制冷剂压缩，制冷剂就变热。这些热量从冰箱背后散到空气里。所以冰箱会让厨房变暖。", "冰箱里的泵也叫「压缩机」。它的电机要用电。所以冰箱不仅买的时候贵，在家里用电也要花钱。厨房越暖，用电越多：所以冬天的运行费用没有夏天那么高。", "欧盟规定，厂家必须标明冰箱或其他电器用多少电。从 A（耗电少）到 G（耗电多）给出字母。这样店里的顾客就知道，想省电最好买标「A」的冰箱。"], "lemmas": [], "gloss": [{"w": "aufbewahren", "de": "an einem Ort lassen, damit man es später hat", "zh": "存放"}, {"w": "verderben", "de": "schlecht werden (Essen)", "zh": "变坏"}, {"w": "Keller", "de": "Raum unter dem Haus", "zh": "地窖"}, {"w": "Kühlmittel", "de": "Stoff, der in einem Gerät für Kälte sorgt", "zh": "制冷剂"}, {"w": "verbraucht", "de": "benutzt und dabei aufbraucht", "zh": "消耗"}, {"w": "Hersteller", "de": "Firma, die etwas produziert", "zh": "厂家"}], "qs": [{"q": "Warum bewahrt man Lebensmittel im Kühlschrank auf?", "qZh": "为什么把食物放进冰箱？", "answer": "Damit sie nicht so schnell verderben.", "wrong": ["Damit sie wärmer werden.", "Damit sie besser riechen."]}, {"q": "Warum kostet ein Kühlschrank im Sommer mehr Strom?", "qZh": "为什么冰箱夏天更费电？", "answer": "Je wärmer die Küche, desto mehr Strom braucht er.", "wrong": ["Im Sommer ist der Strom teurer.", "Im Sommer öffnet man ihn nie."]}, {"q": "Welchen Kühlschrank sollte man kaufen, um Strom zu sparen?", "qZh": "想省电该买哪种冰箱？", "answer": "Einen mit dem Buchstaben „A“.", "wrong": ["Einen mit dem Buchstaben „G“.", "Den größten."]}], "src": "改编自 Klexikon《Kühlschrank》", "url": "https://klexikon.zum.de/index.php?oldid=161202", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-029", "seg": 10, "title": "Urheberrecht", "de": ["Das Urheberrecht ist das Recht eines Urhebers. Urheber ist man, wenn man ein Werk erschafft. Das Werk kann ein Bild sein, oder ein Text, oder ein Musikstück. Wer zum Beispiel ein Foto macht, ist der Urheber des Fotos.", "Wenn man Urheber ist, dann darf man bestimmen, was mit dem Werk passieren soll. Andere Leute dürfen das Werk nicht ohne Erlaubnis verwenden. Wenn sie es trotzdem tun, können sie bestraft werden. Für manche Menschen ist es sehr wichtig, dass nicht jeder das Werk verwenden darf: Sie wollen Geld damit verdienen.", "Nach dem Tod eines Urhebers bleibt das Urheberrecht bestehen und geht an seine Familie über. Manchmal wurden die Nutzungsrechte an ein Unternehmen verkauft. Wenn schon 70 Jahre seit dem Tod vergangen sind, ist ein Werk in Deutschland und seinen Nachbarländern jedoch nicht mehr geschützt und wird als gemeinfrei bezeichnet. Dann darf jeder das Werk nutzen, verbreiten oder verändern.", "Darum haben sie die Idee der Freien Inhalte gehabt. Solche Freien Inhalte dürfen von Fremden genutzt werden. Die Nutzenden müssen aber bestimmte Regeln einhalten. Zum Beispiel müssen sie erwähnen, wer sich den Inhalt ausgedacht hat. Was genau erlaubt ist und verlangt wird, das steht in Texten mit Regeln. Diese Texte nennt man Freie Lizenz."], "zh": ["版权是作者的权利。创作出一件作品的人就是作者。作品可以是一幅画、一篇文字或一首乐曲。比如拍了一张照片的人，就是这张照片的作者。", "作者可以决定作品怎样使用。别人未经允许不能使用这件作品。如果照样用了，可能会受罚。对有些人来说，不是谁都能用自己的作品这一点很重要：他们想靠作品挣钱。", "作者去世后，版权依然存在，转给他的家人。有时使用权被卖给了一家公司。不过在德国及其邻国，作者去世满 70 年后，作品就不再受保护，被称为公有领域作品。这时谁都可以使用、传播或修改它。", "所以有人想出了「自由内容」的主意。这样的自由内容陌生人也可以用，但使用者要遵守一定的规则。比如必须注明内容是谁想出来的。具体允许什么、要求什么，写在规则文本里。这种文本叫自由许可证。"], "lemmas": [], "gloss": [{"w": "Urheber", "de": "jemand, der ein Werk gemacht hat", "zh": "作者"}, {"w": "erschafft", "de": "neu macht, herstellt", "zh": "创作"}, {"w": "Erlaubnis", "de": "wenn jemand sagt, dass man etwas darf", "zh": "允许"}, {"w": "gemeinfrei", "de": "frei für alle, ohne Urheberrecht", "zh": "公有领域的"}, {"w": "verbreiten", "de": "an viele Menschen weitergeben", "zh": "传播"}, {"w": "einhalten", "de": "sich an etwas halten", "zh": "遵守"}], "qs": [{"q": "Wer ist der Urheber eines Fotos?", "qZh": "照片的作者是谁？", "answer": "Die Person, die das Foto gemacht hat.", "wrong": ["Die Person, die das Foto kauft.", "Die Person auf dem Foto."]}, {"q": "Wann ist ein Werk in Deutschland gemeinfrei?", "qZh": "在德国作品什么时候进入公有领域？", "answer": "70 Jahre nach dem Tod des Urhebers.", "wrong": ["Sofort nach dem Tod des Urhebers.", "Nach 10 Jahren."]}, {"q": "Was muss man bei Freien Inhalten zum Beispiel tun?", "qZh": "使用自由内容时比如要做什么？", "answer": "Erwähnen, wer sich den Inhalt ausgedacht hat.", "wrong": ["Viel Geld bezahlen.", "Den Inhalt geheim halten."]}], "src": "改编自 Klexikon《Urheberrecht》", "url": "https://klexikon.zum.de/index.php?oldid=159323", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-030", "seg": 10, "title": "Dating-Plattform", "de": ["Eine Dating-Plattform ist eine Website oder eine App, auf der sich Menschen kennenlernen können. Viele Menschen nutzen sie, um neue Freunde zu finden, oder auch jemanden zu finden, in den man sich verliebt.", "Auf einer Dating-Plattform kann man ein eigenes Profil erstellen. Dort gibt man einen Namen an, wie alt man ist und was man mag. Oft kann man auch ein Foto hochladen. Andere Nutzer können dieses Profil sehen und entscheiden, ob sie Kontakt aufnehmen möchten.", "Bevor es das Internet gab, haben sich viele Menschen an echten Orten getroffen: am Arbeitsplatz, im Verein, in Kneipen, in Diskotheken oder woanders. Das passiert heute aber viel weniger, die meisten Leute sind abends zuhause.", "Danach erstellt man ein Profil über sich: Auf dieser Seite schreibt man etwas über sich selbst. Dann sucht man nach anderen Menschen, man schaut sich deren Profile an. Viele Plattformen schlagen auch Menschen vor, die zu einem passen könnten.", "Wenn zwei Menschen Interesse aneinander haben, dann können sie sich Nachrichten schreiben oder miteinander sprechen. Nach einer Weile vereinbaren sie vielleicht, dass sie sich auch persönlich, im echten Leben, kennenlernen.", "Die Plattformen haben den Vorteil, dass man dort Menschen kennenlernt, die man ansonsten vielleicht nicht treffen würde. Gerade schüchterne Menschen haben lieber erst einmal einen Kontakt online, bevor sie jemanden in echt kennenlernen.", "Es gibt Menschen, die auf der Plattform über sich lügen. Sie sagen also Dinge über sich, die nicht stimmen. Sie behaupten zum Beispiel, dass sie jünger sind als in echt, oder sie laden ein Foto hoch, auf dem tatsächlich jemand anders zu sehen ist."], "zh": ["交友平台是让人们相识的网站或应用。很多人用它来交新朋友，或者找一个能爱上的人。", "在交友平台上可以建立自己的个人资料。在那里填上名字、年龄和喜好，常常还可以上传一张照片。别的用户能看到这份资料，再决定要不要联系。", "有互联网之前，很多人在真实的地方相识：在工作单位、社团、小酒馆、迪斯科舞厅或别的地方。但如今这种事少多了，大多数人晚上都待在家里。", "之后给自己写一份资料：在这一页上写一些关于自己的事。然后寻找别人，看看他们的资料。很多平台也会推荐可能合适的人。", "如果两个人对彼此有兴趣，就可以互发消息或聊天。过一阵子他们也许会约好亲自见面，在现实生活中认识。", "这些平台的好处是能认识平时可能遇不到的人。特别是害羞的人，更愿意先在网上联系，再见真人。", "有人在平台上说关于自己的谎话，也就是说一些不真实的事。比如他们声称自己比实际年轻，或者上传的照片上其实是别人。"], "lemmas": [], "gloss": [{"w": "Profil", "de": "Seite mit Angaben über eine Person", "zh": "个人资料"}, {"w": "hochladen", "de": "ins Internet schicken", "zh": "上传"}, {"w": "Kneipen", "de": "einfache Lokale, wo man etwas trinkt", "zh": "小酒馆"}, {"w": "vereinbaren", "de": "zusammen beschließen, verabreden", "zh": "约定"}, {"w": "schüchterne", "de": "die Angst haben, mit Fremden zu sprechen", "zh": "害羞的"}, {"w": "behaupten", "de": "sagen, dass etwas so ist (auch wenn es nicht stimmt)", "zh": "声称"}], "qs": [{"q": "Was gibt man in einem Profil an?", "qZh": "个人资料里填什么？", "answer": "Namen, Alter und was man mag.", "wrong": ["Seine Kontonummer.", "Seine Adresse und Telefonnummer der Eltern."]}, {"q": "Für wen sind Dating-Plattformen besonders praktisch?", "qZh": "交友平台特别适合谁？", "answer": "Für schüchterne Menschen.", "wrong": ["Nur für sehr alte Menschen.", "Nur für Kinder."]}, {"q": "Wie lügen manche Menschen auf der Plattform?", "qZh": "有些人在平台上怎样撒谎？", "answer": "Sie sagen, dass sie jünger sind, oder zeigen ein fremdes Foto.", "wrong": ["Sie schreiben gar nichts.", "Sie melden sich zweimal an."]}], "src": "改编自 Klexikon《Dating-Plattform》", "url": "https://klexikon.zum.de/index.php?oldid=163623", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-031", "seg": 10, "title": "Plakat", "de": ["Ein Plakat ist eine große Fläche aus Papier, Stoff oder einem anderen Material. Auf die Fläche wird etwas gemalt, gezeichnet oder gedruckt. Das Plakat soll auf etwas aufmerksam machen. Häufig zeigen Plakate Werbung.", "Schon im Altertum gab es Flächen, auf die man etwas geschrieben hat. Oder man hat ein Bild gezeigt. Das Wort Plakat kommt aus der niederländischen Sprache im Mittelalter: „Placken“ hieß so viel wie beschmieren oder einen Klecks auf etwas werfen. Im Kampf gegen Spanien haben Niederländer Plakate aufgehängt, um ihre Meinung zu sagen. Das war vor etwa 400 Jahren.", "Ein anderes Wort ist Poster. Im Englischen bedeutet es, dass man etwas an einen Pfosten geklebt hat. Man sagt auch Posteranschlag oder Plakatanschlag.", "In den Jahren um 1850 und vor allem nach 1900 gab es immer mehr Plakate. Das kam auch daher, dass die Technik des Druckens besser wurde. Man konnte viele Plakate für recht wenig Geld drucken. Manche Plakate haben sich sogar bekannte Künstler ausgedacht.", "Mit Plakaten wird oft Werbung für eine Ware gemacht, oder für ein Theaterstück oder heute für einen Film. Im Ersten Weltkrieg etwa hat man auch Propaganda gegen die Feinde auf Plakate gedruckt. Später haben auch politische Parteien Plakate aufgehängt, vor allem im Wahlkampf."], "zh": ["海报是用纸、布或别的材料做的一大块平面。上面画着、描着或印着东西。海报要让人注意到某件事。海报常常是广告。", "古代就已经有可以在上面写字的平面，或者人们展示一幅画。Plakat 这个词来自中世纪的荷兰语：placken 的意思差不多是涂抹，或者往东西上甩一块污渍。在反抗西班牙的斗争中，荷兰人张贴海报来表达意见。那是大约 400 年前的事。", "另一个词是 Poster。在英语里它的意思是把东西贴在柱子上。也说 Posteranschlag 或 Plakatanschlag（张贴的海报）。", "1850 年前后，特别是 1900 年以后，海报越来越多。这也是因为印刷技术变好了。人们能花很少的钱印很多海报。有些海报甚至是有名的艺术家设计的。", "海报常常用来给商品做广告，或者给一出戏、今天则给一部电影做广告。比如第一次世界大战时，人们也把针对敌人的宣传印在海报上。后来政党也张贴海报，特别是在竞选时。"], "lemmas": [], "gloss": [{"w": "Fläche", "de": "flaches Stück, Oberfläche", "zh": "平面"}, {"w": "aufmerksam", "de": "so, dass man etwas bemerkt", "zh": "注意的"}, {"w": "Altertum", "de": "sehr alte Zeit, z. B. bei den Römern", "zh": "古代"}, {"w": "Klecks", "de": "kleiner Fleck von Farbe oder Tinte", "zh": "污渍"}, {"w": "Pfosten", "de": "Holz- oder Metallstange, die im Boden steht", "zh": "柱子"}, {"w": "Wahlkampf", "de": "Zeit vor einer Wahl, in der Parteien werben", "zh": "竞选"}], "qs": [{"q": "Wozu ist ein Plakat da?", "qZh": "海报是干什么用的？", "answer": "Es soll auf etwas aufmerksam machen.", "wrong": ["Es soll ein Fenster ersetzen.", "Es soll Briefe verschicken."]}, {"q": "Warum gab es nach 1900 viel mehr Plakate?", "qZh": "为什么 1900 年后海报多了很多？", "answer": "Das Drucken wurde besser und billiger.", "wrong": ["Es gab kein Radio mehr.", "Papier war verboten."]}, {"q": "Wann hängen Parteien besonders viele Plakate auf?", "qZh": "政党什么时候张贴特别多的海报？", "answer": "Im Wahlkampf.", "wrong": ["Im Urlaub.", "An Weihnachten."]}], "src": "改编自 Klexikon《Plakat》", "url": "https://klexikon.zum.de/index.php?oldid=165557", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-032", "seg": 10, "title": "Eisenbahn", "de": ["Die Eisenbahn ist ein Mittel, um schnell von Ort zu Ort zu kommen, also von einem Bahnhof zu einem anderen. Der Name Eisenbahn kommt von den Schienen, auf denen sie fährt und die vor allem aus Eisen bestehen. Mit Bahn meinte man den Weg, der gebahnt wurde.", "Oft denkt man beim Wort Eisenbahn an das Fahrzeug selbst, also einen Zug. Der heißt so, weil seine Waggons von einer Lokomotive oder einem Triebwagen gezogen werden. Es kann mit Eisenbahn oder Bahn aber auch alles drum herum gemeint sein, also Schienen, Bahnhöfe, Stellwerke und Leute, die für die Bahn arbeiten. Häufig heißen die Unternehmen, die Züge betreiben, auch einfach Bahn.", "In den Jahren nach 1800 hat man angefangen, die Wagen mit Dampfkraft zu bewegen. Wie zuvor hat man solche Wagen auf Schienen für den Bergbau benutzt. Eine richtige Eisenbahn für alle gab es zum ersten Mal 1825 in Großbritannien. Zehn Jahre später fuhr die erste Eisenbahn in Deutschland. Bald gab es immer mehr Strecken. Wer vor 1850 von Köln nach Berlin wollte, musste fast eine Woche mit Pferd oder Kutsche reisen. Einige Jahre später konnte man den gleichen Weg mit der Eisenbahn an einem Tag schaffen. Mit dem ICE dauert es heute nur noch etwas mehr als vier Stunden.", "Im 20. Jahrhundert endete fast überall die Zeit der Dampflokomotiven. Die Eisenbahnen wechselten auf Dieselmotoren oder elektrischen Strom für den Antrieb. Gleichzeitig hatten immer mehr Menschen ein Auto, so dass sie weniger mit der Bahn gefahren sind. Auf Fernstrecken hat sich das Flugzeug durchgesetzt. Darum hat die Eisenbahn weniger Geld verdient und konnte sich weniger Strecken und Wagen leisten. Trotzdem ist die Eisenbahn immer noch eines der wichtigsten Verkehrsmittel."], "zh": ["铁路是一种从一个地方快速到另一个地方的工具，也就是从一个火车站到另一个火车站。Eisenbahn 这个名字来自它行驶的铁轨，铁轨主要是铁做的。Bahn 指的是开辟出来的路。", "说到 Eisenbahn，人们常常想到车辆本身，也就是火车（Zug）。它叫 Zug，是因为车厢由机车或动车拉（ziehen）着走。但 Eisenbahn 或 Bahn 也可以指周围的一切：铁轨、车站、信号楼和为铁路工作的人。经营火车的公司也常常就叫 Bahn。", "1800 年以后，人们开始用蒸汽动力推动车厢。和以前一样，这种轨道车先用在采矿上。第一条面向所有人的真正铁路 1825 年出现在英国。十年后德国开通了第一条铁路。很快线路越来越多。1850 年以前，从科隆到柏林骑马或坐马车要走将近一周。几年后坐火车一天就能到。今天坐 ICE 只要四个多小时。", "20 世纪，蒸汽机车的时代几乎在各地都结束了。铁路改用柴油机或电力驱动。同时越来越多的人有了汽车，坐火车的人少了。长途方面飞机占了上风。所以铁路挣的钱少了，能负担的线路和车厢也少了。尽管如此，铁路仍然是最重要的交通工具之一。"], "lemmas": [], "gloss": [{"w": "Schienen", "de": "Eisenstangen, auf denen ein Zug fährt", "zh": "铁轨"}, {"w": "Waggons", "de": "Wagen eines Zuges", "zh": "车厢"}, {"w": "Dampfkraft", "de": "Kraft aus heißem Wasserdampf", "zh": "蒸汽动力"}, {"w": "Strecken", "de": "Wege, die ein Zug fährt", "zh": "线路"}, {"w": "Kutsche", "de": "Wagen, den Pferde ziehen", "zh": "马车"}, {"w": "durchgesetzt", "de": "hat gewonnen, ist üblich geworden", "zh": "占上风"}], "qs": [{"q": "Woher hat die Eisenbahn ihren Namen?", "qZh": "Eisenbahn 这个名字从哪来？", "answer": "Von den Schienen aus Eisen.", "wrong": ["Von einem Mann namens Eisen.", "Von der Farbe der Züge."]}, {"q": "Wie lange dauerte die Reise von Köln nach Berlin vor 1850?", "qZh": "1850 年前从科隆到柏林要多久？", "answer": "Fast eine Woche.", "wrong": ["Vier Stunden.", "Einen Tag."]}, {"q": "Warum fuhren im 20. Jahrhundert weniger Menschen mit der Bahn?", "qZh": "20 世纪为什么坐火车的人少了？", "answer": "Immer mehr Menschen hatten ein Auto.", "wrong": ["Die Züge wurden verboten.", "Die Fahrkarten waren gratis."]}], "src": "改编自 Klexikon《Eisenbahn》", "url": "https://klexikon.zum.de/index.php?oldid=156599", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-033", "seg": 10, "title": "U-Bahn", "de": ["Eine U-Bahn ist ein Zug, der in einem Tunnel unter der Erde fährt. U-Bahn steht für Untergrund-Bahn. U-Bahnen werden vor allem in großen Städten benutzt, um Wege innerhalb der Stadt in kurzer Zeit zu bewältigen. Die U-Bahn soll Menschen schnell befördern, auch wenn auf der Erde die Straßen voll sind und man mit dem Auto oder dem Bus nur schwer vorankommt. Darum fahren besonders viele Menschen mit der U-Bahn zur Arbeit.", "Die erste U-Bahn fuhr im Jahr 1863 in London in Großbritannien und hieß „Metropolitan Railway“. Die ersten U-Bahnen wurden mit Dampf betrieben. Sobald es Elektrizität gab, machte man auch die U-Bahnen elektrisch. Der Rauch der Dampfmaschinen ließ den Fahrgästen nämlich kaum Luft zum Atmen.", "Heute gibt es in der ganzen Welt U-Bahnen. In vielen Städten wie zum Beispiel Paris, Moskau oder Brüssel heißt die U-Bahn „Metro“, in London „Underground“ und in New York und anderen Städten der USA „Subway“. Der Gedanke dahinter ist aber immer derselbe: Die U-Bahn soll Menschen schnell von einem Ort zum anderen bringen, darum fährt sie unter der Erde an allen Ampeln und Staus vorbei.", "Eine U-Bahn kann viele Menschen gleichzeitig mitnehmen. Das ist für die Umwelt viel besser, als wenn diese Leute mit dem Auto auf der Straße fahren würden. Viele Autos verschmutzen die Luft. Doch es gibt einen Grund, warum es nicht noch mehr U-Bahnen auf der Welt gibt: Es ist ziemlich teuer, die Tunnel dafür zu bauen.", "Die Idee von Zügen, die unter der Erde fahren, breitete sich schnell aus. Das lag auch daran, dass damals die Städte in Europa und Nordamerika immer größer wurden. Viele Menschen zogen vom Lande in eine größere Stadt. Darum wurde es sinnvoll, U-Bahnen zu bauen. In Deutschland fuhr die erste U-Bahn in Berlin und wurde im Jahr 1902 eröffnet. In den USA fuhr die erste U-Bahn in New York City im Jahr 1904."], "zh": ["地铁是在地下隧道里行驶的列车。U-Bahn 是 Untergrund-Bahn（地下铁路）的缩写。地铁主要在大城市使用，用来在短时间里走完城里的路程。即使地面上街道拥挤、开车或坐公交很难前进，地铁也能快速运送人。所以特别多的人坐地铁上班。", "第一条地铁 1863 年在英国伦敦开通，叫「大都会铁路」。最早的地铁用蒸汽驱动。一有了电，人们就把地铁也改成电动。因为蒸汽机的烟让乘客几乎喘不过气。", "今天世界各地都有地铁。在巴黎、莫斯科或布鲁塞尔等许多城市，地铁叫 Metro，伦敦叫 Underground，纽约和美国其他城市叫 Subway。但背后的想法总是一样：地铁要把人快速从一个地方送到另一个地方，所以它在地下行驶，绕开所有红绿灯和堵车。", "地铁能同时载很多人。这比这些人都开车上路对环境好得多。很多汽车会污染空气。但世界上地铁没有更多是有原因的：修地铁隧道相当贵。", "地下行驶的列车这个主意传播得很快。这也是因为当时欧洲和北美的城市越来越大。很多人从乡下搬到大城市。所以修地铁变得有意义。在德国，第一条地铁在柏林，1902 年开通。在美国，第一条地铁 1904 年在纽约市开通。"], "lemmas": [], "gloss": [{"w": "bewältigen", "de": "schaffen, fertig machen", "zh": "完成、应付"}, {"w": "befördern", "de": "transportieren", "zh": "运送"}, {"w": "vorankommt", "de": "nach vorne kommt, weiterkommt", "zh": "前进"}, {"w": "Fahrgästen", "de": "Menschen, die mitfahren", "zh": "乘客"}, {"w": "verschmutzen", "de": "schmutzig machen", "zh": "污染"}, {"w": "sinnvoll", "de": "hat einen guten Grund", "zh": "有意义的"}], "qs": [{"q": "Wo fuhr die erste U-Bahn?", "qZh": "第一条地铁在哪里？", "answer": "In London.", "wrong": ["In Berlin.", "In New York."]}, {"q": "Warum machte man die U-Bahnen elektrisch?", "qZh": "为什么把地铁改成电动？", "answer": "Der Rauch der Dampfmaschinen war schlecht für die Fahrgäste.", "wrong": ["Elektrizität war billiger als Wasser.", "Die Züge waren zu schnell."]}, {"q": "Warum gibt es nicht noch mehr U-Bahnen?", "qZh": "为什么地铁没有更多？", "answer": "Es ist teuer, die Tunnel zu bauen.", "wrong": ["Niemand fährt gern U-Bahn.", "U-Bahnen sind verboten."]}], "src": "改编自 Klexikon《U-Bahn》", "url": "https://klexikon.zum.de/index.php?oldid=153608", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-034", "seg": 10, "title": "Straßenbahn", "de": ["Die Straßenbahn ist ein Verkehrsmittel. Wie ein Zug fährt die Straßenbahn auf Schienen. Die Schienen sind aber in eine Straße eingebunden. Fast alle Straßenbahnen fahren innerhalb einer Stadt, meist dort, wo viele Leute mitfahren wollen.", "Manche Leute, vor allem in der Schweiz und in Österreich, nennen die Straßenbahn Tram oder Trambahn. Das kommt vom englischen Wort „tramway“. Tram nannte man eine Schiene, auf der man zum Beispiel in einem Bergwerk Waggons mit Kohle bewegte.", "Straßenbahnen können viel mehr Menschen transportieren als zum Beispiel Busse. Sie fahren ruhiger, weil es in den Schienen keine Schlaglöcher gibt wie in manchen Straßen. Manche Straßenbahnen, gerade die alten, ziehen auch Touristen an. Berühmt ist zum Beispiel die Straßenbahn von San Francisco in den USA, das „Cable Car“.", "Später trieb man die Wagen durch Dampfkraft oder Gas an. Um das Jahr 1900 fuhren immer mehr Wagen dank Elektrizität. Das ist auch heute noch das Normale. Darum verschmutzt die Straßenbahn die Luft nicht so wie Autobusse. Manche Straßenbahnen erhalten den Strom über Kabel oberhalb der Spur, andere über die Schienen.", "Früher gab es mehr Straßenbahnen als heute. Etwa um das Jahr 1970 richteten die Städte stattdessen Buslinien ein. Ein Grund dafür war, dass Straßenbahnen recht viel Platz brauchen. In engen Straßen konnten Autos nicht gut links oder rechts daran vorbeifahren.", "Allerdings kann eine einzige Straßenbahn so viele Menschen mitnehmen, wie in 40 Autos oder drei Busse passen. So gesehen nutzt man den Platz sehr gut, wenn eine Straßenbahn fährt. Auch steckt die Straßenbahn nur selten im Stau fest, da sie meist ihre eigene Spur hat. Auf Strecken, die viele Menschen befahren wollen, sind Straßenbahnen also ein sehr geeignetes Verkehrsmittel."], "zh": ["有轨电车是一种交通工具。它像火车一样在铁轨上行驶，但铁轨嵌在街道里。几乎所有有轨电车都在城市里运行，大多在很多人想乘车的地方。", "有些人，特别是在瑞士和奥地利，把有轨电车叫 Tram 或 Trambahn。这来自英语 tramway。Tram 原本指一种轨道，比如在矿井里用它推运装煤的车厢。", "有轨电车能运的人比公交车多得多。它开起来更平稳，因为铁轨上没有像某些街道那样的坑洼。有些有轨电车，尤其是老的，也吸引游客。比如美国旧金山的有轨电车「缆车」就很有名。", "后来人们用蒸汽或煤气来推动车厢。大约 1900 年，越来越多的车靠电行驶，今天这也还是常态。所以有轨电车不像公共汽车那样污染空气。有些有轨电车从轨道上方的电线取电，有些从铁轨取电。", "以前有轨电车比现在多。大约 1970 年，城市改设了公交线路。原因之一是有轨电车很占地方。在窄街上，汽车不容易从它左右开过去。", "不过一辆有轨电车能载的人，相当于 40 辆汽车或三辆公交车的载客量。这样看来，有轨电车很好地利用了空间。而且有轨电车很少堵在路上，因为它大多有自己的车道。所以在很多人要走的线路上，有轨电车是非常合适的交通工具。"], "lemmas": [], "gloss": [{"w": "eingebunden", "de": "eingebaut, ein Teil davon", "zh": "嵌入"}, {"w": "Bergwerk", "de": "Ort, wo man unter der Erde Kohle oder Erz holt", "zh": "矿井"}, {"w": "Schlaglöcher", "de": "Löcher in der Straße", "zh": "坑洼"}, {"w": "oberhalb", "de": "über, höher als", "zh": "在上方"}, {"w": "Spur", "de": "Teil der Straße für eine Reihe von Fahrzeugen", "zh": "车道"}, {"w": "geeignetes", "de": "passendes, gutes für diesen Zweck", "zh": "合适的"}], "qs": [{"q": "Warum fährt eine Straßenbahn ruhiger als ein Bus?", "qZh": "有轨电车为什么比公交车平稳？", "answer": "In den Schienen gibt es keine Schlaglöcher.", "wrong": ["Sie fährt langsamer.", "Sie hat weichere Sitze."]}, {"q": "Warum richteten Städte um 1970 Buslinien ein?", "qZh": "1970 年左右城市为什么改设公交线路？", "answer": "Straßenbahnen brauchen recht viel Platz.", "wrong": ["Busse fahren auf Schienen.", "Straßenbahnen waren zu leise."]}, {"q": "Wie viele Menschen passen in eine Straßenbahn?", "qZh": "一辆有轨电车能载多少人？", "answer": "So viele wie in 40 Autos oder drei Busse.", "wrong": ["So viele wie in ein Auto.", "So viele wie in 400 Busse."]}], "src": "改编自 Klexikon《Straßenbahn》", "url": "https://klexikon.zum.de/index.php?oldid=161292", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-035", "seg": 10, "title": "Bahnhof", "de": ["Ein Bahnhof ist ein Ort, an dem Eisenbahn-Züge halten. Dort können Reisende ein- und aussteigen. Kleine Bahnhöfe haben oft nur ein oder zwei Bahnsteige, an denen nur Nahverkehrszüge halten.", "Große Bahnhöfe in großen Städten sind oft riesige Hallen mit vielen Gleisen. Dort halten auch Fernverkehrszüge wie der ICE. In sehr großen Städten gibt es auch mehrere Bahnhöfe, den wichtigsten nennt man meist Hauptbahnhof.", "Die meisten Bahnhöfe sind für Reisende da, die Passagiere. Dort gibt es oft auch Geschäfte, in denen man einkaufen kann. Außerdem gibt es Güterbahnhöfe, auf denen keine Menschen ein- und aussteigen, sondern Waren verladen werden. Diese Güterbahnhöfe brauchen sehr viel Platz und liegen deshalb heute meist außerhalb der Städte.", "Einfacher kann man einen Kopfbahnhof bauen. Er hat Gleise an nur einer Seite. Die Züge fahren also von dieser Seite in den Kopfbahnhof und auf demselben Gleis wieder hinaus. Die Züge haben eine Lokomotive vorn und eine zweite hinten. Wenn ein Zug in den Kopfbahnhof eingefahren ist, steigt der Lokführer vorn aus und geht am Zug entlang zur Lok am Ende. Die fährt den Zug wieder aus dem Bahnhof heraus.", "Kopfbahnhöfe brauchen weniger Platz und können leichter an den Rand der Innenstadt gebaut werden. Aber die Züge brauchen mehr Zeit, allein schon, weil die Lokführer die Lok wechseln müssen. Und oft will ein Zug nicht einfach wieder zurück dorthin fahren, woher er kommt, sondern in derselben Richtung weiterfahren. Er muss dann für die Weiterfahrt einen Umweg um die Stadt machen."], "zh": ["火车站是火车停靠的地方，旅客在那里上下车。小火车站常常只有一两个站台，只停短途列车。", "大城市的大火车站常常是有很多股轨道的巨大大厅，ICE 这样的长途列车也在那里停。在特别大的城市里还有好几个火车站，最重要的那个大多叫中央火车站。", "大多数火车站是为旅客，也就是乘客服务的。那里常常还有可以购物的商店。此外还有货运站，那里没有人上下车，而是装卸货物。这些货运站需要很大的地方，所以今天大多在城外。", "尽头式车站修起来更简单。它只有一边有轨道。列车从这一边开进尽头站，再从同一股轨道开出去。列车前面有一个车头，后面还有一个。列车开进尽头站后，司机从前面下车，沿着列车走到尾部的车头，由它把列车开出车站。", "尽头式车站需要的地方少，比较容易修在市中心边上。但列车要花更多时间，光是司机换车头就要时间。而且列车常常不是要原路返回，而是要朝同一方向继续开。那它就得绕城走一段弯路才能继续行驶。"], "lemmas": [], "gloss": [{"w": "Bahnsteige", "de": "Orte neben den Gleisen, wo man einsteigt", "zh": "站台"}, {"w": "Gleisen", "de": "Schienen, auf denen ein Zug fährt", "zh": "轨道"}, {"w": "Hauptbahnhof", "de": "wichtigster Bahnhof einer Stadt", "zh": "中央火车站"}, {"w": "verladen", "de": "auf ein Fahrzeug bringen", "zh": "装卸"}, {"w": "Lokführer", "de": "jemand, der einen Zug fährt", "zh": "火车司机"}, {"w": "Umweg", "de": "längerer Weg als nötig", "zh": "弯路"}], "qs": [{"q": "Wie nennt man meist den wichtigsten Bahnhof einer Stadt?", "qZh": "城市里最重要的火车站一般叫什么？", "answer": "Hauptbahnhof.", "wrong": ["Güterbahnhof.", "Kopfbahnhof."]}, {"q": "Was passiert auf einem Güterbahnhof?", "qZh": "货运站做什么？", "answer": "Waren werden verladen.", "wrong": ["Reisende steigen ein.", "Man kauft Fahrkarten."]}, {"q": "Was ist ein Nachteil eines Kopfbahnhofs?", "qZh": "尽头式车站有什么缺点？", "answer": "Die Züge brauchen mehr Zeit.", "wrong": ["Er braucht sehr viel Platz.", "Man kann nicht einsteigen."]}], "src": "改编自 Klexikon《Bahnhof》", "url": "https://klexikon.zum.de/index.php?oldid=158454", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-036", "seg": 10, "title": "Autobahn", "de": ["Eine Autobahn ist eine besondere Art von Straße. Auf so einer Straße dürfen nur Autos und Lastwagen fahren. Genauer gesagt: Fahrzeuge mit Motor, die schnell genug für die Autobahn sind. Mofas, Fahrräder und Fußgänger sind auf Autobahnen verboten.", "Sinn der Autobahn ist es, dass man möglichst schnell vorankommt. Auf der Autobahn darf man nur im Notfall anhalten. Es gibt keine Ampeln und Kreuzungen. In jeder Richtung verlaufen mindestens zwei Fahrspuren, damit man gut überholen kann. In den meisten Ländern gibt es eine Höchstgeschwindigkeit, zum Beispiel 120 Kilometer pro Stunde. In Deutschland darf man auch schneller fahren, aber auf vielen Teilen der Autobahn gibt es trotzdem eine Obergrenze für die Geschwindigkeit.", "Die erste Autobahn der Welt wurde 1921 in Berlin vorgestellt. Es war eine kurze Strecke, um die Idee der Autobahn auszuprobieren. Die erste Autobahn für die Öffentlichkeit gibt es seit 1932: Sie verbindet die Städte Köln und Bonn. Wirklich viele Autobahnen, ein Netz von Autobahnen, hat man erst in den Jahren nach 1950 gebaut. Erst dann gab es genügend Autos, so dass sich das gelohnt hat.", "In den einzelnen Ländern der Welt haben die Autobahnen unterschiedliche Namen und Regeln. In den USA heißen sie zum Beispiel Interstate oder in Großbritannien Motorway. Häufig müssen die Autofahrer und Lastwagenfahrer für das Befahren der Autobahnen Geld bezahlen. Dies nennt man eine Maut. In einigen Ländern bezahlt man sie an Zahlstellen, anderswo, indem man im Laden einen Aufkleber kauft, der dann an die Scheibe geklebt wird."], "zh": ["高速公路是一种特殊的道路。这种路上只准汽车和卡车行驶。确切地说：有发动机、速度够快、能上高速的车辆。轻便摩托、自行车和行人禁止上高速公路。", "高速公路的意义在于尽可能快地前进。在高速公路上只有紧急情况才能停车。没有红绿灯，也没有十字路口。每个方向至少有两条车道，方便超车。大多数国家有最高时速，比如每小时 120 公里。在德国也可以开得更快，但很多路段仍然有限速。", "世界上第一条高速公路 1921 年在柏林亮相。那是很短的一段路，用来试验高速公路的想法。第一条对公众开放的高速公路从 1932 年开始使用：它连接科隆和波恩两座城市。真正大量的高速公路，也就是高速公路网，直到 1950 年以后才修起来。那时汽车才够多，修路才划算。", "世界各国的高速公路名字和规则各不相同。比如在美国叫 Interstate，在英国叫 Motorway。汽车司机和卡车司机常常要为使用高速公路付钱，这叫过路费。有些国家在收费站付，有的地方则在商店买一张贴纸，贴在车窗上。"], "lemmas": [], "gloss": [{"w": "Fußgänger", "de": "jemand, der zu Fuß geht", "zh": "行人"}, {"w": "Notfall", "de": "gefährliche Situation, in der man schnell Hilfe braucht", "zh": "紧急情况"}, {"w": "überholen", "de": "an einem anderen Fahrzeug vorbeifahren", "zh": "超车"}, {"w": "Höchstgeschwindigkeit", "de": "das schnellste Tempo, das erlaubt ist", "zh": "最高时速"}, {"w": "Öffentlichkeit", "de": "alle Menschen", "zh": "公众"}, {"w": "Maut", "de": "Geld, das man für die Benutzung einer Straße zahlt", "zh": "过路费"}], "qs": [{"q": "Wer darf nicht auf der Autobahn fahren?", "qZh": "谁不准上高速公路？", "answer": "Radfahrer und Fußgänger.", "wrong": ["Lastwagen.", "Schnelle Autos."]}, {"q": "Welche Städte verbindet die erste öffentliche Autobahn?", "qZh": "第一条公共高速公路连接哪两座城市？", "answer": "Köln und Bonn.", "wrong": ["Berlin und Hamburg.", "München und Stuttgart."]}, {"q": "Was ist eine Maut?", "qZh": "过路费是什么？", "answer": "Geld für das Befahren der Autobahn.", "wrong": ["Eine Strafe für zu schnelles Fahren.", "Ein Schild an der Autobahn."]}], "src": "改编自 Klexikon《Autobahn》", "url": "https://klexikon.zum.de/index.php?oldid=160742", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-037", "seg": 10, "title": "Stau", "de": ["Ein Stau ist etwas, das im Verkehr passiert. Normalerweise soll ein Auto ohne Probleme zügig über eine Straße fahren können. Bei einem Stau stockt dieser Verkehrsfluss: Das Auto muss öfter langsam fahren oder gar stoppen. Wenn zu viele Autos dieselbe Straße benutzen wollen, fehlt es ihnen an Platz, und es kommt zum Stau.", "Bei den eigentlichen Staus stehen die Autos fast immer richtig still. Ansonsten spricht man von stockendem Verkehr. Was genau ein Stau ist, das hängt von Land zu Land ab. In der Schweiz bedeutet ein Stau: Mindestens eine Minute lang kann man auf der Straße nicht einmal 10 Stundenkilometer schnell fahren. In den Niederlanden sagt man stillstehender Verkehr, wenn man mindestens zwei Kilometer lang langsamer als 25 Stundenkilometer fährt.", "Den längsten Stau der Welt hat man im Jahr 1980 gesehen, und zwar in Frankreich. Zwischen Paris und Lyon gab es einen einzigen Stau von 176 Kilometern Länge. In Deutschland stehen die Autos am meisten in Hamburg, Berlin und Wiesbaden im Stau.", "Viele Staus bilden sich, wenn eine Straße gesperrt ist, wenn man dort nicht weiterfahren kann. Das passiert oft nach einem Unfall. Manchmal ist zwar nur eine Spur gesperrt, wie man es oft bei einer Baustelle macht. Die andere Spur ist frei. Auch dann kommt es zum Stau, zum Beispiel, wenn mit einer Ampel geregelt wird, in welche Richtung man wann fahren darf.", "Zum Stau kommt es auch, wenn zu viele Autos gleichzeitig eine Straße befahren wollen. Auch schnelles Fahren sorgt für Stau. Ein Auto braucht Platz, besonders, wenn es schnell fährt. Es braucht zum Beispiel etwas mehr Platz neben sich, weil schnelle Autos ein wenig schlingern. An einer Baustelle, wo die übrige Spur schmal ist, muss man deswegen langsam fahren."], "zh": ["堵车是交通中发生的事。正常情况下，汽车应该能毫无问题地在路上顺畅行驶。堵车时，这种车流就停滞了：车要经常慢行，甚至停下。如果太多汽车想走同一条路，就没有足够的空间，于是就堵车了。", "真正堵车时，车几乎总是完全停着不动。不然就叫车流缓慢。什么才算堵车，各国不一样。在瑞士，堵车的意思是：至少一分钟里，车速连每小时 10 公里都达不到。在荷兰，如果至少两公里都慢于每小时 25 公里，就叫交通停滞。", "世界上最长的堵车出现在 1980 年的法国。巴黎和里昂之间出现了一条长达 176 公里的车龙。在德国，车堵得最多的是汉堡、柏林和威斯巴登。", "很多堵车是因为道路被封、无法继续前进而形成的，这常发生在事故之后。有时只封了一条车道，比如修路时常常这样，另一条车道是通的。这时也会堵车，比如用红绿灯控制什么时候往哪个方向开。", "太多车同时想走一条路，也会堵车。开得快也会造成堵车。汽车需要空间，开得快时尤其如此。比如快车旁边需要多一点空间，因为它会有点摇摆。所以在剩下的车道很窄的工地旁，必须开慢一点。"], "lemmas": [], "gloss": [{"w": "zügig", "de": "schnell und ohne Pause", "zh": "顺畅地"}, {"w": "stockt", "de": "geht nicht weiter, bleibt stehen", "zh": "停滞"}, {"w": "Verkehrsfluss", "de": "wie sich der Verkehr bewegt", "zh": "车流"}, {"w": "gesperrt", "de": "geschlossen, man darf nicht durch", "zh": "封闭的"}, {"w": "Baustelle", "de": "Ort, an dem gebaut wird", "zh": "工地"}, {"w": "schlingern", "de": "hin und her schwanken", "zh": "摇摆"}], "qs": [{"q": "Warum kommt es zum Stau?", "qZh": "为什么会堵车？", "answer": "Zu viele Autos wollen dieselbe Straße benutzen.", "wrong": ["Die Autos sind zu klein.", "Es gibt zu viele Ampeln auf der Autobahn."]}, {"q": "Wo gab es den längsten Stau der Welt?", "qZh": "世界上最长的堵车在哪里？", "answer": "Zwischen Paris und Lyon.", "wrong": ["Zwischen Hamburg und Berlin.", "In Wiesbaden."]}, {"q": "Was passiert oft nach einem Unfall?", "qZh": "事故后常发生什么？", "answer": "Die Straße wird gesperrt und es gibt Stau.", "wrong": ["Alle fahren schneller.", "Die Ampeln gehen aus."]}], "src": "改编自 Klexikon《Stau》", "url": "https://klexikon.zum.de/index.php?oldid=159126", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-038", "seg": 10, "title": "Verkehr", "de": ["Verkehr nennt man es, wenn man Menschen oder Dinge von einem Ort zum anderen bringt. Man spricht auch von Transport. Das macht man mit Autos, Schiffen oder anderen Gefährten. So ein Gefährt ist ein Verkehrsmittel. Die Verkehrsmittel bewegen sich auf Verkehrswegen, die wir meist Wege oder Straßen nennen.", "Verkehr ist teuer. Für den Autoverkehr braucht man zum Beispiel nicht nur Autos, sondern auch Straßen. Wer ein Auto fahren will, muss sich selbst das Auto kaufen. Aber die Straßen werden vom Staat gebaut – dafür müssen auch Menschen bezahlen, die kein Auto haben. Außerdem brauchen Straßen viel Platz.", "Auch wer nur zu Fuß geht, ist Verkehrsteilnehmer. Als Fußgänger muss man sich genauso an die Regeln halten wie andere Leute auch. In armen Ländern gehen viele Menschen sehr, sehr weit zu Fuß, zum Beispiel, um Wasser von einer Wasserstelle zu holen.", "Wer Glück hat, kann mit einem öffentlichen Verkehrsmittel fahren. Öffentlicher Verkehr ist der Verkehr für alle: Busse oder Eisenbahn darf jeder benutzen. Man muss jedoch das Fahrgeld bezahlen.", "Wenn man aber nicht in einer Stadt wohnt, sondern auf dem platten Lande, kann es sein, dass nur wenige öffentliche Verkehrsmittel fahren. Mit den wenigen Menschen, die dort wohnen, lässt sich nicht viel Geld verdienen. Oftmals muss ein Staat sowieso den öffentlichen Verkehr mit Geld unterstützen.", "In öffentliche Verkehrsmittel wie einen Bus passen viel mehr Menschen als in ein einzelnes Auto. Darum findet der Staat es gut, wenn viele Leute die „Öffentlichen“ nehmen. Das hilft gegen Staus, und es ist auch besser für die Umwelt."], "zh": ["把人或东西从一个地方送到另一个地方，就叫交通，也叫运输。人们用汽车、船或别的交通工具来做这件事。交通工具在交通路线上移动，我们大多把这些路线叫道路或街道。", "交通很贵。比如汽车交通不仅需要汽车，还需要道路。想开车的人得自己买车。但道路是国家修的，没有车的人也要为此出钱。而且道路很占地方。", "只靠走路的人也是交通参与者。行人和别人一样要遵守规则。在贫穷国家，很多人要走非常非常远的路，比如去水源地打水。", "运气好的人可以坐公共交通工具。公共交通是所有人的交通：公交车或火车谁都可以坐，但要付车费。", "但如果不住在城市，而住在偏僻的乡下，公共交通工具可能很少。那里住的人少，挣不了多少钱。国家往往本来就要出钱支持公共交通。", "公交车这样的公共交通工具能装的人比一辆汽车多得多。所以国家希望很多人坐「公共交通」。这有助于减少堵车，对环境也更好。"], "lemmas": [], "gloss": [{"w": "Verkehrsmittel", "de": "Fahrzeug, mit dem man reist (Bus, Zug ...)", "zh": "交通工具"}, {"w": "Verkehrsteilnehmer", "de": "jemand, der auf der Straße unterwegs ist", "zh": "交通参与者"}, {"w": "öffentlichen", "de": "für alle Menschen da", "zh": "公共的"}, {"w": "Fahrgeld", "de": "Geld für die Fahrt", "zh": "车费"}, {"w": "platten Lande", "de": "weit weg von der Stadt, auf dem Dorf", "zh": "乡下"}, {"w": "unterstützen", "de": "helfen, z. B. mit Geld", "zh": "支持"}], "qs": [{"q": "Wer bezahlt die Straßen?", "qZh": "谁为道路出钱？", "answer": "Der Staat, also auch Menschen ohne Auto.", "wrong": ["Nur die Autofahrer.", "Nur die Busfahrer."]}, {"q": "Warum fahren auf dem Land wenige Busse?", "qZh": "为什么乡下公交车少？", "answer": "Dort wohnen wenige Menschen, also verdient man wenig Geld.", "wrong": ["Auf dem Land gibt es keine Straßen.", "Die Menschen dort mögen keine Busse."]}, {"q": "Warum findet der Staat öffentliche Verkehrsmittel gut?", "qZh": "国家为什么喜欢公共交通？", "answer": "Sie helfen gegen Staus und sind besser für die Umwelt.", "wrong": ["Sie sind schneller als Flugzeuge.", "Sie kosten nichts."]}], "src": "改编自 Klexikon《Verkehr》", "url": "https://klexikon.zum.de/index.php?oldid=158077", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-039", "seg": 10, "title": "Verkehrszeichen", "de": ["Ein Verkehrszeichen ist ein Zeichen, um den Verkehr zu regeln und zu steuern. Das Zeichen kann auf ein Schild, auf eine Tafel oder direkt auf die Straße gemalt sein. Andere Wörter sind Verkehrssignal oder Straßensignal.", "Wer sich nicht an ein Zeichen hält, kann bestraft werden. Das gilt nicht nur für Autofahrer, sondern auch für alle anderen, die am Verkehr teilnehmen: für Radfahrer, Motorradfahrer oder Fußgänger.", "Manche Verkehrszeichen warnen vor Gefahren, zum Beispiel vor Wildwechsel. Das bedeutet, dass ab und zu Rehe oder andere Tiere über die Straße laufen. Andere Verkehrszeichen regeln die Vorfahrt oder ob man überholen darf oder wo man parken darf.", "Manchmal ist das Verkehrszeichen auf die Straße gemalt, zum Beispiel wie schnell man hier fahren darf. Noch etwas anderes ist die Fahrbahnmarkierung. So eine Markierung zeigt zum Beispiel an, wo am Straßenrand die Fahrbahn endet.", "Auch Wegweiser sind Verkehrszeichen. Damit wird an Straßen angegeben, wohin der Weg führt und wie viele Kilometer die Städte und Dörfer entfernt sind. Außerdem steht am Anfang eines Ortes ein Ortsschild mit dem Namen des Ortes. So weiß man, wo man gerade ist.", "Schließlich gibt es noch Ampeln. Eigentlich heißen sie „Signalgeber“ und gehören zu einer Lichtzeichenanlage oder Lichtsignalanlage. Wenn eine Ampel mal nicht funktioniert, dann gelten die Schilder, die daneben stehen, oder die Regel „rechts vor links“."], "zh": ["交通标志是用来规范和引导交通的标志。它可以画在牌子上、板上，或者直接画在路面上。别的说法有交通信号或道路信号。", "不遵守标志的人可能会受罚。这不只适用于汽车司机，也适用于所有其他交通参与者：骑自行车的人、骑摩托车的人或行人。", "有些交通标志警告危险，比如野生动物出没。意思是时不时会有狍子或别的动物跑过马路。另一些交通标志规定谁先行、能不能超车或者在哪儿可以停车。", "有时交通标志画在路面上，比如这里允许开多快。路面标线又是另一回事。这种标线比如会显示路边的车道在哪里结束。", "路标也是交通标志。路上用它标出路通向哪里，城市和村庄有多少公里远。此外每个地方的入口都有一块地名牌，写着地名。这样就知道自己在哪儿。", "最后还有红绿灯。它们其实叫「信号器」，属于灯光信号设备。红绿灯坏了的时候，就按旁边的牌子，或者按「右侧先行」的规则。"], "lemmas": [], "gloss": [{"w": "regeln", "de": "bestimmen, wie etwas ablaufen soll", "zh": "规范"}, {"w": "Wildwechsel", "de": "Stelle, wo wilde Tiere über die Straße laufen", "zh": "野生动物出没"}, {"w": "Vorfahrt", "de": "das Recht, zuerst zu fahren", "zh": "先行权"}, {"w": "Fahrbahnmarkierung", "de": "Linien auf der Straße", "zh": "路面标线"}, {"w": "Wegweiser", "de": "Schild, das den Weg zeigt", "zh": "路标"}, {"w": "gelten", "de": "richtig sein, gültig sein", "zh": "有效"}], "qs": [{"q": "Für wen gelten Verkehrszeichen?", "qZh": "交通标志适用于谁？", "answer": "Für alle im Verkehr, auch Radfahrer und Fußgänger.", "wrong": ["Nur für Autofahrer.", "Nur für Lastwagen."]}, {"q": "Was bedeutet das Zeichen für Wildwechsel?", "qZh": "野生动物出没的标志是什么意思？", "answer": "Tiere können über die Straße laufen.", "wrong": ["Man darf hier jagen.", "Hier gibt es einen Zoo."]}, {"q": "Was gilt, wenn eine Ampel nicht funktioniert?", "qZh": "红绿灯坏了怎么办？", "answer": "Die Schilder daneben oder „rechts vor links“.", "wrong": ["Man darf nicht weiterfahren.", "Alle dürfen gleichzeitig fahren."]}], "src": "改编自 Klexikon《Verkehrszeichen》", "url": "https://klexikon.zum.de/index.php?oldid=161206", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-040", "seg": 10, "title": "Führerschein", "de": ["Ein Führerschein zeigt, dass man ein Fahrzeug führen darf. Man darf also nur dann ein Auto oder ein anderes Fahrzeug fahren, wenn man so einen Führerschein hat. Je nach Land gibt es dafür verschiedene Ausdrücke: Fahrerlaubnis, Lenkberechtigung, Fahrberechtigung oder eben Führerschein.", "Die erste Fahrerlaubnis der Welt stammt aus dem Jahr 1888. Damals hat das Land Baden dem Erfinder des Autos, Carl Benz, erlaubt: Benz darf mit seinem Auto auf den öffentlichen Straßen fahren. Im Jahr 1903 verlangte Großbritannien als erstes Land, dass jeder so eine Erlaubnis haben muss, wenn er ein Auto fährt. Einige Jahre später machten das viele weitere Länder schon genauso.", "Bevor man einen Führerschein bekommt, muss man lernen, wie ein Auto bedient wird. Außerdem muss man sich mit allen Verkehrsregeln und mit den Schildern auskennen. Wird man ohne Führerschein beim Fahren erwischt, dann muss man eine hohe Strafe zahlen.", "Mit der Zeit wurde die Prüfung immer strenger, weil es schlimme Unfälle mit Autos gab. Der Staat hat auch dafür gesorgt, dass nicht jeder so einfach „Fahrlehrer“ sein darf. Das ist im Jahr 1969 in Deutschland ein richtiger Beruf geworden.", "Wer heute einen Führerschein haben will, muss auch alt genug sein. Für das Auto muss man 18 Jahre alt sein. Man kann aber mit dem Lernen schon drei Monate früher anfangen.", "Wenn man nur ein Mofa fahren will, also ein Fahrrad mit Hilfsmotor, braucht man nur 15 Jahre alt zu sein. Mit 16 darf man schon schnellere Zweiräder fahren und auch große, langsame Fahrzeuge, wie man sie in der Landwirtschaft kennt - einen Traktor zum Beispiel. Ein Motorrad darf man auch erst mit 18 Jahren benutzen."], "zh": ["驾照证明一个人可以驾驶车辆。也就是说，只有有驾照才能开汽车或别的车。不同国家有不同的说法：驾驶许可、驾驶授权、驾驶资格，或者就是驾照。", "世界上第一份驾驶许可是 1888 年的。当时巴登邦允许汽车的发明者卡尔·本茨开着他的车上公共道路。1903 年英国成为第一个要求每个开车的人都必须有这种许可的国家。几年后许多国家也这样做了。", "拿驾照之前，要学会怎样操作汽车。此外还要熟悉所有交通规则和标志。没有驾照开车被抓到，要交很高的罚款。", "随着时间推移，考试越来越严，因为发生了严重的车祸。国家还规定，不是谁都能随便当「驾校教练」。1969 年这在德国成了一门正式职业。", "今天想拿驾照的人还得年龄够大。开汽车要满 18 岁，但可以提前三个月开始学。", "如果只想骑轻便摩托，也就是带辅助发动机的自行车，只要满 15 岁就行。16 岁就可以骑更快的两轮车，也可以开农业上用的那种又大又慢的车，比如拖拉机。摩托车也要满 18 岁才能骑。"], "lemmas": [], "gloss": [{"w": "Fahrzeug", "de": "Auto, Bus, Motorrad usw.", "zh": "车辆"}, {"w": "verlangte", "de": "forderte, wollte haben", "zh": "要求"}, {"w": "bedient", "de": "benutzt, gesteuert", "zh": "操作"}, {"w": "auskennen", "de": "viel über etwas wissen", "zh": "熟悉"}, {"w": "erwischt", "de": "bei etwas Verbotenem gesehen", "zh": "抓到"}, {"w": "Landwirtschaft", "de": "Arbeit der Bauern", "zh": "农业"}], "qs": [{"q": "Wer bekam die erste Fahrerlaubnis der Welt?", "qZh": "谁拿到了世界上第一份驾驶许可？", "answer": "Carl Benz.", "wrong": ["Ein britischer König.", "Ein Fahrlehrer."]}, {"q": "Was passiert, wenn man ohne Führerschein fährt und erwischt wird?", "qZh": "无证驾驶被抓到会怎样？", "answer": "Man muss eine hohe Strafe zahlen.", "wrong": ["Man bekommt sofort einen Führerschein.", "Nichts."]}, {"q": "Wie alt muss man für den Autoführerschein sein?", "qZh": "考汽车驾照要多大？", "answer": "18 Jahre.", "wrong": ["15 Jahre.", "16 Jahre."]}], "src": "改编自 Klexikon《Führerschein》", "url": "https://klexikon.zum.de/index.php?oldid=160637", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-041", "seg": 10, "title": "Fähre", "de": ["Eine Fähre ist ein Schiff, das Autos, Menschen oder auch Gepäck und Güter an einen anderen Ort über einen Fluss, einen See oder ein Randmeer bringt. Die Fähre fährt zwischen Häfen oder kleinen Anlegestellen. Oft muss man eine Gebühr bezahlen, damit man die Fähre nutzen darf.", "Früher haben die Menschen häufiger eine Fähre benutzt als heute. Es gab damals weniger Brücken, da es schwierig war, sie zu bauen. Aber auch heute kann zum Beispiel ein Fluss zu breit sein, um eine Brücke zu bauen. Oder man findet, dass eine Brücke zu teuer wäre oder dass nur wenige Leute sie täglich brauchen. Andere Strecken sind so lang, dass viele Passagiere lieber fliegen.", "Auf kleinere Fähren passen nur wenige Leute oder auch einige Autos. Die Überfahrt dauert nicht lange, und die Leute stehen einfach auf dem Deck. Andere Fähren sind größer und fahren eine halbe Stunde oder länger. Dort können sich die Leute hinsetzen, ähnlich wie bei einem Bus.", "Einige Fähren sehen aus wie große Schiffe. Sie fahren zum Beispiel auf der Ostsee von Hafen zu Hafen, wie bei einer Kreuzfahrt. Das kann mehrere Tage dauern, darum braucht man auch Kabinen, in denen man übernachten kann. Ostseestädte wie Kiel, Rostock oder Puttgarden auf Fehmarn haben große Fährhäfen.", "Eine kleine Fähre wird von einem Fährmann gesteuert, eine große von einem Kapitän. Außerdem arbeiten auf großen Fähren Leute im Maschinenraum, bewirten die Gäste oder sorgen für Unterhaltung."], "zh": ["渡轮是一种船，它把汽车、人或者行李和货物运过河流、湖泊或边缘海送到另一个地方。渡轮在港口或小码头之间行驶。乘坐渡轮常常要付费。", "以前人们比今天更常坐渡轮。那时桥少，因为桥很难修。但今天也会有河太宽、修不了桥的情况。或者人们觉得桥太贵，或者每天只有很少人需要它。还有些航线太长，很多乘客宁愿坐飞机。", "小一点的渡轮只能装几个人或几辆车。过渡时间不长，人们就站在甲板上。别的渡轮大一些，要开半小时或更久，人们可以坐下，有点像坐公交车。", "有些渡轮看起来像大船。比如它们在波罗的海上从一个港口开到另一个港口，像游轮一样。这可能要好几天，所以还需要可以过夜的船舱。基尔、罗斯托克或费马恩岛上的普特加登等波罗的海城市都有大渡轮港。", "小渡轮由船夫驾驶，大渡轮由船长驾驶。此外大渡轮上还有人在机舱工作、招待客人或提供娱乐。"], "lemmas": [], "gloss": [{"w": "Güter", "de": "Waren, die man transportiert", "zh": "货物"}, {"w": "Anlegestellen", "de": "Orte, wo ein Schiff anhält", "zh": "码头"}, {"w": "Gebühr", "de": "Geld, das man für etwas bezahlt", "zh": "费用"}, {"w": "Überfahrt", "de": "Fahrt über das Wasser", "zh": "过渡"}, {"w": "Kabinen", "de": "kleine Zimmer auf einem Schiff", "zh": "船舱"}, {"w": "bewirten", "de": "Essen und Getränke bringen", "zh": "招待"}], "qs": [{"q": "Was transportiert eine Fähre?", "qZh": "渡轮运什么？", "answer": "Autos, Menschen, Gepäck und Güter.", "wrong": ["Nur Briefe.", "Nur Tiere."]}, {"q": "Warum benutzte man früher häufiger Fähren?", "qZh": "以前为什么更常坐渡轮？", "answer": "Es gab weniger Brücken.", "wrong": ["Es gab mehr Wasser.", "Flugzeuge waren verboten."]}, {"q": "Wozu braucht man auf großen Ostsee-Fähren Kabinen?", "qZh": "波罗的海大渡轮上为什么要有船舱？", "answer": "Die Fahrt kann mehrere Tage dauern.", "wrong": ["Damit man dort arbeitet.", "Für das Gepäck."]}], "src": "改编自 Klexikon《Fähre》", "url": "https://klexikon.zum.de/index.php?oldid=156094", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-042", "seg": 10, "title": "Wohnwagen", "de": ["Ein Wohnwagen oder Caravan ist ein Wagen, in dem man wohnen kann. Man hängt ihn hinten an ein Auto oder ein anderes Verkehrsmittel, wenn man weiterfahren will. Es ist also ein Anhänger ohne Motor. Dadurch unterscheidet er sich vom Wohnmobil. Dieses hat einen Motor und kann selber fahren.", "In den meisten Wohnwagen gibt es einen Schlafplatz, eine Toilette und eine kleine Küche. In der Küche gibt es meistens einen Gaskocher, eine Spüle und einen Kühler. Es gibt auch einen Wassertank, der regelmäßig mit einem Kanister aufgefüllt werden muss.", "Das Gas für den Kocher kommt aus einer Gasflasche, wie man sie auch vom Gasgrill kennt. Die Fäkalien aus der Toilette landen in einem weiteren Behälter, den man regelmäßig leeren und putzen muss. Wohnwagen können mit einem Kabel an den Strom angeschlossen werden. Unterwegs bekommt der Wohnwagen Strom vom Fahrzeug, an dem er hängt.", "Mit einem Anhänger fährt sich ein Auto schwieriger. Besonders bei engen Kurven und hoher Geschwindigkeit muss man aufpassen. Das Auto verbraucht auch mehr Benzin. Durch das Gewicht des Anhängers muss der Motor nämlich mehr Kraft aufwenden, um das Ganze zu bewegen. Wiegen Auto und Wohnwagen zusammen mehr als 3,5 Tonnen, braucht der Fahrer einen zusätzlichen Führerschein, um das Fahrzeuggespann führen zu dürfen. Während der Fahrt darf sich niemand im Wohnwagen aufhalten.", "In Deutschland gab es sie erstmals um das Jahr 1930. Erfunden wurde der deutsche Wohnwagen von Arist Dethleffs, der vorher Peitschen und Skistöcke herstellen ließ. Damals war der Wohnwagen ein beliebtes Hochzeitsgeschenk. Frisch vermählte Pärchen fuhren mit ihm durch Deutschland und machten so Werbung für das Gefährt."], "zh": ["住宿挂车（Caravan）是一种可以住人的车。想继续赶路时，就把它挂在汽车或别的交通工具后面。所以它是没有发动机的挂车。这一点和房车不同，房车有发动机，自己能开。", "大多数住宿挂车里有床位、厕所和一个小厨房。厨房里大多有燃气灶、水槽和冷藏箱。还有一个水箱，要定期用水桶加满。", "灶用的燃气来自燃气瓶，就是燃气烧烤炉上用的那种。厕所里的排泄物进到另一个容器里，要定期倒掉并清洗。住宿挂车可以用电线接上电源。路上它从拉着它的车上取电。", "挂着挂车的汽车更难开。特别是急转弯和高速时要小心。汽车也更费油，因为挂车有重量，发动机要用更大的力才能拉动整体。汽车和挂车合起来超过 3.5 吨的话，司机还需要另一种驾照才能驾驶这个车组。行驶途中挂车里不能有人。", "在德国，住宿挂车大约在 1930 年第一次出现。德国的住宿挂车是阿里斯特·德特莱夫斯发明的，他之前让人生产鞭子和滑雪杖。当时住宿挂车是很受欢迎的结婚礼物。新婚夫妇开着它周游德国，就这样给这种车做了广告。"], "lemmas": [], "gloss": [{"w": "Anhänger", "de": "Wagen ohne Motor, den ein Auto zieht", "zh": "挂车"}, {"w": "Spüle", "de": "Becken in der Küche zum Abwaschen", "zh": "水槽"}, {"w": "Behälter", "de": "etwas, in das man etwas hineintun kann", "zh": "容器"}, {"w": "angeschlossen", "de": "verbunden (z. B. mit Strom)", "zh": "接上"}, {"w": "aufwenden", "de": "brauchen, einsetzen (Kraft, Geld)", "zh": "耗费"}, {"w": "vermählte", "de": "verheiratete", "zh": "结了婚的"}], "qs": [{"q": "Was ist der Unterschied zwischen Wohnwagen und Wohnmobil?", "qZh": "住宿挂车和房车有什么区别？", "answer": "Ein Wohnmobil hat einen Motor, ein Wohnwagen nicht.", "wrong": ["Ein Wohnwagen ist immer größer.", "Ein Wohnmobil hat keine Küche."]}, {"q": "Warum verbraucht ein Auto mit Wohnwagen mehr Benzin?", "qZh": "为什么拉挂车的车更费油？", "answer": "Der Motor braucht mehr Kraft wegen des Gewichts.", "wrong": ["Der Wohnwagen hat einen eigenen Motor.", "Man fährt immer schneller."]}, {"q": "Was war der Wohnwagen um 1930 in Deutschland?", "qZh": "1930 年左右住宿挂车在德国是什么？", "answer": "Ein beliebtes Hochzeitsgeschenk.", "wrong": ["Ein Fahrzeug für Soldaten.", "Eine Art Bus."]}], "src": "改编自 Klexikon《Wohnwagen》", "url": "https://klexikon.zum.de/index.php?oldid=157730", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-043", "seg": 10, "title": "Hubschrauber", "de": ["Ein Hubschrauber ist ein Gerät, mit dem man fliegen kann. Ein anderes Wort ist Helikopter. Das Besondere am Hubschrauber ist, dass man mit ihm senkrecht starten und landen kann.", "Man kann mit dem Hubschrauber auch in der Luft stehen bleiben. Flugzeuge hingegen müssen sich immer vorwärts bewegen, sonst stürzen sie ab. Das liegt daran, dass immer Luft um die Flügel strömen muss, damit Auftrieb entsteht. Beim Flugzeug sind die Flügel starr, es braucht also Geschwindigkeit, um Auftrieb zu haben. Beim Hubschrauber bewegen sich die Flügel. Sie drehen sich, man sagt sie rotieren. Deshalb nennt man sie auch den Rotor.", "Hubschrauber braucht man heute nicht nur in der Armee: Die meisten Hubschrauber sind dazu da, um etwas aus der Luft zu beobachten und um Menschen zu retten. Außerdem gibt es reiche Leute, die mit dem Hubschrauber viel schneller ans Ziel gelangen wollen als mit dem Auto.", "Flugzeuge brauchen eine lange Bahn zum Landen und zum Starten. Hubschrauber brauchen das nicht, das ist wichtig, wenn man zum Beispiel im Gebirge jemanden abholen will, der einen Unfall hatte. Außerdem können Flugzeuge nicht unbeweglich in der Luft an einer Stelle stehen bleiben. Wer eine schwere Last genau an einem bestimmten Punkt auf der Erde absetzen will, macht das am besten mit dem Hubschrauber.", "Hubschrauber haben aber viele Nachteile. Im Vergleich zu einem Flugzeug brauchen sie deutlich mehr Energie und damit Benzin. Das ist teuer. Für einen Hubschrauber sind 300 Stundenkilometer schon ziemlich schnell. Der Rekord liegt bei etwa 470 Stundenkilometer. Die schnellsten Flugzeuge sind aber mehr als doppelt so schnell. Hubschrauber können auch nicht so hoch fliegen."], "zh": ["直升机是一种可以用来飞行的器械，另一个说法是 Helikopter。直升机的特别之处在于它能垂直起飞和降落。", "直升机还能停在空中不动。而飞机必须一直向前飞，否则就会坠落。这是因为机翼周围必须一直有空气流过，才能产生升力。飞机的机翼是固定的，所以需要速度才有升力。直升机的翼会动，它们在转，人们说它们在旋转，所以也把它们叫旋翼。", "今天不只军队需要直升机：大多数直升机用来从空中观察和救人。此外还有一些有钱人想坐直升机比开车快得多地到达目的地。", "飞机起降需要很长的跑道，直升机不需要。这在比如要去山里接一个出了事故的人时很重要。此外飞机不能一动不动地停在空中某一处。谁想把重物准确地放到地面某一点，最好用直升机。", "但直升机有很多缺点。和飞机比，它需要多得多的能源，也就是汽油，这很贵。对直升机来说，每小时 300 公里已经相当快了，纪录大约是每小时 470 公里，而最快的飞机比这快一倍多。直升机也飞不了那么高。"], "lemmas": [], "gloss": [{"w": "senkrecht", "de": "gerade nach oben oder unten", "zh": "垂直地"}, {"w": "stürzen", "de": "hier: stürzen … ab = fallen aus der Luft nach unten", "zh": "坠落"}, {"w": "Auftrieb", "de": "Kraft, die etwas nach oben drückt", "zh": "升力"}, {"w": "starr", "de": "fest, beweglos", "zh": "固定的"}, {"w": "gelangen", "de": "an einen Ort kommen", "zh": "到达"}, {"w": "Last", "de": "schweres Ding, das man trägt", "zh": "重物"}], "qs": [{"q": "Was ist das Besondere am Hubschrauber?", "qZh": "直升机的特别之处是什么？", "answer": "Er kann senkrecht starten und landen.", "wrong": ["Er ist schneller als jedes Flugzeug.", "Er braucht kein Benzin."]}, {"q": "Wozu braucht man die meisten Hubschrauber?", "qZh": "大多数直升机用来做什么？", "answer": "Um etwas zu beobachten und Menschen zu retten.", "wrong": ["Um Briefe zu bringen.", "Für Urlaubsreisen."]}, {"q": "Was ist ein Nachteil des Hubschraubers?", "qZh": "直升机有什么缺点？", "answer": "Er braucht viel mehr Energie als ein Flugzeug.", "wrong": ["Er braucht eine lange Bahn.", "Er kann nicht in der Luft stehen bleiben."]}], "src": "改编自 Klexikon《Hubschrauber》", "url": "https://klexikon.zum.de/index.php?oldid=160064", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-044", "seg": 10, "title": "Fußball", "de": ["Fußball ist eine Sportart, bei der zwei Mannschaften mit einem Ball spielen. Es ist eine der beliebtesten Sportarten der Welt. Ursprünglich kommt das Fußballspiel aus England. Im Laufe der Zeit hat Fußball seine heutigen Regeln bekommen.", "Für diesen Sport gibt es Fußballvereine, deren Mannschaften gegeneinander spielen. Alle vier Jahre richtet der Welt-Verband FIFA eine Fußball-Weltmeisterschaft aus. Da tritt jeweils eine Mannschaft pro Land an. Fußball wird in einigen Ländern mehr von Männern gespielt, in anderen eher von Frauen.", "Die eine Mannschaft versucht, mehr Tore zu schießen als die andere Mannschaft. Jede Mannschaft hat elf Spieler, einer davon ist der Torwart. Ein Spiel dauert normalerweise 90 Minuten lang, das sind zwei Halbzeiten mit jeweils 45 Minuten. Hinzu kommt die Nachspielzeit, wenn es im Spiel Unterbrechungen durch Verletzungen gab.", "Neben den Spielern hat der Schiedsrichter eine wichtige Rolle. Er entscheidet darüber, ob ein Tor gezählt wird oder nicht. Außerdem pfeift er das Spiel mit seiner Pfeife an und ab, und er kann es auch unterbrechen, wenn jemand unfair spielt. Dann bekommt die andere Mannschaft den Ball.", "Gespielt werden darf der Ball mit dem ganzen Körper, nur nicht mit den Armen und Händen. Trotzdem wird Fußball vor allem mit dem Fuß gespielt. Fußball ist der beliebteste Mannschaftssport der Welt, vielleicht sogar die beliebteste Sportart überhaupt.", "Auch viele Kinder spielen gerne Fußball, manche im Verein. Bei ihnen dauern die Halbzeiten nicht so lang. Zudem sind bei den Jüngeren der Platz und die Tore kleiner. Die G-Jugend nennt man auch U7-Jugend, das sind Kinder unter sieben Jahren. Dann geht es weiter bis zur A-Jugend, das sind alle, die unter 19 Jahre alt sind. Das U steht für „unter“."], "zh": ["足球是两支球队用一个球比赛的运动，是世界上最受欢迎的运动之一。足球最早来自英国。随着时间推移，足球有了今天的规则。", "这项运动有足球俱乐部，俱乐部的球队互相比赛。世界足球联合会国际足联每四年举办一届世界杯，每个国家派一支球队参赛。在有些国家踢足球的男性多，在别的国家则女性多。", "一支球队要设法比另一支进更多球。每队有十一名球员，其中一名是守门员。一场比赛一般 90 分钟，分两个半场，各 45 分钟。如果比赛中因受伤中断过，还要加上补时。", "除了球员，裁判也很重要。他决定进球算不算。此外他用哨子吹响比赛开始和结束，有人犯规时也可以中断比赛，这时球归另一队。", "除了手臂和手，身体任何部位都可以碰球。尽管如此，足球主要还是用脚踢。足球是世界上最受欢迎的团体运动，也许甚至是最受欢迎的运动。", "很多孩子也喜欢踢足球，有的在俱乐部踢。他们的半场没那么长。此外年纪小的孩子场地和球门也更小。G 青年组也叫 U7 组，是七岁以下的孩子。然后一直到 A 青年组，就是所有不满 19 岁的人。U 代表 unter（以下）。"], "lemmas": [], "gloss": [{"w": "Mannschaften", "de": "Gruppen von Spielern, Teams", "zh": "球队"}, {"w": "Weltmeisterschaft", "de": "Wettkampf, bei dem man den Besten der Welt sucht", "zh": "世界杯"}, {"w": "Torwart", "de": "Spieler, der das Tor schützt", "zh": "守门员"}, {"w": "Halbzeiten", "de": "die zwei Hälften eines Spiels", "zh": "半场"}, {"w": "Schiedsrichter", "de": "jemand, der auf die Regeln achtet", "zh": "裁判"}, {"w": "unterbrechen", "de": "kurz stoppen", "zh": "中断"}], "qs": [{"q": "Wie viele Spieler hat eine Fußballmannschaft?", "qZh": "一支足球队有几名球员？", "answer": "Elf.", "wrong": ["Fünf.", "Sieben."]}, {"q": "Was macht der Schiedsrichter?", "qZh": "裁判做什么？", "answer": "Er entscheidet, ob ein Tor zählt, und pfeift das Spiel an und ab.", "wrong": ["Er schießt die Tore.", "Er verkauft Karten."]}, {"q": "Womit darf man den Ball nicht spielen?", "qZh": "不能用什么碰球？", "answer": "Mit den Armen und Händen.", "wrong": ["Mit dem Kopf.", "Mit dem Fuß."]}], "src": "改编自 Klexikon《Fußball》", "url": "https://klexikon.zum.de/index.php?oldid=160960", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-045", "seg": 10, "title": "Basketball", "de": ["Basketball ist ein Ballspiel, das in Mannschaften gespielt wird. Erfunden hat man es in den Jahren nach 1890 in den USA. Beim Spiel geht es darum, einen Ball in einen Ring aus Eisen zu werfen. Je nach dem, wie weit der Werfer vom Ring entfernt war, bekommt seine Mannschaft zwei oder drei Punkte. Am Ende geht es darum, welche Mannschaft mehr Punkte hat.", "Am Anfang spielte man tatsächlich mit einem Korb: Genau das bedeutet das englische Wort „basket“. Bald darauf hat man unten in den Korb ein großes Loch geschnitten, damit man den Ball nicht immer erst wieder herausholen musste. Das wurde dann zu einem Ring, an dem ein Netz hängt.", "Außerdem war der Korb zunächst an einer Wand angebracht. Man wollte aber, dass die Spieler sich nicht daran abstützen können, und dass mehr Platz unter dem Korb ist. Darum hängt der Korb heute an einem großen Brett, das von einer Wand weit genug entfernt sein muss. Jede Mannschaft hat auf ihrer Seite des Feldes einen Korb, den sie beschützen muss. Das ist ähnlich wie beim Fußball mit den Toren, nur eben mit Körben und ohne Torhüter.", "Eine Mannschaft hat fünf Spieler. Bei den wichtigen Wettkämpfen mit Mannschaften, die Basketball als Beruf spielen, gibt es bestimmte Regeln. Je nach Wettkampf können sie etwas anders sein. Besonders ist, dass man den Ball nicht einfach unter den Arm nehmen und loslaufen darf. Man muss den Ball stets auf den Boden auftupfen lassen oder ihn zu einem Mitspieler werfen.", "Die Mannschaft hat noch sieben weitere Spieler zum Auswechseln. Man spielt viermal 10 Minuten, und es gibt Auszeiten. Die Spieler müssen also nicht so lange aushalten wie ein Fußballspieler, sondern können mit aller Energie spielen, auch da im Basketball häufiger ausgewechselt wird. Außerdem muss eine Mannschaft, die gerade den Ball hat, nach 24 Sekunden auf den Korb geworfen haben. Das alles macht das Basketballspiel sehr schnell und spannend."], "zh": ["篮球是分队进行的球类运动，1890 年后的几年里在美国发明。比赛要把球投进一个铁圈。根据投篮的人离篮圈多远，他的球队得两分或三分。最后看哪个队得分多。", "一开始真的是用篮子打：英语 basket 正是这个意思。不久人们在篮子底部剪了个大洞，这样就不用每次先把球拿出来。后来它变成了挂着网的圈。", "此外篮子起初装在墙上。但人们不想让球员能扶着墙，也想让篮下有更多空间。所以今天篮筐挂在一块大板上，这块板必须离墙足够远。每个队在自己那半场有一个篮筐要防守。这有点像足球的球门，只不过换成了篮筐，也没有守门员。", "一个队有五名球员。在职业球队参加的重要比赛中有一定的规则，不同比赛可能略有不同。特别的是，不能把球夹在胳膊下就跑。必须一直拍球让它弹地，或者把球传给队友。", "每队还有七名替补队员。比赛分四节，每节 10 分钟，还有暂停。所以球员不必像足球运动员那样坚持那么久，可以全力以赴，也因为篮球换人更频繁。此外持球的一队必须在 24 秒内投篮。这一切让篮球比赛又快又紧张。"], "lemmas": [], "gloss": [{"w": "Korb", "de": "Behälter aus geflochtenem Material", "zh": "篮子"}, {"w": "abstützen", "de": "sich auf etwas lehnen, um nicht zu fallen", "zh": "扶、撑"}, {"w": "beschützen", "de": "aufpassen, dass nichts passiert", "zh": "保护"}, {"w": "auftupfen", "de": "kurz auf den Boden springen lassen", "zh": "拍（球）"}, {"w": "Auswechseln", "de": "einen Spieler durch einen anderen ersetzen", "zh": "换人"}, {"w": "aushalten", "de": "durchhalten, nicht aufgeben", "zh": "坚持"}], "qs": [{"q": "Wie viele Punkte bekommt man für einen Korb?", "qZh": "投进一个球得几分？", "answer": "Zwei oder drei, je nach Entfernung.", "wrong": ["Immer einen.", "Zehn."]}, {"q": "Was bedeutet das englische Wort „basket“?", "qZh": "英语 basket 是什么意思？", "answer": "Korb.", "wrong": ["Ball.", "Netz."]}, {"q": "Was darf man beim Basketball nicht?", "qZh": "打篮球时不能做什么？", "answer": "Mit dem Ball unter dem Arm loslaufen.", "wrong": ["Den Ball werfen.", "Den Ball auf den Boden tupfen."]}], "src": "改编自 Klexikon《Basketball》", "url": "https://klexikon.zum.de/index.php?oldid=156694", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-046", "seg": 10, "title": "Brettspiel", "de": ["Ein Brettspiel ist ein Spiel, das auf einem flachen Brett gespielt wird. Meistens gibt es dabei Spielfiguren, Würfel, Karten und viele bunte Felder. Man spielt Brettspiele oft zusammen mit Freunden oder der Familie. Ziel ist es, Spaß zu haben und vielleicht auch etwas zu lernen. Brettspiele sind Gesellschaftsspiele, genau wie auch Kartenspiele.", "Ein Beispiel für ein Brettspiel ist „Mensch ärger Dich nicht“. Dabei versucht man, seine Figuren ins Ziel zu bringen, ohne dass sie von anderen Mitspielern herausgeworfen werden. Ein anderes bekanntes Spiel ist „Monopoly“, bei dem man Grundstücke kauft und versucht, möglichst viel Geld zu verdienen.", "Brettspiele sollen Spaß machen. Man kann mit anderen Menschen die Zeit verbringen. Weil man bei vielen Spielen gut nachdenken muss, trainieren sie das Gehirn. Das ist zum Beispiel gut für ältere Leute, die nicht mehr so einfach draußen Dinge erleben können.", "Kinder können durch Brettspiele und andere Spiele lernen, sich an Regeln zu halten. Sie dürfen nicht einfach etwas machen, sondern müssen warten, bis sie an die Reihe kommen. Sie merken, dass es keinen Spaß macht, wenn jemand sich nicht an die Regeln hält.", "Je nach Spiel müssen die Spieler miteinander reden und zusammenarbeiten. Nur dann können sie das Spiel gewinnen. Sie trainieren ihr Gedächtnis und lernen Probleme zu lösen. Das hilft auch sonst im Leben oder später im Beruf.", "Für viele Kinder ist es nicht einfach, geduldig still zu sitzen und sich auf eine Sache zu konzentrieren. Für ein Brettspiel ist aber genau das wichtig. Nicht zuletzt lernen Kinder mit Gefühlen umzugehen, zum Beispiel mit Frust, wenn man verliert."], "zh": ["棋盘游戏是在一块平板上玩的游戏。大多有棋子、骰子、卡片和许多彩色格子。人们常和朋友或家人一起玩。目的是玩得开心，也许还能学到点东西。棋盘游戏和纸牌游戏一样，都是聚会游戏。", "「别生气」就是一种棋盘游戏。玩的时候要把自己的棋子走到终点，不被别的玩家踢出去。另一个有名的游戏是「大富翁」，在游戏里买地，尽量多挣钱。", "棋盘游戏应该让人开心，可以和别人一起度过时光。因为很多游戏要好好动脑，所以能锻炼大脑。这比如对不太容易出门体验事物的老年人有好处。", "孩子通过棋盘游戏和别的游戏能学会遵守规则。他们不能想做什么就做什么，而要等轮到自己。他们会发现，有人不守规则就不好玩了。", "根据游戏不同，玩家要互相交流、合作，只有这样才能赢。他们锻炼记忆力，学会解决问题。这对日常生活或以后工作也有帮助。", "对很多孩子来说，耐心地静坐、专注于一件事并不容易。而玩棋盘游戏正需要这一点。最后，孩子还能学会处理情绪，比如输了时的沮丧。"], "lemmas": [], "gloss": [{"w": "Würfel", "de": "kleines Ding mit sechs Seiten und Punkten", "zh": "骰子"}, {"w": "Gesellschaftsspiele", "de": "Spiele, die man mit anderen zusammen spielt", "zh": "聚会游戏"}, {"w": "Grundstücke", "de": "Stücke Land", "zh": "地块"}, {"w": "an die Reihe", "de": "dran, als Nächster", "zh": "轮到"}, {"w": "Gedächtnis", "de": "die Fähigkeit, sich an etwas zu erinnern", "zh": "记忆力"}, {"w": "Frust", "de": "Ärger, wenn etwas nicht klappt", "zh": "沮丧"}], "qs": [{"q": "Was macht man bei „Monopoly“?", "qZh": "「大富翁」里做什么？", "answer": "Man kauft Grundstücke und versucht, viel Geld zu verdienen.", "wrong": ["Man bringt Figuren ins Ziel.", "Man baut Häuser aus Holz."]}, {"q": "Was lernen Kinder durch Brettspiele?", "qZh": "孩子通过棋盘游戏学会什么？", "answer": "Sich an Regeln zu halten und zu warten.", "wrong": ["Schnell zu laufen.", "Am Computer zu arbeiten."]}, {"q": "Warum sind Brettspiele gut für ältere Leute?", "qZh": "棋盘游戏为什么对老年人有好处？", "answer": "Sie trainieren das Gehirn.", "wrong": ["Sie machen sie schneller.", "Sie kosten nichts."]}], "src": "改编自 Klexikon《Brettspiel》", "url": "https://klexikon.zum.de/index.php?oldid=164620", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-047", "seg": 10, "title": "Museum", "de": ["In einem Museum werden verschiedene Dinge gesammelt und gezeigt. Die Mehrzahl heißt: Museen. Es sind besondere Sachen, die man woanders wahrscheinlich nicht sehen würde. Meistens dürfen die Besucher sich diese Dinge nur ansehen. Nur in wenigen Museen ist es erlaubt, sie auch anzufassen.", "In einem Museum arbeiten Menschen, die diese Sachen sammeln und sich um sie kümmern. Manche dieser Mitarbeiter erforschen die Sachen und finden heraus, welche Geschichten dahinter stehen. Sie sorgen auch dafür, dass die Sachen gut erhalten bleiben. Andere Mitarbeiter des Museums betreuen die Besucher und erklären ihnen, was es zu sehen gibt. Wenn es keine Museen gäbe, gäbe es oft auch diese besonderen Sachen nicht mehr.", "Die allermeisten Museen sind entweder Geschichtsmuseen, Kunstmuseen oder Naturkundemuseen. Geschichtsmuseen zeigen, was früher passiert ist, wie Menschen früher gelebt haben, was für Sachen sie benutzt haben und so weiter. Kunstmuseen stellen Kunst aus. Kunst sind besonders schöne oder besonders interessante Dinge, oft Gemälde oder Statuen.", "Naturkundemuseen oder naturgeschichtliche Museen zeigen Dinge aus der Natur: Tiere, Pflanzen und Landschaften. Normalerweise leben die Tiere nicht mehr, sondern sind ausgestopft. Landschaften zeigt man meist mit Fotos. Vor allem zeigen diese Museen, wie die Natur früher ausgesehen hat. Dazu gehören dann zum Beispiel Knochen von Tieren, die es heute nicht mehr gibt. In einem Science Center werden nicht so sehr alte Dinge ausgestellt: Mit allerlei Geräten zeigt man, wie etwas in der Natur oder Technik funktioniert.", "Manche Museen sind für ganz bestimmte Dinge da. Bei uns gibt es ein Museum für Bilderbücher, ein Buchstabenmuseum, ein Luftmuseum, ein Schokoladenmuseum, ein Bananenmuseum, ein Museum über Schweine und ein anderes über Katzen, ein Hundehalsbandmuseum in Großbritannien und in Indien sogar ein Toilettenmuseum."], "zh": ["博物馆收集并展示各种东西。复数是 Museen。那是些别处可能看不到的特别物品。参观者大多只能看，只有少数博物馆允许触摸。", "博物馆里有人收集并照管这些东西。有些工作人员研究这些物品，弄清它们背后的故事。他们也负责让物品保存完好。另一些工作人员接待参观者，给他们讲解能看到什么。如果没有博物馆，这些特别的东西常常就不复存在了。", "绝大多数博物馆要么是历史博物馆，要么是艺术博物馆，要么是自然博物馆。历史博物馆展示过去发生的事、人们以前怎样生活、用过什么东西等等。艺术博物馆展出艺术品。艺术品是特别美或特别有意思的东西，常常是油画或雕像。", "自然博物馆展示自然中的东西：动物、植物和风景。动物一般已经不是活的，而是做成了标本。风景大多用照片展示。这些博物馆主要展示自然以前是什么样子，比如今天已经不存在的动物的骨头。科学中心展出的则不是那么多老东西：它用各种仪器展示自然或技术中某样东西怎样运作。", "有些博物馆专门展示某种东西。我们这儿有图画书博物馆、字母博物馆、空气博物馆、巧克力博物馆、香蕉博物馆、猪博物馆和猫博物馆，英国有狗项圈博物馆，印度甚至有厕所博物馆。"], "lemmas": [], "gloss": [{"w": "anzufassen", "de": "mit der Hand zu berühren", "zh": "触摸"}, {"w": "erforschen", "de": "genau untersuchen", "zh": "研究"}, {"w": "erhalten", "de": "so bleiben, nicht kaputtgehen", "zh": "保存"}, {"w": "betreuen", "de": "sich um jemanden kümmern", "zh": "照顾、接待"}, {"w": "Gemälde", "de": "gemaltes Bild", "zh": "油画"}, {"w": "ausgestopft", "de": "tot, aber so gemacht, dass es echt aussieht", "zh": "制成标本的"}], "qs": [{"q": "Was dürfen Besucher in den meisten Museen nicht?", "qZh": "大多数博物馆里参观者不能做什么？", "answer": "Die Dinge anfassen.", "wrong": ["Die Dinge ansehen.", "Fragen stellen."]}, {"q": "Was zeigt ein Geschichtsmuseum?", "qZh": "历史博物馆展示什么？", "answer": "Wie die Menschen früher gelebt haben.", "wrong": ["Lebende Tiere.", "Neue Autos."]}, {"q": "Welches Museum gibt es in Indien?", "qZh": "印度有什么博物馆？", "answer": "Ein Toilettenmuseum.", "wrong": ["Ein Bananenmuseum.", "Ein Hundehalsbandmuseum."]}], "src": "改编自 Klexikon《Museum》", "url": "https://klexikon.zum.de/index.php?oldid=162674", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-048", "seg": 10, "title": "Bibliothek", "de": ["Eine Bibliothek oder Bücherei ist eine Sammlung von sehr vielen Büchern. Das Wort Bibliothek stammt aus der griechischen Sprache und bedeutet so viel wie „Buch-Behälter“. Heute sind in einer Bibliothek meistens auch andere Medien zu finden.", "Damit man die Bücher und die anderen Medien nutzen kann, muss man meist einen bestimmten Betrag im Monat oder im Jahr bezahlen. Mit seinem Benutzerausweis darf man dann eine bestimmte Anzahl an Medien ausleihen und mit nach Hause nehmen. Man kann die Zeit, in der man sie nutzen darf, die Ausleihzeit, verlängern. Allerdings hängt das davon ab, ob auch andere Menschen das Buch lesen möchten.", "Eine Bibliothek hat normalerweise einen Freihandbereich und ein Magazin. In den Freihandbereich darf jeder gehen und sich Bücher aus den Regalen holen. Im Magazin stehen die Bücher, die selten gewünscht werden. Mitarbeiter der Bibliothek dürfen dorthin und bestellte Bücher holen. Wenn das gewünschte Buch nicht in der eigenen Bücherei vorhanden ist, kann man es sich aus der Bibliothek einer anderen Stadt bringen lassen. Das nennt man eine Fernleihe.", "Wenn man Bücher nicht ausleihen kann oder möchte, kann man sie in der Bibliothek in einem Lesesaal lesen. Dort sitzen die Leser an Tischen, können in den Büchern blättern und den Computer fürs Schreiben benutzen. Um andere nicht zu stören, darf in Lesesälen meist nur leise gesprochen werden.", "Manche Bibliotheken haben auch einen eigenen Bereich für Kinder. Dort muss man nicht immer leise sein. Es gibt oft gemütliche Sessel, Kissen oder Matten, wo man es sich zum Lesen bequem machen oder auch mit anderen gemeinsam lesen kann.", "Bei einer Bibliothek denkt man vor allem an Bücher. Doch in den Lesesälen stehen meist auch Ständer mit Zeitungen und Zeitschriften. Darin findet man neue Informationen, die meist noch nicht in Büchern stehen."], "zh": ["图书馆或图书室是收藏很多很多书的地方。Bibliothek 这个词来自希腊语，意思差不多是「装书的容器」。今天图书馆里大多也有别的媒体。", "要使用书和其他媒体，大多要每月或每年付一笔钱。有了借书证，就能借一定数量的媒体带回家。可以延长使用时间，也就是借期，但这要看是不是别人也想读这本书。", "图书馆一般有开架区和书库。开架区谁都能进，可以自己从书架上取书。书库里放着很少有人要的书，图书馆员工可以进去取预订的书。要是自己的图书馆没有想要的书，可以从别的城市的图书馆调来，这叫馆际互借。", "不能或不想借书的话，可以在图书馆的阅览室里读。读者坐在桌前，可以翻书，也可以用电脑写东西。为了不打扰别人，阅览室里大多只能小声说话。", "有些图书馆还有专门的儿童区，那里不一定要保持安静。常常有舒适的扶手椅、靠垫或垫子，可以舒舒服服地看书，也可以和别人一起读。", "说到图书馆，人们主要想到书。但阅览室里大多也有放报纸和杂志的架子。在那里能找到大多还没写进书里的新信息。"], "lemmas": [], "gloss": [{"w": "Benutzerausweis", "de": "Karte, mit der man die Bibliothek benutzen darf", "zh": "借书证"}, {"w": "ausleihen", "de": "für kurze Zeit mitnehmen", "zh": "借"}, {"w": "verlängern", "de": "länger machen", "zh": "延长"}, {"w": "Regalen", "de": "Möbeln mit Brettern für Bücher", "zh": "书架"}, {"w": "Fernleihe", "de": "Ausleihen aus einer Bibliothek in einer anderen Stadt", "zh": "馆际互借"}, {"w": "blättern", "de": "die Seiten umdrehen", "zh": "翻（书）"}], "qs": [{"q": "Was bedeutet das griechische Wort „Bibliothek“?", "qZh": "希腊语 Bibliothek 是什么意思？", "answer": "Buch-Behälter.", "wrong": ["Lesesaal.", "Zeitung."]}, {"q": "Was ist eine Fernleihe?", "qZh": "馆际互借是什么？", "answer": "Man lässt sich ein Buch aus einer anderen Stadt bringen.", "wrong": ["Man liest ein Buch im Internet.", "Man kauft ein Buch."]}, {"q": "Wie muss man sich im Lesesaal verhalten?", "qZh": "在阅览室里该怎样？", "answer": "Man darf meist nur leise sprechen.", "wrong": ["Man darf laut Musik hören.", "Man muss stehen."]}], "src": "改编自 Klexikon《Bibliothek》", "url": "https://klexikon.zum.de/index.php?oldid=154259", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-049", "seg": 10, "title": "Theater", "de": ["Ein Theater ist ein Ort, an dem eine Geschichte gespielt wird, ein Schauspiel oder Theaterstück. In manchen Theatern zeigt man auch Opern oder Musicals. Theater gab es schon im Altertum. Manchmal nennt man aber auch das Theaterstück selber abgekürzt einfach Theater.", "Am wichtigsten ist beim Theater die Bühne. Dieser Platz liegt meistens etwas höher, damit die Zuschauer gut sehen können, was dort gezeigt wird. Die meisten Theater haben Sitzplätze für die Zuschauer. Manche Theater sind im Freien, die Bühne oder die Zuschauerplätze sind unter freiem Himmel. Meistens denkt man beim Theater aber an ein Gebäude.", "Auf der Bühne spielen die Schauspieler oder andere Künstler. Kulissen nennt man einen Hintergrund, der so aussieht, als wenn man an einem bestimmten Ort wäre. So können die Kulissen so aussehen, als wenn das Stück im Wald spielen würde. Heute haben die Theater viel Technik, damit sie die Kulissen schnell wechseln können.", "Wichtig ist nicht nur der Bühnenbildner, der die Kulissen und anderes baut. Ein Kostümbildner sorgt dafür, dass die Schauspieler das Richtige zum Anziehen haben für ihre Rolle. Maskenbildner schminken die Schauspieler. Noch viele weitere Leute arbeiten mit, damit das Theaterstück gut aussieht. Am bekanntesten ist oft der Regisseur, der mit den Schauspielern das Stück geübt hat.", "Viele Menschen mögen Theaterstücke. Einige Autoren, die Theaterstücke geschrieben haben, sind auch nach Jahrhunderten noch berühmt. William Shakespeare kennt man vor allem für die Werke „Hamlet“ sowie „Romeo und Julia“. Molière schrieb in der Zeit des Absolutismus viele Komödien, also lustige Theaterstücke. Aber auch einige deutsche Stücke sind sehr bekannt, zum Beispiel „Wilhelm Tell“ von Friedrich Schiller. Daraus wurde eine wichtige Geschichte für die Schweiz als Nation."], "zh": ["剧院是上演故事、话剧或戏剧的地方。有些剧院也演歌剧或音乐剧。古代就已经有剧院了。不过有时人们也把戏剧本身简称为 Theater。", "剧院里最重要的是舞台。这个地方大多高一点，好让观众看清台上演什么。大多数剧院为观众设有座位。有些剧院在露天，舞台或观众席在开阔的天空下。但说到剧院，人们大多想到一栋建筑。", "舞台上表演的是演员或别的艺术家。布景是一种背景，让人看起来好像身处某个地方。比如布景可以看起来像戏是在森林里演的。今天的剧院有很多技术设备，可以快速更换布景。", "重要的不只是制作布景等东西的舞台美术师。服装设计师负责让演员穿上适合角色的衣服。化妆师给演员化妆。还有很多人参与，好让戏看起来好看。最有名的常常是和演员一起排练的导演。", "很多人喜欢戏剧。有些写过戏剧的作家几百年后仍然有名。人们知道威廉·莎士比亚主要是因为《哈姆雷特》和《罗密欧与朱丽叶》。莫里哀在专制主义时代写了很多喜剧，也就是好笑的戏。也有些德语戏剧很有名，比如弗里德里希·席勒的《威廉·退尔》，它成了瑞士作为一个民族的重要故事。"], "lemmas": [], "gloss": [{"w": "Bühne", "de": "erhöhter Platz, auf dem gespielt wird", "zh": "舞台"}, {"w": "unter freiem Himmel", "de": "draußen, ohne Dach", "zh": "露天"}, {"w": "Kulissen", "de": "Hintergrund auf der Bühne", "zh": "布景"}, {"w": "schminken", "de": "Farbe ins Gesicht machen", "zh": "化妆"}, {"w": "Regisseur", "de": "jemand, der ein Stück oder einen Film leitet", "zh": "导演"}, {"w": "Komödien", "de": "lustige Stücke", "zh": "喜剧"}], "qs": [{"q": "Warum liegt die Bühne meist etwas höher?", "qZh": "舞台为什么大多高一点？", "answer": "Damit die Zuschauer gut sehen können.", "wrong": ["Damit es nicht regnet.", "Damit die Schauspieler nicht weglaufen."]}, {"q": "Was macht ein Maskenbildner?", "qZh": "化妆师做什么？", "answer": "Er schminkt die Schauspieler.", "wrong": ["Er baut die Kulissen.", "Er verkauft Karten."]}, {"q": "Wer schrieb „Wilhelm Tell“?", "qZh": "谁写了《威廉·退尔》？", "answer": "Friedrich Schiller.", "wrong": ["William Shakespeare.", "Molière."]}], "src": "改编自 Klexikon《Theater》", "url": "https://klexikon.zum.de/index.php?oldid=154689", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-10-050", "seg": 10, "title": "Tennis", "de": ["Tennis ist ein Ballspiel, das von zwei oder vier Spielern gespielt wird. Erfunden hat man ein ähnliches Spiel schon im Mittelalter in französischen Klöstern. Das Spiel verbreitete sich in ganz Frankreich und in anderen Ländern. Damals spielte man es noch mit der Hand oder einem Handschuh. Schläger werden erst im Jahre 1495 erwähnt.", "Ein Tennisplatz hat zwei Hälften, die durch ein Netz getrennt werden. Ein Spieler muss den Ball über das Netz in die andere Hälfte schlagen. Dort steht der andere Spieler, der den Ball wieder zurück in die andere Hälfte schlägt. Ein Platz hat einen Boden aus Gras, Sand, Ton oder eine Art Plastik.", "Ähnlich wie Golf nennt man Tennis einen „weißen“ Sport. Das liegt nicht nur daran, dass die Spieler meist weiße Kleidung anhaben. Gemeint ist: Der Sport ist eher etwas für reiche Leute, die sich viel Platz für nur zwei Spieler leisten können.", "Die besten Tennisspieler der Welt sind Profis. Sie verdienen mit dem Sport viel Geld und reisen von einem Tennisturnier zum nächsten. Viermal im Jahr spielen die besten Frauen und Männer an einem sogenannten Grand-Slam-Turnier, das jeweils zwei Wochen lang dauert. Das älteste und wichtigste dieser Turniere ist in Wimbledon, einem Stadtteil von London. Tennis ist alle vier Jahre auch eine Sportart bei den Olympischen Sommerspielen."], "zh": ["网球是由两名或四名选手进行的球类运动。中世纪时，法国的修道院里就发明了一种类似的游戏。这种游戏传遍了整个法国和别的国家。当时还用手或手套打。球拍直到 1495 年才第一次被提到。", "网球场分为两半，中间用网隔开。一名选手要把球打过网到另一半场。那边站着另一名选手，他再把球打回对面。球场的地面是草地、沙土、红土或一种塑料。", "和高尔夫一样，网球被称为「白色」运动。这不只是因为选手大多穿白衣服。意思是：这项运动更像是有钱人的运动，他们负担得起只供两个人用的大场地。", "世界上最好的网球选手是职业选手。他们靠这项运动挣很多钱，从一个网球赛事赶到下一个。每年四次，最好的女选手和男选手参加所谓的大满贯赛事，每次持续两周。其中最古老、最重要的赛事在伦敦的一个城区温布尔登。网球每四年也是夏季奥运会的一个项目。"], "lemmas": [], "gloss": [{"w": "Klöstern", "de": "Häusern, in denen Mönche oder Nonnen leben", "zh": "修道院"}, {"w": "Schläger", "de": "Gerät, mit dem man den Ball schlägt", "zh": "球拍"}, {"w": "erwähnt", "de": "kurz genannt", "zh": "提到"}, {"w": "getrennt", "de": "voneinander geteilt", "zh": "隔开"}, {"w": "Profis", "de": "Menschen, die etwas als Beruf machen", "zh": "职业选手"}, {"w": "Turnier", "de": "Wettkampf mit vielen Spielen", "zh": "赛事"}], "qs": [{"q": "Wo hat man ein ähnliches Spiel im Mittelalter erfunden?", "qZh": "中世纪时类似的游戏是在哪里发明的？", "answer": "In französischen Klöstern.", "wrong": ["In englischen Schulen.", "In Wimbledon."]}, {"q": "Warum nennt man Tennis einen „weißen“ Sport?", "qZh": "为什么说网球是「白色」运动？", "answer": "Er ist eher etwas für reiche Leute.", "wrong": ["Der Ball ist immer weiß.", "Man spielt nur im Winter."]}, {"q": "Wo findet das älteste Grand-Slam-Turnier statt?", "qZh": "最古老的大满贯赛在哪里？", "answer": "In Wimbledon in London.", "wrong": ["In Paris.", "In New York."]}], "src": "改编自 Klexikon《Tennis》", "url": "https://klexikon.zum.de/index.php?oldid=158269", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-001", "seg": 11, "title": "Wetter", "de": ["Das Wetter ist der Zustand am Himmel. Um die Erde ist eine Lufthülle, die Atmosphäre. Mit Wetter ist gemeint, wie es in dieser Lufthülle zugeht, und zwar an einem bestimmten Ort und zu einer bestimmten Zeit. Das Klima hingegen besagt, ob es an einem Ort normalerweise eher warm oder eher kalt ist, im Durchschnitt vieler Jahre.", "Zum Wetter gehören Wind, Stürme, Regen, Schnee und manches mehr. Das alles kommt durch die Sonne zustande. Die Hitze der Sonne über dem Meer sorgt dafür, dass Wasser verdunstet und die Feuchtigkeit in die Luft aufsteigt. Daraus werden später Wolken. Wind entsteht dadurch, dass es an manchen Stellen wärmere Luft gibt als woanders.", "Spricht jemand von gutem Wetter, denkt man meist an Sonnenschein. Für Bauern zum Beispiel ist es aber wichtig, dass das Wetter sich ändert. In der Landwirtschaft braucht man sowohl Sonnenschein als auch Regen, damit die Pflanzen genug Wasser bekommen.", "Weil das Wetter für viele Menschen wichtig ist, wollten sie es schon immer vorhersagen. Heute macht das eine eigene Wissenschaft, die Meteorologie. Fast überall auf der Welt stehen Wetterstationen, in denen der Wind, der Regen und anderes gemessen wird. Mit diesem Wissen kann man für die nächsten Tage recht gut ausrechnen, wo es wann zum Beispiel regnen wird. Mit dem Wort Witterung meint man das Wetter in einem Zeitraum in einer bestimmten Gegend."], "zh": ["天气是天空的状态。地球周围有一层空气外壳，叫大气层。天气指的是这层空气里在某个地方、某个时间的情况。而气候说的是一个地方平常偏暖还是偏冷，是很多年的平均情况。", "天气包括风、风暴、雨、雪等等。这一切都是太阳造成的。太阳照在海面上的热量让水蒸发，水汽升到空气里，后来变成云。风的产生是因为有些地方的空气比别处暖。", "有人说天气好，大家大多想到阳光。但比如对农民来说，天气有变化很重要。农业既需要阳光也需要雨水，这样植物才能得到足够的水。", "因为天气对很多人很重要，人们一直想预报天气。今天这由一门专门的科学来做，就是气象学。世界上几乎到处都有气象站，测量风、雨等等。凭这些知识，能把接下来几天哪里什么时候会下雨算得相当准。Witterung 这个词指某个地区一段时间里的天气。"], "lemmas": [], "gloss": [{"w": "Zustand", "de": "wie etwas gerade ist", "zh": "状态"}, {"w": "Durchschnitt", "de": "Mittelwert", "zh": "平均"}, {"w": "verdunstet", "de": "wird zu Dampf und steigt in die Luft", "zh": "蒸发"}, {"w": "Feuchtigkeit", "de": "Wasser in der Luft", "zh": "湿气"}, {"w": "vorhersagen", "de": "sagen, was in der Zukunft passiert", "zh": "预报"}, {"w": "gemessen", "de": "festgestellt, wie viel es ist", "zh": "测量"}], "qs": [{"q": "Was ist der Unterschied zwischen Wetter und Klima?", "qZh": "天气和气候有什么区别？", "answer": "Das Klima ist der Durchschnitt vieler Jahre.", "wrong": ["Das Wetter gilt für viele Jahre.", "Es gibt keinen Unterschied."]}, {"q": "Warum brauchen Bauern Regen?", "qZh": "农民为什么需要雨？", "answer": "Damit die Pflanzen genug Wasser bekommen.", "wrong": ["Damit die Tiere baden können.", "Damit es kälter wird."]}, {"q": "Was macht die Meteorologie?", "qZh": "气象学做什么？", "answer": "Sie sagt das Wetter vorher.", "wrong": ["Sie baut Häuser.", "Sie zählt die Tiere."]}], "src": "改编自 Klexikon《Wetter》", "url": "https://klexikon.zum.de/index.php?oldid=160482", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-002", "seg": 11, "title": "Klima", "de": ["Wenn man vom Klima spricht, ist gemeint, dass es irgendwo normalerweise warm oder kalt ist, dass es trocken oder feucht ist. Das Klima einer Gegend ist so, wie man es über Jahre beobachtet hat. Man denkt also an einen langen Zeitraum. Das Wetter ist etwas Ähnliches, aber vom Wetter spricht man, wenn man an einen Tag oder wenige Wochen denkt. Es geht also beim Wetter um einen kurzen Zeitraum.", "Das Klima hängt stark von der Nähe zum Äquator ab. In seiner Nähe ist es heißer, gegen den Nordpol oder den Südpol hin wird es kälter. Europa liegt etwa in der Mitte. Deshalb haben hier die meisten Länder ein gemäßigtes Klima. Es wird also meistens nicht sehr kalt und nicht sehr warm, außer in vielen Gebieten südlich der Alpen.", "Heiß ist es hingegen in den Gegenden um den Äquator, zum Beispiel in Afrika und in Südamerika. Dieses Gebiet nennt man Tropen. Dort kann es feucht-heiß sein, dort findet man oft Regenwald. Ist es trocken-heiß, findet man Wüste.", "Das Klima kann sich ändern, das dauert aber normalerweise viele Jahre. Auch die Menschen tragen dazu bei, dass das Klima der Welt sich ändert. Dieser Klimawandel kommt dadurch, dass vor allem Fabriken, Autos, Flugzeuge, Heizungen und Vieh Gase ausstoßen, zum Beispiel Kohlenstoffdioxid. Solche Gase sorgen dafür, dass bestimmte Teile der Sonnenstrahlen die Erde stärker erwärmen. Wer sich für den Klimaschutz einsetzt, will etwas dagegen tun.", "In den Tropen gibt es keine Jahreszeiten, weil die Sonne das ganze Jahr über am Mittag fast senkrecht über der Erde steht. Dadurch sind die Tage und Nächte immer gleich lang und es ist sehr heiß. In den meisten Gebieten fällt auch sehr viel Regen, deshalb entsteht Regenwald.", "In den Subtropen ist es im Sommer warm bis heiß und im Winter nicht sehr kalt, zumindest tagsüber. In vielen Gebieten gibt es Wüste. In Europa gehören Italien, Griechenland und Teile Spaniens zu den Subtropen."], "zh": ["说到气候，指的是某个地方平常是暖还是冷、是干还是湿。一个地区的气候是人们多年观察到的样子，所以想的是一段很长的时间。天气和它相似，但说天气时想的是一天或几周，也就是一段很短的时间。", "气候很大程度上取决于离赤道多近。赤道附近更热，往北极或南极去就越来越冷。欧洲大约在中间，所以这里大多数国家是温和气候：一般不会很冷，也不会很热，阿尔卑斯山以南的很多地区除外。", "而赤道周围的地区很热，比如非洲和南美洲，这片地区叫热带。那里可能湿热，常有雨林；如果干热，就是沙漠。", "气候会变，但通常要很多年。人类也促成了世界气候的变化。这种气候变化主要是因为工厂、汽车、飞机、暖气和牲畜排放气体，比如二氧化碳。这些气体会让一部分阳光更强地加热地球。致力于保护气候的人想对此有所作为。", "热带没有四季，因为一年到头中午太阳几乎都垂直照在地面上。所以白天和黑夜一样长，而且很热。大多数地区雨也很多，所以形成了雨林。", "亚热带夏天温暖到炎热，冬天不太冷，至少白天是这样。很多地区有沙漠。欧洲的意大利、希腊和西班牙的部分地区属于亚热带。"], "lemmas": [], "gloss": [{"w": "feucht", "de": "ein bisschen nass", "zh": "潮湿的"}, {"w": "Äquator", "de": "gedachte Linie in der Mitte um die Erde", "zh": "赤道"}, {"w": "gemäßigtes", "de": "nicht zu heiß und nicht zu kalt", "zh": "温和的"}, {"w": "Wüste", "de": "sehr trockenes Gebiet mit viel Sand", "zh": "沙漠"}, {"w": "ausstoßen", "de": "nach draußen geben (Gas, Rauch)", "zh": "排放"}, {"w": "tagsüber", "de": "während des Tages", "zh": "白天"}], "qs": [{"q": "Wovon hängt das Klima stark ab?", "qZh": "气候很大程度上取决于什么？", "answer": "Von der Nähe zum Äquator.", "wrong": ["Von der Größe der Städte.", "Von der Zahl der Autos."]}, {"q": "Wodurch kommt der Klimawandel?", "qZh": "气候变化是怎么来的？", "answer": "Fabriken, Autos und andere stoßen Gase aus.", "wrong": ["Die Sonne wird kleiner.", "Es gibt mehr Wälder."]}, {"q": "Warum gibt es in den Tropen keine Jahreszeiten?", "qZh": "热带为什么没有四季？", "answer": "Die Sonne steht das ganze Jahr fast senkrecht.", "wrong": ["Dort regnet es nie.", "Dort gibt es keine Sonne."]}], "src": "改编自 Klexikon《Klima》", "url": "https://klexikon.zum.de/index.php?oldid=168194", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-003", "seg": 11, "title": "Klimawandel", "de": ["Klimawandel nennt man die gegenwärtige Änderung des Klimas. Im Gegensatz zum Wetter bedeutet Klima, wie warm oder kalt es an einem Ort über längere Zeit ist und welches Wetter dort normalerweise herrscht. Das Klima bleibt eigentlich über lange Zeit gleich, es ändert sich also nicht oder nur sehr langsam.", "Über lange Zeiträume gesehen hat sich das Klima auf der Erde schon mehrmals verändert. So gab es zum Beispiel in der Altsteinzeit eine Eiszeit. Damals war es wesentlich kälter als heute. Diese Klimawandel sind natürlich und haben verschiedene Ursachen. Normalerweise verändert sich das Klima sehr langsam, also über viele Jahrhunderte. Ein einzelner Mensch würde einen solchen Wandel innerhalb seines Lebens nicht bemerken, weil er zu langsam vorangeht.", "Zurzeit erleben wir aber einen Klimawandel, der wesentlich schneller vorangeht, so schnell, dass sich die Temperaturen sogar in der kurzen Zeit eines Menschenlebens verändern. Das Klima auf der ganzen Erde wird nämlich wärmer. Man spricht auch von Klimawechsel, Klimakatastrophe oder globaler Erwärmung. Die Ursache für diesen rasanten Klimawandel ist der Mensch. Wenn man heute den Begriff Klimawandel nennt, dann meint man damit meistens diese Katastrophe.", "Der sogenannte Treibhauseffekt sorgt eigentlich dafür, dass es auf der Erde angenehm warm und nicht eiskalt wie im Weltall ist. Die Atmosphäre, also die Luft, die unseren Planeten umgibt, besteht aus vielen verschiedenen Gasen. Einige davon sind sogenannte Treibhausgase. Das bekannteste davon ist Kohlendioxid, abgekürzt CO2.", "Diese Gase erzeugen auf der Erde einen Effekt, den zum Beispiel Gärtner in ihren Treibhäusern oder Gewächshäusern nutzen. Diese „Häuser“ aus Glas lassen nämlich das ganze Sonnenlicht hinein, aber die Wärme nur zum Teil wieder hinaus. Das Glas sorgt dafür. Steht ein Auto längere Zeit in der Sonne, so kann man dasselbe beobachten: es wird unerträglich heiß im Auto.", "In der Atmosphäre übernehmen die Treibhausgase die Rolle des Glases. Die meisten Sonnenstrahlen gelangen durch die Atmosphäre zum Erdboden. Dadurch erwärmen sie den Erdboden. Der Erdboden gibt diese Wärme allerdings auch wieder ab. Die Treibhausgase sorgen dafür, dass nicht die ganze Wärme zurück ins Weltall entweicht. Dadurch erwärmt sich die Erde. Dies ist der natürliche Treibhauseffekt. Er ist sehr wichtig, denn ohne ihn gäbe es kein so angenehmes Klima auf der Erde."], "zh": ["气候变化指的是当前气候的改变。和天气不同，气候指一个地方长时间里有多暖或多冷，平常是什么天气。气候本来长时间保持不变，也就是不变或者变得很慢。", "从很长的时间看，地球上的气候已经变过好几次。比如旧石器时代有过冰期，那时比今天冷得多。这些气候变化是自然的，原因各不相同。一般气候变化很慢，要经过好几个世纪。一个人一生中察觉不到这样的变化，因为它进展太慢。", "但现在我们经历的气候变化快得多，快到在一个人一生这么短的时间里气温都在变。因为整个地球的气候正在变暖。人们也说气候更替、气候灾难或全球变暖。这种急剧气候变化的原因是人类。今天说到气候变化，大多指的就是这场灾难。", "所谓的温室效应本来让地球温暖宜人，而不像太空那样冰冷。大气层，也就是包围我们星球的空气，由许多不同气体组成，其中一些是所谓的温室气体。最有名的是二氧化碳，简写 CO2。", "这些气体在地球上产生一种效应，比如园丁在温室或暖房里就利用这种效应。这种玻璃「房子」让所有阳光照进来，但热量只能部分散出去，这是玻璃的作用。汽车在太阳下停久了也能看到同样的现象：车里热得受不了。", "在大气层中，温室气体扮演玻璃的角色。大部分阳光穿过大气到达地面，让地面变暖。不过地面也会把这些热量散发出去。温室气体让热量不会全部逃回太空，于是地球变暖。这就是自然的温室效应。它非常重要，因为没有它，地球上就没有这么宜人的气候。"], "lemmas": [], "gloss": [{"w": "gegenwärtige", "de": "die jetzt gerade ist", "zh": "当前的"}, {"w": "Ursachen", "de": "Gründe, warum etwas passiert", "zh": "原因"}, {"w": "rasanten", "de": "sehr schnellen", "zh": "急剧的"}, {"w": "Treibhauseffekt", "de": "Wärme wird wie in einem Glashaus festgehalten", "zh": "温室效应"}, {"w": "unerträglich", "de": "so schlimm, dass man es nicht aushalten kann", "zh": "受不了的"}, {"w": "entweicht", "de": "geht hinaus, ohne dass man es will", "zh": "逃逸"}], "qs": [{"q": "Was ist anders am heutigen Klimawandel?", "qZh": "今天的气候变化有什么不同？", "answer": "Er geht viel schneller und kommt vom Menschen.", "wrong": ["Er geht sehr langsam.", "Es wird kälter."]}, {"q": "Was ist das bekannteste Treibhausgas?", "qZh": "最有名的温室气体是什么？", "answer": "Kohlendioxid.", "wrong": ["Sauerstoff.", "Wasserdampf aus dem Auto."]}, {"q": "Warum ist der natürliche Treibhauseffekt wichtig?", "qZh": "自然的温室效应为什么重要？", "answer": "Ohne ihn wäre es auf der Erde nicht so angenehm warm.", "wrong": ["Er macht die Luft sauber.", "Er bringt Regen."]}], "src": "改编自 Klexikon《Klimawandel》", "url": "https://klexikon.zum.de/index.php?oldid=170363", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-004", "seg": 11, "title": "Umwelt", "de": ["Mit dem Wort Umwelt meint man zunächst die Umgebung, also alles was um einen herum ist. Umwelt ist aber mehr als das. Alle Lebewesen sind von ihrer Umwelt abhängig und umgekehrt. Die Umwelt verändert die Lebewesen und die Lebewesen verändern ihre Umwelt. Umwelt und Lebewesen haben viel miteinander zu tun. Heute meint man deshalb mit dem Wort Umwelt oft die gesamte Natur.", "Den Ausdruck „Umwelt“ gibt es erst seit etwa 200 Jahren. Richtig wichtig wurde er aber erst in den Jahren nach 1960. Da stellten manche Leute nämlich fest, dass die Menschen einen schlechten Einfluss auf die Umwelt ausüben. Vor allem verschmutzten sie die Umwelt: Abgase aus Autos und Heizungen verpesteten die Luft. Toilettenspülungen und Abwässer von Fabriken verdreckten die Flüsse, Seen und Meere. Immer mehr Menschen wollten das nicht und haben mit dem Umweltschutz begonnen.", "Heute spricht man auch oft von „Nachhaltigkeit“. Das bedeutet, dass man alles so tun sollte, dass es ewig so weitergehen könnte. In der Natur ist das so: Es gibt zum Beispiel den Wasserkreislauf, der nie aufhört. Tiere fressen Pflanzen. Ihr Kot ist Dünger für den Erdboden. So wachsen neue Pflanzen. Das kann ewig so weitergehen. Derzeit brauchen wir Menschen aber viel mehr Erdöl, Erdgas und andere Bodenschätze, als sie sich neu bilden können. Irgendwann werden also keine mehr da sein. Und vor allem verschmutzen wir mit diesem übermäßigen Verbrauch unsere Umwelt. Das ist nicht nachhaltig, also nicht umweltgerecht.", "Seit den Jahren nach 1970 begannen auch die Schulen, mehr über die Umwelt zu sprechen. Sie wollen den Kindern auch beibringen, wie sie sich umweltgerecht verhalten sollten. Fächer wie Naturkunde, Geografie und Geschichte bekamen gemeinsame Übertitel wie zum Beispiel „Mensch und Umwelt“. An den Universitäten haben Naturwissenschaftler aus vielen Fächern wie Biologie, Geologie oder Chemie begonnen, Umweltwissenschaften zu lehren. Ein Teil davon ist auch die Ökologie. In diesem Fach wird geforscht, wie man schonend mit der Umwelt umgeht."], "zh": ["Umwelt 这个词首先指周围环境，也就是自己周围的一切。但环境不止于此。所有生物都依赖它们的环境，反过来也一样。环境改变生物，生物也改变环境，两者关系密切。所以今天说 Umwelt，常常指整个自然。", "Umwelt 这个说法大约 200 年前才有，但直到 1960 年以后才真正重要起来。那时有些人发现，人类对环境有坏影响，主要是污染环境：汽车和暖气的废气弄臭了空气，冲厕所的水和工厂的废水弄脏了河流、湖泊和海洋。越来越多的人不愿这样，开始保护环境。", "今天人们也常说「可持续性」，意思是做任何事都应该能永远这样继续下去。自然里就是这样：比如水循环永不停止。动物吃植物，它们的粪便是土壤的肥料，于是又长出新的植物。这可以永远继续。但现在我们人类用的石油、天然气和其他矿产比它们新生成的多得多，所以总有一天会用完。而且这种过度消耗还污染了我们的环境。这不可持续，也就是不环保。", "1970 年以后，学校也开始更多地谈论环境，想教孩子们怎样做才环保。自然课、地理和历史等科目有了「人与环境」之类的共同标题。大学里生物、地质、化学等许多学科的自然科学家开始教环境科学，其中一部分是生态学。这门学科研究怎样爱护环境。"], "lemmas": [], "gloss": [{"w": "abhängig", "de": "braucht etwas, um zu leben", "zh": "依赖的"}, {"w": "Abgase", "de": "schmutzige Luft aus Motoren", "zh": "废气"}, {"w": "Nachhaltigkeit", "de": "so leben, dass es auch später noch geht", "zh": "可持续性"}, {"w": "Bodenschätze", "de": "Dinge im Boden wie Öl, Kohle oder Gold", "zh": "矿产"}, {"w": "übermäßigen", "de": "zu großen, zu vielen", "zh": "过度的"}, {"w": "schonend", "de": "vorsichtig, ohne zu schaden", "zh": "爱护地"}], "qs": [{"q": "Seit wann ist das Wort „Umwelt“ richtig wichtig?", "qZh": "Umwelt 这个词从什么时候起真正重要？", "answer": "Seit den Jahren nach 1960.", "wrong": ["Seit 200 Jahren.", "Seit dem Mittelalter."]}, {"q": "Was bedeutet Nachhaltigkeit?", "qZh": "可持续性是什么意思？", "answer": "Alles so tun, dass es ewig weitergehen könnte.", "wrong": ["Möglichst viel Erdöl verbrauchen.", "Nur in der Stadt leben."]}, {"q": "Was erforscht die Ökologie?", "qZh": "生态学研究什么？", "answer": "Wie man schonend mit der Umwelt umgeht.", "wrong": ["Wie man Autos baut.", "Wie man Geld verdient."]}], "src": "改编自 Klexikon《Umwelt》", "url": "https://klexikon.zum.de/index.php?oldid=152068", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-005", "seg": 11, "title": "Umweltschutz", "de": ["Beim Umweltschutz sorgt man dafür, dass die Umwelt nicht geschädigt wird. Die Umwelt ist im weitesten Sinn die Erde, auf der wir leben. Der Umweltschutz entstand in der Zeit, als die Menschen merkten, wie weit es mit der Umweltverschmutzung bereits gekommen ist.", "Beim Umweltschutz geht es einerseits darum, der Umwelt keine weiteren Schäden zuzufügen. Deshalb wird Abwasser gereinigt, bevor es in einen Fluss geleitet wird. Möglichst viele Dinge werden wiederverwertet anstatt weggeworfen, das nennt man Recycling. Müll wird verbrannt und die Asche richtig gelagert. Wald wird nicht kahlgeschlagen, sondern es werden nur so viele Bäume gefällt, wie nachwachsen.", "Andererseits geht es aber auch darum, alte Schäden an der Umwelt möglichst gut zu beheben. Als einfachstes Beispiel sammelt man den Müll im Wald oder in Gewässern wieder ein. Oft tun das Schulklassen. Man kann auch Gifte wieder aus dem Erdboden herausholen. Dazu braucht es besondere Betriebe und es kostet viel Geld. Abgeholzte Wälder kann man wieder aufforsten, also neue Bäume pflanzen. Auch dazu gibt es noch viele weitere Beispiele.", "Besonders wichtig ist der Umgang mit der Energie. Häuser können gedämmt werden, damit man weniger heizen muss. Es gibt auch neue Heizsysteme, die fast oder gar kein Erdöl oder Erdgas mehr verbrauchen. In vielen Bereichen funktioniert das aber noch nicht. Der Flugverkehr beispielsweise nimmt sehr stark zu und verbraucht immer mehr Treibstoff, obwohl die einzelnen Flugzeuge weniger verbrauchen. Auch Autos fahren heute sparsamer als früher."], "zh": ["环境保护就是让环境不受损害。广义上说，环境就是我们生活的地球。人们发现环境污染已经多么严重的时候，环境保护就出现了。", "环保一方面是不再给环境造成新的损害。所以废水在排进河里之前要净化。尽可能多的东西要回收利用而不是扔掉，这叫回收。垃圾被焚烧，灰烬要妥善存放。森林不会被砍光，砍的树只和长回来的一样多。", "另一方面也要尽量修复环境原有的损害。最简单的例子是把森林里或水里的垃圾捡回来，这常常由学校班级来做。也可以把毒物从土壤里弄出来，这需要专门的企业，花费很多钱。被砍伐的森林可以重新造林，也就是种新树。这方面还有许多别的例子。", "能源的使用尤其重要。房子可以做保温，这样就少用暖气。也有新的供暖系统，几乎或完全不用石油或天然气。但很多领域还做不到。比如航空交通增长很快，消耗的燃料越来越多，尽管单架飞机耗油更少了。汽车今天也比以前省油。"], "lemmas": [], "gloss": [{"w": "geschädigt", "de": "kaputt gemacht", "zh": "损害"}, {"w": "wiederverwertet", "de": "noch einmal benutzt (Material)", "zh": "回收利用"}, {"w": "beheben", "de": "in Ordnung bringen", "zh": "修复"}, {"w": "aufforsten", "de": "neue Bäume pflanzen", "zh": "造林"}, {"w": "gedämmt", "de": "so gebaut, dass keine Wärme verloren geht", "zh": "保温的"}, {"w": "Treibstoff", "de": "Benzin, Diesel usw.", "zh": "燃料"}], "qs": [{"q": "Was macht man mit Abwasser, bevor es in einen Fluss kommt?", "qZh": "废水排进河里前要怎么处理？", "answer": "Man reinigt es.", "wrong": ["Man kocht es.", "Man färbt es."]}, {"q": "Was bedeutet „aufforsten“?", "qZh": "aufforsten 是什么意思？", "answer": "Neue Bäume pflanzen.", "wrong": ["Bäume fällen.", "Müll sammeln."]}, {"q": "Warum dämmt man Häuser?", "qZh": "为什么给房子做保温？", "answer": "Damit man weniger heizen muss.", "wrong": ["Damit sie schöner aussehen.", "Damit sie größer werden."]}], "src": "改编自 Klexikon《Umweltschutz》", "url": "https://klexikon.zum.de/index.php?oldid=159133", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-006", "seg": 11, "title": "Nationalpark", "de": ["Ein Nationalpark ist eine Gegend, in der die Natur geschützt wird. Menschen sollen die Gegend nicht zu stark nutzen. Das kann ein großer Wald, ein riesiges Gebiet oder auch ein Stück des Meeres sein. Auf diese Weise will man dafür sorgen, dass diese Gegend auch später noch so aussieht wie jetzt.", "Schon in der Zeit um 1800 haben sich manche Menschen überlegt, wie man die Natur bewahren kann. In der Zeit der Romantik haben sie gesehen, dass zum Beispiel die Industrie viel Schmutz macht. Den ersten Nationalpark gibt es seit dem Jahr 1864. Man hat ihn in den USA eingerichtet, dort, wo heute der Yosemite-Nationalpark ist.", "Später hat man solche Gebiete auch woanders eingerichtet. Sie heißen allerdings oft anders, und die Regeln sind unterschiedlich. In Deutschland, Österreich und der Schweiz gibt es Naturschutzgebiete. Einige nennt man auch tatsächlich Nationalpark. Manche sind sogar ein Weltnaturerbe der UNESCO, sie gelten also als Naturdenkmal, das für die gesamte Welt wichtig ist.", "Im Nationalpark sollen Tiere und Pflanzen nicht von Menschen gestört werden. Das heißt aber nicht, dass sich Menschen dort überhaupt nicht aufhalten dürfen. Viele Menschen machen dort Urlaub, indem sie zum Beispiel zelten oder campen. Aber die Regeln dazu können streng sein.", "Der Nationalpark muss manchmal vor Tieren und Pflanzen geschützt werden, und zwar vor solchen, die von außen dorthin geraten. Sonst könnten diese neu eingewanderten Tiere und Pflanzen die dortigen verdrängen. Ein Nationalpark ist dazu da, dass Tiere und Pflanzen überleben, die es woanders nicht gibt."], "zh": ["国家公园是自然受到保护的地区。人们不应过度利用这个地区。它可以是一大片森林、一个巨大的区域，也可以是一片海。这样要确保这个地区以后也还是现在的样子。", "早在 1800 年前后，就有人思考怎样保护自然。在浪漫主义时期，他们看到比如工业造成了很多污染。第一个国家公园从 1864 年开始存在，建在美国，就是今天优胜美地国家公园所在的地方。", "后来别的地方也设立了这样的区域，不过名字常常不同，规则也不一样。在德国、奥地利和瑞士有自然保护区，其中一些确实叫国家公园。有些甚至是联合国教科文组织的世界自然遗产，被看作对全世界都重要的自然遗迹。", "国家公园里的动植物不应被人打扰。但这不是说人完全不能待在那里。很多人在那里度假，比如搭帐篷或露营，但相关规定可能很严。", "国家公园有时也要防范动植物，就是那些从外面进来的。否则这些新迁入的动植物可能会排挤原有的。国家公园的作用就是让别处没有的动植物活下去。"], "lemmas": [], "gloss": [{"w": "bewahren", "de": "schützen, erhalten", "zh": "保护"}, {"w": "eingerichtet", "de": "gegründet, gemacht", "zh": "设立"}, {"w": "Naturschutzgebiete", "de": "Gebiete, in denen die Natur geschützt ist", "zh": "自然保护区"}, {"w": "gestört", "de": "bei etwas behindert, unruhig gemacht", "zh": "打扰"}, {"w": "geraten", "de": "ohne Absicht irgendwohin kommen", "zh": "（无意中）进入"}, {"w": "verdrängen", "de": "von ihrem Platz wegschieben", "zh": "排挤"}], "qs": [{"q": "Wozu gibt es einen Nationalpark?", "qZh": "国家公园是干什么的？", "answer": "Damit die Natur geschützt wird.", "wrong": ["Damit man dort Fabriken baut.", "Damit man dort jagen kann."]}, {"q": "Wo gab es den ersten Nationalpark?", "qZh": "第一个国家公园在哪里？", "answer": "In den USA.", "wrong": ["In Deutschland.", "In der Schweiz."]}, {"q": "Dürfen Menschen in einen Nationalpark?", "qZh": "人可以进国家公园吗？", "answer": "Ja, aber es gibt Regeln.", "wrong": ["Nein, nie.", "Ja, ohne jede Regel."]}], "src": "改编自 Klexikon《Nationalpark》", "url": "https://klexikon.zum.de/index.php?oldid=157324", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-007", "seg": 11, "title": "Landschaft", "de": ["Eine Landschaft ist ein Teil eines Landes, eine Gegend. Diese Gegend unterscheidet sich von Gebieten, die daran grenzen. So eine Landschaft wird bestimmt von der Natur: vom Erdboden dort, vom Wetter oder von den Tieren und Pflanzen dort. Auch Menschen haben Einfluss auf Landschaften.", "Das Wort Kulturlandschaft besagt, dass eine Gegend zwar eine Landschaft ist. Sie liegt draußen in der Natur. Aber sie wurde von Menschen verändert: Die Menschen haben Wiesen oder Felder angelegt, es gibt Wege und auch Gebäude. Das Wort Kultur hat hier in gewisser Weise mit Landwirtschaft zu tun.", "Menschen wollen in schönen Landschaften außerdem wandern gehen, spielen oder Tiere und Pflanzen erkunden. Eine Landschaft spielt dann eine wichtige Rolle für die Naherholung: Man kann dort seine Freizeit verbringen, ohne weit weg fahren zu müssen. Landschaften sind aber auch in Gefahr, dass Menschen sie zerstören, weil sie dort Häuser bauen oder ihren Müll hinterlassen.", "„Landschaft“ ist auch ein wichtiger Ausdruck aus der Malerei und der Fotografie. Ein Landschaftsbild zeigt keine oder kaum Menschen, sondern einen Ort oder eine Gegend. Meistens ist das eine Gegend in der Natur, außerhalb der Städte.", "Mit so einem Bild will man oft auch eine bestimmte Stimmung einfangen: Ein einsamer Wald strahlt Ruhe und Friedlichkeit aus. Ein hoher Berg beeindruckt und lässt die Menschen fühlen, dass sie selbst nur ganz klein sind. Dunkle Wolken sorgen für eine düstere, dramatische Stimmung."], "zh": ["风景（地貌）是一个国家的一部分，一个地区。这个地区和相邻的地区不同。风景由自然决定：由那里的土壤、天气或动植物决定。人也会影响风景。", "Kulturlandschaft（人文景观）这个词是说，一个地区虽然是风景，在外面的大自然里，但被人改变过：人们开辟了草地或田地，有道路，也有建筑。这里的 Kultur 在某种程度上和农业有关。", "人们还想在美丽的风景里徒步、玩耍或探索动植物。这样风景对就近休闲就很重要：不用跑很远，就能在那里度过空闲时间。但风景也面临被人破坏的危险，因为人在那里盖房子或留下垃圾。", "「风景」也是绘画和摄影中的重要说法。风景画上没有人或几乎没有人，画的是一个地方或一个地区，大多是城市以外大自然里的地方。", "人们常想用这样的画捕捉一种特定的氛围：寂静的森林散发出安宁祥和；高山令人震撼，让人觉得自己很渺小；乌云带来阴沉、戏剧性的氛围。"], "lemmas": [], "gloss": [{"w": "grenzen", "de": "direkt daneben liegen", "zh": "相邻"}, {"w": "Einfluss", "de": "Wirkung auf etwas", "zh": "影响"}, {"w": "angelegt", "de": "gemacht, gebaut (Garten, Feld)", "zh": "开辟"}, {"w": "Naherholung", "de": "Erholung ganz in der Nähe der Wohnung", "zh": "就近休闲"}, {"w": "Stimmung", "de": "Gefühl, das ein Ort oder Bild gibt", "zh": "氛围"}, {"w": "düstere", "de": "dunkle, traurige", "zh": "阴沉的"}], "qs": [{"q": "Was ist eine Kulturlandschaft?", "qZh": "人文景观是什么？", "answer": "Eine Landschaft, die Menschen verändert haben.", "wrong": ["Eine Landschaft in einem Museum.", "Eine Landschaft ganz ohne Menschen."]}, {"q": "Warum sind Landschaften in Gefahr?", "qZh": "风景为什么面临危险？", "answer": "Menschen bauen Häuser und lassen Müll liegen.", "wrong": ["Es gibt zu viele Tiere.", "Es regnet zu viel."]}, {"q": "Was zeigt ein Landschaftsbild meist?", "qZh": "风景画大多画什么？", "answer": "Eine Gegend in der Natur, kaum Menschen.", "wrong": ["Viele Menschen in der Stadt.", "Ein Auto."]}], "src": "改编自 Klexikon《Landschaft》", "url": "https://klexikon.zum.de/index.php?oldid=159042", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-008", "seg": 11, "title": "Jahreszeiten", "de": ["Die Jahreszeiten sind Teile eines Jahres. In vielen Ländern unterscheidet man vier Jahreszeiten: Zum Frühling gehören März, April und Mai, zum Sommer gehören Juni, Juli und August, zum Herbst gehören September, Oktober und November, zum Winter gehören Dezember, Januar und Februar. Manche Völker teilen es anders ein und haben mehr Jahreszeiten.", "Die Erde hat eine Achse, so nennt man die gedachte Linie durch Nordpol und Südpol, um die sie sich dreht. Außerdem umkreist die Erde die Sonne, und zwar einmal pro Jahr. Die Erdachse steht schief auf dieser Umlaufbahn. Das sieht man auch bei jedem Globus. Diese Schiefstellung der Erdachse ist der Grund für die Jahreszeiten.", "Die Bahn der Erde um die Sonne ist kein vollkommener Kreis, darum ist die Erde nicht immer gleich fern von der Sonne. Viele Leute denken, dass das für die Jahreszeiten wichtig sei: Es wäre Winter, weil wir weiter von der Sonne entfernt seien. In Wirklichkeit machen diese Unterschiede aber fast nichts aus. Es kommt drauf an, wo die Sonne über der Erde steht.", "Im Lauf des Jahres gibt es drei besondere Orte, an denen die Sonne am Mittag stehen kann. Einer ist der nördlichste Ort. Ihn nennt man den nördlichen Wendekreis. Es ist ein Breitenkreis, der sich rund um die Erde zieht. Die Sonne nähert sich ihm von Süden her, jeden Mittag ein bisschen mehr. Am 20., 21. oder 22. Juni erreicht sie ihn und erscheint später wieder immer näher über dem Äquator. Den Tag, an dem diese Wende stattfindet, nennt man die Sommersonnenwende.", "Der nächste Ort ist der Äquator. Darüber steht die Sonne am 21. oder 22. September. Tag und Nacht sind dann bei uns gleich lang. Deshalb spricht man an diesem Datum von der Tag-und-Nacht-Gleiche."], "zh": ["季节是一年的几个部分。很多国家分四季：三月、四月、五月属于春天，六月、七月、八月属于夏天，九月、十月、十一月属于秋天，十二月、一月、二月属于冬天。有些民族分法不同，季节更多。", "地球有一根轴，就是穿过北极和南极的那条假想的线，地球绕着它转。此外地球绕太阳转，一年一圈。地轴斜着立在这条轨道上，这在每个地球仪上都能看到。地轴的倾斜就是四季的原因。", "地球绕太阳的轨道不是完美的圆，所以地球离太阳不总是一样远。很多人以为这对季节很重要：之所以是冬天，是因为我们离太阳更远。实际上这些差别几乎没有影响。关键在于太阳在地球哪里的上空。", "一年中，正午的太阳会到达三个特别的位置。一个是最北的位置，叫北回归线。它是一条环绕地球的纬线。太阳从南边接近它，每天中午近一点。6 月 20、21 或 22 日太阳到达那里，之后又越来越靠近赤道上空。发生这个转折的那一天叫夏至。", "下一个位置是赤道。9 月 21 或 22 日太阳在它的正上方。这时我们这里昼夜一样长，所以这一天叫昼夜平分日。"], "lemmas": [], "gloss": [{"w": "Achse", "de": "gedachte Linie, um die sich etwas dreht", "zh": "轴"}, {"w": "schief", "de": "nicht gerade", "zh": "倾斜的"}, {"w": "vollkommener", "de": "perfekter", "zh": "完美的"}, {"w": "Wendekreis", "de": "Linie, an der die Sonne umkehrt", "zh": "回归线"}, {"w": "Breitenkreis", "de": "Linie um die Erde, parallel zum Äquator", "zh": "纬线"}, {"w": "Sommersonnenwende", "de": "Tag mit dem längsten Tag im Jahr", "zh": "夏至"}], "qs": [{"q": "Was ist der Grund für die Jahreszeiten?", "qZh": "四季的原因是什么？", "answer": "Die Erdachse steht schief.", "wrong": ["Die Erde ist im Winter weiter von der Sonne weg.", "Der Mond."]}, {"q": "Wann ist die Sommersonnenwende?", "qZh": "夏至是什么时候？", "answer": "Am 20., 21. oder 22. Juni.", "wrong": ["Am 1. Juni.", "Im Dezember."]}, {"q": "Was passiert bei der Tag-und-Nacht-Gleiche?", "qZh": "昼夜平分日时会怎样？", "answer": "Tag und Nacht sind gleich lang.", "wrong": ["Die Sonne geht nicht unter.", "Es ist den ganzen Tag dunkel."]}], "src": "改编自 Klexikon《Jahreszeiten》", "url": "https://klexikon.zum.de/index.php?oldid=155862", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-009", "seg": 11, "title": "Frühling", "de": ["Der Frühling oder das Frühjahr ist eine Jahreszeit. Nach dem Winter, der kalten Jahreszeit, wird es im Frühling wieder wärmer. Auf den Frühling folgt dann der Sommer.", "Im Frühling wachsen und blühen die Pflanzen wieder. Die Landschaft wird wieder grün. Viele Tiere bekommen ihre Jungen. Die Bauern mähen die Wiesen und machen Heu.", "Für die Wetterforscher beginnt der Frühling auf der Nordhalbkugel am 1. März und dauert bis zum 31. Mai. Frühlingsmonate sind also der März, der April und der Mai. Für die Astronomen jedoch beginnt der Frühling zur Tag-und-Nacht-Gleiche, wenn die Tage und Nächte also gleich lang sind. Das ist in den nächsten Jahren immer der 20. März, es kann aber auch der 19. oder 21. März sein. In diese Zeit fällt das Osterfest. Der Frühling endet bei der Sommersonnenwende, wenn die Tage am längsten sind. Das ist am 20. oder 21. Juni, und damit beginnt dann der Sommer.", "Die Menschen fanden den Frühling schon immer sehr wichtig: Man musste sich nicht mehr warm anziehen oder sich ins warme Haus verkriechen. Den Anfang des Frühlings feierte man deshalb groß. Besonders bekannt sind bei uns das Münchner Frühlingsfest, das Nürnberger Frühlingsfest oder das Frühlingsfest Hannover. In Zürich heißt das Frühlingsfest Sechseläuten. Auch anderswo auf der Welt gibt es viele Frühlingsfeste. Man sagt auch, im Frühling würden sich mehr Menschen verlieben als in anderen Jahreszeiten."], "zh": ["春天（Frühling 或 Frühjahr）是一个季节。冬天这个寒冷的季节过去后，春天又变暖了。春天之后是夏天。", "春天植物又生长开花，大地又变绿了。很多动物生下幼崽。农民割草晒干草。", "对气象学家来说，北半球的春天从 3 月 1 日开始，到 5 月 31 日结束，所以春季月份是三月、四月和五月。但对天文学家来说，春天从昼夜平分日开始，也就是白天和黑夜一样长的时候。未来几年这一天总是 3 月 20 日，但也可能是 19 日或 21 日。复活节就在这段时间。春天在白天最长的夏至结束，也就是 6 月 20 或 21 日，然后夏天开始。", "人们一直觉得春天很重要：不用再穿得暖暖的，也不用躲在温暖的屋里。所以人们隆重庆祝春天的开始。我们这儿特别有名的是慕尼黑春节、纽伦堡春节或汉诺威春节。在苏黎世，春节叫 Sechseläuten。世界其他地方也有很多春天的节日。人们还说，春天坠入爱河的人比别的季节多。"], "lemmas": [], "gloss": [{"w": "blühen", "de": "Blüten haben", "zh": "开花"}, {"w": "Jungen", "de": "Tierbabys", "zh": "幼崽"}, {"w": "mähen", "de": "Gras abschneiden", "zh": "割（草）"}, {"w": "Heu", "de": "getrocknetes Gras", "zh": "干草"}, {"w": "Wetterforscher", "de": "Wissenschaftler, die das Wetter untersuchen", "zh": "气象学家"}, {"w": "verkriechen", "de": "sich an einem geschützten Ort verstecken", "zh": "躲藏"}], "qs": [{"q": "Was machen die Bauern im Frühling?", "qZh": "春天农民做什么？", "answer": "Sie mähen die Wiesen und machen Heu.", "wrong": ["Sie ernten Kartoffeln.", "Sie schlafen."]}, {"q": "Wann beginnt der Frühling für die Wetterforscher?", "qZh": "对气象学家来说春天什么时候开始？", "answer": "Am 1. März.", "wrong": ["Am 20. März.", "Am 1. April."]}, {"q": "Was sagt man über den Frühling und die Liebe?", "qZh": "人们说春天和爱情有什么关系？", "answer": "Im Frühling verlieben sich mehr Menschen.", "wrong": ["Im Frühling heiratet niemand.", "Im Frühling gibt es keine Feste."]}], "src": "改编自 Klexikon《Frühling》", "url": "https://klexikon.zum.de/index.php?oldid=157441", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-010", "seg": 11, "title": "Sommer", "de": ["Der Sommer ist die wärmste der vier Jahreszeiten. Er folgt auf den Frühling. Nach dem Sommer kommt der kühlere Herbst.", "Viele Pflanzen tragen nur im Sommer Blätter. Die sorgen dafür, dass im Sommer die Landschaften grün aussehen. Im Sommer ernten die Bauern die frühen Kartoffeln, und das meiste Getreide. Im Sommer müssen die Tiere ihre Jungen so weit kriegen, dass sie danach die kalten Jahreszeiten überleben. Manche Tiere fressen sich schon Fett für den Winterschlaf oder sammeln Vorräte.", "Im Sommer gibt es die längsten Ferien. Das lag früher daran, dass die Schüler bei der Ernte mithelfen mussten. Heute hingegen geht es vor allem darum, dass die meisten Leute einen schönen, langen Urlaub im Sommer machen wollen. An der Küste und in anderen Urlaubsgebieten ist es meist voller Menschen.", "Für die Wetterforscher beginnt der Sommer auf der Nordhalbkugel am 1. Juni und dauert bis zum 31. August. Sommermonate sind also der Juni, der Juli und der August.", "Für die Astronomen jedoch beginnt der Sommer zur Sommersonnenwende, wenn die Tage am längsten sind. Das ist immer am 20., 21. oder 22. Juni. Der Sommer endet bei der Tag-und-Nacht-Gleiche, wenn der Tag genauso lang ist wie die Nacht. Das ist am 22., 23. oder 24. September, und damit beginnt dann der Herbst."], "zh": ["夏天是四季中最暖和的季节。它在春天之后。夏天之后是比较凉的秋天。", "很多植物只在夏天长叶子，叶子让夏天的风景看起来绿油油的。夏天农民收获早熟土豆和大部分谷物。夏天动物必须把幼崽养大，好让它们挺过之后的寒冷季节。有些动物已经开始为冬眠长膘或储存食物。", "夏天有最长的假期。以前是因为学生要帮忙收割。而今天主要是因为大多数人想在夏天好好休个长假。海边和其他度假地大多人满为患。", "对气象学家来说，北半球的夏天从 6 月 1 日开始，到 8 月 31 日结束，所以夏季月份是六月、七月和八月。", "但对天文学家来说，夏天从白天最长的夏至开始，总是在 6 月 20、21 或 22 日。夏天在白天和黑夜一样长的昼夜平分日结束，也就是 9 月 22、23 或 24 日，然后秋天开始。"], "lemmas": [], "gloss": [{"w": "ernten", "de": "reife Früchte oder Getreide holen", "zh": "收获"}, {"w": "Getreide", "de": "Weizen, Roggen, Gerste usw.", "zh": "谷物"}, {"w": "Winterschlaf", "de": "langer Schlaf von Tieren im Winter", "zh": "冬眠"}, {"w": "Vorräte", "de": "Essen, das man für später sammelt", "zh": "储备"}, {"w": "Ernte", "de": "das Einsammeln von Früchten und Getreide", "zh": "收割"}, {"w": "Küste", "de": "Land direkt am Meer", "zh": "海岸"}], "qs": [{"q": "Warum gab es früher im Sommer die längsten Ferien?", "qZh": "以前为什么夏天假期最长？", "answer": "Die Schüler mussten bei der Ernte helfen.", "wrong": ["Die Schulen waren zu heiß.", "Die Lehrer machten Urlaub am Meer."]}, {"q": "Was machen manche Tiere im Sommer?", "qZh": "有些动物夏天做什么？", "answer": "Sie fressen sich Fett für den Winterschlaf.", "wrong": ["Sie halten Winterschlaf.", "Sie verlieren ihr Fell."]}, {"q": "Welche Monate sind für Wetterforscher Sommermonate?", "qZh": "对气象学家来说哪些是夏季月份？", "answer": "Juni, Juli und August.", "wrong": ["Mai, Juni und Juli.", "Juli, August und September."]}], "src": "改编自 Klexikon《Sommer》", "url": "https://klexikon.zum.de/index.php?oldid=156626", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-011", "seg": 11, "title": "Herbst", "de": ["Der Herbst ist eine Jahreszeit. In Süddeutschland nennt man ihn auch Spätjahr, das Gegenteil zum Frühjahr oder Frühling. Der Herbst folgt auf den heißen Sommer. Nach dem Herbst kommt der kältere Winter.", "In der Natur ist der Herbst die Zeit, wenn die Blätter an den Bäumen sich verfärben. Das Wasser in den Bäumen zieht sich zurück in die Äste, den Stamm und die Wurzeln. Die Blätter werden auch steif und fallen von den meisten Bäumen ab.", "Für viele Produkte der Landwirtschaft ist der Herbst die Zeit der Ernte. Auf den Feldern ist der Mais reif und die späten Kartoffeln. Auch die Weintrauben und viele späte Apfelsorten sind im Herbst reif. Es gibt auch Gemüsesorten, die erst im Herbst reif sind, beispielsweise die Kürbisse.", "In vielen christlichen Ländern feiert man im Herbst daher das Erntedankfest. Dabei dankt man Gott dafür, dass man genügend Ernte und daher genügend zu essen hat. Dieser Brauch kommt noch aus der Zeit, als viele Menschen Bauern waren. Der Reformationstag und Allerheiligen sind in manchen Ländern und Gegenden Feiertage im Herbst. Ein weiteres Fest in dieser Jahreszeit ist Halloween.", "Für die Wetterforscher beginnt der Herbst auf der Nordhalbkugel am 1. September und dauert bis zum 30. November. Herbstmonate sind also der September, der Oktober und der November."], "zh": ["秋天是一个季节。在德国南部也叫 Spätjahr，是 Frühjahr（春天）的反义词。秋天在炎热的夏天之后，秋天之后是更冷的冬天。", "在自然界，秋天是树叶变色的时候。树里的水退回到树枝、树干和树根里。叶子也变硬，从大多数树上落下来。", "对很多农产品来说，秋天是收获的季节。田里的玉米和晚熟土豆熟了。葡萄和很多晚熟苹果也在秋天成熟。还有些蔬菜要到秋天才熟，比如南瓜。", "所以在很多基督教国家，秋天要庆祝感恩节（丰收节）。人们感谢上帝让收成足够、有足够的东西吃。这个习俗来自很多人还是农民的时代。在有些国家和地区，宗教改革日和万圣节是秋天的节日。这个季节的另一个节日是万圣夜。", "对气象学家来说，北半球的秋天从 9 月 1 日开始，到 11 月 30 日结束，所以秋季月份是九月、十月和十一月。"], "lemmas": [], "gloss": [{"w": "verfärben", "de": "eine andere Farbe bekommen", "zh": "变色"}, {"w": "Stamm", "de": "dicker Teil eines Baumes", "zh": "树干"}, {"w": "Wurzeln", "de": "Teile der Pflanze in der Erde", "zh": "根"}, {"w": "reif", "de": "fertig gewachsen, kann man essen", "zh": "成熟的"}, {"w": "Kürbisse", "de": "große, runde, orange Gemüse", "zh": "南瓜"}, {"w": "Brauch", "de": "alte Gewohnheit, Tradition", "zh": "习俗"}], "qs": [{"q": "Was passiert im Herbst mit den Blättern?", "qZh": "秋天叶子会怎样？", "answer": "Sie verfärben sich und fallen ab.", "wrong": ["Sie werden größer.", "Sie werden grüner."]}, {"q": "Was ist im Herbst reif?", "qZh": "秋天什么成熟？", "answer": "Mais, Weintrauben und Kürbisse.", "wrong": ["Erdbeeren und Spargel.", "Nur Äpfel aus dem Supermarkt."]}, {"q": "Wofür dankt man beim Erntedankfest?", "qZh": "感恩节感谢什么？", "answer": "Für genügend Ernte und Essen.", "wrong": ["Für den ersten Schnee.", "Für ein neues Auto."]}], "src": "改编自 Klexikon《Herbst》", "url": "https://klexikon.zum.de/index.php?oldid=160593", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-012", "seg": 11, "title": "Winter", "de": ["Der Winter ist eine der vier Jahreszeiten. Im Winter sind die Tage kurz, und die Strahlen der Sonne fallen nur schräg auf die Erde. Darum ist es im Winter kalt, oft sinken die Temperaturen sogar unter Null Grad Celsius.", "Es kommt zu Frost. Das Wasser in Seen und Bächen gefriert zu Eis, statt Regen fällt oft Schnee. Viele Tiere halten Winterschlaf oder sind in der Winterstarre. Manche Vogel-Arten fliegen in wärmere Gebiete, um dort zu überwintern.", "Für die Menschen, die nicht in den Tropen leben, ist der Winter die Jahreszeit, für die man gut vorgesorgt haben muss, damit man etwas zu essen und es warm hat. Heutzutage empfinden die meisten Menschen den Winter aber nicht mehr so schlimm wie früher. Manche mögen ihn sogar, weil sie dann Wintersport treiben oder einen Schneemann bauen können.", "Für die Wetterforscher beginnt der Winter auf der Nordhalbkugel am 1. Dezember und dauert bis zum 28. oder 29. Februar. Wintermonate sind also der Monat Dezember, der Januar und der Februar.", "Für die Astronomen jedoch beginnt der Winter zur Wintersonnenwende, wenn die Tage am kürzesten sind. Das ist immer am 21. oder 22. Dezember, also kurz vor dem Weihnachtsfest. Der Winter endet bei der Tag-und-Nacht-Gleiche, wenn der Tag genauso lang ist wie die Nacht. Das ist am 19., 20. oder 21. März, und damit beginnt dann der Frühling."], "zh": ["冬天是四季之一。冬天白天短，阳光只是斜着照到地面上。所以冬天很冷，气温常常甚至降到零摄氏度以下。", "会出现霜冻。湖泊和小溪里的水冻成冰，下的常常不是雨而是雪。很多动物冬眠或处于冬季僵眠状态。有些鸟类飞到更暖的地方去过冬。", "对不住在热带的人来说，冬天是必须做好准备的季节，这样才有东西吃、才暖和。不过如今大多数人不再觉得冬天像以前那么难熬。有些人甚至喜欢冬天，因为可以做冬季运动或堆雪人。", "对气象学家来说，北半球的冬天从 12 月 1 日开始，到 2 月 28 或 29 日结束，所以冬季月份是十二月、一月和二月。", "但对天文学家来说，冬天从白天最短的冬至开始，总是在 12 月 21 或 22 日，也就是圣诞节前不久。冬天在白天和黑夜一样长的昼夜平分日结束，也就是 3 月 19、20 或 21 日，然后春天开始。"], "lemmas": [], "gloss": [{"w": "schräg", "de": "nicht gerade, schief", "zh": "斜的"}, {"w": "Frost", "de": "Kälte unter null Grad", "zh": "霜冻"}, {"w": "gefriert", "de": "wird zu Eis", "zh": "结冰"}, {"w": "überwintern", "de": "den Winter verbringen", "zh": "过冬"}, {"w": "vorgesorgt", "de": "sich vorher um etwas gekümmert", "zh": "预先准备"}, {"w": "empfinden", "de": "fühlen", "zh": "感觉"}], "qs": [{"q": "Warum ist es im Winter kalt?", "qZh": "冬天为什么冷？", "answer": "Die Tage sind kurz und die Sonne scheint schräg.", "wrong": ["Die Sonne ist ausgeschaltet.", "Es gibt mehr Wind."]}, {"q": "Was machen manche Vögel im Winter?", "qZh": "有些鸟冬天做什么？", "answer": "Sie fliegen in wärmere Gebiete.", "wrong": ["Sie bauen Schneemänner.", "Sie halten Winterschlaf im Meer."]}, {"q": "Warum mögen manche Menschen den Winter?", "qZh": "有些人为什么喜欢冬天？", "answer": "Sie können Wintersport treiben.", "wrong": ["Die Tage sind lang.", "Es gibt keine Schule."]}], "src": "改编自 Klexikon《Winter》", "url": "https://klexikon.zum.de/index.php?oldid=158222", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-013", "seg": 11, "title": "Gewitter", "de": ["Ein Gewitter ist etwas, das am Himmel passiert. Wenn die Luft elektrisch aufgeladen ist, kommt es zu einer plötzlichen Entladung: Ein Blitz sucht sich den Weg zum Erdboden. Dabei entsteht ein lauter Knall, der Donner.", "Die Elektrizität entlädt sich in einem Blitz. Er kann über einen Kilometer lang sein und geht in die Erde. Bei der Entladung wird die Luft so heiß, dass sie sich wie bei einer Explosion plötzlich ausdehnt. Die Luft bewegt sich schnell, und Schallwellen entstehen. Das hört man als lauten Donner. Da Licht schneller als Schall ist, sieht man erst den Blitz. Der Donner kommt erst später bei einem an.", "Dazu gibt es eine einfache Faustregel: Wenn zwischen Blitz und Donner drei Sekunden liegen, dann entstand der Blitz einen Kilometer weit entfernt. Bei einer Sekunde Zeitabstand beträgt der Abstand zwischen dem Blitz und dem Hörer also nur etwas über 300 Meter.", "Viele Leute haben bei Gewitter Angst, oder sie fühlen sich zumindest etwas unsicher. Vor allem durch den Donner erschreckt man sich leicht. Wirklich gefährlich ist aber der Blitz. Jedes Jahr sterben auf der Welt Hunderte von Menschen dadurch. Wer vom Blitz getroffen wird, wird schwer verbrannt.", "Am besten geschützt ist man in einem Haus. Besonders hohe Häuser oder solche, die allein stehen, haben nämlich einen Blitzableiter auf dem Dach. Der führt den Blitz in die Erde, so dass den Bewohnern nichts geschieht. Ebenfalls gut geschützt ist man im Auto. Es wirkt wie ein Käfig aus Metall."], "zh": ["雷雨是天空中发生的现象。空气带了电，就会突然放电：一道闪电找路通到地面，同时发出一声巨响，就是雷。", "电在闪电中释放出来。闪电可能长达一公里以上，钻进地里。放电时空气变得极热，像爆炸一样突然膨胀。空气快速运动，产生声波，听起来就是响亮的雷声。因为光比声音快，所以人先看到闪电，雷声后到。", "这有个简单的经验法则：如果闪电和雷声之间隔三秒，闪电就在一公里外。所以间隔一秒的话，闪电和听者之间只有三百多米。", "很多人遇到雷雨会害怕，或者至少有点不安。人主要是被雷声吓到。但真正危险的是闪电。全世界每年有几百人因此丧生。被闪电击中的人会严重烧伤。", "在房子里最安全。特别高的房子或孤零零的房子屋顶上有避雷针，它把闪电引进地里，住的人就不会出事。在汽车里也很安全，汽车就像一个金属笼子。"], "lemmas": [], "gloss": [{"w": "Entladung", "de": "wenn Elektrizität plötzlich herauskommt", "zh": "放电"}, {"w": "Donner", "de": "lauter Knall nach einem Blitz", "zh": "雷"}, {"w": "ausdehnt", "de": "größer wird, mehr Platz braucht", "zh": "膨胀"}, {"w": "Faustregel", "de": "einfache Regel, die ungefähr stimmt", "zh": "经验法则"}, {"w": "erschreckt", "de": "plötzlich Angst bekommt", "zh": "受惊"}, {"w": "Blitzableiter", "de": "Metallstange, die den Blitz in die Erde leitet", "zh": "避雷针"}], "qs": [{"q": "Warum sieht man erst den Blitz und hört dann den Donner?", "qZh": "为什么先看到闪电后听到雷？", "answer": "Licht ist schneller als Schall.", "wrong": ["Der Donner kommt von weiter weg.", "Die Ohren sind langsam."]}, {"q": "Wie weit ist ein Blitz weg, wenn man drei Sekunden zählt?", "qZh": "数到三秒，闪电有多远？", "answer": "Etwa einen Kilometer.", "wrong": ["Etwa drei Kilometer.", "Etwa 100 Meter."]}, {"q": "Wo ist man bei Gewitter gut geschützt?", "qZh": "雷雨时哪里安全？", "answer": "In einem Haus oder im Auto.", "wrong": ["Unter einem hohen Baum.", "Auf einem Berg."]}], "src": "改编自 Klexikon《Gewitter》", "url": "https://klexikon.zum.de/index.php?oldid=165366", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-014", "seg": 11, "title": "Tsunami", "de": ["Ein Tsunami ist eine Flutwelle, die im Meer entsteht und auf eine Küste trifft. Der Tsunami reißt in den Häfen und an den Küsten alles mit: Schiffe, Bäume, Autos und Häuser, aber auch Menschen und Tiere. Dann fließt das Wasser wieder zurück ins Meer und richtet weitere Schäden an. Bei einem Tsunami sterben viele Menschen und Tiere.", "Ein Tsunami entsteht meistens durch ein Erdbeben auf dem Meeresgrund, selten durch einen Vulkanausbruch im Meer. Wenn der Meeresboden sich hebt, hat das Wasser keinen Platz mehr und wird auf alle Seiten gedrängt. So entsteht eine Welle, die sich rundherum ausbreitet wie ein Kreis. Meist entstehen mehrere Wellen mit Pausen dazwischen.", "Mitten auf dem Meer bemerkt man diese Welle aber nicht. Weil das Wasser hier sehr tief ist, ist die Welle noch nicht so hoch. An der Küste ist das Wasser aber weniger tief, so muss die Welle hier viel mehr in die Höhe ausweichen. Dadurch entsteht beim Tsunami eine richtige Wasserwand. Sie kann über 30 Meter hoch werden, das ist so hoch wie ein zehnstöckiges Wohnhaus. Diese Flutwelle kann alles zerstören. Große Schäden entstehen aber auch durch das Material, das sie beim Überfluten des Landes mit sich reißt.", "Den Begriff „Tsunami“ haben japanische Fischer erfunden. Sie waren auf dem Meer und haben nichts bemerkt. Als sie zurückkamen, war der Hafen zerstört. Das japanische Wort „Tsu-nami“ bedeutet: Welle im Hafen.", "Die vergangenen Tsunamis haben sehr viele Tote gefordert. Heute kann man die Menschen warnen, sobald man ein Erdbeben auf dem Meeresgrund messen kann. Der Tsunami breitet sich aber extrem schnell aus, im tiefen Meer so schnell wie ein Flugzeug. Bei einer Warnung müssen die Menschen sofort die Küste verlassen und möglichst weit weg oder besser noch auf einen Hügel fliehen."], "zh": ["海啸是在海里形成、冲上海岸的巨浪。海啸把港口和海岸上的一切都卷走：船、树、汽车和房子，还有人和动物。然后水又退回海里，造成更多破坏。海啸中会死很多人和动物。", "海啸大多由海底地震引起，很少由海里的火山爆发引起。海底升起时，水没有了地方，被挤向四面八方。于是形成一道像圆圈一样向四周扩散的波浪。大多会形成好几道浪，中间有间隔。", "但在海中央察觉不到这道浪。因为这里水很深，浪还没那么高。到了海岸，水变浅，浪就不得不往高处涨得多。于是海啸形成一道真正的水墙，可能高达 30 多米，相当于一栋十层住宅楼。这道巨浪能摧毁一切。不过很大的破坏也来自它淹没陆地时卷走的东西。", "「海啸」这个词是日本渔民创造的。他们在海上什么也没察觉，回来时港口却被毁了。日语「津波」的意思是：港口里的浪。", "过去的海啸夺去了很多人的生命。今天一测到海底地震，就能警告人们。但海啸扩散得极快，在深海里像飞机一样快。收到警报时，人们必须立即离开海岸，尽量跑远，最好逃到小山上。"], "lemmas": [], "gloss": [{"w": "Flutwelle", "de": "sehr große Welle, die Land überflutet", "zh": "巨浪"}, {"w": "reißt", "de": "nimmt mit großer Kraft mit", "zh": "卷走"}, {"w": "Erdbeben", "de": "wenn die Erde wackelt", "zh": "地震"}, {"w": "gedrängt", "de": "mit Kraft geschoben", "zh": "挤"}, {"w": "ausweichen", "de": "zur Seite oder nach oben gehen", "zh": "避开"}, {"w": "fliehen", "de": "schnell weglaufen vor einer Gefahr", "zh": "逃"}], "qs": [{"q": "Wodurch entsteht ein Tsunami meistens?", "qZh": "海啸大多由什么引起？", "answer": "Durch ein Erdbeben auf dem Meeresgrund.", "wrong": ["Durch starken Wind.", "Durch große Schiffe."]}, {"q": "Warum bemerkt man den Tsunami mitten auf dem Meer nicht?", "qZh": "为什么在海中央察觉不到海啸？", "answer": "Das Wasser ist tief, die Welle ist noch nicht hoch.", "wrong": ["Es ist immer Nacht.", "Dort gibt es keine Wellen."]}, {"q": "Was sollen Menschen bei einer Tsunami-Warnung tun?", "qZh": "海啸警报时人们该怎么做？", "answer": "Sofort die Küste verlassen und auf einen Hügel fliehen.", "wrong": ["Zum Strand gehen und schauen.", "Ins Wasser springen."]}], "src": "改编自 Klexikon《Tsunami》", "url": "https://klexikon.zum.de/index.php?oldid=158896", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-015", "seg": 11, "title": "Quelle", "de": ["Bei einer Quelle kommt Wasser aus dem Erdboden an die Oberfläche. Dieses Wasser nennt man Grundwasser. Mehrere Quellen vereinigen sich meistens zu einem Bach und später zu einem Fluss, der ins Meer mündet.", "Meistens handelt es sich um Regenwasser, das im Boden versickert ist. Es sucht seinen Weg durch die Erde, bis es auf eine Schicht aus Felsen oder Lehm stößt. Da kann das Wasser nicht durch und fließt an dieser Schicht entlang. Irgendwann findet es dann meist den Weg an die Oberfläche.", "Während Wasser durch den Erdboden fließt, wird es gereinigt wie durch einen Filter. Quellen, die aus der Tiefe kommen, führen also meist sehr sauberes Wasser, das man direkt als Trinkwasser verwenden kann. Versickert aber das Regenwasser auf einer Weide oder auf einem Acker mit viel Dünger und tritt dann gleich wieder an die Oberfläche, kann das Wasser für den Menschen schädlich sein.", "Manche Quellen geben sehr warmes Wasser, das sind die Thermalquellen. Das Wasser ist warm, weil es aus der Tiefe der Erde kommt, wo es heiß ist. Oder es wurde durch einen Vulkan erwärmt. Andere Quellen haben in sich Stoffe wie zum Beispiel Mineralien. Wenn solche Stoffe gut für die Gesundheit sind, spricht man von einer Heilquelle.", "Das Wort Quelle verwendet man nicht nur für Wasser, das aus der Erde kommt. Mit „Quelle“ meint man oft einfach die Herkunft einer Nachricht. Wenn in der Zeitung etwas steht, fragt man sich manchmal, aus welcher Quelle das kommt. Man fragt sich also, woher der Schreiber das weiß. Vielleicht hat er es selber gesehen, das wäre eine sichere Quelle. Vielleicht hat er es aber nur gehört oder selber irgendwo gelesen, das wäre eine unsichere Quelle."], "zh": ["泉是水从地下冒到地面的地方。这种水叫地下水。几处泉水大多汇成一条小溪，后来汇成一条河，流入大海。", "泉水大多是渗进土里的雨水。它在地下找路，直到碰到一层岩石或黏土。水穿不过去，就沿着这一层流。总有一天它大多会找到通往地面的路。", "水流过土层时会像经过过滤器一样被净化。所以从深处来的泉水大多很干净，可以直接当饮用水。但如果雨水渗进施了很多肥的牧场或田地，又马上冒出地面，这水就可能对人有害。", "有些泉流出很热的水，那就是温泉。水热是因为它来自很热的地球深处，或者被火山加热过。别的泉水里含有矿物质之类的物质。如果这些物质对健康有好处，就叫疗养泉。", "Quelle 这个词不只用来说从地下出来的水，也常常简单地指一条消息的来源。报纸上写了什么，人们有时会问这消息出自哪个来源，也就是问写的人是怎么知道的。也许他亲眼看到，那是可靠的来源；也许他只是听说或在哪儿读到的，那就是不可靠的来源。"], "lemmas": [], "gloss": [{"w": "mündet", "de": "fließt hinein (Fluss ins Meer)", "zh": "流入"}, {"w": "versickert", "de": "langsam in den Boden geht", "zh": "渗入"}, {"w": "Lehm", "de": "schwere, feuchte Erde", "zh": "黏土"}, {"w": "schädlich", "de": "nicht gut für die Gesundheit", "zh": "有害的"}, {"w": "Heilquelle", "de": "Quelle mit Wasser, das gesund macht", "zh": "疗养泉"}, {"w": "Herkunft", "de": "woher etwas kommt", "zh": "来源"}], "qs": [{"q": "Warum ist Quellwasser aus der Tiefe meist sauber?", "qZh": "为什么深处的泉水大多干净？", "answer": "Der Erdboden reinigt es wie ein Filter.", "wrong": ["Man kocht es vorher.", "Es regnet dort nie."]}, {"q": "Was ist eine Thermalquelle?", "qZh": "温泉是什么？", "answer": "Eine Quelle mit sehr warmem Wasser.", "wrong": ["Eine Quelle mit Eis.", "Eine Quelle im Meer."]}, {"q": "Was ist eine sichere Quelle für eine Nachricht?", "qZh": "什么是消息的可靠来源？", "answer": "Jemand hat es selbst gesehen.", "wrong": ["Jemand hat es irgendwo gehört.", "Jemand hat es geträumt."]}], "src": "改编自 Klexikon《Quelle》", "url": "https://klexikon.zum.de/index.php?oldid=156619", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-016", "seg": 11, "title": "Zoo", "de": ["Ein Zoo ist ein Ort, an dem Tiere in Gehegen leben. Dort können Besucher sie sich anschauen. Die Tiere werden von Menschen gepflegt und gefüttert. Das Wort kommt von „Zoologischer Garten“. Die Zoologie ist die Wissenschaft, die sich mit Tieren beschäftigt. Andere Wörter sind „Tierpark“ und „Menagerie“.", "Schon vor Tausenden von Jahren haben Menschen sich wilde Tiere gehalten. Heute sagen die Besitzer von Zoos: Die Besucher sollen nicht nur in den Zoo kommen, weil es ihnen Spaß macht, Tiere zu sehen. Die Besucher sollen auch etwas lernen. Allerdings gibt es auch Menschen, die es überhaupt nicht gut finden, wilde Tiere einzusperren.", "In fast jedem Land der Welt gibt es mindestens einen Zoo. Manche sind groß, manche klein. Nicht alle haben auch „exotische“ Tiere aus fernen Ländern. Allein in Deutschland kann man über 800 Zoos besuchen. Sie werden von vielen Millionen Menschen besucht.", "Schon im Altertum haben Herrscher und reiche Leute Gärten bauen lassen, in denen sie Tiere eingesperrt hielten. Den Tiergarten Schönbrunn in Wien gibt es seit über 250 Jahren. Er ist der älteste Zoo, den es heute noch gibt.", "In London entstand der erste moderne Zoo, im Jahr 1828. Eigentlich sollte er Wissenschaftlern dienen, damit sie besser die Tiere studieren konnten. Der eigentliche Sinn war es aber, die Einwohner Londons zu unterhalten. Darum wurde er auch mitten in die Stadt gebaut. Der Londoner Zoo wurde Vorbild für viele weitere Zoos.", "Besucher sollen im Zoo einen schönen Tag verleben. Für Kinder gibt es oftmals Spielplätze. Manche Zoos haben Kinos, in denen Filme über Tiere zu sehen sind. In Andenkenläden gibt es zum Beispiel Figuren von Tieren zu kaufen. Nicht zuletzt sollen die Besucher sich etwas zu essen und zu trinken kaufen können."], "zh": ["动物园是动物住在围栏里的地方，参观者可以去看它们。动物由人照料和喂养。Zoo 这个词来自「动物学花园」。动物学是研究动物的科学。别的说法有「动物公园」和「动物展览园」。", "几千年前人们就已经养野生动物了。今天动物园的主人说：参观者来动物园不应只是因为看动物好玩，还应该学到东西。不过也有人完全不赞成把野生动物关起来。", "世界上几乎每个国家都至少有一个动物园，有的大，有的小。不是所有动物园都有来自遥远国家的「异域」动物。光在德国就有 800 多家动物园可去，每年有好几百万人参观。", "古代的统治者和有钱人就让人修建花园，把动物关在里面。维也纳的美泉宫动物园已有 250 多年历史，是现存最古老的动物园。", "第一座现代动物园 1828 年在伦敦建成。它本来应该为科学家服务，让他们更好地研究动物。但真正的用意是让伦敦居民消遣，所以它就建在城中心。伦敦动物园成了很多动物园的榜样。", "参观者应该在动物园里度过美好的一天。常常有给孩子的游乐场。有些动物园有电影院，放映关于动物的影片。纪念品商店里能买到比如动物小雕像。最后，参观者还要能买到吃的喝的。"], "lemmas": [], "gloss": [{"w": "Gehegen", "de": "Plätzen mit Zaun für Tiere", "zh": "围栏"}, {"w": "gepflegt", "de": "versorgt, betreut", "zh": "照料"}, {"w": "einzusperren", "de": "in einen Raum zu schließen, aus dem man nicht kann", "zh": "关起来"}, {"w": "exotische", "de": "aus fernen, fremden Ländern", "zh": "异域的"}, {"w": "Herrscher", "de": "König oder Fürst", "zh": "统治者"}, {"w": "Andenkenläden", "de": "Läden für Souvenirs", "zh": "纪念品商店"}], "qs": [{"q": "Woher kommt das Wort „Zoo“?", "qZh": "Zoo 这个词从哪来？", "answer": "Von „Zoologischer Garten“.", "wrong": ["Von einem englischen Tier.", "Von einem Mann namens Zoo."]}, {"q": "Welcher Zoo ist der älteste, den es noch gibt?", "qZh": "现存最古老的动物园是哪个？", "answer": "Der Tiergarten Schönbrunn in Wien.", "wrong": ["Der Londoner Zoo.", "Der Zoo in Duisburg."]}, {"q": "Was sollen die Besucher im Zoo laut den Besitzern auch tun?", "qZh": "动物园主人说参观者还应该做什么？", "answer": "Etwas lernen.", "wrong": ["Die Tiere füttern.", "Im Zoo schlafen."]}], "src": "改编自 Klexikon《Zoo》", "url": "https://klexikon.zum.de/index.php?oldid=154817", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-017", "seg": 11, "title": "Haustiere", "de": ["Haustiere sind Tiere, die der Mensch gezüchtet hat. Sie sind nicht miteinander verwandt. Die Vorfahren unserer Haustiere waren Wildtiere und wurden von den Menschen gefangen. Einige haben vielleicht von sich aus den Weg zum Menschen gefunden, wie die Vorfahren der Hunde.", "Meistens hat man das gemacht, um an Nutztiere zu gelangen. Die Menschen kommen so leichter an Fleisch und Leder als durch die Jagd. Auch die Milch oder Eier bekommt man so einfacher als von wilden Tieren. Hunde können bei der Jagd helfen.", "Viele Haustiere haben die Fähigkeiten ihrer wilden Vorfahren verloren. Sie können oft nicht mehr allein in der Wildnis überleben, weil sie sich an den Schutz und die Fütterung durch den Menschen gewöhnt haben. Eine Ausnahme ist hier allerdings die Hauskatze, die sich gut wieder auf ein Leben ohne Menschen umstellen kann.", "Das älteste Haustier der Welt ist der Hund. Er stammt vom Wolf ab. Schon seit mindestens 15.000 Jahren lebt er gezähmt bei den Menschen. Manche Wissenschaftler sagen sogar, dass das schon vor 135.000 Jahren gelungen ist. Die Zucht von Schweinen, Rindern und Schafen hat vor etwa 10.000 Jahren im Nahen Osten angefangen. Mit den Pferden ging das erst vor etwa 5.000 bis 6.000 Jahren los."], "zh": ["家畜（家养动物）是人培育出来的动物。它们彼此之间没有亲缘关系。我们家养动物的祖先是野生动物，被人抓来。有些也许是自己找到人这里来的，比如狗的祖先。", "人们这样做大多是为了得到役用、食用的动物。这样人们得到肉和皮革比打猎容易。从家养动物那里得到奶或蛋也比从野生动物那里容易。狗可以帮忙打猎。", "很多家养动物失去了它们野生祖先的本领。它们常常不能再独自在野外生存，因为它们已经习惯了人的保护和喂养。不过家猫是个例外，它能很好地重新适应没有人的生活。", "世界上最古老的家养动物是狗，它是狼的后代。至少一万五千年来，它就被驯化，和人生活在一起。有些科学家甚至说，早在十三万五千年前就驯化成功了。猪、牛、羊的饲养大约一万年前在近东开始。马的驯养大约五六千年前才开始。"], "lemmas": [], "gloss": [{"w": "gezüchtet", "de": "so vermehrt, wie der Mensch es will", "zh": "培育"}, {"w": "Vorfahren", "de": "Eltern, Großeltern und noch früher", "zh": "祖先"}, {"w": "Nutztiere", "de": "Tiere, die dem Menschen nützen (Kuh, Huhn ...)", "zh": "役用、食用动物"}, {"w": "Leder", "de": "Haut von Tieren für Schuhe oder Taschen", "zh": "皮革"}, {"w": "gewöhnt", "de": "normal geworden", "zh": "习惯"}, {"w": "gezähmt", "de": "nicht mehr wild", "zh": "驯化的"}], "qs": [{"q": "Woher kommen die Haustiere?", "qZh": "家养动物从哪来？", "answer": "Ihre Vorfahren waren Wildtiere.", "wrong": ["Sie kamen schon immer aus Häusern.", "Sie kommen aus dem Meer."]}, {"q": "Welches Haustier kann gut ohne Menschen leben?", "qZh": "哪种家养动物能很好地离开人生活？", "answer": "Die Hauskatze.", "wrong": ["Das Huhn.", "Das Schaf."]}, {"q": "Was ist das älteste Haustier?", "qZh": "最古老的家养动物是什么？", "answer": "Der Hund.", "wrong": ["Das Pferd.", "Das Schwein."]}], "src": "改编自 Klexikon《Haustiere》", "url": "https://klexikon.zum.de/index.php?oldid=169988", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-018", "seg": 11, "title": "Tierquälerei", "de": ["Tierquälerei bedeutet, dass Menschen Tiere quälen, ihnen also absichtlich Schmerzen zufügen oder sie ohne Grund töten. Das kann auf viele Arten geschehen. Manche Menschen schlagen oder treten Tiere. Andere lassen sie hungern oder sperren sie in viel zu kleine Käfige. Viele Tiere haben keine Zähne oder Krallen, um sich selbst zu schützen. Deshalb brauchen Haustiere wohlwollende Menschen, die sie betreuen.", "Tierquälerei ist in vielen Ländern verboten. Zumindest über die schlimmsten Formen ist man sich weitgehend einig und auch die Gesetze dazu sind klar. Stierkämpfe zum Beispiel sind bei uns verboten, in Spanien, Portugal und Frankreich sowie in vier südamerikanischen Ländern sind sie aber nach wie vor erlaubt. In der Schweiz ist es verboten, Delfine zu halten, im Zoo von Duisburg in Deutschland gibt es immer noch welche, ohne dass das verboten wäre.", "Auch in der Landwirtschaft gibt es große Unterschiede. In der Schweiz haben Hühner am meisten Platz und dürfen nicht in Käfigen gehalten werden. In der EU gehen die Vorschriften weniger weit und außerhalb davon noch weniger. Eier, die von dort aus Käfighaltung kommen, darf man aber in Nudeln verwenden, zu uns bringen und hier verkaufen.", "Im Buddhismus und im Hinduismus denken die Menschen schon seit Tausenden von Jahren, dass Tiere fühlen und somit auch leiden können. Im Hinduismus gelten viele Tiere als besonders heilig. Allen voran ist das die Kuh. Aber auch Elefanten und Affen stehen im Hinduismus ganz oben. Tiere verdienen also seit jeher einen hohen Respekt."], "zh": ["虐待动物是指人折磨动物，也就是故意让它们疼痛，或者无故杀死它们。方式有很多种：有人打或踢动物，有人让它们挨饿，或者把它们关在太小的笼子里。很多动物没有牙齿或爪子来保护自己。所以家养动物需要善待它们的人来照顾。", "在很多国家虐待动物是被禁止的。至少对最恶劣的形式，大家基本意见一致，相关法律也很清楚。比如斗牛在我们这儿是禁止的，但在西班牙、葡萄牙、法国以及南美的四个国家仍然允许。在瑞士禁止饲养海豚，而德国杜伊斯堡的动物园里还有海豚，并不违法。", "农业上也有很大差别。在瑞士，鸡的空间最大，不准关在笼子里。欧盟的规定没那么严，欧盟以外更松。但那些地方笼养鸡下的蛋可以用在面条里，运到我们这儿来卖。", "在佛教和印度教里，几千年来人们就认为动物有感觉，所以也会受苦。在印度教里，很多动物被看作特别神圣，首先是牛，大象和猴子也地位很高。所以动物自古以来就受到很大的尊重。"], "lemmas": [], "gloss": [{"w": "quälen", "de": "einem Tier oder Menschen weh tun", "zh": "折磨"}, {"w": "absichtlich", "de": "mit Absicht, nicht aus Versehen", "zh": "故意地"}, {"w": "Krallen", "de": "spitze Nägel bei Tieren", "zh": "爪子"}, {"w": "wohlwollende", "de": "freundliche, gute", "zh": "善意的"}, {"w": "Vorschriften", "de": "Regeln, die man befolgen muss", "zh": "规定"}, {"w": "heilig", "de": "von Gott, sehr verehrt", "zh": "神圣的"}], "qs": [{"q": "Was ist Tierquälerei?", "qZh": "虐待动物是什么？", "answer": "Tieren absichtlich Schmerzen zufügen.", "wrong": ["Tiere füttern.", "Tiere fotografieren."]}, {"q": "Wo sind Stierkämpfe noch erlaubt?", "qZh": "哪里仍然允许斗牛？", "answer": "Zum Beispiel in Spanien.", "wrong": ["In der Schweiz.", "In Deutschland."]}, {"q": "Welches Tier ist im Hinduismus besonders heilig?", "qZh": "印度教里哪种动物特别神圣？", "answer": "Die Kuh.", "wrong": ["Der Hund.", "Das Pferd."]}], "src": "改编自 Klexikon《Tierquälerei》", "url": "https://klexikon.zum.de/index.php?oldid=163119", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-019", "seg": 11, "title": "Qualzucht", "de": ["Qualzucht bedeutet, dass Tiere so gezüchtet werden, dass sie Merkmale haben, die für sie selbst schädlich sind. Manche Leute finden es schön oder niedlich, wenn Hunde oder Katzen zum Beispiel sehr kurze Nasen oder große Augen haben. Doch für die Tiere ist das oft mit Schmerzen und Krankheiten verbunden.", "Auch Nutztiere auf dem Bauernhof leiden oft unter ihrer Zucht. So gibt es Hühner, die kaum noch laufen können, weil sie zu schnell wachsen und sie zu schwer sind. Qualzucht ist Tierquälerei und in manchen Ländern zum Teil verboten.", "Wer sich ein Haustier kaufen will, sollte daher auch etwas über Qualzucht wissen. Außerdem sind manche Rassen zwar nicht unbedingt eine Qualzucht. Trotzdem leiden sie öfter unter einer Krankheit oder Behinderung als andere Rassen.", "Viele Rassen von Hunden und Katzen sind betroffen. Zum Beispiel haben Möpse und Bulldoggen oft Probleme beim Atmen, weil ihre Nase so kurz ist. Manche Katzen haben so große Augen, dass sie die Augenlider nicht richtig schließen können. Manchmal sind die Tränenkanäle zu eng."], "zh": ["虐待性育种是指把动物培育成带有对它们自己有害的特征。有些人觉得狗或猫比如鼻子很短、眼睛很大很好看或很可爱。但对动物来说，这常常带来疼痛和疾病。", "农场里的家畜也常因育种受苦。比如有些鸡几乎走不了路，因为它们长得太快、太重。虐待性育种就是虐待动物，在有些国家部分被禁止。", "所以想买宠物的人也应该了解一些虐待性育种的知识。此外有些品种虽然不一定算虐待性育种，但比别的品种更常患病或有残疾。", "很多狗和猫的品种都受影响。比如哈巴狗和斗牛犬常常呼吸困难，因为它们的鼻子太短。有些猫眼睛太大，眼皮合不严。有时泪管太窄。"], "lemmas": [], "gloss": [{"w": "Merkmale", "de": "typische Eigenschaften", "zh": "特征"}, {"w": "niedlich", "de": "süß, lieb", "zh": "可爱的"}, {"w": "leiden", "de": "Schmerzen haben, es geht einem schlecht", "zh": "受苦"}, {"w": "Rassen", "de": "Gruppen einer Tierart mit gleichem Aussehen", "zh": "品种"}, {"w": "Behinderung", "de": "wenn ein Körperteil nicht richtig funktioniert", "zh": "残疾"}, {"w": "betroffen", "de": "von etwas Schlechtem erreicht", "zh": "受影响的"}], "qs": [{"q": "Was ist Qualzucht?", "qZh": "虐待性育种是什么？", "answer": "Tiere werden mit Merkmalen gezüchtet, die ihnen schaden.", "wrong": ["Man kauft ein Tier im Laden.", "Man trainiert einen Hund."]}, {"q": "Warum können manche Hühner kaum laufen?", "qZh": "为什么有些鸡几乎走不了路？", "answer": "Sie wachsen zu schnell und sind zu schwer.", "wrong": ["Sie haben keine Beine.", "Sie sind zu alt."]}, {"q": "Warum haben Möpse oft Probleme beim Atmen?", "qZh": "哈巴狗为什么常呼吸困难？", "answer": "Ihre Nase ist so kurz.", "wrong": ["Sie rennen zu viel.", "Sie fressen zu wenig."]}], "src": "改编自 Klexikon《Qualzucht》", "url": "https://klexikon.zum.de/index.php?oldid=163111", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-020", "seg": 11, "title": "Tierarzt", "de": ["Tierarzt oder Tierärztin ist ein Beruf. Tierärzte kümmern sich um kranke oder verletzte Tiere oder sie impfen die Tiere. Wenn ein Haustier krank wird, kann man es zum Tierarzt bringen, um es untersuchen zu lassen. So kann der Tierarzt sehen, was dem Tier fehlt und ihm helfen.", "Tierärzte besuchen auch Tiere auf Bauernhöfen oder sie arbeiten im Tierschutz oder in der Forschung. Manche arbeiten auch nur mit toten Tieren: Sie begutachten geschlachtete Tiere, damit kein Fleisch von kranken Tieren verkauft wird. Sonst könnten die Menschen, die das Fleisch essen, selbst krank werden.", "Um Tierarzt zu werden, muss man an einer Hochschule studieren. Das Studienfach heißt Veterinärmedizin, das bedeutet Tiermedizin. Im Studium lernt man, wie man verschiedene Tierkrankheiten erkennt und behandelt. Man kann sich auch Tierarten oder besondere Arten der Behandlung aussuchen, über die man besonders viel lernen möchte. Es gibt zum Beispiel Tierärzte, welche die Zähne von Tieren untersuchen und behandeln. Genauso gibt es Tierärzte, die sich besonders gut mit einer einzelnen Tierart auskennen, zum Beispiel mit Pferden.", "Manche Tierärzte haben eine eigene Praxis, während andere in einer größeren Tierklinik arbeiten. Auch im Zoo braucht man Tierärzte. Die müssen sich gut mit Tieren aus verschiedenen Ländern auskennen. Da manche Tiere sehr gefährlich sind, müssen sie betäubt werden, wenn der Tierarzt sie untersuchen möchte. Gerade wenn große Tiere behandelt werden müssen, kann die Arbeit eines Tierarztes auch sehr anstrengend sein. Soll zum Beispiel ein betäubtes Nashorn umgedreht werden, dann brauchen der Tierarzt und seine Helfer viel Kraft."], "zh": ["兽医是一种职业。兽医照顾生病或受伤的动物，或者给动物打疫苗。宠物生病时，可以带它去看兽医，让兽医检查。这样兽医就能看出动物哪里不对，帮助它。", "兽医也去农场看动物，或者在动物保护或研究领域工作。有些兽医只和死去的动物打交道：他们检验屠宰后的动物，免得病畜的肉被卖掉。否则吃肉的人自己也可能生病。", "要当兽医，必须上大学。专业叫兽医学，意思是动物医学。学习中要学会识别和治疗各种动物疾病。也可以选某些动物种类或特殊的治疗方法深入学习。比如有专门检查和治疗动物牙齿的兽医，也有特别了解某一种动物的兽医，比如马。", "有些兽医有自己的诊所，有的在较大的动物医院工作。动物园也需要兽医，他们必须很了解来自各国的动物。因为有些动物很危险，兽医要检查时必须先把它们麻醉。尤其是要给大型动物治疗时，兽医的工作也可能很累。比如要给麻醉了的犀牛翻身，兽医和助手们就要用很大力气。"], "lemmas": [], "gloss": [{"w": "verletzte", "de": "die sich wehgetan haben", "zh": "受伤的"}, {"w": "impfen", "de": "eine Spritze gegen Krankheiten geben", "zh": "打疫苗"}, {"w": "geschlachtete", "de": "getötete (für Fleisch)", "zh": "屠宰的"}, {"w": "behandelt", "de": "ärztlich geholfen", "zh": "治疗"}, {"w": "Praxis", "de": "Räume, in denen ein Arzt arbeitet", "zh": "诊所"}, {"w": "betäubt", "de": "in Schlaf versetzt, damit es nicht weh tut", "zh": "麻醉的"}], "qs": [{"q": "Warum untersuchen manche Tierärzte geschlachtete Tiere?", "qZh": "有些兽医为什么检验屠宰的动物？", "answer": "Damit kein Fleisch von kranken Tieren verkauft wird.", "wrong": ["Damit das Fleisch billiger wird.", "Damit die Tiere wieder lebendig werden."]}, {"q": "Wie heißt das Studienfach für Tierärzte?", "qZh": "兽医的专业叫什么？", "answer": "Veterinärmedizin.", "wrong": ["Zoologie.", "Biologie."]}, {"q": "Warum werden manche Tiere im Zoo betäubt?", "qZh": "为什么动物园里有些动物要麻醉？", "answer": "Weil sie gefährlich sind.", "wrong": ["Weil sie müde sind.", "Weil sie Hunger haben."]}], "src": "改编自 Klexikon《Tierarzt》", "url": "https://klexikon.zum.de/index.php?oldid=159211", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-021", "seg": 11, "title": "Hunde", "de": ["Hunde sind Säugetiere. Für Wissenschaftler sind die Hunde eine Tierfamilie, zu der auch die Füchse gehören. Die meisten Menschen denken bei einem Hund an das, was die Wissenschaftler Haushund nennen. Das Männchen heißt Rüde, das Weibchen heißt Hündin, das Jungtier ist ein Welpe.", "Die Haushunde stammen vom Wolf ab: Schon vor vielen tausend Jahren haben Menschen Wölfe an sich gewöhnt. Es gibt Funde, die beweisen, dass Menschen bereits vor 30.000 Jahren mit Hunden zusammengelebt haben. Hunde haben sich verändert, oft hat der Mensch ganz bewusst Hunde gezüchtet, damit sie so wurden, wie er sie haben wollte. Heute gibt es etwa 800 Hunderassen.", "Früher waren Hunde sehr nützlich bei der Jagd, sie wärmten die Menschen und sie kämpften gegen Feinde mit. Heute haben manche Hunde ganz besondere Aufgaben, zum Beispiel helfen sie Blinden, den Weg zu finden. Außerdem können sie etwas bewachen und auch Schafe hüten. Die allermeisten Hunde sind heute aber nur dazu da, damit Menschen Freude an ihnen haben. Auf der Welt soll es über 500 Millionen Hunde geben.", "Hunde sehen zwar nicht besonders gut, sie haben Mühe, Farben gut zu unterscheiden. Aber dafür haben sie sehr gute Ohren. Sie hören Töne, die so hoch sind, dass Menschen sie gar nicht wahrnehmen können. Vor allem können Hunde hervorragend riechen, eine Million Mal besser als der Mensch. Dies hängt nicht nur mit der langen Schnauze zusammen, wie die Nase bei Hunden heißt; viele Hunderassen haben eine kurze Nase. Der starke Geruchssinn kommt daher, dass die Hunde einen viel größeren Teil des Gehirns dazu nutzen, Gerüche zu erkennen, als wir Menschen.", "Die meisten Hunde halten sich die Menschen als Freund oder wie ein zusätzliches Mitglied der Familie. Das geht mit Hunden besonders gut, denn sie sind Rudeltiere wie die Wölfe. Sie bleiben dem Rudel treu, vor allem dem Rudelführer. Sie wollen nämlich nicht aus dem Rudel ausgeschlossen werden, weil sie allein nicht jagen können und so verhungern würden. Aus demselben Grund bewachen sie auch ihre Familie oder deren Haus und verteidigen beides."], "zh": ["狗是哺乳动物。对科学家来说，犬科是一个动物科，狐狸也属于这一科。大多数人说到狗，想到的是科学家所说的家犬。公狗叫 Rüde，母狗叫 Hündin，小狗叫 Welpe。", "家犬是狼的后代：几千年前人们就让狼习惯了和人在一起。有发现证明，人和狗三万年前就生活在一起了。狗变了很多，人常常有意地培育狗，让它们变成人想要的样子。今天大约有 800 个狗的品种。", "以前狗在打猎时很有用，它们给人取暖，还一起和敌人战斗。今天有些狗有很特别的任务，比如帮盲人找路。此外它们还能看守东西和放羊。但今天绝大多数狗只是为了让人开心。据说世界上有五亿多只狗。", "狗的视力虽然不太好，很难分辨颜色，但耳朵非常灵。它们能听到人根本听不到的高音。最重要的是，狗的嗅觉极好，比人好一百万倍。这不只和长长的口鼻有关，因为很多品种的狗鼻子很短。嗅觉灵是因为狗用来辨别气味的大脑部分比我们人大得多。", "大多数人把狗当朋友，或者当家里多出的一个成员。这和狗特别合得来，因为它们和狼一样是群居动物。它们忠于狗群，特别是头领。因为它们不想被赶出群体，独自一个打不了猎，会饿死。出于同样的原因，它们也看守并保卫自己的家人和房子。"], "lemmas": [], "gloss": [{"w": "Säugetiere", "de": "Tiere, die ihre Jungen mit Milch füttern", "zh": "哺乳动物"}, {"w": "Welpe", "de": "junger Hund", "zh": "小狗"}, {"w": "hüten", "de": "aufpassen auf (Tiere)", "zh": "放牧、看管"}, {"w": "wahrnehmen", "de": "bemerken, hören oder sehen", "zh": "察觉"}, {"w": "Rudeltiere", "de": "Tiere, die in Gruppen leben", "zh": "群居动物"}, {"w": "verteidigen", "de": "schützen gegen einen Angriff", "zh": "保卫"}], "qs": [{"q": "Von welchem Tier stammt der Haushund ab?", "qZh": "家犬是哪种动物的后代？", "answer": "Vom Wolf.", "wrong": ["Vom Fuchs.", "Vom Bären."]}, {"q": "Was können Hunde besonders gut?", "qZh": "狗特别擅长什么？", "answer": "Riechen.", "wrong": ["Farben sehen.", "Schwimmen im Meer."]}, {"q": "Warum sind Hunde ihrer Familie treu?", "qZh": "狗为什么忠于家人？", "answer": "Sie sind Rudeltiere und wollen nicht allein sein.", "wrong": ["Sie haben Angst vor Katzen.", "Sie bekommen Geld."]}], "src": "改编自 Klexikon《Hunde》", "url": "https://klexikon.zum.de/index.php?oldid=165879", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-022", "seg": 11, "title": "Hauskatze", "de": ["Unsere Hauskatzen nennt man meist nur Katzen. Es gibt sie in allerlei Farben und mit kurzem oder langem Haar. Sie stammen von der Afrikanischen Wildkatze ab und gehören zur Familie der Katzen und somit zu den Säugetieren. Sie sind also eng verwandt mit dem Löwen, dem Tiger und vielen anderen Arten.", "Menschen halten sich schon seit 10.000 Jahren Hauskatzen. Der Grund war am Anfang wohl der, dass Katzen Mäuse fangen. Mäuse fressen nicht nur Getreide, sondern fast alle Nahrungsmittel, die sie in einem Haus finden. Die Menschen freuen sich deshalb über eine Katze, die dafür sorgt, dass es weniger Mäuse gibt.", "Viele Menschen halten sich aber auch gern eine Katze als Tier zum Streicheln. Im Alten Ägypten verehrte man Katzen sogar als Götter. Es wurden Mumien von Katzen gefunden. Manche Katzen wurden also genauso für ein Leben nach dem Tod vorbereitet wie Pharaonen und andere wichtige Menschen.", "Katzen sind Jäger und können sich sehr schnell bewegen. Manche Katzen schaffen bis zu 50 Stundenkilometer. Das ist so schnell wie ein Auto in einer Stadt fahren darf. Katzen sehen nicht so breit wie die Pferde, sondern nur, was sich gerade vor ihnen befindet. Im Dunkeln sieht eine Katze sechsmal besser als ein Mensch. Noch erstaunlicher ist jedoch ihr Gehör. Kaum ein anderes Säugetier hört so gut. Ihre Ohren kann die Katze drehen und so an einen bestimmten Ort hinhören.", "Katzen können etwas schlechter riechen als Hunde. Dafür haben sie einen hervorragenden Tastsinn. Die langen Haare um den Mund heißen „Tasthaare“ oder „Schnurrhaare“. Sie haben am unteren Ende sehr empfindliche Nerven. Die nehmen wahr, ob ein Durchgang zu schmal ist oder gerade ausreicht."], "zh": ["我们的家猫一般就叫猫。它们有各种颜色，毛有短有长。它们是非洲野猫的后代，属于猫科，也就属于哺乳动物。所以它们和狮子、老虎以及许多别的种类是近亲。", "人们养家猫已经有一万年了。起初的原因大概是猫会抓老鼠。老鼠不只吃粮食，几乎吃屋里能找到的一切食物。所以人们很高兴有只猫让老鼠变少。", "但很多人养猫也是喜欢有只可以抚摸的动物。古埃及人甚至把猫当神来崇拜。人们发现过猫的木乃伊。所以有些猫和法老等重要人物一样，也被准备好迎接死后的生活。", "猫是猎手，动作非常快。有些猫能跑到每小时 50 公里，和汽车在城里允许开的速度一样快。猫不像马那样看得宽，只看得到正前方的东西。在黑暗中，猫的视力比人好六倍。更惊人的是它的听力，几乎没有别的哺乳动物听得这么好。猫能转动耳朵，朝某个地方仔细听。", "猫的嗅觉比狗差一点，但触觉极好。嘴边的长毛叫「触须」或「胡须」，根部有非常敏感的神经，能感觉一个通道是太窄还是刚好过得去。"], "lemmas": [], "gloss": [{"w": "stammen", "de": "kommen von (Vorfahren)", "zh": "起源于"}, {"w": "Nahrungsmittel", "de": "Dinge, die man essen kann", "zh": "食物"}, {"w": "Streicheln", "de": "sanft mit der Hand über etwas fahren", "zh": "抚摸"}, {"w": "verehrte", "de": "hatte großen Respekt, betete an", "zh": "崇拜"}, {"w": "Gehör", "de": "Fähigkeit zu hören", "zh": "听力"}, {"w": "Tastsinn", "de": "Fähigkeit, durch Berühren etwas zu spüren", "zh": "触觉"}], "qs": [{"q": "Warum hielten sich Menschen am Anfang Katzen?", "qZh": "人们起初为什么养猫？", "answer": "Katzen fangen Mäuse.", "wrong": ["Katzen bewachen das Haus.", "Katzen geben Milch."]}, {"q": "Wie sah man Katzen im Alten Ägypten?", "qZh": "古埃及人怎样看猫？", "answer": "Man verehrte sie als Götter.", "wrong": ["Man hatte Angst vor ihnen.", "Man aß sie."]}, {"q": "Wozu dienen die Schnurrhaare?", "qZh": "胡须有什么用？", "answer": "Die Katze spürt, ob ein Durchgang breit genug ist.", "wrong": ["Damit sie besser sieht.", "Damit sie schneller läuft."]}], "src": "改编自 Klexikon《Hauskatze》", "url": "https://klexikon.zum.de/index.php?oldid=160035", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-023", "seg": 11, "title": "Ratten", "de": ["Ratten sind eine Gattung von Nagetieren. Es gibt über 60 verschiedene Arten von Ratten. Außerdem werden manchmal andere kleine Nagetiere als Ratten bezeichnet, obwohl sie nicht zu dieser Gattung gehören.", "Am weitesten verbreitet ist die Wanderratte, von der auch die heutigen Ratten abstammen, die wir als Haustiere halten. Sie leben gern zusammen und sind sehr klug. Sie können gut riechen, hören und bei wenig Licht sehen. Wichtig für die Ratte ist der Schwanz. Er ist leicht behaart und dient als eine Art Antenne, mit der die Ratte ihre Umgebung abtastet. Außerdem können sie sich mit ihm abstützen oder das Gleichgewicht halten.", "Viele Menschen fürchten Ratten, andere finden Ratten toll. Manche haben sogar eine Ratte als Haustier, diese bestimmten Ratten werden Farbratten genannt, sind aber sehr selten.", "Die Wanderratten, die draußen leben, fühlen sich in der Nähe von Menschen sehr wohl, weil sie dort leicht Futter finden. Sie halten sich zum Beispiel in Abwasser-Kanälen auf, weil sie dort Essenreste finden. Viele Menschen spülen diese nämlich ins Klo runter, aber das sollte man eben deshalb nicht tun. Früher haben diese Tiere das Getreide aus den Kornkammern gefressen.", "Ratten sind sehr scheue Tiere, man braucht keine Angst zu haben, sie ziehen sich schnell zurück, wenn sie Menschen begegnen. Aber man sollte sie auch nicht anfassen, da sie Krankheiten übertragen."], "zh": ["大鼠是啮齿动物中的一个属，有 60 多个不同的种。此外有时别的小型啮齿动物也被叫作大鼠，尽管它们不属于这个属。", "分布最广的是褐家鼠，今天我们当宠物养的大鼠也是它的后代。它们喜欢群居，非常聪明。它们嗅觉、听觉都好，光线弱时也看得见。尾巴对大鼠很重要。尾巴上有稀疏的毛，像一种天线，大鼠用它探测周围环境。此外它们还能用尾巴撑住身体或保持平衡。", "很多人怕大鼠，也有人觉得大鼠很棒。有些人甚至养一只大鼠当宠物，这种特定的大鼠叫花鼠，不过很少见。", "住在外面的褐家鼠很喜欢待在人附近，因为那里容易找到吃的。比如它们待在下水道里，因为那里能找到剩饭。很多人把剩饭冲进马桶，正因为这样才不应该这么做。以前这些动物会吃粮仓里的粮食。", "大鼠是很怕人的动物，不必害怕，它们遇到人会很快躲开。但也不该碰它们，因为它们会传播疾病。"], "lemmas": [], "gloss": [{"w": "Nagetieren", "de": "Tieren mit großen Vorderzähnen, z. B. Mäuse", "zh": "啮齿动物"}, {"w": "verbreitet", "de": "an vielen Orten zu finden", "zh": "分布广的"}, {"w": "abtastet", "de": "durch Berühren untersucht", "zh": "探测"}, {"w": "fürchten", "de": "Angst haben vor", "zh": "害怕"}, {"w": "Abwasser-Kanälen", "de": "Röhren unter der Stadt für schmutziges Wasser", "zh": "下水道"}, {"w": "scheue", "de": "die Angst vor Menschen haben", "zh": "怕人的"}], "qs": [{"q": "Wozu braucht die Ratte ihren Schwanz?", "qZh": "大鼠的尾巴有什么用？", "answer": "Um die Umgebung abzutasten und das Gleichgewicht zu halten.", "wrong": ["Um zu schwimmen.", "Um Futter zu tragen."]}, {"q": "Warum sollte man keine Essensreste ins Klo spülen?", "qZh": "为什么不该把剩饭冲进马桶？", "answer": "Ratten finden dort Futter.", "wrong": ["Das Klo wird zu voll.", "Es riecht nicht gut."]}, {"q": "Warum sollte man Ratten nicht anfassen?", "qZh": "为什么不该碰大鼠？", "answer": "Sie übertragen Krankheiten.", "wrong": ["Sie sind sehr gefährlich und beißen immer.", "Sie sind zu klein."]}], "src": "改编自 Klexikon《Ratten》", "url": "https://klexikon.zum.de/index.php?oldid=152042", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-024", "seg": 11, "title": "Ameisen", "de": ["Ameisen sind Insekten, die in Staaten zusammenleben. Als Allesfresser fressen sie auch andere Insekten und Spinnen. Weltweit sind über 14.000 Ameisenarten bekannt. Davon leben mehr als 600 in Europa. Die bei uns bekannteste Ameisenart ist die Rote Waldameise. Sie ist einen halben bis einen ganzen Zentimeter groß.", "Wie alle Insekten haben auch Ameisen sechs Beine, einen harten Panzer und einen dreiteiligen Körper aus Kopf, Brust und Hinterleib. Ameisen können unterschiedliche Farben haben: rötlich-braun, schwarz oder auch gelblich. Die beiden „geknickten“ Fühler am Kopf nennt man auch Antennen. Damit orientieren sie sich, weil sie mit den Antennen tasten, riechen und schmecken können.", "Zu einem Ameisenstaat gehören ein paar Hundert Ameisen oder auch mehrere Millionen. Fast alle Ameisen in einem Staat sind Weibchen: Arbeiterinnen und Königinnen. Die Männchen sind nur kurz im Frühling zu sehen. In der Zeit befruchten sie die Weibchen. Danach sterben sie wieder.", "Arbeiterinnen kümmern sich um den Nachwuchs, um Nahrung, und sie bauen das Ameisennest. Sie werden höchstens zwei oder drei Jahre alt. Königinnen sind oft größer als die anderen Ameisen und können bis zu 25 Jahre alt werden. Nur sie legen die Eier. Aus diesen Eiern entwickeln sich dann die neuen Ameisen. Wird eine Königin geboren, so nennt man sie Jungkönigin. Junge Königinnen gründen entweder einen neuen Ameisenstaat oder bleiben in ihrem Staat, wenn es dort mehrere Königinnen gibt.", "Staaten mit einer Königin werden nur so alt wie die Königin selbst. Das liegt daran, dass nach ihrem Tod keine Eier mehr gelegt werden. Mit mehreren Königinnen können Ameisenstaaten deutlich älter werden: etwa 50 bis 80 Jahre."], "zh": ["蚂蚁是群居在「国家」里的昆虫。它们是杂食动物，也吃别的昆虫和蜘蛛。世界上已知的蚂蚁有一万四千多种，其中六百多种生活在欧洲。我们这儿最有名的是红林蚁，它有半厘米到一厘米大。", "和所有昆虫一样，蚂蚁有六条腿、一层硬壳和分成头、胸、腹三部分的身体。蚂蚁有不同的颜色：红褐色、黑色或者偏黄。头上两根「弯折」的触角也叫天线。它们靠触角辨认方向，因为触角能触摸、闻和尝。", "一个蚁群有几百只蚂蚁，也可能有几百万只。一个蚁群里几乎所有蚂蚁都是雌性：工蚁和蚁后。雄蚁只在春天短时间出现，那时它们让雌蚁受精，之后就死了。", "工蚁照顾后代、找食物、建蚁巢，最多活两三年。蚁后常常比别的蚂蚁大，能活到 25 岁。只有蚁后产卵，新的蚂蚁就从这些卵里发育出来。新生的蚁后叫幼蚁后。年轻的蚁后要么建立一个新蚁群，要么在有好几个蚁后的蚁群里留下来。", "只有一个蚁后的蚁群，寿命和蚁后一样长，因为她死后就不再有人产卵了。有好几个蚁后的蚁群能活得长得多，大约 50 到 80 年。"], "lemmas": [], "gloss": [{"w": "Allesfresser", "de": "Tier, das Pflanzen und Tiere frisst", "zh": "杂食动物"}, {"w": "Panzer", "de": "harte Schale um den Körper", "zh": "硬壳"}, {"w": "Fühler", "de": "dünne Teile am Kopf zum Tasten", "zh": "触角"}, {"w": "orientieren", "de": "herausfinden, wo man ist und wohin man geht", "zh": "辨认方向"}, {"w": "Nachwuchs", "de": "die Kinder, die Jungen", "zh": "后代"}, {"w": "gründen", "de": "neu anfangen, aufbauen", "zh": "建立"}], "qs": [{"q": "Wie viele Beine haben Ameisen?", "qZh": "蚂蚁有几条腿？", "answer": "Sechs.", "wrong": ["Acht.", "Vier."]}, {"q": "Wer legt im Ameisenstaat die Eier?", "qZh": "蚁群里谁产卵？", "answer": "Nur die Königinnen.", "wrong": ["Die Arbeiterinnen.", "Die Männchen."]}, {"q": "Warum werden Staaten mit mehreren Königinnen älter?", "qZh": "为什么有好几个蚁后的蚁群活得更久？", "answer": "Es werden weiter Eier gelegt, wenn eine Königin stirbt.", "wrong": ["Die Arbeiterinnen leben länger.", "Sie haben mehr Futter."]}], "src": "改编自 Klexikon《Ameisen》", "url": "https://klexikon.zum.de/index.php?oldid=168788", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-025", "seg": 11, "title": "Zugvögel", "de": ["Zugvögel sind Vögel, die jedes Jahr weit fliegen an einen wärmeren Ort. Dort verbringen sie den Winter. Zu den Zugvögeln gehören Störche, Kraniche, Gänse und viele andere Vögel. Vögel, die das ganze Jahr mehr oder weniger am gleichen Standort verbringen, nennt man „Standvögel“.", "Dieser Ortswechsel zu den verschiedenen Jahreszeiten ist für ihr Überleben sehr wichtig und geschieht alljährlich ungefähr zur gleichen Zeit. Dabei fliegen sie meistens ungefähr den gleichen Weg. Dieses Verhalten ist angeboren, also von Geburt an vorhanden.", "Es gibt aus unserer Sicht zwei Arten: Die eine Art verbringt den Sommer bei uns und den Winter im Süden, wo es wärmer ist. Das sind die eigentlichen Zugvögel. Die andere Art verbringt den Sommer im hohen Norden und den Winter bei uns, weil es hier für sie immer noch wärmer ist als im Norden. Die nennt man „Gastvögel“.", "Die Zugvögel leben also im Sommer in Europa. Dies sind beispielsweise einzelne Arten von Störchen, die Kuckucks, die Nachtigallen, die Schwalben, die Kraniche und viele andere. Sie verlassen uns im Herbst und kommen im Frühling wieder zurück. Dann ist es angenehm warm und die Tage sind länger, das macht es für sie einfacher, die Jungen großzuziehen. Es gibt ausreichend Nahrung und nicht so viele Fressfeinde wie im Süden.", "Wenn hier der Winter einkehrt und das Nahrungsangebot knapp wird, ziehen sie weiter in den Süden, meist nach Afrika. Dort ist es zu diesem Zeitpunkt deutlich wärmer als bei uns. Um diese langen Reisen zu überstehen, fressen sich die Zugvögel vorher Fettpolster an."], "zh": ["候鸟是每年飞很远到更暖的地方去的鸟，它们在那里过冬。鹳、鹤、雁和许多别的鸟都是候鸟。一年到头差不多待在同一个地方的鸟叫「留鸟」。", "随季节换地方对它们的生存非常重要，每年大约在同一时间发生。它们飞的路线大多也差不多。这种行为是天生的，也就是生来就有。", "从我们的角度看有两种：一种在我们这儿过夏天，到更暖的南方过冬，这是真正的候鸟。另一种在遥远的北方过夏天，到我们这儿过冬，因为对它们来说这里还是比北方暖。这种叫「冬候鸟」。", "所以候鸟夏天住在欧洲，比如某些鹳、杜鹃、夜莺、燕子、鹤等等。它们秋天离开，春天回来。那时天气暖和宜人，白天更长，养育幼鸟更容易。食物充足，天敌也没有南方那么多。", "这里冬天来临、食物变少时，它们就继续往南飞，大多飞到非洲。那时那里比我们这儿暖和得多。为了熬过这么长的旅程，候鸟事先要吃出一层脂肪。"], "lemmas": [], "gloss": [{"w": "Standort", "de": "Ort, wo etwas immer ist", "zh": "所在地"}, {"w": "Überleben", "de": "am Leben bleiben", "zh": "生存"}, {"w": "angeboren", "de": "schon bei der Geburt da", "zh": "天生的"}, {"w": "großzuziehen", "de": "bis sie erwachsen sind zu versorgen", "zh": "养大"}, {"w": "Fressfeinde", "de": "Tiere, die andere Tiere fressen", "zh": "天敌"}, {"w": "knapp", "de": "wenig, fast nicht genug", "zh": "紧缺的"}], "qs": [{"q": "Was ist ein Standvogel?", "qZh": "留鸟是什么？", "answer": "Ein Vogel, der das ganze Jahr am gleichen Ort bleibt.", "wrong": ["Ein Vogel, der nicht fliegen kann.", "Ein Vogel aus Afrika."]}, {"q": "Woher wissen Zugvögel ihren Weg?", "qZh": "候鸟怎么知道路？", "answer": "Das Verhalten ist angeboren.", "wrong": ["Die Eltern zeigen ihn jedes Jahr auf einer Karte.", "Sie folgen Flugzeugen."]}, {"q": "Was machen Zugvögel vor der langen Reise?", "qZh": "长途旅行前候鸟做什么？", "answer": "Sie fressen sich Fett an.", "wrong": ["Sie schlafen lange.", "Sie bauen ein Nest."]}], "src": "改编自 Klexikon《Zugvögel》", "url": "https://klexikon.zum.de/index.php?oldid=159177", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-026", "seg": 11, "title": "Aussterben", "de": ["Aussterben bedeutet, dass es bestimmte Tiere oder Pflanzen auf der Erde nicht mehr gibt, die vorher für lange Zeit da waren. Wenn das letzte Tier oder die letzte Pflanze einer Art gestorben ist, ist die ganze Tierart oder Pflanzenart ausgestorben. Solche Lebewesen wird es dann nie mehr auf der Erde geben. Ein Beispiel sind die Dinosaurier, deren Aussterben etwa 65 Millionen Jahre zurückliegt.", "Manchmal stirbt eine einzelne Tierart aus, wie etwa der Auerochse. Manchmal stirbt nur eine Unterart aus, wie zum Beispiel das Nördliche Breitmaulnashorn, von dem es im Jahr 2022 nur noch zwei Weibchen, aber keinen Bullen mehr gab. Manchmal stirbt aber auch eine ganze Gattung aus, eine Familie oder eine noch größere Gruppe.", "Das Aussterben kann auch nur in einem bestimmten Gebiet stattfinden. In der Schweiz wurde im Jahr 1914 der letzte Braunbär erschossen. Er galt also seither in der Schweiz als ausgestorben. Oder besser gesagt: Er wurde ausgerottet. Heute gibt es in der Schweiz wieder Braunbären, die von Italien her eingewandert sind.", "Den Pflanzen oder Tieren wird der Lebensraum genommen. Häufig wird der Urwald abgeholzt, damit dort Plantagen angelegt werden können, zum Beispiel für Palmöl oder als Weiden für Rinder. Bei uns verschwinden viele Hecken, in denen Vögel nisten und andere wertvolle Lebensräume, damit größere Felder angelegt werden können, auf denen man mit modernen Maschinen arbeiten kann.", "Auch die Umweltverschmutzung trägt ihren Teil zum Aussterben bei. Schadstoffe aus Autos und Heizungen gelangen in die Luft. Abfälle aus der Chemie gelangen manchmal überall hin. Plastik wird in die Meere geschwemmt. Schildkröten zum Beispiel meinen dann, das seien Quallen, fressen sie und sterben daran.", "Heute sieht man auch, wie sich die Landschaft durch den Klimawandel verändert. Die Eisdecke in der Arktis verkleinert sich und zerfällt in immer kleinere Schollen. Das bereitet den Eisbären Schwierigkeiten, weil sie auf der Jagd große Strecken zurücklegen. Bei uns zum Beispiel werden viele Gebiete heißer und trockener. Dies führt zum Beispiel dazu, dass sich die Buche immer weniger wohl fühlt und die Bestände eher zurückgehen."], "zh": ["灭绝是指某些以前长期存在的动物或植物在地球上不再有了。一个物种的最后一只动物或最后一棵植物死了，整个物种就灭绝了。这样的生物在地球上再也不会有了。恐龙就是一个例子，它们灭绝已经大约 6500 万年了。", "有时是单独一个物种灭绝，比如原牛。有时只是一个亚种灭绝，比如北方白犀牛，2022 年只剩两头母的，没有公的了。但有时也会整个属、整个科甚至更大的类群灭绝。", "灭绝也可能只发生在某个地区。1914 年瑞士最后一头棕熊被枪杀，从那以后棕熊在瑞士就算灭绝了，或者更准确地说：被消灭了。今天瑞士又有了从意大利迁过来的棕熊。", "动植物的生存空间被夺走。原始森林常常被砍伐，好开辟种植园，比如种油棕或做养牛的牧场。在我们这儿，很多鸟筑巢的灌木篱和其他宝贵的生境在消失，为的是开辟能用现代机器耕作的更大的田。", "环境污染也是灭绝的一个原因。汽车和暖气的有害物质进入空气。化工废料有时到处都是。塑料被冲进大海。比如海龟会以为那是水母，吃下去就死了。", "今天也能看到气候变化怎样改变着风景。北极的冰盖在缩小，碎成越来越小的浮冰。这给北极熊带来困难，因为它们捕猎时要走很远的路。在我们这儿，比如很多地区变得更热更干，这导致山毛榉越来越不适应，数量趋于减少。"], "lemmas": [], "gloss": [{"w": "ausgestorben", "de": "es gibt keine mehr davon", "zh": "灭绝的"}, {"w": "ausgerottet", "de": "von Menschen ganz vernichtet", "zh": "被消灭的"}, {"w": "eingewandert", "de": "von woanders hergekommen", "zh": "迁入的"}, {"w": "Lebensraum", "de": "Ort, an dem ein Tier oder eine Pflanze lebt", "zh": "生存空间"}, {"w": "nisten", "de": "ein Nest bauen und darin brüten", "zh": "筑巢"}, {"w": "Schadstoffe", "de": "Stoffe, die schaden", "zh": "有害物质"}], "qs": [{"q": "Wann ist eine Tierart ausgestorben?", "qZh": "一个动物物种什么时候算灭绝？", "answer": "Wenn das letzte Tier dieser Art gestorben ist.", "wrong": ["Wenn nur noch 100 Tiere leben.", "Wenn sie in einem Zoo lebt."]}, {"q": "Warum gibt es in der Schweiz wieder Braunbären?", "qZh": "瑞士为什么又有棕熊了？", "answer": "Sie sind von Italien eingewandert.", "wrong": ["Man hat sie im Labor gemacht.", "Sie haben sich lange versteckt."]}, {"q": "Warum sterben manche Schildkröten durch Plastik?", "qZh": "为什么有些海龟因塑料而死？", "answer": "Sie halten es für Quallen und fressen es.", "wrong": ["Sie verfangen sich in Autos.", "Das Plastik ist zu heiß."]}], "src": "改编自 Klexikon《Aussterben》", "url": "https://klexikon.zum.de/index.php?oldid=170342", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-027", "seg": 11, "title": "Nahrungskette", "de": ["Die meisten Lebewesen fressen andere Lebewesen und werden selber gefressen. Das nennt man eine Nahrungskette.", "Es gibt zum Beispiel kleine Krebse, die fressen Algen. Fische fressen die kleinen Krebse, Fischreiher fressen die Fische und Wölfe fressen die Reiher. Das hängt alles hintereinander, wie die Perlen an einer Kette. Deshalb spricht man auch von der Nahrungskette.", "Die Nahrungskette ist ein Begriff aus der Biologie. Das ist die Wissenschaft über das Leben. Alle Lebewesen benötigen Energie und Bausteine, um zu leben. Pflanzen holen sich diese Energie aus dem Sonnenlicht. Die Bausteine für das Wachstum holen sie sich durch die Wurzeln aus dem Boden.", "Tiere können das nicht. Sie holen sich deshalb ihre Energie aus anderen Lebewesen, die sie fressen und verdauen. Dies können Pflanzen oder andere Tiere sein. Also bedeutet die Nahrungskette: Energie und Bausteine gehen von einer Art zur anderen.", "Diese Kette geht nicht immer weiter. Manchmal steht eine Art am Ende der Nahrungskette. Zum Beispiel isst der Mensch allerlei Tiere und Pflanzen. Es gibt aber kein Tier, das Menschen frisst. Außerdem können sich Menschen heute mit Waffen gegen Angriffe von Tieren wehren.", "Dass der Mensch am Ende der Nahrungskette steht, bringt ihm aber auch Probleme: Eine Pflanze kann ein Gift aufnehmen, beispielsweise ein Schwermetall wie Quecksilber. Ein kleiner Fisch frisst die Pflanze. Ein großer Fisch frisst den kleinen Fisch. Das Schwermetall geht immer mit. Zum Schluss fängt der Mensch große Fische und isst dann alle Schwermetalle, die sich im Fisch angesammelt haben. So kann er sich mit der Zeit vergiften.", "Im Grunde genommen hat die Nahrungskette aber gar kein Ende, denn auch Menschen sterben. Nach ihrem Tod begräbt man sie oft in der Erde. Dort werden sie von kleinen Tieren, wie Würmern gefressen. Nahrungsketten bilden also eigentlich eher Kreise."], "zh": ["大多数生物吃别的生物，自己也被吃。这叫食物链。", "比如有些小甲壳动物吃藻类。鱼吃小甲壳动物，苍鹭吃鱼，狼吃苍鹭。这一切一个接一个，像链子上的珠子。所以也叫食物链。", "食物链是生物学的概念，生物学是研究生命的科学。所有生物都需要能量和养分才能活。植物从阳光中获取能量，生长所需的养分则通过根从土壤里获取。", "动物做不到这一点。所以它们从吃下并消化的别的生物那里获取能量，可以是植物，也可以是别的动物。所以食物链的意思是：能量和养分从一个物种传给另一个物种。", "这条链不会一直延续下去。有时一个物种站在食物链的顶端。比如人吃各种动植物，但没有动物吃人。此外如今人还能用武器抵御动物的攻击。", "人站在食物链顶端也给人带来问题：植物可能吸收毒物，比如汞这样的重金属。小鱼吃了这种植物，大鱼吃了小鱼，重金属一直跟着走。最后人捕到大鱼，就把鱼体内积累的所有重金属都吃了下去。这样时间长了人就可能中毒。", "不过说到底食物链根本没有终点，因为人也会死。人死后常被埋在土里，在那里被虫子之类的小动物吃掉。所以食物链其实更像是圈。"], "lemmas": [], "gloss": [{"w": "Krebse", "de": "Wassertiere mit harter Schale und Scheren", "zh": "甲壳动物"}, {"w": "Bausteine", "de": "kleine Teile, aus denen etwas gebaut wird", "zh": "养分、组成单元"}, {"w": "verdauen", "de": "Essen im Bauch verarbeiten", "zh": "消化"}, {"w": "wehren", "de": "sich schützen, kämpfen", "zh": "抵御"}, {"w": "Quecksilber", "de": "giftiges, flüssiges Metall", "zh": "汞"}, {"w": "angesammelt", "de": "nach und nach mehr geworden", "zh": "积累"}], "qs": [{"q": "Woher holen Pflanzen ihre Energie?", "qZh": "植物从哪里获取能量？", "answer": "Aus dem Sonnenlicht.", "wrong": ["Aus anderen Tieren.", "Aus dem Regen."]}, {"q": "Warum kann Fisch für Menschen gefährlich sein?", "qZh": "鱼为什么可能对人有危险？", "answer": "Gifte wie Quecksilber sammeln sich in großen Fischen.", "wrong": ["Fische haben zu viele Knochen.", "Fische sind zu salzig."]}, {"q": "Warum bilden Nahrungsketten eigentlich Kreise?", "qZh": "为什么食物链其实是圈？", "answer": "Auch Menschen sterben und werden von kleinen Tieren gefressen.", "wrong": ["Weil die Erde rund ist.", "Weil Tiere im Kreis laufen."]}], "src": "改编自 Klexikon《Nahrungskette》", "url": "https://klexikon.zum.de/index.php?oldid=158260", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-028", "seg": 11, "title": "Evolution", "de": ["Das Wort Evolution bedeutet Entwicklung. Es geht darum, wie sich die Lebewesen entwickelt haben. Aus einfachen Lebewesen sind viele weitere entstanden. Die Lehre von der Evolution erklärt, warum es unterschiedliche Pflanzen und Tiere auf der Welt gibt.", "Vor allem im 19. Jahrhundert gab es neue Ideen, wie es zu den vielen unterschiedlichen Lebewesen kam. Um das Jahr 1900 setzte sich die Idee der Evolution durch. Die allermeisten Wissenschaftler halten sie für die beste mögliche Erklärung. Ausgedacht hat sie sich vor allem Charles Darwin aus Großbritannien.", "Wenn zum Beispiel Tiere Kinder haben, dann hat das Kind ähnliche Eigenschaften wie die Eltern. Eine Giraffe sieht so aus wie eine Giraffe, weil die Eltern auch schon so ausgesehen haben. Warum aber haben die Giraffen einen so langen Hals?", "Die Giraffen sind entstanden aus ähnlichen Tieren, die noch einen kürzeren Hals hatten. Man hat die Knochen solcher Tiere gefunden. Für Giraffen ist es aber gut, einen langen Hals zu haben: Damit kommen sie an die Blätter von hohen Bäumen, um sie zu fressen.", "Charles Darwin erkannte aber: Wenn ein Kind entsteht, dann passiert es manchmal, dass etwas dabei „schiefgeht“: Das Kind wird ein bisschen anders als die Eltern. Wie anders, das ist reiner Zufall. Manchmal ist die Änderung schlecht, manchmal nützlich, oft macht sie nichts aus.", "Einige Giraffen hatten also von Geburt an etwas längere Hälse als andere Giraffen, aus Zufall. Die Giraffen mit den langen Hälsen hatten einen Vorteil: Sie konnten besser an die hohen Blätter heran. Die anderen Giraffen, mit kürzerem Hals, hatten Pech und sind vielleicht eher verhungert. Die Giraffen mit langem Hals hingegen lebten lange genug und bekamen selber Kinder. Weil schon ihre Eltern recht lange Hälse hatten, waren auch diese Kinder langhalsiger."], "zh": ["Evolution 这个词的意思是发展。它讲的是生物怎样发展而来。从简单的生物中产生了许多别的生物。进化论解释了为什么世界上有各种不同的植物和动物。", "主要在 19 世纪，出现了关于这么多不同生物如何产生的新想法。1900 年前后，进化的观点占了上风。绝大多数科学家认为它是最好的解释。主要是英国的查尔斯·达尔文想出了它。", "比如动物生了孩子，孩子的特征和父母相似。长颈鹿长得像长颈鹿，因为父母就长这样。可长颈鹿为什么脖子那么长呢？", "长颈鹿是从脖子还比较短的类似动物演变来的，人们找到过这类动物的骨头。而对长颈鹿来说，长脖子很有好处：能够到高树上的叶子吃。", "但查尔斯·达尔文认识到：孩子出生时，有时会「出点差错」，孩子会和父母有点不同。不同在哪儿纯属偶然。有时这种变化是坏的，有时有用，常常没什么影响。", "所以有些长颈鹿出于偶然，生来脖子就比别的长一点。长脖子的长颈鹿有优势：更容易够到高处的叶子。脖子短的长颈鹿就倒霉了，可能更容易饿死。长脖子的则活得够久，自己也生了孩子。因为父母脖子就比较长，这些孩子的脖子也更长。"], "lemmas": [], "gloss": [{"w": "Entwicklung", "de": "wie etwas langsam anders wird", "zh": "发展"}, {"w": "Erklärung", "de": "Antwort auf die Frage „warum?“", "zh": "解释"}, {"w": "Eigenschaften", "de": "wie jemand oder etwas ist", "zh": "特征"}, {"w": "Zufall", "de": "etwas, das ohne Plan passiert", "zh": "偶然"}, {"w": "Vorteil", "de": "etwas, das besser ist als bei anderen", "zh": "优势"}, {"w": "verhungert", "de": "gestorben, weil es nichts zu essen gab", "zh": "饿死"}], "qs": [{"q": "Was bedeutet das Wort „Evolution“?", "qZh": "Evolution 是什么意思？", "answer": "Entwicklung.", "wrong": ["Erfindung.", "Bewegung."]}, {"q": "Wer hat sich die Idee der Evolution vor allem ausgedacht?", "qZh": "进化的观点主要是谁想出来的？", "answer": "Charles Darwin.", "wrong": ["Ein Pharao.", "Pythagoras."]}, {"q": "Warum hatten Giraffen mit langem Hals einen Vorteil?", "qZh": "长脖子的长颈鹿为什么有优势？", "answer": "Sie kamen besser an die hohen Blätter.", "wrong": ["Sie konnten schneller laufen.", "Sie sahen schöner aus."]}], "src": "改编自 Klexikon《Evolution》", "url": "https://klexikon.zum.de/index.php?oldid=158186", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-029", "seg": 11, "title": "Pilze", "de": ["Pilze sind Lebewesen. Sie bestehen aus einzelnen Zellen mit einem Zellkern. Sie bilden in der Biologie ein eigenes Reich neben den Tieren und den Pflanzen. Die Wissenschaft von den Pilzen heißt Mykologie.", "Was wir meistens Pilz nennen, ist nur ein Teil des gesamten Lebewesens. Bei Großpilzen sehen wir nämlich oft nur den Fruchtkörper, der für die Vermehrung da ist. Der eigentliche Pilz ist ein feines, meist fast unsichtbares Geflecht im Boden oder im Holz.", "Pilze sind sehr wichtig im Kreislauf der Natur: Sie zerkleinern Abfälle, tote Tiere und tote Pflanzen. Die werden dadurch wieder zu Erde. Diese Arbeit erledigt beispielsweise der Schimmelpilz. Wenn der jedoch Nahrungsmittel oder Wohnräume befällt, können Menschen davon krank werden.", "In den USA gibt es einen Pilz, der über eine Fläche von fast neun Quadratkilometern gewachsen ist. Wahrscheinlich ist er 2400 Jahre alt. Dieser Pilz ist eines der ältesten und größten Lebewesen unserer Erde.", "Die Fortpflanzung erfolgt bei den meisten Pilzen ungeschlechtlich. Die Pilze spalten einfach winzige Teilchen von sich ab, die nennt man Sporen. Die fallen dann ab, oft werden sie durch den Wind weggetragen. Fallen sie an einen günstigen Ort, können sie dort weiterwachsen.", "Einige Pilze können gegessen werden. Es gibt gesunde, schmackhafte Pilze. Andere sind zwar nicht schmackhaft, sie schaden aber auch nicht. Eine dritte Gruppe verursacht Bauchschmerzen, ist aber nicht weiter gefährlich. Eine vierte Gruppe von Pilzen ist so giftig, dass Menschen sterben, wenn sie davon essen."], "zh": ["真菌是生物。它们由带细胞核的单个细胞组成。在生物学里，它们在动物和植物之外自成一界。研究真菌的科学叫真菌学。", "我们平常叫作蘑菇的，只是整个生物的一部分。大型真菌我们常常只看到子实体，它是用来繁殖的。真正的真菌是土里或木头里一张细密的、大多几乎看不见的网。", "真菌在自然循环中非常重要：它们分解废物、死去的动物和植物，使之重新变成泥土。比如霉菌就做这项工作。但霉菌侵袭食物或住房时，人可能因此生病。", "美国有一种真菌，长满了将近九平方公里的面积，大概有 2400 岁了。这种真菌是地球上最古老、最大的生物之一。", "大多数真菌的繁殖是无性的。真菌直接分出微小的颗粒，叫孢子。孢子落下来，常常被风带走。落到合适的地方，就能在那里继续生长。", "有些真菌可以吃。有健康美味的蘑菇；有的虽然不好吃，但也无害；第三类会引起肚子疼，但不算危险；第四类毒性很强，人吃了会死。"], "lemmas": [], "gloss": [{"w": "Zellkern", "de": "Mitte einer Zelle", "zh": "细胞核"}, {"w": "Fruchtkörper", "de": "Teil des Pilzes, den man über der Erde sieht", "zh": "子实体"}, {"w": "Vermehrung", "de": "wenn mehr Lebewesen entstehen", "zh": "繁殖"}, {"w": "Geflecht", "de": "Netz aus vielen dünnen Fäden", "zh": "网状物"}, {"w": "befällt", "de": "angreift, sich darauf ausbreitet", "zh": "侵袭"}, {"w": "Sporen", "de": "winzige Teile, aus denen neue Pilze wachsen", "zh": "孢子"}], "qs": [{"q": "Was sehen wir bei Großpilzen meistens?", "qZh": "大型真菌我们大多看到的是什么？", "answer": "Nur den Fruchtkörper.", "wrong": ["Das ganze Lebewesen.", "Die Wurzeln."]}, {"q": "Warum sind Pilze wichtig für die Natur?", "qZh": "真菌为什么对自然重要？", "answer": "Sie machen tote Tiere und Pflanzen wieder zu Erde.", "wrong": ["Sie machen Sauerstoff.", "Sie fressen Insekten."]}, {"q": "Wie vermehren sich die meisten Pilze?", "qZh": "大多数真菌怎样繁殖？", "answer": "Durch Sporen, die der Wind wegträgt.", "wrong": ["Durch Samen von Blumen.", "Durch Eier."]}], "src": "改编自 Klexikon《Pilze》", "url": "https://klexikon.zum.de/index.php?oldid=164381", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-030", "seg": 11, "title": "Gift", "de": ["Ein Gift ist etwas, das schädigt. Wenn jemand ein Gift zu sich nimmt, kann er krank werden oder sterben. Auch Tiere und Pflanzen können durch Gifte Schaden nehmen. Manchmal sagt man von Flüssen, Meeren, Wäldern und ganzen Landschaften, dass sie vergiftet worden sind.", "Das deutsche Wort „Gift“ bedeutete ursprünglich nur Gabe oder Geschenk. Man kennt das heute noch aus dem Wort Mitgift, die Gabe, die eine Braut von ihren Eltern für die Ehe mitbekommt. Im Griechischen sagt man „dosis“ für ein Geschenk, aber auch für eine Arznei oder die Menge an Arznei.", "Daher kommt der Spruch: Die Menge macht das Gift. Gemeint ist, dass so gut wie jeder Stoff giftig sein kann, wenn er in großen Mengen eingenommen wird. So ist Kochsalz nicht wirklich giftig für Menschen. Wer aber zu viel Salz zu sich nimmt, kann daran sterben.", "Viele Menschen denken bei dem Wort Gift sofort an die Industrie, an Fabriken und überhaupt an etwas, das von Menschen künstlich hergestellt wird. Doch auch in der Natur kommen Gifte vor. Bekannt ist etwa der Fliegenpilz. Es gibt Schlangen mit Gift in den Zähnen. Besondere Frösche in den Tropen haben giftigen Schleim auf der Haut.", "Es gibt aber auch Gifte im Verkauf. Viele Reinigungsmittel gelten als giftig. Es gibt viele strenge Regeln, wie man mit Giften umgeht. Beispielsweise müssen sie sicher aufbewahrt werden. Durch Zeichen wird angegeben, dass es sich um Gift handelt. Gifte dürfen nicht einfach so weggeworfen oder weggeschüttet werden."], "zh": ["毒物是有害的东西。人摄入毒物，可能会生病或死亡。动物和植物也会受毒物伤害。有时人们说河流、海洋、森林乃至整片地区被毒化了。", "德语 Gift 一词原本只是赠品、礼物的意思。今天在 Mitgift（嫁妆）这个词里还能看出来，就是新娘从父母那里带进婚姻的礼物。希腊语 dosis 指礼物，也指药或药量。", "由此有了一句俗语：剂量决定毒性。意思是几乎任何物质大量摄入都可能有毒。比如食盐对人其实没什么毒，但吃太多盐的人也可能因此丧命。", "很多人一听到「毒」字，马上想到工业、工厂，总之是人工制造的东西。但自然界也有毒物，比如有名的毒蝇伞。有些蛇的牙里有毒，热带的某些青蛙皮肤上有有毒的黏液。", "但商店里也卖有毒的东西，很多清洁剂就算有毒。怎样处理毒物有很多严格规定，比如必须安全存放，用标志注明这是毒物。毒物不能随便扔掉或倒掉。"], "lemmas": [], "gloss": [{"w": "schädigt", "de": "Schaden macht, verletzt", "zh": "损害"}, {"w": "ursprünglich", "de": "am Anfang, zuerst", "zh": "原本"}, {"w": "Braut", "de": "Frau, die heiratet", "zh": "新娘"}, {"w": "Arznei", "de": "Medizin", "zh": "药"}, {"w": "künstlich", "de": "von Menschen gemacht", "zh": "人工的"}, {"w": "Schleim", "de": "dicke, klebrige Flüssigkeit", "zh": "黏液"}], "qs": [{"q": "Was bedeutete das Wort „Gift“ ursprünglich?", "qZh": "Gift 原本是什么意思？", "answer": "Gabe oder Geschenk.", "wrong": ["Krankheit.", "Tod."]}, {"q": "Was bedeutet „Die Menge macht das Gift“?", "qZh": "「剂量决定毒性」是什么意思？", "answer": "Fast jeder Stoff kann in großen Mengen giftig sein.", "wrong": ["Nur große Tiere sind giftig.", "Gift ist immer teuer."]}, {"q": "Was gilt für Gifte im Haushalt?", "qZh": "家里的毒物要怎样处理？", "answer": "Man muss sie sicher aufbewahren.", "wrong": ["Man kann sie einfach wegschütten.", "Man sollte sie offen stehen lassen."]}], "src": "改编自 Klexikon《Gift》", "url": "https://klexikon.zum.de/index.php?oldid=169265", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-031", "seg": 11, "title": "Parasiten", "de": ["Parasiten sind allermeist kleine Lebewesen, die sich von einem großen Lebewesen ernähren. Sie nutzen diese großen Lebewesen also aus. Parasiten bezeichnet man auch als Schmarotzer. Oft rechnet man sie zu den Schädlingen. Das große Lebewesen nennt man „Wirt“, es kann auch ein Mensch sein.", "In manchen Fällen bemerkt der Wirt seinen Parasiten nicht einmal. Es gibt allerdings auch Parasiten, welche Krankheiten übertragen. Bei uns kommt dies am häufigsten bei Zecken vor. Sie können eine bestimmte Art von Hirnhautentzündung auslösen, die sehr gefährlich sein kann.", "Parasiten können Tiere und Pflanzen sein, aber auch Bakterien und Pilze. Parasiten können im Wirt leben oder außerhalb. Sie können ihn töten oder nicht. Es gibt also sehr viele Möglichkeiten, Parasiten in verschiedene Gruppen einzuteilen. Verwandt untereinander sind nur die wenigsten.", "Ein bekannter Parasit außerhalb des Wirts sind die Flöhe. Sie leben auf der Haut von Menschen oder Tieren und beißen diese, damit sie ihr Blut saugen können. Davon ernähren sie sich. Solche Parasiten lassen ihren Wirt meistens leben. Sie sind zwar ärgerlich, aber ungefährlich, so lange sie keine Krankheiten übertragen.", "Ein Beispiel für Parasiten, die in ihrem Wirt leben, ist die Schlupfwespe. Sie legt ihre Eier in Schmetterlingsraupen. Die Wespenlarve frisst dann die Raupe langsam von innen auf. Wenn schließlich die Raupe stirbt, ist die Larve bereits so weit entwickelt, dass sie aus der Raupe kommt und sich verpuppt."], "zh": ["寄生虫大多是靠一个大生物为生的小生物，也就是利用这些大生物。寄生虫也叫 Schmarotzer（吃白食的）。人们常把它们算作有害生物。那个大生物叫「宿主」，也可能是人。", "有时宿主甚至察觉不到它的寄生虫。但也有会传播疾病的寄生虫。在我们这儿最常见的是蜱虫，它们会引发一种可能很危险的脑膜炎。", "寄生虫可以是动物和植物，也可以是细菌和真菌。寄生虫可以住在宿主体内，也可以在体外；可以杀死宿主，也可以不杀。所以给寄生虫分类有很多种方法。它们之间有亲缘关系的很少。", "一种有名的体外寄生虫是跳蚤。它们住在人或动物的皮肤上，咬他们好吸血，靠血为生。这类寄生虫大多让宿主活着。它们虽然烦人，但只要不传播疾病就没有危险。", "住在宿主体内的寄生虫，例子是姬蜂。它把卵产在蝴蝶的毛虫体内。蜂的幼虫就从里面慢慢把毛虫吃掉。毛虫最终死去时，幼虫已经发育得能从毛虫里出来化蛹了。"], "lemmas": [], "gloss": [{"w": "ernähren", "de": "sich Nahrung holen, leben von", "zh": "以……为生"}, {"w": "Schädlingen", "de": "Tieren, die Schaden machen", "zh": "有害生物"}, {"w": "Wirt", "de": "Lebewesen, auf oder in dem ein Parasit lebt", "zh": "宿主"}, {"w": "Zecken", "de": "kleine Tiere, die Blut saugen", "zh": "蜱虫"}, {"w": "ärgerlich", "de": "so, dass man sich ärgert", "zh": "烦人的"}, {"w": "Raupe", "de": "Larve eines Schmetterlings", "zh": "毛虫"}], "qs": [{"q": "Wie nennt man das große Lebewesen, von dem ein Parasit lebt?", "qZh": "寄生虫依赖的大生物叫什么？", "answer": "Wirt.", "wrong": ["Gast.", "Schädling."]}, {"q": "Welche Parasiten übertragen bei uns am häufigsten Krankheiten?", "qZh": "在我们这儿哪种寄生虫最常传播疾病？", "answer": "Zecken.", "wrong": ["Flöhe.", "Schlupfwespen."]}, {"q": "Wo legt die Schlupfwespe ihre Eier?", "qZh": "姬蜂把卵产在哪里？", "answer": "In Schmetterlingsraupen.", "wrong": ["In Blumen.", "Im Wasser."]}], "src": "改编自 Klexikon《Parasiten》", "url": "https://klexikon.zum.de/index.php?oldid=155775", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-032", "seg": 11, "title": "Kartoffel", "de": ["Die Kartoffel ist eine Pflanze, die entfernt mit Tomate, Paprika und Tabak verwandt ist. Man nennt die Kartoffel in einigen Gegenden auch Erdapfel. Das Wort Kartoffel geht auf einen lateinischen Ausdruck zurück, der Erdknolle bedeutet.", "Die eigentliche Pflanze ist grün und leicht giftig. Auch die Früchte kann man nicht essen. Was man isst, das sind Knollen, die im Erdboden wachsen. Die Knolle besteht vor allem aus Wasser und Stärke. Stärke gehört zu den Kohlenhydraten wie Zucker oder viele Teile des Getreides.", "Die Kartoffel stammt aus den Anden, einem Gebirge in Südamerika. Schon die Inka haben sie angebaut. Später haben spanische Entdecker die Pflanze kennengelernt. Um das Jahr 1570 scheint sie zum ersten Mal nach Spanien gekommen zu sein. Mit der Zeit baute man sie auch in anderen Ländern Europas und der Welt an. Es gibt viele Geschichten, wer genau die Kartoffeln nach Europa gebracht hat. Tatsächlich weiß man es nicht.", "Viele Menschen hatten dank der Kartoffel genug zu essen. Als aber die Kartoffelpflanzen krank wurden, zum Beispiel um das Jahr 1850 in Irland, verhungerten viele. Heute bebauen die Menschen auf der Welt große Landflächen mit Kartoffeln, vor allem in Europa und Asien. In diese Flächen würde Österreich zweimal hineinpassen. Ein Deutscher isst im Jahr durchschnittlich etwa 50 Kilogramm Kartoffeln, also etwa jede Woche ein Kilogramm.", "Kartoffeln kann man höchstens über einen Winter aufbewahren. Später werden sie faul. Man kann mit ihnen also keine Vorräte anlegen wie mit Getreide. Kartoffeln werden erst gekocht, bevor man sie isst. Oft werden aber gar nicht die gekochten Kartoffeln gegessen. Die Industrie verarbeitet Kartoffeln zu Pommes frites, Chips oder anderen Produkten."], "zh": ["土豆是一种植物，和番茄、甜椒、烟草有远亲关系。有些地区也把土豆叫 Erdapfel（地里的苹果）。Kartoffel 这个词可以追溯到一个意为「地下块茎」的拉丁语说法。", "土豆植株本身是绿色的，略有毒性，果实也不能吃。人吃的是长在土里的块茎。块茎主要由水和淀粉组成。淀粉和糖或粮食的很多成分一样，属于碳水化合物。", "土豆原产于南美洲的安第斯山脉。印加人就已经种植它。后来西班牙探险者认识了这种植物。它好像大约在 1570 年第一次来到西班牙。随着时间推移，欧洲其他国家和世界各地也种上了它。关于到底是谁把土豆带到欧洲，有很多故事，其实没人知道。", "很多人靠土豆才有足够的东西吃。但土豆生病时，比如 1850 年前后在爱尔兰，很多人饿死了。今天世界上有大片土地种土豆，主要在欧洲和亚洲，这些面积能装下两个奥地利。德国人平均每年吃大约 50 公斤土豆，也就是大约每周一公斤。", "土豆最多只能存放一个冬天，之后就会烂。所以不能像粮食那样用它来储备。土豆要先煮熟再吃。不过人们吃的常常根本不是煮土豆，工业会把土豆加工成炸薯条、薯片或别的产品。"], "lemmas": [], "gloss": [{"w": "verwandt", "de": "aus derselben Familie", "zh": "有亲缘关系的"}, {"w": "Knollen", "de": "dicke, runde Teile einer Pflanze in der Erde", "zh": "块茎"}, {"w": "Stärke", "de": "weißer Stoff in Kartoffeln und Getreide", "zh": "淀粉"}, {"w": "angebaut", "de": "gepflanzt, um zu ernten", "zh": "种植"}, {"w": "durchschnittlich", "de": "im Mittel", "zh": "平均"}, {"w": "faul", "de": "verdorben, schlecht", "zh": "腐烂的"}], "qs": [{"q": "Welchen Teil der Kartoffel isst man?", "qZh": "土豆吃的是哪部分？", "answer": "Die Knollen in der Erde.", "wrong": ["Die grünen Blätter.", "Die Früchte."]}, {"q": "Woher stammt die Kartoffel?", "qZh": "土豆原产于哪里？", "answer": "Aus den Anden in Südamerika.", "wrong": ["Aus Irland.", "Aus Spanien."]}, {"q": "Wie viele Kartoffeln isst ein Deutscher etwa pro Jahr?", "qZh": "德国人每年大约吃多少土豆？", "answer": "Etwa 50 Kilogramm.", "wrong": ["Etwa 5 Kilogramm.", "Etwa 500 Kilogramm."]}], "src": "改编自 Klexikon《Kartoffel》", "url": "https://klexikon.zum.de/index.php?oldid=164403", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-033", "seg": 11, "title": "Ernährung", "de": ["Ernährung bedeutet, dass Menschen essen oder trinken. Genauer gesagt geht es darum, dass sie Nährstoffe aufnehmen. Das sind Stoffe, die man zum Leben braucht. Der Körper holt sich daraus Energie, er wächst und erneuert sich. Nahrung oder Nahrungsmittel nennt man hingegen das, was jemand isst oder trinkt.", "Nicht nur Menschen ernähren sich, sondern auch Tiere und Pflanzen. Bei den Tieren unterscheidet man drei Gruppen: Pflanzenfresser wie zum Beispiel die Rinder, Fleischfresser wie die Löwen und Allesfresser wie zum Beispiel wir Menschen. Alles was lebt, braucht Nahrung: Auch Bakterien müssen etwas fressen. Pflanzen holen sich ihre Nährstoffe mit den Wurzeln.", "Die Ernährung ist ein wichtiger Teil der Wirtschaft: Viele Menschen verdienen ihr Geld, indem sie Nahrungsmittel herstellen. Diesen Zweig nennt man die Landwirtschaft. Andere verkaufen Nahrung. Dazu gehören der Handel, die Läden, Straßenverkäufer und viele andere.", "Essen und Trinken gehört auch zur Kultur: Was man isst, und wie man isst, kann von Mensch zu Mensch, von Land zu Land oder von Volk zu Volk unterschiedlich sein. Frankreich ist für seinen Weichkäse bekannt, Italien für die Spagetti und so weiter.", "Viele arme Menschen können sich zu wenig Nahrung leisten. Wer zu wenig isst oder essen kann, ist unterernährt. Dies betrifft etwa jeden neunten Menschen auf der Welt. Unterernährung ist vor allem schlimm für Kinder, weil sie nicht richtig wachsen. Wer unterernährt ist, leidet Hunger. Viele andere Menschen bekommen zwar den Bauch voll, aber oft zum Beispiel nur mit Reis. Das ist sehr einseitig und diesen Menschen fehlen dann viele Vitamine. Diese einseitige Ernährung nennt man auch Mangelernährung.", "An erster Stelle steht sauberes Trinkwasser. Ohne zu trinken hält es ein Mensch nur etwa drei Tage lang aus. Ob man reines Wasser trinkt oder zum Beispiel Tee, ist dabei mehr oder weniger unwichtig. Man sollte nur daran denken, dass viele Getränke sehr viel Zucker enthalten."], "zh": ["营养是指人吃喝东西，更准确地说，是摄取营养物质。营养物质是生存所需的物质。身体从中获取能量，生长并更新自己。而人吃喝的东西叫食物。", "不只人要摄取营养，动物和植物也要。动物分三类：比如牛这样的食草动物，狮子这样的食肉动物，还有比如我们人类这样的杂食动物。一切活的东西都需要食物：细菌也得吃东西。植物用根获取营养。", "营养是经济的重要部分：很多人靠生产食物挣钱，这个行业叫农业。另一些人卖食物，包括商业、商店、街头小贩等等。", "吃喝也是文化的一部分：吃什么、怎么吃，每个人、每个国家、每个民族都可能不同。法国以软奶酪闻名，意大利以意大利面闻名，等等。", "很多穷人买不起足够的食物。吃得太少或没法吃饱的人就营养不足，这大约涉及世界上每九个人中的一个。营养不足对孩子特别严重，因为他们长不好。营养不足的人要挨饿。还有很多人虽然能吃饱，但比如常常只吃米饭。这非常单一，这些人就缺很多维生素。这种单一的饮食也叫营养不良。", "排在第一位的是干净的饮用水。不喝水的话，人只能撑大约三天。喝白水还是比如喝茶，差别不太大。只是应该想到，很多饮料含糖很多。"], "lemmas": [], "gloss": [{"w": "Nährstoffe", "de": "Stoffe im Essen, die der Körper braucht", "zh": "营养物质"}, {"w": "erneuert", "de": "macht neu", "zh": "更新"}, {"w": "Zweig", "de": "Teil eines größeren Ganzen (Wirtschaft)", "zh": "行业、分支"}, {"w": "unterernährt", "de": "hat zu wenig zu essen bekommen", "zh": "营养不足的"}, {"w": "einseitig", "de": "immer nur dasselbe", "zh": "单一的"}, {"w": "enthalten", "de": "in etwas drin sein", "zh": "含有"}], "qs": [{"q": "Zu welcher Gruppe gehören die Menschen?", "qZh": "人属于哪一类？", "answer": "Zu den Allesfressern.", "wrong": ["Zu den Pflanzenfressern.", "Zu den Fleischfressern."]}, {"q": "Wofür ist Frankreich bekannt?", "qZh": "法国以什么闻名？", "answer": "Für seinen Weichkäse.", "wrong": ["Für Spagetti.", "Für Reis."]}, {"q": "Wie lange hält es ein Mensch ohne Trinken aus?", "qZh": "人不喝水能撑多久？", "answer": "Etwa drei Tage.", "wrong": ["Etwa drei Wochen.", "Etwa drei Stunden."]}], "src": "改编自 Klexikon《Ernährung》", "url": "https://klexikon.zum.de/index.php?oldid=155224", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-034", "seg": 11, "title": "Gesundheit", "de": ["Gesundheit bedeutet, dass man keine Krankheit hat. Außerdem ist jemand nur gesund, wenn es ihm allgemein gut geht, sowohl was den Körper als auch was den Geist und die Seele angeht. Was Gesundheit genau bedeutet, darüber gibt es unterschiedliche Meinungen.", "Die Weltgesundheitsorganisation hat genau beschrieben, was sie unter Gesundheit versteht: „Gesundheit ist ein Zustand vollkommenen körperlichen, geistigen und sozialen Wohlbefindens und nicht allein das Fehlen von Krankheit und Gebrechen.“ Es kommt also auch darauf an, wie gesund man sich selber fühlt. Dazu gehört ferner, dass man sich den Menschen gegenüber wohlfühlt, die einem oft begegnen. Wer zum Beispiel in der Schule gemobbt wird, fühlt sich dadurch auch nicht wirklich gesund.", "Von der Medizin her gesehen sind viele Menschen krank, weil sie zum Beispiel Krebs haben. So lange einer aber diesen Krebs nicht bemerkt, kann er sich für gesund halten, sofern er die wichtigsten Aufgaben im Leben erledigen kann.", "Gut für die Gesundheit sind das richtige Essen und Bewegung. Wenn man immer nur schlechte Dinge isst oder sich wenig bewegt, kann man leichter krank werden. Zur Gesundheit gehört auch, dass man gute Kontakte zu anderen Menschen hat. Zu viele Stunden am Computer oder am Smartphone sind schlecht für die Gesundheit. Man kann aber auch gesund sein und gleichzeitig behindert: Wer blind ist oder im Rollstuhl sitzt, ist dadurch nicht krank.", "Die vielen Menschen, Einrichtungen und Gebäude, die für die Gesundheit da sind, nennt man Gesundheitswesen. Dabei denkt man zuerst an Ärzte und Krankenhäuser. Hinzu kommt die Pflege: Pflegende wie zum Beispiel Altenpfleger helfen Kranken, Alten und Behinderten, die sich selbst nicht helfen können. Auch bestimmte Versicherungen gehören zum Gesundheitswesen, besonders die Krankenkassen."], "zh": ["健康就是没有疾病。此外，只有一个人总体上状态良好，身体、精神和心灵都好，才算健康。健康到底是什么意思，说法不一。", "世界卫生组织准确描述了它对健康的理解：「健康不仅是没有疾病和虚弱，而是身体、精神和社会适应上的完满状态。」所以自己觉得多健康也很重要。此外，和常打交道的人相处得舒服也属于健康。比如在学校被欺凌的人，也不会觉得自己真正健康。", "从医学上看，很多人是有病的，比如得了癌症。但只要一个人没察觉到这个癌症，只要还能做好生活中最重要的事，他就可以认为自己健康。", "正确的饮食和运动对健康有好处。总吃不好的东西或很少运动，就更容易生病。和别人有良好的交往也属于健康。在电脑或智能手机前待太多小时对健康不好。不过人也可以既健康又有残疾：失明或坐轮椅的人并不因此就是病人。", "为健康服务的许多人员、机构和建筑合称卫生体系。人们首先想到的是医生和医院。此外还有护理：比如老年护理员等护理人员帮助无法自理的病人、老人和残疾人。某些保险也属于卫生体系，特别是医疗保险公司。"], "lemmas": [], "gloss": [{"w": "Geist", "de": "das Denken, der Verstand", "zh": "精神"}, {"w": "Wohlbefindens", "de": "des guten Gefühls, dass es einem gut geht", "zh": "良好状态"}, {"w": "gemobbt", "de": "immer wieder von anderen geärgert und ausgegrenzt", "zh": "被欺凌"}, {"w": "behindert", "de": "mit einer Behinderung", "zh": "有残疾的"}, {"w": "Einrichtungen", "de": "Stellen, Institutionen (Ämter, Heime ...)", "zh": "机构"}, {"w": "Krankenkassen", "de": "Versicherungen, die Arztkosten bezahlen", "zh": "医疗保险公司"}], "qs": [{"q": "Was gehört laut WHO zur Gesundheit?", "qZh": "按世卫组织的说法，健康包括什么？", "answer": "Körperliches, geistiges und soziales Wohlbefinden.", "wrong": ["Nur, dass man keine Krankheit hat.", "Viel Geld zu haben."]}, {"q": "Was ist schlecht für die Gesundheit?", "qZh": "什么对健康不好？", "answer": "Zu viele Stunden am Computer.", "wrong": ["Viel Bewegung.", "Gute Kontakte zu Freunden."]}, {"q": "Was gehört zum Gesundheitswesen?", "qZh": "什么属于卫生体系？", "answer": "Ärzte, Krankenhäuser und Krankenkassen.", "wrong": ["Schulen und Kinos.", "Banken."]}], "src": "改编自 Klexikon《Gesundheit》", "url": "https://klexikon.zum.de/index.php?oldid=160770", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-035", "seg": 11, "title": "Krankheit", "de": ["Krankheit ist das Gegenteil von Gesundheit. Es ist oft schwierig, die Grenze zwischen beiden zu ziehen. Wenn jemand Windpocken oder Masern hat oder unter einer Blinddarmentzündung leidet, dann ist er sicherlich krank. Ein Arzt untersucht und behandelt den Kranken.", "Schwieriger wird es aber schon bei einer leichteren Krankheit. Mit einer Erkältung zum Beispiel kann man trotzdem zur Schule oder zur Arbeit gehen. Erst wenn die Krankheit schlimmer wird, stellt der Arzt dem Kranken eine Bescheinigung aus, dass er zu Hause bleiben soll.", "Krankheiten kann man auf verschiedene Arten voneinander unterscheiden und zu Gruppen zusammenfassen. Wichtig ist zum Beispiel die Unterscheidung zwischen ansteckenden und nicht-ansteckenden Krankheiten. Eine Erkältung zum Beispiel ist nicht schlimm, aber ansteckend. In der Spucke befinden sich nämlich Viren, die wir beim Husten in kleinen Tröpfchen hinauspusten. Krebs hingegen kann zum Tod führen, ist aber nicht ansteckend.", "Eine besondere Gruppe bilden auch die Kinderkrankheiten wie Mumps, Röteln oder Scharlach. Die meisten von ihnen bekommt man später als Erwachsener nicht mehr. Gegen viele Kinderkrankheiten kann man die Kinder impfen lassen, damit sie gar nicht erst daran krank werden.", "Etwas anderes als die Krankheit ist die Behinderung. Wer behindert ist, kann vielleicht etwas Bestimmtes nicht. Ein Blinder kann nicht sehen. Dadurch ist er aber nicht krank, es ist für ihn normal. Das Blindsein geht auch nicht für ihn irgendwann wieder vorbei. Es gibt jedoch chronische Krankheiten: „chronisch“ ist ein Wort für „Zeit“ und meint hier, dass man die Krankheit sehr lange oder sogar für immer hat."], "zh": ["疾病是健康的反面。两者之间常常很难划界。如果有人得了水痘或麻疹，或者患了阑尾炎，那他肯定是病了。医生给病人检查和治疗。", "病得轻一些时就难说了。比如感冒了照样可以上学或上班。病情加重时，医生才会给病人开一张证明，让他待在家里。", "疾病可以用不同的方法区分并归类。比如很重要的一点是区分传染病和非传染病。比如感冒不严重，但会传染，因为唾液里有病毒，我们咳嗽时会把它们随着小飞沫喷出去。而癌症可能致命，却不传染。", "儿童病也是一个特别的类别，比如腮腺炎、风疹或猩红热。大多数儿童病长大后就不会再得了。很多儿童病可以给孩子打疫苗，让他们根本不得这种病。", "残疾和疾病不是一回事。有残疾的人可能某件事做不了，比如盲人看不见。但他并不因此就是病人，这对他来说是正常的，失明也不会哪天过去。不过也有慢性病：chronisch 是表示「时间」的词，这里指一个人患病很久甚至一辈子。"], "lemmas": [], "gloss": [{"w": "Grenze", "de": "Linie zwischen zwei Dingen", "zh": "界限"}, {"w": "Erkältung", "de": "leichte Krankheit mit Schnupfen und Husten", "zh": "感冒"}, {"w": "Bescheinigung", "de": "Papier, das etwas bestätigt", "zh": "证明"}, {"w": "ansteckenden", "de": "die man von anderen bekommen kann", "zh": "传染的"}, {"w": "Spucke", "de": "Flüssigkeit im Mund", "zh": "唾液"}, {"w": "chronische", "de": "die sehr lange dauern", "zh": "慢性的"}], "qs": [{"q": "Wann stellt der Arzt eine Bescheinigung aus?", "qZh": "医生什么时候开证明？", "answer": "Wenn die Krankheit schlimmer wird.", "wrong": ["Bei jeder kleinen Erkältung.", "Wenn man Urlaub will."]}, {"q": "Warum ist eine Erkältung ansteckend?", "qZh": "感冒为什么会传染？", "answer": "Viren sind in der Spucke und kommen beim Husten heraus.", "wrong": ["Weil man friert.", "Weil man zu wenig schläft."]}, {"q": "Was kann man gegen viele Kinderkrankheiten tun?", "qZh": "很多儿童病能怎么预防？", "answer": "Die Kinder impfen lassen.", "wrong": ["Viel Eis essen.", "Nichts."]}], "src": "改编自 Klexikon《Krankheit》", "url": "https://klexikon.zum.de/index.php?oldid=158309", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-036", "seg": 11, "title": "Erkältung", "de": ["Erkältung sagt man, wenn jemand an den Atemwegen krank wird. Die Atemwege gehen von der Lunge über den Hals und Rachen bis zu Mund und Nase. Wer erkältet ist, muss zum Beispiel husten, oder die Nase ist mit Nasenschleim verstopft. Eine Erkältung ist normalerweise harmlos und geht rasch von selbst wieder weg.", "Man kann sich erkälten, wenn man sich mit bestimmten Viren ansteckt. Manchmal kommen Bakterien hinzu, die die Erkältung schlimmer machen. Der Körper versucht, sich gegen die Viren zu wehren. Dafür hat er Abwehrkräfte, das Immunsystem. Je besser das Immunsystem funktioniert, desto weniger wird man erkältet.", "Die Erkältung kommt durch eine Ansteckung mit Viren. Die Viren stammen aus dem Körper eines anderen Menschen: Wenn dieser Mensch hustet, niest oder auch nur spricht, dann verbreitet er kleine Tröpfchen in der Luft. Andere Menschen, die diese Tröpfchen einatmen, können sich dann infizieren.", "Neben dieser Tröpfcheninfektion gibt es noch die Kontaktinfektion. Wer erkältet ist, hat manchmal Viren an den Händen. Das passiert zum Beispiel, wenn er sich an die Nase gefasst hat, etwa, um sie zu putzen. Wenn dieser Mensch einem anderen Menschen die Hand gibt, kann dieser andere Mensch sich infizieren. Oder beide fassen nacheinander denselben Gegenstand an.", "Obwohl man „Erkältung“ sagt, sind Wissenschaftler sich nicht sicher, welche Rolle Kälte spielt. Viele Menschen glauben, dass sie sich erkälten werden, wenn sie sich nicht warm genug anziehen oder lange in der Kälte draußen sind.", "Tatsächlich erkälten die Menschen sich meistens in der kalten Jahreszeit, also im Herbst und vor allem im Winter. Dafür kann es aber viele verschiedene Gründe geben. An sich sagen Wissenschafter: Die Erkältung kommt von Viren. Es kann aber sein, dass die Viren es in der kalten Jahreszeit leichter haben."], "zh": ["呼吸道生病就叫感冒。呼吸道从肺经过喉咙和咽部，一直到嘴和鼻子。感冒的人比如会咳嗽，或者鼻子被鼻涕堵住。感冒一般无害，很快会自己好。", "感染了某些病毒就可能感冒。有时还会有细菌加入，让感冒更重。身体会设法抵抗病毒，为此它有抵抗力，也就是免疫系统。免疫系统越好，感冒就越少。", "感冒是因为感染了病毒。病毒来自另一个人的身体：这个人咳嗽、打喷嚏甚至只是说话时，就把小飞沫散播到空气中。吸进这些飞沫的人就可能被感染。", "除了这种飞沫传染，还有接触传染。感冒的人手上有时有病毒，比如他摸过鼻子，像是擤鼻涕的时候。这个人和别人握手，对方就可能被感染。或者两人先后摸了同一样东西。", "虽然叫「Erkältung」（受凉），科学家并不确定寒冷起什么作用。很多人相信，穿得不够暖或者在外面冷的地方待久了就会感冒。", "人们确实大多在寒冷的季节感冒，也就是秋天，尤其是冬天。但这可能有很多不同的原因。科学家本来就说：感冒来自病毒。不过可能病毒在寒冷季节更容易传播。"], "lemmas": [], "gloss": [{"w": "Atemwegen", "de": "Teilen des Körpers, durch die die Luft geht", "zh": "呼吸道"}, {"w": "verstopft", "de": "zu, nicht mehr frei", "zh": "堵塞"}, {"w": "harmlos", "de": "nicht gefährlich", "zh": "无害的"}, {"w": "Abwehrkräfte", "de": "Kräfte des Körpers gegen Krankheiten", "zh": "抵抗力"}, {"w": "niest", "de": "Luft plötzlich durch Nase und Mund stößt", "zh": "打喷嚏"}, {"w": "infizieren", "de": "eine Krankheit bekommen", "zh": "感染"}], "qs": [{"q": "Woher kommt eine Erkältung?", "qZh": "感冒是从哪来的？", "answer": "Von Viren.", "wrong": ["Nur von kalter Luft.", "Von zu viel Essen."]}, {"q": "Was ist eine Kontaktinfektion?", "qZh": "接触传染是什么？", "answer": "Man bekommt Viren über die Hände oder Gegenstände.", "wrong": ["Man bekommt Viren durch Fernsehen.", "Man wird krank durch Sonne."]}, {"q": "Wann erkälten sich die meisten Menschen?", "qZh": "大多数人什么时候感冒？", "answer": "Im Herbst und vor allem im Winter.", "wrong": ["Im Sommer.", "Im Frühling."]}], "src": "改编自 Klexikon《Erkältung》", "url": "https://klexikon.zum.de/index.php?oldid=157950", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-037", "seg": 11, "title": "Grippe", "de": ["Die Grippe ist eine Krankheit, die durch Viren ausgelöst wird. In der Fachsprache heißt sie „Influenza“. Es gibt sie auf der ganzen Welt. Das Virus lebt auf der Schleimhaut. Schleimhäute gibt es in der Nase, im Mund und in den Augen.", "Das Virus kann auf verschiedene Weise dorthin kommen. Die häufigste Weise ist die Tröpfcheninfektion: Wenn jemand mit Grippe hustet oder niest, gelangen kleine Schleimtröpfchen mit Viren in die Luft. Diese bleiben an den Oberflächen von Gegenständen kleben, auch an den Händen. Man kann sich dann mit dem Virus anstecken, wenn man diese Gegenstände oder Hände berührt und sich danach an Nase, Mund oder Augen fasst.", "Eine Grippe ist so ähnlich wie eine Erkältung, meistens fühlt man sich aber deutlich kränker. Man ist sehr schwach und hat weniger Hunger als sonst. Man kann auch hohes Fieber oder Schüttelfrost bekommen. Bei Schüttelfrost wird einem kalt und man zittert. Oft hat man auch Kopfschmerzen. Wenn die Schleimhäute angeschwollen sind, kann man schlecht atmen. Wenn sie trocken sind, muss man husten. Manchmal ist einem auch übel, so dass man sich übergeben muss.", "Die Anzeichen einer Krankheit heißen in der Fachsprache „Symptome“. Bei der Grippe erscheinen sie sehr schnell, nachdem das Virus in den eigenen Körper gelangt ist. Die Zeit zwischen dem ersten Kontakt mit dem Virus und dem ersten Symptom nennt man Inkubationszeit. Die Symptome bleiben bei der Grippe zwischen sieben und 14 Tage lang.", "Man kann sich auch vor der Grippe schützen, bevor man sie bekommt. Dazu lässt man sich impfen. Dann steckt man sich nicht mehr so leicht an. Der beste und einfachste Schutz ist jedoch, dass man sich regelmäßig die Hände wäscht. Bei einer Begrüßung mit Handschlag überträgt man nämlich am meisten Viren. Übertragungen gibt es aber auch, wenn man Türklinken, Treppengeländer oder andere Handläufe anfasst und sich dann vor dem Händewaschen ins Gesicht greift."], "zh": ["流感是由病毒引起的疾病，专业术语叫 Influenza，全世界都有。病毒生活在黏膜上，鼻子、嘴和眼睛里都有黏膜。", "病毒可以通过不同的方式到达那里。最常见的是飞沫传染：得流感的人咳嗽或打喷嚏时，带病毒的小黏液飞沫进入空气。它们会粘在物品表面上，也会粘在手上。摸了这些东西或手，然后再碰鼻子、嘴或眼睛，就可能感染病毒。", "流感和感冒有点像，但大多会觉得病得重得多。人很虚弱，胃口比平时差，还可能发高烧或打寒战。打寒战时人觉得冷、发抖。常常还会头疼。黏膜肿起来就呼吸困难，黏膜干了就要咳嗽。有时还会恶心，甚至呕吐。", "疾病的迹象在专业术语里叫「症状」。流感的症状在病毒进入身体后很快出现。从第一次接触病毒到出现第一个症状的这段时间叫潜伏期。流感症状会持续七到十四天。", "也可以在得流感之前预防它，办法是打疫苗，这样就不那么容易被传染。但最好也最简单的保护是经常洗手。因为握手打招呼时传播的病毒最多。如果摸了门把手、楼梯扶手或其他扶手，没洗手就摸脸，也会传播病毒。"], "lemmas": [], "gloss": [{"w": "ausgelöst", "de": "verursacht, in Gang gesetzt", "zh": "引起"}, {"w": "Schleimhaut", "de": "feuchte Haut innen in Nase und Mund", "zh": "黏膜"}, {"w": "Schüttelfrost", "de": "starkes Zittern vor Kälte bei Fieber", "zh": "寒战"}, {"w": "angeschwollen", "de": "dicker geworden", "zh": "肿起来的"}, {"w": "übergeben", "de": "erbrechen, das Essen aus dem Mund herausbringen", "zh": "呕吐"}, {"w": "Türklinken", "de": "Griffe an Türen", "zh": "门把手"}], "qs": [{"q": "Wie heißt die Grippe in der Fachsprache?", "qZh": "流感的专业术语叫什么？", "answer": "Influenza.", "wrong": ["Erkältung.", "Allergie."]}, {"q": "Was ist die Inkubationszeit?", "qZh": "潜伏期是什么？", "answer": "Die Zeit vom Kontakt mit dem Virus bis zum ersten Symptom.", "wrong": ["Die Zeit im Krankenhaus.", "Die Zeit, bis man wieder gesund ist."]}, {"q": "Was ist der beste und einfachste Schutz vor Grippe?", "qZh": "最好最简单的流感预防是什么？", "answer": "Regelmäßig die Hände waschen.", "wrong": ["Viel Fernsehen.", "Keine Jacke tragen."]}], "src": "改编自 Klexikon《Grippe》", "url": "https://klexikon.zum.de/index.php?oldid=159216", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-038", "seg": 11, "title": "Fieber", "de": ["Man spricht von Fieber, wenn der Körper eines Menschen wärmer ist als normal. Das ist oft ein Zeichen, dass man krank ist, weil man sich Viren oder Bakterien eingefangen hat. Je wärmer der Körper ist, desto höher ist die Temperatur. Wie hoch das Fieber ist, misst man mit einem Thermometer.", "Die Temperatur unseres Körpers erhöht sich dabei nicht so sehr an Armen und Beinen, sondern mehr an Bauch, Brust und Kopf. Deshalb misst man das Fieber auch dort: meist im Mund, im Po oder auch im Ohr oder unter den Achseln. Der Regler für die Temperatur unseres Körpers sitzt im Gehirn. Wenn das Fieber steigt, empfindet man oft ein Frieren, wenn es sinkt, schwitzt man.", "Bei uns Menschen liegt die normale Körpertemperatur in aller Regel nicht über 37 Grad Celsius. Liegt sie über 38 Grad, dann sprechen Ärzte von Fieber. Liegt sie zwischen 37 einhalb und 38 Grad, sagen sie: „Die Temperatur ist erhöht.“ Bei Tieren kann die normale Temperatur anders sein.", "Wenn ein Mensch Fieber hat, behandelt der Arzt die Krankheit, die die Ursache des Fiebers ist. Wenn das jedoch nicht genügt und das Fieber sehr hoch bleibt, dann gibt er dem kranken Menschen ein Medikament, welches das Fieber senkt. Fieber über 40 Grad ist gefährlich."], "zh": ["人的身体比平常热，就叫发烧。这常常说明人病了，因为感染了病毒或细菌。身体越热，体温就越高。烧有多高要用体温计量。", "发烧时，体温升高主要不在胳膊和腿上，而在肚子、胸口和头部。所以量体温也在这些地方：大多在嘴里、肛门，或者耳朵里、腋下。调节体温的中枢在大脑里。体温上升时人常常觉得冷，下降时会出汗。", "我们人的正常体温一般不超过 37 摄氏度。超过 38 度，医生就说是发烧。在 37.5 到 38 度之间，他们说：「体温偏高。」动物的正常体温可能不一样。", "人发烧时，医生治疗引起发烧的疾病。如果这样还不够、烧一直很高，他就给病人吃退烧药。超过 40 度的高烧很危险。"], "lemmas": [], "gloss": [{"w": "eingefangen", "de": "sich angesteckt, bekommen (Krankheit)", "zh": "染上"}, {"w": "Thermometer", "de": "Gerät, das die Temperatur misst", "zh": "体温计"}, {"w": "Achseln", "de": "Stellen unter den Armen", "zh": "腋下"}, {"w": "Regler", "de": "Teil, das etwas steuert", "zh": "调节器"}, {"w": "schwitzt", "de": "Wasser kommt aus der Haut", "zh": "出汗"}, {"w": "senkt", "de": "macht niedriger", "zh": "降低"}], "qs": [{"q": "Womit misst man Fieber?", "qZh": "用什么量体温？", "answer": "Mit einem Thermometer.", "wrong": ["Mit einer Waage.", "Mit einer Uhr."]}, {"q": "Ab wie viel Grad sprechen Ärzte von Fieber?", "qZh": "多少度以上医生说是发烧？", "answer": "Über 38 Grad.", "wrong": ["Über 36 Grad.", "Über 42 Grad."]}, {"q": "Was fühlt man oft, wenn das Fieber steigt?", "qZh": "体温上升时常常有什么感觉？", "answer": "Man friert.", "wrong": ["Man schwitzt.", "Man hat Hunger."]}], "src": "改编自 Klexikon《Fieber》", "url": "https://klexikon.zum.de/index.php?oldid=158216", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-039", "seg": 11, "title": "Allergie", "de": ["Eine Allergie ist eine Reaktion des Körpers. Der Körper hält einen Stoff, den er bekommt, für Gift, obwohl der Stoff für andere Menschen gar nicht giftig ist. Allergien kommen häufig vor. Viele Menschen haben Allergien, besonders häufig gegen das Metall Nickel oder Pollen aus den Blüten.", "Wer eine Allergie hat, sollte versuchen, den Stoff zu meiden. Es kommt darauf an, wie stark die Allergie ist. Es kann sein, dass man allergisch auf einen Stoff reagiert, wenn man ihn isst. Das ist oft bei Erdnüssen so. Manchmal reicht es schon, etwas nur zu riechen oder zu berühren. Dann bekommen Allergiker Tränen in den Augen, Schnupfen, sie können schlecht atmen oder ihnen ist übel und sie müssen sich übergeben. Es kann auch passieren, dass sie zusammenklappen und ohnmächtig werden.", "Wenn man nicht weiß, dass man eine Allergie hat, kann das gefährlich werden. Man kann aber beim Arzt einen Allergietest machen. Dazu ritzt der Arzt die Haut an mehreren Stellen leicht ein und tropft verschiedene Stoffe darauf. Gegen solche Stoffe sind manche Leute allergisch. Wenn die Haut auf einen oder mehrere Stoffe reagiert und anschwillt, ist das ein Zeichen für eine Allergie.", "Man kann in der Apotheke ein Gegenmittel gegen bestimmte Allergien kaufen. Dann reagiert der Körper für eine kurze Zeit nicht mehr allergisch. Es gibt auch Medikamente, die man einnehmen kann, wenn die Allergie schon da ist. Dann sind die Folgen weniger schlimm."], "zh": ["过敏是身体的一种反应。身体把摄入的某种物质当成毒物，尽管这种物质对别人一点也不毒。过敏很常见。很多人有过敏，特别常见的是对金属镍或花粉过敏。", "有过敏的人应该尽量避开那种物质，这要看过敏有多严重。可能是吃了某种东西才过敏，花生常常就是这样。有时只要闻一闻或碰一下就够了。这时过敏的人会流眼泪、流鼻涕、呼吸困难，或者恶心呕吐。也可能突然倒下、昏过去。", "不知道自己有过敏可能会很危险。不过可以在医生那里做过敏测试。医生在皮肤上几个地方轻轻划一下，滴上不同的物质，有些人对这些物质过敏。如果皮肤对一种或几种物质有反应、肿起来，就说明有过敏。", "可以在药店买针对某些过敏的药，这样身体在短时间内就不再过敏。也有过敏发作时可以吃的药，这样后果会轻一些。"], "lemmas": [], "gloss": [{"w": "Pollen", "de": "feiner Staub aus Blüten", "zh": "花粉"}, {"w": "meiden", "de": "nicht in die Nähe kommen", "zh": "避开"}, {"w": "Schnupfen", "de": "Nase läuft", "zh": "流鼻涕"}, {"w": "ohnmächtig", "de": "plötzlich ohne Bewusstsein", "zh": "昏过去的"}, {"w": "anschwillt", "de": "dicker wird", "zh": "肿起来"}, {"w": "Apotheke", "de": "Geschäft für Medikamente", "zh": "药店"}], "qs": [{"q": "Was ist eine Allergie?", "qZh": "过敏是什么？", "answer": "Der Körper hält einen harmlosen Stoff für Gift.", "wrong": ["Eine Krankheit durch Viren.", "Ein Unfall."]}, {"q": "Wogegen sind besonders viele Menschen allergisch?", "qZh": "特别多的人对什么过敏？", "answer": "Gegen Nickel oder Pollen.", "wrong": ["Gegen Wasser.", "Gegen Brot."]}, {"q": "Wie macht der Arzt einen Allergietest?", "qZh": "医生怎样做过敏测试？", "answer": "Er ritzt die Haut und tropft Stoffe darauf.", "wrong": ["Er misst das Fieber.", "Er macht ein Foto."]}], "src": "改编自 Klexikon《Allergie》", "url": "https://klexikon.zum.de/index.php?oldid=158918", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-040", "seg": 11, "title": "Krankenhaus", "de": ["Ein Krankenhaus oder Spital ist ein Ort, an dem Kranke sind. Dort versucht man sie gesund zu machen oder ihr Leiden zu lindern. Manche Kranke leben für eine Weile im Krankenhaus, andere sind dort nur ganz kurz. Viele Kinder werden heute in einem Krankenhaus geboren und nicht zu Hause.", "Früher haben sich Tempel und Kirchen um Kranke gekümmert. In der christlichen Welt waren es Nonnen in den Klöstern. Die Menschen glaubten, dass es durch einen Gott oder den Teufel kam, wenn jemand krank wurde. Heute gehören noch viele Krankenhäuser zu einer Kirche, viele andere zum Staat. Manche Krankenhäuser gehören einem Unternehmen, das Geld für sich selbst verdienen will.", "Im Krankenhaus arbeiten nicht nur Ärzte. Auch Krankenschwestern und Krankenpfleger kümmern sich um die Kranken. Köche sorgen dafür, dass die Kranken etwas zu essen haben, wieder andere Menschen machen sauber oder reparieren etwas.", "Wegen der vielen Menschen, die dort arbeiten, sind Krankenhäuser sehr teuer. Außerdem braucht man teure Geräte, zum Beispiel in der Chirurgie, zum Röntgen oder für ähnliche Untersuchungen. Ein großes Krankenhaus kann sich so etwas eher leisten als ein kleines, weil dort mehr Patienten sind."], "zh": ["医院（Krankenhaus 或 Spital）是病人待的地方。人们在那里设法让他们恢复健康，或者减轻他们的痛苦。有些病人在医院住一段时间，有些只待很短。今天很多孩子在医院出生，而不是在家里。", "以前是寺庙和教堂照顾病人，在基督教世界是修道院的修女。人们相信，有人生病是神或魔鬼造成的。今天仍有很多医院属于教会，很多属于国家。有些医院属于想为自己挣钱的公司。", "医院里工作的不只是医生。护士和护工也照顾病人。厨师负责让病人有饭吃，还有人打扫卫生或修东西。", "因为在那里工作的人很多，医院很贵。此外还需要昂贵的设备，比如外科、拍 X 光片或类似的检查用的设备。大医院比小医院更负担得起这些，因为那里病人更多。"], "lemmas": [], "gloss": [{"w": "lindern", "de": "weniger schlimm machen", "zh": "减轻"}, {"w": "Leiden", "de": "Schmerzen, Krankheit", "zh": "痛苦"}, {"w": "Nonnen", "de": "Frauen, die in einem Kloster leben", "zh": "修女"}, {"w": "Teufel", "de": "das Böse in der Religion", "zh": "魔鬼"}, {"w": "Chirurgie", "de": "Medizin, bei der man operiert", "zh": "外科"}, {"w": "Röntgen", "de": "Bilder vom Inneren des Körpers machen", "zh": "拍 X 光"}], "qs": [{"q": "Wer kümmerte sich früher um Kranke?", "qZh": "以前谁照顾病人？", "answer": "Tempel, Kirchen und Nonnen.", "wrong": ["Die Polizei.", "Die Schulen."]}, {"q": "Wer arbeitet außer Ärzten im Krankenhaus?", "qZh": "除了医生，医院里还有谁工作？", "answer": "Krankenschwestern, Köche und andere.", "wrong": ["Nur Patienten.", "Lehrer."]}, {"q": "Warum sind Krankenhäuser so teuer?", "qZh": "医院为什么这么贵？", "answer": "Viele Menschen arbeiten dort und die Geräte sind teuer.", "wrong": ["Das Essen ist sehr teuer.", "Sie sind sehr groß gebaut."]}], "src": "改编自 Klexikon《Krankenhaus》", "url": "https://klexikon.zum.de/index.php?oldid=158873", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-041", "seg": 11, "title": "Erste Hilfe", "de": ["Erste Hilfe nennt man es, wenn man einem Verletzten hilft. Meist ist kein Arzt dabei, wenn ein Unfall passiert. Wer es sieht, muss dem Verletzten die Erste Hilfe leisten, damit die Verletzung nicht noch schlimmer wird oder der Verletzte gar stirbt.", "Zuerst muss man dafür sorgen, dass der Verletzte nicht mehr in Gefahr ist. Wenn er zum Beispiel auf einer Straße liegt, achtet man darauf, dass er nicht überfahren wird. Dann ruft man den Rettungsdienst, etwa mit dem Notruf: In Europa wählt man dazu die Nummer 112.", "Bis der Rettungsdienst kommt, leistet man die eigentliche Erste Hilfe. Man sorgt zum Beispiel dafür, dass der Verletzte auf eine bestimmte Weise liegt. Bei dieser stabilen Seitenlage kann Blut aus dem Mund herausfließen. Sonst erstickt der Verletzte womöglich daran. Wenn er nicht mehr atmet, braucht er eine künstliche Beatmung: Dabei bläst man Luft in seinen Mund.", "Wie man Erste Hilfe leistet, muss man lernen. Unterricht in Erster Hilfe kann man in einem Kurs bekommen. Das Rote Kreuz zum Beispiel bietet solche Kurse an. Manche Leute müssen sogar daran teilgenommen haben, Erzieher und Sportlehrer zum Beispiel. In Deutschland darf man nur Auto fahren, wenn man einen Erste-Hilfe-Kurs gehabt hat.", "Wer einen Verletzten sieht, muss ihm helfen. Wer sich trotzdem nicht um ihn kümmert, kann dafür bestraft werden. Viele Leute haben Angst zu helfen. Sie ekeln sich oder fürchten, dass sie etwas falsch machen. Meist ist es aber besser, überhaupt zu helfen als gar nicht. Zumindest ist es wichtig, Hilfe zu holen und andere Menschen anzusprechen, dass sie mithelfen."], "zh": ["帮助伤员就叫急救。事故发生时大多没有医生在场。看到的人必须给伤员急救，免得伤势更重，甚至伤员死去。", "首先要确保伤员不再有危险。比如他躺在马路上，就要注意别让他被车轧到。然后打电话叫救护，比如拨急救电话：在欧洲拨 112。", "救护人员到来之前，要做真正的急救。比如让伤员以一种特定的方式躺着。在这种稳定侧卧位下，血可以从嘴里流出来，否则伤员可能会被呛死。如果他不再呼吸，就需要人工呼吸：往他嘴里吹气。", "怎样急救需要学习。可以参加急救课程，比如红十字会就开这样的课。有些人甚至必须上过这种课，比如幼教老师和体育老师。在德国，必须上过急救课才能开车。", "看到伤员的人必须帮助他。如果不管不顾，可能受罚。很多人怕帮忙，他们觉得恶心，或者怕做错。但大多数情况下，帮总比不帮好。至少重要的是去叫人帮忙，并请别人一起帮。"], "lemmas": [], "gloss": [{"w": "Verletzten", "de": "jemandem, der sich wehgetan hat", "zh": "伤员"}, {"w": "überfahren", "de": "von einem Auto getroffen", "zh": "轧到"}, {"w": "Rettungsdienst", "de": "Krankenwagen und Helfer im Notfall", "zh": "救护服务"}, {"w": "erstickt", "de": "stirbt, weil er keine Luft bekommt", "zh": "窒息"}, {"w": "Beatmung", "de": "Luft in die Lunge geben", "zh": "人工呼吸"}, {"w": "ekeln", "de": "etwas eklig finden", "zh": "觉得恶心"}], "qs": [{"q": "Welche Notrufnummer wählt man in Europa?", "qZh": "在欧洲拨什么急救号码？", "answer": "112.", "wrong": ["911.", "110."]}, {"q": "Was macht man zuerst bei einem Unfall?", "qZh": "发生事故时首先做什么？", "answer": "Dafür sorgen, dass der Verletzte nicht mehr in Gefahr ist.", "wrong": ["Ein Foto machen.", "Weggehen."]}, {"q": "Was braucht man in Deutschland für den Führerschein?", "qZh": "在德国考驾照需要什么？", "answer": "Einen Erste-Hilfe-Kurs.", "wrong": ["Einen Sportkurs.", "Einen Kochkurs."]}], "src": "改编自 Klexikon《Erste Hilfe》", "url": "https://klexikon.zum.de/index.php?oldid=158244", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-042", "seg": 11, "title": "Notruf", "de": ["Mit einem Notruf zeigt man, dass man Hilfe braucht. Die Hilfe braucht man selbst oder jemand anders. In ganz Europa ist „112“ die Notrufnummer. Wer diese Nummer mit dem Telefon wählt, spricht mit jemandem, der weiß, was weiter getan werden muss. Wenn es nötig ist, kommt dann die Feuerwehr, die Polizei oder ein Krankenwagen.", "Wer einen Notruf abschickt, gibt an, wo man ist und was genau passiert ist, zum Beispiel ein Unfall. Wichtig ist es zu sagen, ob jemand verletzt wurde. Man sagt auch seinen Namen und eine Nummer, unter der man erreichbar ist.", "Zuerst hat man in London eine solche Notrufnummer eingerichtet. Im Jahr 1937 hatte es einen großen Brand gegeben. Seitdem erhielt man Hilfe unter der Nummer 999. In den Jahren nach dem Zweiten Weltkrieg dauerte es noch viele Jahre, bis in den meisten Ländern solche Nummern eingeführt wurden.", "Es gibt auch Notruftelefone, mit denen man nur Notrufe senden kann. Sie stehen manchmal in der Stadt, oft aber auch an wichtigen Straßen. Wenn ein Notruf eintrifft, weiß man immer gleich, wo das Notruftelefon steht.", "Manche Menschen machen einen Notruf ohne Grund, nur so aus Spaß. Das ist ein falscher Gebrauch, ein Missbrauch. Dafür wird man streng bestraft, in manchen Ländern sogar mit Gefängnis. Wenn etwa ein Krankenwagen zu einem falschen Ort geschickt wird, ist er nicht da, wenn man ihn wirklich braucht."], "zh": ["打急救电话表示需要帮助，可能是自己需要，也可能是别人。在整个欧洲，急救号码是 112。拨这个号码，就会和知道接下来该怎么做的人通话。需要的话，消防队、警察或救护车就会来。", "打急救电话的人要说明自己在哪儿、到底发生了什么，比如出了事故。重要的是说清楚有没有人受伤。还要说自己的名字和一个能联系上自己的号码。", "最早在伦敦设立了这样的急救号码。1937 年那里发生过一场大火，从那以后拨 999 就能得到帮助。第二次世界大战后，又过了很多年，大多数国家才设立了这样的号码。", "还有只能拨急救电话的急救电话亭。它们有时在城里，也常在重要道路旁。有急救电话打进来时，总能马上知道这部急救电话在哪儿。", "有些人无缘无故地打急救电话，只是为了好玩。这是错误使用，是滥用。这样做会受到严厉惩罚，有些国家甚至会坐牢。比如救护车被派到错误的地方，真正需要时它就不在。"], "lemmas": [], "gloss": [{"w": "Notrufnummer", "de": "Telefonnummer für Notfälle", "zh": "急救号码"}, {"w": "Feuerwehr", "de": "Leute, die Feuer löschen", "zh": "消防队"}, {"w": "erreichbar", "de": "so, dass man jemanden anrufen kann", "zh": "联系得上的"}, {"w": "Brand", "de": "großes Feuer", "zh": "火灾"}, {"w": "eintrifft", "de": "ankommt", "zh": "到达"}, {"w": "Missbrauch", "de": "falscher, schlechter Gebrauch", "zh": "滥用"}], "qs": [{"q": "Was soll man bei einem Notruf sagen?", "qZh": "打急救电话时该说什么？", "answer": "Wo man ist, was passiert ist und ob jemand verletzt ist.", "wrong": ["Nur seinen Namen.", "Wie das Wetter ist."]}, {"q": "Wo gab es die erste Notrufnummer?", "qZh": "第一个急救号码在哪里？", "answer": "In London.", "wrong": ["In Berlin.", "In New York."]}, {"q": "Warum ist ein Notruf aus Spaß schlimm?", "qZh": "为什么开玩笑打急救电话很恶劣？", "answer": "Der Krankenwagen fehlt dann, wenn man ihn wirklich braucht.", "wrong": ["Das Telefon geht kaputt.", "Es kostet viel Geld."]}], "src": "改编自 Klexikon《Notruf》", "url": "https://klexikon.zum.de/index.php?oldid=158250", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-043", "seg": 11, "title": "Unfall", "de": ["Bei einem Unfall passiert plötzlich etwas, bei dem unfreiwillig Menschen oder Sachen verletzt oder beschädigt werden. Es kommt also zu Personenschaden oder Sachschaden oder zu beidem. Auch unsere Umwelt kann durch Unfälle Schaden nehmen, zum Beispiel durch extreme Wasser- oder Luft-Verschmutzung.", "Unfälle unterscheidet man danach, wo sie passiert sind. So gibt es Unfälle bei der Arbeit, im Verkehr und mit Autos, in der Freizeit oder beim Sport. Viele Unfälle geschehen, weil Menschen nicht aufpassen oder Fehler machen. Tatsächlich passieren viele Unfälle, bei denen Menschen zu Schaden kommen, bei irgendeiner Hausarbeit, zum Beispiel weil jemand von einer Leiter fällt oder einen Stromschlag bekommt.", "Für Unfälle gibt es eine ganze Reihe von Gründen. Zu ihnen zählen Nachlässigkeit und menschliches Versagen, wenn also jemand etwas schlecht oder falsch gemacht oder etwas Notwendiges unterlassen hat. Ein weiterer Grund für Unfälle können technische Mängel oder fehlerhafte Maschinen oder Bauteile sein.", "Oft passieren Unfälle, obwohl man alles richtig gemacht hat, alle Dinge in Ordnung sind und nichts darauf hindeutet, dass gleich etwas passieren könnte. Wenn dann doch etwas geschieht, spricht man von „Höherer Gewalt“. Oft spielt der Zufall eine Rolle, was dann hin und wieder eine „Verkettung unglücklicher Umstände“ genannt wird."], "zh": ["事故就是突然发生了什么，人或物非自愿地受了伤或损坏。所以会有人身伤害或财产损失，或者两者都有。我们的环境也会因事故受损，比如严重的水污染或空气污染。", "事故按发生的地方来区分。所以有工伤事故、交通和车辆事故、休闲或运动中的事故。很多事故是因为人不小心或犯了错。实际上，很多伤人的事故发生在做某种家务时，比如有人从梯子上摔下来或触电。", "事故的原因有一大串。其中包括疏忽和人为失误，也就是有人把事做得很差、做错了，或者没做必须做的事。另一个原因可能是技术缺陷，或者机器、零件有毛病。", "常常事故发生时，人们明明一切都做对了，所有东西都完好，也没有任何迹象表明马上会出事。如果还是出了事，就叫「不可抗力」。偶然常常起作用，人们有时就把它叫作「一连串不幸的巧合」。"], "lemmas": [], "gloss": [{"w": "unfreiwillig", "de": "ohne dass man es will", "zh": "非自愿地"}, {"w": "Leiter", "de": "Gerät mit Stufen zum Hochsteigen", "zh": "梯子"}, {"w": "Stromschlag", "de": "wenn Strom durch den Körper fließt", "zh": "触电"}, {"w": "Nachlässigkeit", "de": "wenn man nicht sorgfältig ist", "zh": "疏忽"}, {"w": "Mängel", "de": "Fehler, Probleme", "zh": "缺陷"}, {"w": "Umstände", "de": "die Situation, wie etwas passiert", "zh": "情况"}], "qs": [{"q": "Wo passieren viele Unfälle, bei denen Menschen verletzt werden?", "qZh": "很多伤人的事故发生在哪里？", "answer": "Bei der Hausarbeit.", "wrong": ["Nur im Flugzeug.", "Nur beim Fußball."]}, {"q": "Was ist ein technischer Grund für Unfälle?", "qZh": "事故的技术原因是什么？", "answer": "Fehlerhafte Maschinen oder Bauteile.", "wrong": ["Zu viel Schlaf.", "Schönes Wetter."]}, {"q": "Was nennt man „Höhere Gewalt“?", "qZh": "什么叫「不可抗力」？", "answer": "Ein Unfall, obwohl alle alles richtig gemacht haben.", "wrong": ["Ein Unfall wegen Alkohol.", "Ein Streit unter Nachbarn."]}], "src": "改编自 Klexikon《Unfall》", "url": "https://klexikon.zum.de/index.php?oldid=154958", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-044", "seg": 11, "title": "Schmerz", "de": ["Der Schmerz ist ein Gefühl im Körper. Es kann unangenehm oder sogar unerträglich sein. Es gibt unterschiedliche Arten von Schmerzen. Sie können durch Verletzungen oder Krankheiten entstehen. Verletzt oder krank kann nicht nur der Körper sein, sondern auch die Seele.", "Jeder Mensch empfindet Schmerz anders. Wenn man zum Beispiel verschiedenen Menschen denselben Stromschlag an derselben Körperstelle zufügt, empfindet lange nicht jeder den Schmerz als gleich stark. Auch gibt es unterschiedliche Formen von Schmerz. Schmerzen können sich wie Stiche oder ein unangenehmes Ziehen anfühlen.", "Schmerz kann den Menschen auf eine Krankheit aufmerksam machen. Wenn es schlimm ist, kann man einen Arzt aufsuchen. Der kann oft verhindern, dass die Krankheit noch schlimmer wird. Auch ein Sonnenbrand ist so eine Warnung, damit man nicht noch länger an der Sonne bleibt.", "Gefühle können Schmerzen bestimmen. Traurigkeit kann den Schmerz verstärken und Glücklichsein kann den Schmerz verringern. Es kann aber auch umgekehrt sein: Wer immer krank ist, kann dadurch erst traurig werden."], "zh": ["疼痛是身体里的一种感觉，可能让人不舒服，甚至难以忍受。疼痛有不同种类，可能由受伤或疾病引起。受伤或生病的不只是身体，也可以是心灵。", "每个人对疼痛的感受都不一样。比如给不同的人在身体同一个部位施加同样的电击，远不是每个人都觉得一样疼。疼痛的形式也不同，可能感觉像针扎，或者像一种难受的牵拉。", "疼痛可以提醒人注意疾病。严重的话可以去看医生，医生常常能防止病情加重。晒伤也是这样一种警告，让人不要继续待在太阳下。", "情绪会影响疼痛。悲伤会让疼痛加重，快乐会让疼痛减轻。但也可能反过来：总是生病的人可能因此才变得悲伤。"], "lemmas": [], "gloss": [{"w": "unangenehm", "de": "nicht schön, man mag es nicht", "zh": "难受的"}, {"w": "empfindet", "de": "fühlt", "zh": "感受"}, {"w": "zufügt", "de": "antut (etwas Schlechtes)", "zh": "施加"}, {"w": "Stiche", "de": "Gefühle wie von einer Nadel", "zh": "刺痛"}, {"w": "aufsuchen", "de": "zu jemandem hingehen", "zh": "去找"}, {"w": "verringern", "de": "kleiner machen", "zh": "减轻"}], "qs": [{"q": "Wodurch können Schmerzen entstehen?", "qZh": "疼痛可能由什么引起？", "answer": "Durch Verletzungen oder Krankheiten.", "wrong": ["Nur durch Kälte.", "Durch gutes Essen."]}, {"q": "Wovor warnt ein Sonnenbrand?", "qZh": "晒伤是在警告什么？", "answer": "Nicht noch länger in der Sonne zu bleiben.", "wrong": ["Mehr zu essen.", "Schneller zu laufen."]}, {"q": "Wie können Gefühle Schmerzen beeinflussen?", "qZh": "情绪怎样影响疼痛？", "answer": "Traurigkeit verstärkt, Glücklichsein verringert Schmerzen.", "wrong": ["Gefühle haben keinen Einfluss.", "Glück macht Schmerzen stärker."]}], "src": "改编自 Klexikon《Schmerz》", "url": "https://klexikon.zum.de/index.php?oldid=157991", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-045", "seg": 11, "title": "Rücken", "de": ["Der Rücken ist die hintere Seite des Oberkörpers. Er liegt also genau auf der anderen Seite als der Bauch und die Brust. Bei den Menschen ist der Rücken hinten, weil sie aufrecht gehen. Bei den meisten Tieren ist er oben. Bei den Vögeln ist er irgendwo zwischendrin.", "Das Wort „Rücken“ braucht man aber noch für andere Dinge: Jedes Buch hat einen Rücken. Das ist das schmale Teil zwischen dem vorderen und dem hinteren Deckel. In einer Bibliothek sieht man also bei den meisten Büchern nur den Rücken. Jedes Blatt und viele andere Dinge haben auch eine Rückseite. Damit ist gemeint, was hinten liegt und was man meist erst sieht, wenn man den Gegenstand umdreht.", "An der Wirbelsäule beginnen längliche Knochen, die Rippen. Sie reichen bis zur Brust. Außerdem gibt es am Rücken sehr viele Muskeln. Damit können wir uns drehen, seitwärts beugen, strecken und aufrichten. Meist müssen wir den Rücken aber einfach aufrecht halten, zum Beispiel beim Sitzen. Dazu braucht es wiederum andere Muskeln. Viele Rückenmuskeln helfen auch mit beim Atmen, denn dabei heben wir den Brustkorb und lassen ihn wieder zusammensinken.", "Alle Sportler trainieren ihre Rückenmuskulatur, denn ohne sie geht gar nichts. Große Probleme gibt es beim langen Sitzen, denn darauf hat die Evolution unseren Körper nicht ausgerichtet. Dies kommt vor allem bei langer Arbeit am Computer vor. Meist bleibt man dabei immer in derselben Stellung. So können sich einzelne Muskeln verkrampfen und es kann zu großen Schmerzen kommen. So ein plötzlich auftretender Schmerz ist der Hexenschuss."], "zh": ["背是上半身的后面，正好在肚子和胸口的另一面。人的背在后面，因为人直立行走。大多数动物的背在上面，鸟的背大概在两者之间。", "Rücken 这个词还用于别的东西：每本书都有书脊，就是前后封面之间窄窄的那部分。所以在图书馆里，大多数书只能看到书脊。每张纸和很多别的东西也有背面，指的是在后面、大多要把东西翻过来才看得到的那一面。", "从脊柱开始长出长条形的骨头，就是肋骨，它们一直延伸到胸前。此外背上还有很多肌肉，靠它们我们能转身、侧弯、伸展和挺直。但我们大多时候只需要让背保持挺直，比如坐着的时候，这又需要别的肌肉。很多背部肌肉也帮助呼吸，因为呼吸时我们要抬起胸廓，再让它落下。", "所有运动员都锻炼背部肌肉，因为没有它们什么都干不了。久坐会带来大问题，因为进化没有让我们的身体适应这个。这主要发生在长时间用电脑工作时。这时人大多保持同一个姿势，个别肌肉可能抽筋，引起剧痛。这种突然出现的疼痛叫腰闪（Hexenschuss）。"], "lemmas": [], "gloss": [{"w": "aufrecht", "de": "gerade nach oben", "zh": "直立的"}, {"w": "Deckel", "de": "Teil, das etwas oben oder vorne zumacht", "zh": "封面、盖子"}, {"w": "Wirbelsäule", "de": "Knochen in der Mitte des Rückens", "zh": "脊柱"}, {"w": "Rippen", "de": "Knochen um die Brust", "zh": "肋骨"}, {"w": "ausgerichtet", "de": "passend gemacht für", "zh": "适应"}, {"w": "verkrampfen", "de": "fest und hart werden (Muskeln)", "zh": "抽筋"}], "qs": [{"q": "Warum ist der Rücken beim Menschen hinten?", "qZh": "人的背为什么在后面？", "answer": "Weil Menschen aufrecht gehen.", "wrong": ["Weil Menschen schwimmen.", "Weil Menschen Bücher lesen."]}, {"q": "Was sieht man in einer Bibliothek bei den meisten Büchern?", "qZh": "在图书馆里大多数书能看到什么？", "answer": "Nur den Rücken.", "wrong": ["Nur die erste Seite.", "Gar nichts."]}, {"q": "Warum ist langes Sitzen ein Problem?", "qZh": "久坐为什么是问题？", "answer": "Die Muskeln können sich verkrampfen.", "wrong": ["Man wird zu schnell.", "Man bekommt Hunger."]}], "src": "改编自 Klexikon《Rücken》", "url": "https://klexikon.zum.de/index.php?oldid=160486", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-046", "seg": 11, "title": "Blutspende", "de": ["Eine Blutspende ist die freiwillige Abgabe von Blut, beispielsweise in einem Krankenhaus. Jeder gesunde Mensch darf Blut spenden. Ausgenommen sind Kinder und Jugendliche unter 18 Jahren, Schwangere und alte Menschen. Nach einer Blutspende muss man mindestens zwei Monate warten, damit der Körper wieder neues Blut bilden kann.", "Bei einem Unfall oder bei einer Operation kann ein Mensch viel Blut verlieren. Wenn der Verletzte in das Krankenhaus kommt, erhält er dann einen oder auch mehrere Beutel von dem Blut, das vorher andere Leute gespendet haben. Es kann aber auch sein, dass jemand Blut braucht, weil er eine schlimme Krankheit wie Krebs hat.", "Die meisten Spender erhalten kein Geld für ihre Blutspende. Sie machen dies freiwillig, um anderen Menschen zu helfen und etwas Gutes zu tun. Das ist sehr wichtig, denn es ist nicht möglich, Blut künstlich herzustellen. Deshalb braucht man unbedingt genug Blutspender.", "Zuerst füllt man einen Fragebogen aus und wird kurz untersucht, damit man dem Arzt zeigt, dass man gesund ist. Danach legt man sich auf eine Liege. Mit einer kleinen Nadel sticht eine Krankenschwester dann in die Armbeuge. Die Nadel ist mit einem langen Schlauch verbunden, der zu einem Beutel führt, in dem das Blut gesammelt wird. In den Beutel passt ein halber Liter Blut. Sobald der Beutel voll ist, entfernt eine Krankenschwester die Nadel.", "Wenn man mit der Blutspende fertig ist, muss man noch ungefähr zwanzig Minuten auf der Liege warten, damit sich der Körper an die kleinere Menge Blut im Körper gewöhnt. Außerdem bekommt man nach der Blutspende etwas zu essen und zu trinken, weil die Abnahme von Blut für den Körper anstrengend ist. Vielleicht fühlt der Spender sich auch etwas müde. Meistens verläuft die Blutspende aber ohne Schwierigkeiten und ist für den Spender ziemlich unkompliziert."], "zh": ["献血是自愿捐出血液，比如在医院里。每个健康的人都可以献血，18 岁以下的儿童和青少年、孕妇和老人除外。献血后至少要等两个月，让身体重新造出新的血。", "出了事故或做手术时，人可能失很多血。伤员到医院后，会输上一袋或好几袋别人事先捐的血。但也可能有人因为得了癌症之类的重病而需要血。", "大多数献血者献血拿不到钱。他们是自愿的，为了帮助别人、做好事。这非常重要，因为血液无法人工制造，所以一定要有足够的献血者。", "先填一张问卷，做个简单检查，向医生证明自己健康。然后躺到一张躺椅上。护士用一根小针扎进肘弯，针连着一根长管子，通到一个收集血液的袋子。袋子能装半升血。袋子一满，护士就把针拔出来。", "献完血还要在躺椅上等大约二十分钟，让身体适应体内血量变少。此外献血后会给些吃的喝的，因为抽血对身体来说很累。献血的人也许还会有点累。但献血大多很顺利，对献血者来说相当简单。"], "lemmas": [], "gloss": [{"w": "freiwillige", "de": "ohne Zwang, weil man es will", "zh": "自愿的"}, {"w": "Schwangere", "de": "Frauen, die ein Baby erwarten", "zh": "孕妇"}, {"w": "Beutel", "de": "weiche Tasche aus Plastik", "zh": "袋子"}, {"w": "Fragebogen", "de": "Blatt mit Fragen zum Ausfüllen", "zh": "问卷"}, {"w": "Armbeuge", "de": "Innenseite des Ellenbogens", "zh": "肘弯"}, {"w": "Schlauch", "de": "lange, weiche Röhre", "zh": "管子"}], "qs": [{"q": "Wer darf kein Blut spenden?", "qZh": "谁不能献血？", "answer": "Kinder unter 18 Jahren und Schwangere.", "wrong": ["Alle Frauen.", "Alle Sportler."]}, {"q": "Warum braucht man unbedingt genug Blutspender?", "qZh": "为什么一定要有足够的献血者？", "answer": "Man kann Blut nicht künstlich herstellen.", "wrong": ["Blut wird sehr schnell schlecht.", "Ärzte trinken Blut."]}, {"q": "Wie viel Blut passt in einen Beutel?", "qZh": "一个袋子能装多少血？", "answer": "Ein halber Liter.", "wrong": ["Fünf Liter.", "Ein Glas."]}], "src": "改编自 Klexikon《Blutspende》", "url": "https://klexikon.zum.de/index.php?oldid=154082", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-047", "seg": 11, "title": "Atmung", "de": ["Bei der Atmung geht es darum, wie Tiere zu Sauerstoff kommen. Sauerstoff gibt es in der Luft und im Wasser. Tiere kommen auf verschiedene Weise an ihren Sauerstoff. Ohne zu atmen stirbt jedes Tier nach kurzer Zeit.", "Säugetiere und somit auch Menschen atmen mit Lungen. Eine Lunge saugt Luft ein und stößt sie wieder aus. In den feinen Lungenbläschen gelangt der Sauerstoff ins Blut. Das Blut bringt den Sauerstoff zu den Zellen und nimmt von dort Kohlendioxid mit. In der Lunge gelangt das Kohlendioxid vom Blut in die Luft dort, danach verlässt es den Körper beim Ausatmen. So atmen außer den Säugetieren die Amphibien, die Reptilien, die Vögel und einige Arten von Schnecken.", "Fische atmen durch Kiemen. Sie saugen Wasser an und lassen es durch die Kiemen gleiten. Dort ist die Haut sehr dünn und hat viele Adern. Die nehmen den Sauerstoff auf. Es gibt auch noch andere Tiere, die so atmen. Einige leben im Wasser, andere an Land.", "Eine weitere Möglichkeit ist die Atmung durch Tracheen. Das sind feine Röhrchen, die auf der Außenseite eines Tiers enden. Sie sind dort offen. Die Luft gelangt in die Tracheen und von dort in den ganzen Körper. So atmen Insekten, Tausendfüßer und einige Arten von Spinnentieren.", "Durch Krankheiten kann das Atmen schwerer werden. Unsere Atmung funktioniert über die Lunge und die Luftwege. Wenn dort etwas krank wird, gelangt weniger Sauerstoff in den Körper, und wir fühlen uns oft müde oder schlapp.", "Das passiert zum Beispiel bei einer Erkältung. Dabei läuft nicht nur die Nase, sondern manchmal sind auch die Bronchien entzündet, und es entsteht Husten. Der Körper versucht, Schleim loszuwerden, der die Atemwege blockiert. Solche Erkältungen sind meistens harmlos, doch für eine Weile wird das Atmen anstrengender."], "zh": ["呼吸讲的是动物怎样获得氧气。空气里和水里都有氧气。动物用不同的方式获得氧气。任何动物不呼吸很快就会死。", "哺乳动物，也包括人，用肺呼吸。肺把空气吸进来，再排出去。在细小的肺泡里，氧气进入血液。血液把氧气送到细胞，再从那里带走二氧化碳。在肺里，二氧化碳从血液进入那里的空气，呼气时离开身体。除了哺乳动物，两栖动物、爬行动物、鸟类和一些蜗牛也这样呼吸。", "鱼用鳃呼吸。它们吸进水，让水流过鳃。那里的皮肤很薄，有很多血管，血管吸收氧气。还有别的动物也这样呼吸，有的生活在水里，有的在陆地上。", "另一种方式是用气管呼吸。气管是细小的管子，开口在动物身体外面。空气进入气管，再从那里到达全身。昆虫、千足虫和一些蛛形动物这样呼吸。", "疾病会让呼吸变困难。我们靠肺和呼吸道呼吸。如果那里生了病，进入身体的氧气就少了，我们常常觉得疲倦乏力。", "比如感冒时就会这样。这时不只流鼻涕，有时支气管也发炎，引起咳嗽。身体想把堵住呼吸道的黏液排出去。这种感冒大多无害，但有一阵子呼吸会更费劲。"], "lemmas": [], "gloss": [{"w": "Sauerstoff", "de": "Gas in der Luft, das wir zum Leben brauchen", "zh": "氧气"}, {"w": "Lungenbläschen", "de": "winzige Säckchen in der Lunge", "zh": "肺泡"}, {"w": "Kiemen", "de": "Teile am Kopf von Fischen zum Atmen", "zh": "鳃"}, {"w": "Adern", "de": "Röhren, in denen Blut fließt", "zh": "血管"}, {"w": "schlapp", "de": "müde, ohne Kraft", "zh": "乏力的"}, {"w": "entzündet", "de": "rot, heiß und krank", "zh": "发炎的"}], "qs": [{"q": "Wo gelangt der Sauerstoff ins Blut?", "qZh": "氧气在哪里进入血液？", "answer": "In den Lungenbläschen.", "wrong": ["Im Magen.", "Im Mund."]}, {"q": "Wie atmen Fische?", "qZh": "鱼怎样呼吸？", "answer": "Durch Kiemen.", "wrong": ["Mit Lungen.", "Durch Tracheen."]}, {"q": "Wie atmen Insekten?", "qZh": "昆虫怎样呼吸？", "answer": "Durch Tracheen.", "wrong": ["Durch Kiemen.", "Mit großen Lungen."]}], "src": "改编自 Klexikon《Atmung》", "url": "https://klexikon.zum.de/index.php?oldid=162309", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-048", "seg": 11, "title": "Schlaganfall", "de": ["Ein Schlaganfall ist eine Krankheit im Gehirn. Dadurch wird ein Mensch plötzlich gelähmt. Oft kann man dann nicht mehr gehen, schlucken, sprechen oder einen Arm heben. Schlaganfälle halten unterschiedlich lange an. Manche vergehen schnell wieder von selbst. Es kann aber auch passieren, dass man stirbt oder für den Rest des Lebens behindert ist.", "Die Ursache dieser Krankheit liegt im Gehirn. Dort erhalten einige Stellen auf einmal nicht mehr genug Blut. Fast immer liegt das daran, dass eine Ader im Gehirn geplatzt ist oder verstopft. Dadurch sterben dort die Zellen ab. Das Gehirn kann nicht sofort, oder auch gar nicht, dafür sorgen, dass eine andere Stelle im Gehirn das macht, was die betroffene Stelle erledigt hat. Die Nerven, die zu den Muskeln führen, erhalten keine Informationen mehr. Die Kranken können sich nicht mehr wie gewohnt bewegen.", "Bei einem Schlaganfall kann man nicht nur gelähmt werden. Manche Menschen sehen plötzlich Dinge doppelt oder einiges gar nicht mehr. Zudem wird einem vielleicht schwindelig, oder der Kopf tut weh.", "Wenn jemand einen frischen Schlaganfall hat, dann muss er sehr schnell behandelt werden. Manchmal kann ein Arzt den Blutpfropf, der die Ader im Gehirn verstopft, noch auflösen. Es sterben dann weniger Zellen, und der Kranke erholt sich schneller wieder. Wenn der Kranke nach einem Schlaganfall bestimmte Dinge nicht mehr tun kann, helfen ihm oft gezielte Übungen, diese wieder zu erlernen."], "zh": ["中风是一种脑部疾病，会让人突然瘫痪。常常人就不能走路、吞咽、说话或抬起一只胳膊了。中风持续的时间长短不一。有的很快自己就好了，但也可能死亡，或者终身残疾。", "这种病的原因在大脑。大脑某些地方突然得不到足够的血液，几乎总是因为脑里一根血管破裂或堵塞了。于是那里的细胞死去。大脑不能马上、甚至根本不能让别的地方接手受损部位原来的工作。通往肌肉的神经收不到信息了，病人就不能像平常那样活动。", "中风不只会让人瘫痪。有些人突然看东西重影，或者有些东西完全看不见了。此外还可能头晕或头疼。", "刚中风的人必须很快得到治疗。有时医生还能把堵住脑血管的血栓溶解掉，这样死去的细胞就少一些，病人恢复得更快。如果病人中风后有些事做不了了，有针对性的练习常常能帮他重新学会。"], "lemmas": [], "gloss": [{"w": "gelähmt", "de": "kann sich nicht mehr bewegen", "zh": "瘫痪的"}, {"w": "schlucken", "de": "Essen vom Mund in den Magen bringen", "zh": "吞咽"}, {"w": "geplatzt", "de": "kaputt gegangen, aufgerissen", "zh": "破裂"}, {"w": "schwindelig", "de": "alles dreht sich", "zh": "头晕的"}, {"w": "Blutpfropf", "de": "Klumpen aus Blut, der eine Ader zumacht", "zh": "血栓"}, {"w": "gezielte", "de": "genau für ein Ziel gemachte", "zh": "有针对性的"}], "qs": [{"q": "Was passiert bei einem Schlaganfall im Gehirn?", "qZh": "中风时大脑里发生了什么？", "answer": "Einige Stellen bekommen nicht mehr genug Blut.", "wrong": ["Das Gehirn wird größer.", "Das Gehirn bekommt zu viel Sauerstoff."]}, {"q": "Was kann ein Schlaganfall außer Lähmung noch bewirken?", "qZh": "中风除了瘫痪还会造成什么？", "answer": "Man sieht doppelt oder einiges gar nicht.", "wrong": ["Man wird größer.", "Man hört besser."]}, {"q": "Was ist bei einem frischen Schlaganfall wichtig?", "qZh": "刚中风时什么最重要？", "answer": "Sehr schnelle Behandlung.", "wrong": ["Viel schlafen.", "Sport machen."]}], "src": "改编自 Klexikon《Schlaganfall》", "url": "https://klexikon.zum.de/index.php?oldid=160497", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-049", "seg": 11, "title": "Herzinfarkt", "de": ["Ein Herzinfarkt ist eine schwere Erkrankung des Herzens. Dabei wird ein Teil des Herzens nicht mehr durchblutet, weil ein Stück verklumptes Blut eine Ader verstopft. Der Teil, der nicht mehr durchblutet wird, stirbt ab. Dort bildet sich dann eine Narbe wie nach einer Verletzung.", "Es gibt viele Gründe, warum jemand einen Herzinfarkt bekommen kann. Manche Leute sind zu dick, essen zu viel oder zu fettig, oder sie bewegen sich zu wenig. Außerdem gibt es bei Erwachsenen noch andere Gründe: Krankheiten wie Diabetes, hoher Blutdruck, Rauchen oder Stress.", "Wenn jemand einen Herzinfarkt bekommt, dann hat er oft starke, stechende Schmerzen im Brustbereich. Die Schmerzen können aber auch ausstrahlen, etwa in die linke Schulter und den linken Arm. In vielen Fällen kommt auch noch Todesangst hinzu. Es fühlt sich an, als würde der Brustkorb zusammengedrückt werden. Bei Männern und Frauen sind die Anzeichen für einen Herzinfarkt unterschiedlich: Frauen wird häufiger übel, wenn sie einen Herzinfarkt haben.", "Sind die Schmerzen ungewohnt und sehr stark, muss dem Menschen mit einem Herzinfarkt schnell und richtig geholfen werden. Am besten ist es, bei Verdacht auf einen Herzinfarkt sofort die Notruf-Nummer 112 zu wählen und damit möglichst rasch einen Rettungswagen zu rufen.", "Im Krankenhaus wird den Patienten geholfen: Bei vielen von ihnen kann man den Blutklumpen in der Ader entfernen. Dann stirbt kein so großer Teil des Herzens ab. Mit einer Art Röhre oder Klammer sorgen die Ärzte dafür, dass das Blut besser fließt."], "zh": ["心肌梗塞是一种严重的心脏病。这时心脏有一部分不再有血液供应，因为一块凝结的血块堵住了一根血管。没有血液供应的那部分会坏死，那里会像受伤后一样留下疤痕。", "一个人得心梗有很多原因。有些人太胖、吃得太多或太油，或者运动太少。此外成年人还有别的原因：糖尿病、高血压等疾病，吸烟或压力。", "有人心梗发作时，胸部常常有剧烈的刺痛。疼痛也可能放射，比如到左肩和左臂。很多时候还伴有濒死的恐惧，感觉像胸廓被压住一样。男性和女性心梗的征兆不同：女性心梗时更常恶心。", "如果疼痛异常且非常剧烈，必须快速正确地帮助心梗病人。怀疑是心梗时，最好马上拨急救电话 112，尽快叫救护车。", "病人在医院会得到救治：很多人的血管里的血块可以取出来，这样心脏坏死的部分就不会那么大。医生用一种管子或夹子让血流得更好。"], "lemmas": [], "gloss": [{"w": "durchblutet", "de": "mit Blut versorgt", "zh": "有血液供应的"}, {"w": "verklumptes", "de": "fest und dick geworden", "zh": "凝结的"}, {"w": "Narbe", "de": "Zeichen auf der Haut nach einer Wunde", "zh": "疤痕"}, {"w": "Blutdruck", "de": "wie stark das Blut gegen die Adern drückt", "zh": "血压"}, {"w": "ausstrahlen", "de": "sich in andere Körperteile ausbreiten", "zh": "放射"}, {"w": "Verdacht", "de": "wenn man glaubt, dass etwas sein könnte", "zh": "怀疑"}], "qs": [{"q": "Was passiert bei einem Herzinfarkt?", "qZh": "心肌梗塞时发生了什么？", "answer": "Ein Teil des Herzens bekommt kein Blut mehr.", "wrong": ["Das Herz schlägt zu langsam vor Freude.", "Das Herz wird größer."]}, {"q": "Wohin können die Schmerzen ausstrahlen?", "qZh": "疼痛可能放射到哪里？", "answer": "In die linke Schulter und den linken Arm.", "wrong": ["In die Füße.", "In die Ohren."]}, {"q": "Was soll man bei Verdacht auf Herzinfarkt tun?", "qZh": "怀疑心梗时该怎么做？", "answer": "Sofort die 112 wählen.", "wrong": ["Abwarten und schlafen.", "Viel Wasser trinken."]}], "src": "改编自 Klexikon《Herzinfarkt》", "url": "https://klexikon.zum.de/index.php?oldid=165835", "lic": "CC BY-SA 4.0", "original": false}, {"id": "b1-11-050", "seg": 11, "title": "Antibiotikum", "de": ["Ein Antibiotikum ist ein Medikament, das gegen krankmachende Bakterien wirkt. Der Name kommt von den zwei Teilen „anti“, „gegen“ und „bios“, „Leben”, vermutlich, weil Bakterien kleinste Lebewesen sind. Die Mehrzahl von Antibiotikum heißt Antibiotika. Das erste Antibiotikum hieß Penicillin und wurde im Jahr 1928 in Schimmelpilzen entdeckt.", "Antibiotika helfen gegen Krankheiten, gegen die ein Arzt vorher nicht helfen konnte. Ein Beispiel ist der Wundstarrkrampf, den man sich leicht holen kann, wenn man eine offene Wunde hat: Bakterien kommen zusammen mit Dreck und Staub hinein. Antibiotika helfen auch bei Lungenentzündungen oder gegen die Pest, an der im Mittelalter viele Millionen Menschen gestorben sind.", "Erst der Schotte Alexander Fleming machte das Penicillin als das erste Antibiotikum bekannt. Er gewann es aus Schimmelpilzen und untersuchte die Wirkung auf Bakterien. Zwar war er nicht der Erste, der das feststellte. Trotzdem bekam er 1945 für seine Entdeckung den Nobelpreis. Inzwischen gibt es viele neue Antibiotika, die vom Penicillin stammen oder von anderen natürlichen Antibiotika.", "Krankheiten kommen meistens von Bakterien und Viren. Bakterien sind kleinste Lebewesen, von denen einige Krankheitserreger sind. Gelangen sie in den Körper, so können sie sich dort vermehren. Probleme hat der Mensch meistens wegen der Gifte, die diese Bakterien abgeben."], "zh": ["抗生素是对付致病细菌的药。这个名字由两部分组成：anti 是「反对」，bios 是「生命」，大概是因为细菌是最小的生物。Antibiotikum 的复数是 Antibiotika。第一种抗生素叫青霉素，1928 年在霉菌里被发现。", "抗生素能治以前医生束手无策的病。比如破伤风，有开放性伤口时很容易得：细菌随着泥土和灰尘进入伤口。抗生素也能治肺炎或鼠疫，中世纪有好几百万人死于鼠疫。", "是苏格兰人亚历山大·弗莱明让青霉素作为第一种抗生素出了名。他从霉菌中提取青霉素，研究它对细菌的作用。虽然他不是第一个发现这一点的人，但他还是在 1945 年因这一发现获得了诺贝尔奖。如今有许多新的抗生素，源自青霉素或别的天然抗生素。", "疾病大多来自细菌和病毒。细菌是最小的生物，其中一些是病原体。它们进入身体后会在那里繁殖。人遇到的问题大多是因为这些细菌释放的毒素。"], "lemmas": [], "gloss": [{"w": "krankmachende", "de": "die krank machen", "zh": "致病的"}, {"w": "Wunde", "de": "Stelle, an der die Haut verletzt ist", "zh": "伤口"}, {"w": "Pest", "de": "schwere Krankheit im Mittelalter", "zh": "鼠疫"}, {"w": "gewann", "de": "holte heraus, stellte her", "zh": "提取"}, {"w": "Krankheitserreger", "de": "Dinge, die Krankheiten machen", "zh": "病原体"}, {"w": "vermehren", "de": "mehr werden", "zh": "繁殖"}], "qs": [{"q": "Wogegen wirkt ein Antibiotikum?", "qZh": "抗生素对付什么？", "answer": "Gegen krankmachende Bakterien.", "wrong": ["Gegen Viren.", "Gegen Kopfschmerzen ohne Grund."]}, {"q": "Wie hieß das erste Antibiotikum?", "qZh": "第一种抗生素叫什么？", "answer": "Penicillin.", "wrong": ["Influenza.", "Aspirin."]}, {"q": "Wer machte das Penicillin bekannt?", "qZh": "谁让青霉素出了名？", "answer": "Alexander Fleming.", "wrong": ["Charles Darwin.", "Carl Benz."]}], "src": "改编自 Klexikon《Antibiotikum》", "url": "https://klexikon.zum.de/index.php?oldid=154235", "lic": "CC BY-SA 4.0", "original": false}];
